def qualify_planar_bands() -> dict[str, object]:
    with TemporaryDirectory(prefix="phydrax-planar-bands-") as temporary:
        embedding, partition = _planar_partition(Path(temporary) / "planar.brep")
        patch = next(
            value for value in partition.patches if len(value.adjacent_region_ids) == 2
        )
        schedule = phx.meshing.LayerSchedule.geometric(2, 0.05, growth_rate=1.0)
        control = phx.meshing.PlanarBandControl(
            patch.name,
            {name: schedule for name in patch.adjacent_region_ids},
            0.1,
        )
        source = phx.meshing.prepare_planar_bands(
            phx.meshing.PlanarBandPlan(partition, embedding, (control,)),
            destination=Path(temporary) / "bands.brep",
        )
        provider = phx.meshing.GmshProvider()
        scope = provider.whole_scope(source, 2)
        band_patch_controls = tuple(
            phx.meshing.PatchControl(
                band_patch.name,
                provider.entity_scope(source, band_patch.entity_ids),
                band_patch.adjacent_region_ids,
            )
            for band_patch in source.partition.patches
            if len(set(band_patch.adjacent_region_ids))
            == len(band_patch.adjacent_region_ids)
        )
        specification = phx.meshing.SurfaceMeshingSpec(
            phx.meshing.CellMeshingTarget(
                2,
                2,
                phx.meshing.CellFamilyPolicy(required=("quadrilateral",)),
            ),
            scope,
            planar_embedding=embedding,
            size_controls=(phx.meshing.UniformSizeControl(scope, 0.1),),
            region_controls=_region_controls(provider, source.partition),
            patch_controls=band_patch_controls,
        )
        mesh_result = provider.plan(source, specification).execute()
    if not mesh_result.audit.passed or not mesh_result.compliance.passed:
        raise RuntimeError("Planar band mesh failed audit or compliance.")
    achieved = dict(mesh_result.compliance.achieved)
    front_residuals = {}
    for layer in source.layer_partitions:
        key = f"planar_band:{layer.control_id}:{layer.region_name}:front:{layer.layer_index + 1}"
        residual = achieved[f"{key}:maximum_residual"]
        if residual > 1.0e-12:
            raise RuntimeError("Planar band front departed from its exact CAD level.")
        front_residuals[key] = residual
    return {
        "plan_id": source.plan_id,
        "result_id": source.result_id,
        "mesh_result_id": mesh_result.result_id,
        "partition_revision": source.partition.revision.revision_id,
        "layer_partitions": len(source.layer_partitions),
        "front_residuals": front_residuals,
    }


def qualify_hybrid_layer() -> dict[str, object]:
    with TemporaryDirectory(prefix="phydrax-hybrid-layer-") as temporary:
        result, control = _hybrid_gmsh_result(Path(temporary) / "hybrid-slab.brep")
    if not result.audit.passed or not result.compliance.passed:
        raise RuntimeError("Generated hybrid layer mesh failed audit or compliance.")
    block_kinds = tuple(block.cell_kind for block in result.mesh.blocks)
    if block_kinds != ("prism", "tetrahedron"):
        raise RuntimeError("Generated hybrid layer mesh lost its required cell families.")
    achieved = dict(result.compliance.achieved)
    return {
        "mesh_id": result.mesh.mesh_id,
        "result_id": result.result_id,
        "control_id": control.control_id,
        "schedule_id": control.schedule.schedule_id,
        "thicknesses": list(control.schedule.thicknesses),
        "block_kinds": block_kinds,
        "cells": result.mesh.entity_set(3).count,
        "maximum_layer_thickness_error": achieved[
            f"layer:{control.control_id}:maximum_thickness_residual"
        ],
        "audit_passed": result.audit.passed,
    }


def qualify_hybrid_diffusion() -> dict[str, object]:
    with TemporaryDirectory(prefix="phydrax-hybrid-diffusion-") as temporary:
        generated, _ = _hybrid_gmsh_result(Path(temporary) / "hybrid-slab.brep")
    mesh = generated.mesh
    field = phx.discretization.FiniteElementFieldSpec(
        "u",
        {
            block.name: phx.discretization.lagrange_element(
                block.cell_kind,
                1,
            )
            for block in mesh.blocks
        },
    )
    discretization = phx.discretization.FiniteElementPlan(mesh, field).prepare()
    cells = mesh.entity_set(3)
    scope = _mesh_scope(mesh, 3, np.asarray(cells.entity_ids))
    domain = discretization.integration_domain(
        "cell", phx.meshing.resolve_mesh_scope(mesh, scope)
    )
    form = phx.equations.FiniteElementForm(
        "hybrid-diffusion",
        "u",
        (phx.equations.DiffusionAction("u", 1.0, domain=domain),),
    )
    compiled = phx.equations.compile_finite_element_problem(form, discretization)
    system, rhs = compiled.linear_system()
    dof_count = discretization.dof_maps[0].global_dof_count
    constant = np.ones(dof_count)
    null_residual = float(np.max(np.abs(np.asarray(system.operator.mv(constant)))))
    coordinates = np.asarray(discretization.vertices)
    values = coordinates[:, 0]
    energy = float(np.vdot(values, np.asarray(system.operator.mv(values))))
    rhs_norm = float(np.max(np.abs(np.asarray(rhs))))
    if not (
        np.isclose(null_residual, 0.0, atol=1.0e-12)
        and np.isclose(rhs_norm, 0.0, atol=1.0e-12)
        and np.isclose(energy, 1.0, atol=1.0e-10)
    ):
        raise RuntimeError("Hybrid diffusion lost its P1 null mode or volume energy.")
    return {
        "mesh_id": mesh.mesh_id,
        "scope": scope.scope_id,
        "dofs": dof_count,
        "null_residual": null_residual,
        "rhs_norm": rhs_norm,
        "x_gradient_energy": energy,
        "generated_result_id": generated.result_id,
    }


def _distribution_lattice(cells_per_axis: int, /) -> phx.discretization.CellMesh:
    """Counterclockwise lattice triangles of the unit square."""
    axis = np.linspace(0.0, 1.0, cells_per_axis + 1)
    points = np.stack(np.meshgrid(axis, axis, indexing="ij"), axis=-1).reshape((-1, 2))
    index = np.arange((cells_per_axis + 1) ** 2, dtype=np.int32).reshape(
        (cells_per_axis + 1, cells_per_axis + 1)
    )
    lower, right = index[:-1, :-1].reshape((-1,)), index[1:, :-1].reshape((-1,))
    upper, left = index[1:, 1:].reshape((-1,)), index[:-1, 1:].reshape((-1,))
    triangles = np.concatenate(
        (np.stack((lower, right, upper), axis=1), np.stack((lower, upper, left), axis=1))
    )
    return phx.discretization.CellMesh.from_triangles(points, triangles)


def _distribution_cells(
    mesh: phx.discretization.CellMesh, /
) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
    """Native-order global IDs, signed areas, and centroids of triangle cells."""
    triangles = np.concatenate([np.asarray(block.vertices) for block in mesh.blocks])
    corners = np.asarray(mesh.coordinates)[triangles]
    edges = corners[:, 1:] - corners[:, :1]
    areas = 0.5 * (edges[:, 0, 0] * edges[:, 1, 1] - edges[:, 0, 1] * edges[:, 1, 0])
    ids = np.concatenate([np.asarray(block.global_ids) for block in mesh.blocks])
    return ids, areas, corners.mean(axis=1)


def _distribution_edge_cut(
    mesh: phx.discretization.CellMesh, owner: np.ndarray, /
) -> int:
    """Edge-sharing cell pairs with different owners, recounted from the triangles."""
    triangles = np.concatenate([np.asarray(block.vertices) for block in mesh.blocks])
    corners = np.asarray(((0, 1), (1, 2), (2, 0)), dtype=np.int32)
    edges = np.sort(triangles[:, corners], axis=2).reshape((-1, 2)).astype(np.int64)
    keys = edges[:, 0] * mesh.coordinates.shape[0] + edges[:, 1]
    order = np.argsort(keys, kind="stable")
    cells = np.repeat(np.arange(triangles.shape[0]), 3)[order]
    shared = keys[order][1:] == keys[order][:-1]
    return int(np.count_nonzero(owner[cells[:-1][shared]] != owner[cells[1:][shared]]))


def _distribution_rows(native: np.ndarray, identifiers: np.ndarray, /) -> np.ndarray:
    """Rows of ``identifiers`` in ``native``; every identifier must be present."""
    order = np.argsort(native, kind="stable")
    located = np.searchsorted(native, identifiers, sorter=order)
    rows = order[np.minimum(located, native.size - 1)]
    if not np.array_equal(native[rows], identifiers):
        raise RuntimeError("Lineage identifiers are missing from the native cell order.")
    return rows


def _distribution_retained_bytes(tree: object, /) -> int:
    """Bytes of the distinct array leaves a prepared value retains."""
    leaves = {
        id(leaf): leaf
        for leaf in jax.tree.leaves(tree)
        if isinstance(leaf, (jax.Array, np.ndarray))
    }
    return sum(leaf.nbytes for leaf in leaves.values())


def _distribution_route(
    part: phx.meshing.MeshPart,
    policy: phx.meshing.MeshPartitionPolicy,
    weights: np.ndarray,
    bound: float,
    /,
    **ownership: np.ndarray,
) -> tuple[phx.meshing.MeshDistribution, dict[str, object]]:
    """Partition ``part`` and check its evidence against an independent recount."""
    distribution, stage = _measured(
        lambda: phx.meshing.prepare_mesh_distribution(
            part, policy=policy, cell_weights=weights, **ownership
        )
    )

    owner = np.asarray(distribution.partition.cell_owner)

    evidence = distribution.evidence
    part_weights = np.bincount(owner, weights=weights, minlength=policy.part_count)

    halos = tuple(np.asarray(rows) for rows in distribution.halo_rows)

    carrier = part.carrier
    if not isinstance(carrier, phx.meshing.CellMeshingResult):
        raise TypeError("Distribution qualification requires a native cell-mesh carrier.")
    edge_cut = _distribution_edge_cut(carrier.mesh, owner)
    ghost_owned = any(np.any(owner[rows] == rank) for rank, rows in enumerate(halos))
    if (
        np.any(part_weights <= 0.0)
        or not np.allclose(np.asarray(evidence.part_weights), part_weights, rtol=1e-14)
        or float(evidence.imbalance) > bound + 1e-12
        or int(evidence.edge_cut) != edge_cut
        or int(evidence.halo_replicas) != sum(rows.size for rows in halos)
        or ghost_owned
    ):
        raise RuntimeError(
            f"{policy.kind.value} distribution evidence failed its recount."
        )
    return distribution, {
        "status": "passed",
        "distribution_id": distribution.distribution_id,
        "evidence_id": evidence.evidence_id,
        "provenance": evidence.provenance,
        "part_weights": part_weights.tolist(),
        "imbalance": float(evidence.imbalance),
        "imbalance_bound": float(bound),
        "edge_cut": edge_cut,
        "halo_replicas": int(evidence.halo_replicas),
        "resources": {
            **stage,
            "retained_bytes": _distribution_retained_bytes(distribution),
        },
    }


def _distribution_transition(
    source: phx.meshing.MeshDistribution,
    target_part: phx.meshing.MeshPart,
    lineage: phx.meshing.MeshLineage,
    policy: phx.meshing.MeshPartitionPolicy,
    weights: np.ndarray,
    source_areas: np.ndarray,
    density: np.ndarray,
    /,
) -> dict[str, object]:
    """Carry ``source`` through ``lineage``; check migration and cell-data transfer."""
    transition, stage = _measured(
        lambda: phx.meshing.prepare_distribution_transition(
            source, target_part, lineage, policy=policy, cell_weights=weights
        )
    )

    target = transition.target

    carrier = target_part.carrier
    if not isinstance(carrier, phx.meshing.CellMeshingResult):
        raise TypeError(
            "Distribution transition qualification requires a native cell-mesh carrier."
        )
    mesh = carrier.mesh
    target_ids, target_areas, _ = _distribution_cells(mesh)
    source_ids = np.asarray(source.cell_global_ids)
    cells = next(record for record in lineage.entities if record.dimension == 2)
    lineage_sources = np.asarray(cells.source_global_ids)
    lineage_targets = np.asarray(cells.target_global_ids)
    parents = np.full(target_ids.shape, -1, dtype=np.int64)
    parents[_distribution_rows(target_ids, lineage_targets)] = _distribution_rows(
        source_ids, lineage_sources
    )

    if np.any(parents < 0) or not np.all(np.asarray(transition.target_defined)):
        raise RuntimeError("Bisection lineage left a target cell without a parent.")

    moved = np.asarray(transition.transfer(jnp.asarray(density)))
    copy_error = float(np.max(np.abs(moved - density[parents])))
    integral_before = float(np.sum(density * source_areas))
    integral_after = float(np.sum(moved * target_areas))
    residual = abs(integral_after - integral_before) / abs(integral_before)
    parts = policy.part_count
    sender = np.asarray(source.partition.cell_owner, dtype=np.int64)[parents]
    receiver = np.asarray(target.partition.cell_owner, dtype=np.int64)
    remote = sender != receiver
    counts = np.bincount(sender * parts + receiver, minlength=parts * parts)

    slots = np.arange(transition.send.capacity)

    sent = np.concatenate([np.asarray(transition.sent_by(rank)) for rank in range(parts)])
    received = np.concatenate(
        [np.asarray(transition.received_by(rank)) for rank in range(parts)]
    )
    preserved = np.asarray(cells.relation_kinds) == int(
        phx.meshing.EntityLineageKind.PRESERVED
    )
    bound = (
        1.0 + parts * np.max(weights) / np.sum(weights)
        if transition.rebalanced
        else policy.maximum_imbalance
    )
    checks = {
        "exact_parent_copy": copy_error == 0.0,
        "integral_preserved": residual <= 1e-12,
        "migration_counts": np.array_equal(
            np.asarray(transition.migration_counts),
            counts.reshape((parts, parts)),
        ),
        "migrated_cells": int(transition.migrated_cells) == np.count_nonzero(remote),
        "migration_volume": np.isclose(
            float(transition.migration_volume),
            np.sum(weights[remote]),
            rtol=1e-14,
            atol=0.0,
        ),
        "message_slots": np.array_equal(np.sort(sent), slots)
        and np.array_equal(np.sort(received), slots),
        "imbalance_bound": float(target.evidence.imbalance) <= bound + 1e-12,
        "edge_cut": int(target.evidence.edge_cut)
        == _distribution_edge_cut(mesh, receiver),
        "source_ids_unchanged": np.array_equal(
            np.asarray(transition.source.cell_global_ids),
            source_ids,
        ),
        "target_ids_native": np.array_equal(
            np.asarray(target.cell_global_ids), target_ids
        ),
        "preserved_ids_unchanged": np.array_equal(
            lineage_sources[preserved], lineage_targets[preserved]
        ),
    }
    failed = sorted(name for name, passed in checks.items() if not passed)
    if failed:
        raise RuntimeError(f"Distribution transition failed checks: {failed}.")
    return {
        "status": "passed",
        "transition_id": transition.transition_id,
        "lineage_id": transition.lineage_id,
        "source_distribution_id": source.distribution_id,
        "target_distribution_id": target.distribution_id,
        "target_provenance": target.evidence.provenance,
        "maximum_imbalance": policy.maximum_imbalance,
        "rebalanced": transition.rebalanced,
        "imbalance_after": float(target.evidence.imbalance),
        "imbalance_bound": float(bound),
        "edge_cut_after": int(target.evidence.edge_cut),
        "halo_replicas_after": int(target.evidence.halo_replicas),
        "migration_counts": counts.reshape((parts, parts)).tolist(),
        "migrated_cells": int(transition.migrated_cells),
        "migration_volume": float(transition.migration_volume),
        "message_slots": int(slots.size),
        "preserved_cells": int(np.count_nonzero(preserved)),
        "checks_passed": sorted(checks),
        "transfer": {
            "maximum_parent_copy_error": copy_error,
            "integral_before": integral_before,
            "integral_after": integral_after,
            "relative_integral_residual": residual,
        },
        "resources": {
            **stage,
            "retained_bytes": _distribution_retained_bytes(transition),
        },
    }


def qualify_distribution() -> dict[str, object]:
    from phydrax.meshing._metis import metis_identity

    kind = phx.meshing.MeshPartitionKind
    parts = 4
    source, certify_stage = _measured(
        lambda: phx.meshing.certify_cell_mesh(_distribution_lattice(8), _contract())
    )
    part = phx.meshing.MeshPart("distribution-square", source)

    cell_ids, areas, centroids = _distribution_cells(source.mesh)
    # The right half costs twice as much, so balanced parts differ in cell count.
    weights = np.where(centroids[:, 0] > 0.5, 2.0, 1.0)
    curve_bound = 1.0 + parts * np.max(weights) / np.sum(weights)
    distributions, routes = {}, {}
    for route in (kind.MORTON, kind.HILBERT):
        distributions[route], routes[route.value] = _distribution_route(
            part, phx.meshing.MeshPartitionPolicy(route, parts), weights, curve_bound
        )
    graph = phx.meshing.MeshPartitionPolicy(kind.GRAPH, parts, maximum_imbalance=1.1)
    _, routes[kind.GRAPH.value] = _distribution_route(
        part, graph, weights, graph.maximum_imbalance
    )
    # METIS is an explicit comparison route; loading its library is the only
    # way to learn whether it is usable.
    try:
        metis = metis_identity()
    except phx.meshing.MetisUnavailableError as error:
        routes[kind.METIS.value] = {
            "status": "missing-dependency",
            "dependency": "METIS",
            "detail": f"{error} Install METIS 5 and set PHYDRAX_METIS_LIBRARY.",
        }
    else:
        comparison = phx.meshing.MeshPartitionPolicy(
            kind.METIS, parts, maximum_imbalance=1.1
        )
        _, record = _distribution_route(
            part, comparison, weights, comparison.maximum_imbalance
        )
        routes[kind.METIS.value] = {**record, "metis": metis}
    # Horizontal strips stand in for ownership computed by an external partitioner.
    strips = np.minimum(np.floor(centroids[:, 1] * parts), parts - 1).astype(np.int32)
    strip_weights = np.bincount(strips, weights=weights, minlength=parts)
    provided, routes[kind.PROVIDER.value] = _distribution_route(
        part,
        phx.meshing.MeshPartitionPolicy(kind.PROVIDER, parts),
        weights,
        np.max(strip_weights) / np.mean(strip_weights),
        ownership=strips,
    )
    if not np.array_equal(np.asarray(provided.partition.cell_owner), strips):
        raise RuntimeError("The PROVIDER route did not keep the supplied ownership.")

    marked = cell_ids[np.all(centroids < 0.3, axis=1)]
    adaptation, adaptation_stage = _measured(
        lambda: phx.meshing.execute_mesh_adaptation(
            phx.meshing.prepare_mesh_adaptation(
                source,
                phx.meshing.MarkedMeshAdaptation(marked),
                policy=phx.meshing.MeshAdaptationPolicy(
                    phx.meshing.MeshAdaptationRoute.NATIVE_BISECTION
                ),
            )
        )
    )

    target = adaptation.target

    if adaptation.lineage is None or not target.audit.passed:
        raise RuntimeError("Native bisection did not refine the marked subregion.")
    target_part = phx.meshing.MeshPart(part.name, target)
    _, _, target_centroids = _distribution_cells(target.mesh)
    target_weights = np.where(target_centroids[:, 0] > 0.5, 2.0, 1.0)
    density = 1.0 + centroids[:, 0] + 2.0 * centroids[:, 1] ** 2
    hilbert = distributions[kind.HILBERT]
    transitions = {
        name: _distribution_transition(
            hilbert,
            target_part,
            adaptation.lineage,
            phx.meshing.MeshPartitionPolicy(
                kind.HILBERT, parts, maximum_imbalance=tolerance
            ),
            target_weights,
            areas,
            density,
        )
        for name, tolerance in (("inherited", 2.0), ("rebalanced", 1.05))
    }
    inherited, rebalanced = transitions["inherited"], transitions["rebalanced"]
    if (
        inherited["rebalanced"]
        or inherited["migrated_cells"] != 0
        or not rebalanced["rebalanced"]
        or rebalanced["migrated_cells"] == 0
    ):
        raise RuntimeError("Transition ownership ignored the maximum-imbalance rule.")
    return {
        "status": "passed",
        "source": {
            **_result_identity(source),
            "part_id": part.part_id,
            "distribution_id": hilbert.distribution_id,
        },
        "target": {
            **_result_identity(target),
            "part_id": target_part.part_id,
            "adaptation_result_id": adaptation.result_id,
            "lineage_id": adaptation.lineage.lineage_id,
        },
        "runtime": _runtime_identity(),
        "quality": {
            "before": _quality_summary(source.quality),
            "after": _quality_summary(target.quality),
        },
        "routes": routes,
        "adaptation": {
            "route": adaptation.route.value,
            "status": adaptation.status.value,
            "marked_cells": int(marked.size),
        },
        "transitions": transitions,
        "transfer": {name: value["transfer"] for name, value in transitions.items()},
        "conservation": {
            name: _record_mapping(value["transfer"], "Distribution transfer")[
                "relative_integral_residual"
            ]
            for name, value in transitions.items()
        },
        "resources": {
            "certification": certify_stage,
            "adaptation": adaptation_stage,
            "routes": {
                name: value["resources"]
                for name, value in routes.items()
                if "resources" in value
            },
            "transitions": {
                name: value["resources"] for name, value in transitions.items()
            },
        },
    }


def _forest_balance(topology: phx.discretization.ForestHierarchyTopology, /) -> Any:
    """Level histogram and the largest level jump across shared faces."""
    levels = topology.leaf_levels().astype(np.int64)
    workset = topology.workset
    valid = np.asarray(workset.face_valid)
    minus = levels[np.asarray(workset.face_minus)[valid]]
    plus = levels[np.asarray(workset.face_plus)[valid]]
    return {
        "topology_id": topology.topology_id,
        "epoch": topology.epoch.index,
        "leaves": topology.leaf_count,
        "faces": topology.face_count,
        "level_histogram": np.bincount(
            levels, minlength=topology.plan.maximum_level + 1
        ).tolist(),
        "maximum_face_level_jump": int(np.max(np.abs(minus - plus))),
        "hanging_faces": int(
            np.count_nonzero(np.asarray(workset.face_coarse_fine)[valid])
        ),
    }


def qualify_forest_amr() -> dict[str, object]:
    grid = phx.discretization.TensorGridPlan(
        (
            phx.discretization.UniformCellAxisSpec(4),
            phx.discretization.UniformCellAxisSpec(4),
        ),
        axis_names=("x", "y"),
    ).prepare(jnp.asarray([[0.0, 0.0], [1.0, 1.0]]))
    plan = phx.discretization.ForestPlan(
        grid,
        maximum_level=4,
        balance=phx.discretization.AMRBalanceStencil.FACE,
        maximum_leaf_capacity=1 << 12,
    )
    compiler = phx.discretization.ForestTopologyCompiler(plan)
    initial, initialize_stage = _measured(lambda: compiler.initialize(1))

    topology = initial.topology
    finest = np.asarray(plan.root_shape, dtype=np.int64) << plan.maximum_level
    # Drive one interior point to the maximum level; every step forces 2:1
    # closure refinements of coarser face neighbors.
    point = (finest * 3 // 8)[None, :]
    refinement_stages, closures = [], 0
    for _ in range(plan.maximum_level - 1):
        marks = np.zeros((topology.signature.leaf_capacity,), dtype=np.int8)
        marks[
            topology.locate_cells(np.asarray([plan.maximum_level], dtype=np.int64), point)
        ] = 1
        refined, stage = _measured(
            lambda topology=topology, marks=marks: compiler.adapt(topology, marks)
        )

        if not refined.status.successful:
            raise RuntimeError(f"Forest refinement failed: {refined.status.message}")

        closures += refined.evidence.balance_refinements
        refinement_stages.append(stage)

        topology = refined.topology
    source = topology
    # One mixed epoch: refine near the center, coarsen every family on the right.
    levels = source.leaf_levels().astype(np.int64)
    shift = plan.maximum_level - levels
    lower = source.leaf_coordinates().astype(np.int64) << shift[:, None]
    centers = (lower + (1 << shift)[:, None] / 2.0) / finest
    marks = np.zeros((source.signature.leaf_capacity,), dtype=np.int8)
    marks[: source.leaf_count] = np.where(centers[:, 0] > 0.75, -1, 0)
    marks[
        source.locate_cells(
            np.asarray([plan.maximum_level], dtype=np.int64), (finest * 5 // 8)[None, :]
        )
    ] = 1
    adapted, adapt_stage = _measured(lambda: compiler.adapt(source, marks))

    evidence = adapted.evidence

    target = adapted.topology
    before, after = _forest_balance(source), _forest_balance(target)
    if (
        not adapted.status.successful
        or evidence.coarsened_families == 0
        or evidence.requested_refinements == 0
        or closures == 0
        or max(before["maximum_face_level_jump"], after["maximum_face_level_jump"]) > 1
    ):
        raise RuntimeError("Forest adaptation did not refine, coarsen, and stay 2:1.")

    transition, transition_stage = _measured(
        lambda: phx.discretization.ForestFieldTransition(source, target)
    )

    routes = transition.routes
    capacity = source.signature.leaf_capacity
    rng = np.random.default_rng(11)
    field = jnp.asarray(
        np.where(
            np.asarray(source.workset.leaf_valid),
            3.0 + rng.normal(size=(capacity,)),
            0.0,
        )
    )
    transferred, apply_stage = _measured(
        lambda: jax.block_until_ready(routes.apply(field))
    )
    content_before = float(jnp.sum(routes.source_measures * field))

    content_after = float(jnp.sum(routes.target_measures * transferred.values))
    residual = abs(content_after - content_before) / abs(content_before)

    reported = float(jnp.max(jnp.abs(transferred.conservation_residual)))
    constant = np.asarray(routes.apply(jnp.full((capacity,), 2.5)).values)
    constant_error = float(
        np.max(np.abs(constant[np.asarray(target.workset.leaf_valid)] - 2.5))
    )
    if (
        not bool(transferred.successful)
        or not transition.properties.conservative
        or not transition.properties.constant_preserving
        or residual > 1e-13
        or reported > 1e-12 * abs(content_before)
        or constant_error > 1e-14
    ):
        raise RuntimeError("Forest transfer failed conservation or constants.")

    partition_plan = phx.discretization.ForestPartitionPlan(4)
    source_partition, source_partition_stage = _measured(
        lambda: partition_plan.prepare(source)
    )
    target_partition, target_partition_stage = _measured(
        lambda: partition_plan.prepare(target)
    )
    migration, migration_stage = _measured(
        lambda: source_partition.migration_to(target_partition, transition=transition)
    )

    migrated = target_partition.unpack(migration.migrate(source_partition.pack(field)))

    migration_error = float(jnp.max(jnp.abs(migrated - transferred.values)))
    round_trip = bool(
        jnp.array_equal(source_partition.unpack(source_partition.pack(field)), field)
    )
    partitions = {
        "source": source_partition.evidence,
        "target": target_partition.evidence,
    }
    if (
        migration_error > 1e-12
        or not round_trip
        or any(min(value.ghost_counts) == 0 for value in partitions.values())
    ):
        raise RuntimeError("Distributed forest migration disagreed with the transfer.")
    return {
        "status": "passed",
        "source": {
            "plan_id": plan.plan_id,
            "topology_id": source.topology_id,
            "epoch_id": source.epoch.epoch_id,
            "leaves": source.leaf_count,
            "partition_id": source_partition.partition_id,
        },
        "target": {
            "topology_id": target.topology_id,
            "epoch_id": target.epoch.epoch_id,
            "leaves": target.leaf_count,
            "adapt_result_id": adapted.result_id,
            "adapt_evidence_id": evidence.evidence_id,
            "partition_id": target_partition.partition_id,
        },
        "runtime": _runtime_identity(),
        "quality": {"before": before, "after": after},
        "balance": {
            "stencil": plan.balance.value,
            "closure_refinements_while_refining": closures,
            "closure_refinements_mixed_epoch": evidence.balance_refinements,
            "balance_vetoed_families": evidence.balance_vetoed_families,
            "depth_limited_refinements": evidence.depth_limited_refinements,
        },
        "adaptation": {
            "requested_refinements": evidence.requested_refinements,
            "requested_coarsenings": evidence.requested_coarsenings,
            "coarsened_families": evidence.coarsened_families,
            "retained_leaves": transition.retained_leaves,
            "prolonged_leaves": transition.prolonged_leaves,
            "restricted_leaves": transition.restricted_leaves,
        },
        "transfer": {
            "transition_id": transition.transition_id,
            "conservative": transition.properties.conservative,
            "constant_preserving": transition.properties.constant_preserving,
            "constant_error": constant_error,
            "distributed_migration_error": migration_error,
        },
        "conservation": {
            "content_before": content_before,
            "content_after": content_after,
            "relative_residual": residual,
            "reported_residual": reported,
        },
        "distribution": {
            "parts": partition_plan.part_count,
            "ghost_stencil": partition_plan.ghost_stencil.value,
            "migration_id": migration.migration_id,
            "moved_leaves": migration.moved_leaves,
            **{
                name: {
                    "evidence_id": value.evidence_id,
                    "part_leaf_counts": list(value.part_leaf_counts),
                    "part_costs": list(value.part_costs),
                    "ghost_counts": list(value.ghost_counts),
                    "maximum_imbalance": value.maximum_imbalance,
                    "cut_faces": value.cut_faces,
                }
                for name, value in partitions.items()
            },
        },
        "resources": {
            "initialize": initialize_stage,
            "refinements": refinement_stages,
            "mixed_adaptation": adapt_stage,
            "transition": transition_stage,
            "transfer_apply": apply_stage,
            "source_partition": source_partition_stage,
            "target_partition": target_partition_stage,
            "migration": migration_stage,
            "retained_bytes": {
                "source_topology": _distribution_retained_bytes(source),
                "target_topology": _distribution_retained_bytes(target),
                "transition": _distribution_retained_bytes(transition),
                "source_partition": _distribution_retained_bytes(source_partition),
                "target_partition": _distribution_retained_bytes(target_partition),
                "migration": _distribution_retained_bytes(migration),
            },
        },
    }


_OMEGA_H_WORKER_HINT = (
    "Build native/providers/omega_h against an Omega_h CMake package (MPI-enabled "
    "for omega-h-distributed; docs/guides_meshing.md), then pass --worker, set "
    "PHYDRAX_OMEGA_H_WORKER, or put phydrax-omega-h-worker on PATH."
)


def _omega_h_worker(worker: str | None, /) -> str | None:
    """Resolve the Omega_h worker exactly as ``OmegaHProvider`` does."""
    return shutil.which(
        worker or os.environ.get("PHYDRAX_OMEGA_H_WORKER", "phydrax-omega-h-worker")
    )


def _qualify_omega_h_ranks(worker: str | None, ranks: int, /) -> dict[str, object]:
    """Metric adaptation with LINEAR and CONSERVE fields on ``ranks`` MPI ranks."""
    executable = _omega_h_worker(worker)
    if executable is None:
        return _missing_dependency("phydrax-omega-h-worker", _OMEGA_H_WORKER_HINT)
    if ranks > 1 and shutil.which("mpiexec") is None:
        return _missing_dependency(
            "mpiexec",
            "Distributed Omega_h adaptation launches its worker under the MPI "
            "launcher of the MPI implementation Omega_h was built with.",
        )
    cells_per_axis = 4
    mesh = _distribution_lattice(cells_per_axis)
    cell_ids, areas, centroids = _distribution_cells(mesh)
    zones = tuple(
        phx.meshing.MeshZone(
            name, phx.meshing.MeshZoneRole.REGION, _mesh_scope(mesh, 2, cell_ids[mask])
        )
        for name, mask in (
            ("left", centroids[:, 0] < 0.5),
            ("right", centroids[:, 0] > 0.5),
        )
    )
    source, certify_stage = _measured(
        lambda: phx.meshing.certify_cell_mesh(mesh, _contract(), zones=zones)
    )
    vertex_order = np.argsort(np.asarray(mesh.vertex_global_ids))
    vertex_ids = np.asarray(mesh.vertex_global_ids)[vertex_order]
    points = np.asarray(mesh.coordinates)[vertex_order]
    matrix = np.eye(2) * (2.0 * cells_per_axis) ** 2
    matrix[0, 1] = matrix[1, 0] = 0.15 * matrix[0, 0]
    metric = phx.meshing.MeshMetricField(
        _mesh_scope(mesh, 0, vertex_ids),
        np.broadcast_to(matrix, (points.shape[0], 2, 2)),
        minimum_size=1.0 / (3.0 * cells_per_axis),
        maximum_size=1.0 / cells_per_axis,
        maximum_anisotropy=2.0,
    )
    gradient = np.asarray((1.0, 2.0))
    cell_order = np.argsort(cell_ids)
    density = 1.0 + np.where(centroids[:, 0] < 0.5, 0.0, 4.0) + centroids[:, 1] ** 2
    fields = (
        phx.meshing.OmegaHField(
            "potential",
            phx.meshing.OmegaHFieldTransfer.LINEAR,
            _mesh_scope(mesh, 0, vertex_ids),
            points @ gradient,
        ),
        phx.meshing.OmegaHField(
            "density",
            phx.meshing.OmegaHFieldTransfer.CONSERVE,
            _mesh_scope(mesh, 2, cell_ids[cell_order]),
            density[cell_order],
        ),
    )
    with phx.meshing.OmegaHProvider(executable) as provider:
        result, adapt_stage = _measured(
            lambda: provider.execute(
                source,
                metric,
                fields=fields,
                ranks=ranks,
                gather=True,
            )
        )

    target = result.target
    if target is None:
        raise RuntimeError(
            "Gathered Omega_h qualification did not publish its target mesh."
        )
    target_ids, target_areas, _ = _distribution_cells(target.mesh)

    potential, transferred = result.fields
    target_points = np.asarray(target.mesh.coordinates)[
        np.argsort(np.asarray(target.mesh.vertex_global_ids))
    ]
    linear_error = float(
        np.max(np.abs(np.asarray(potential.values) - target_points @ gradient))
    )
    rows = _distribution_rows(np.asarray(transferred.scope.entity_ids), target_ids)
    mass_before = float(np.sum(density * areas))
    mass_after = float(np.sum(np.asarray(transferred.values)[rows] * target_areas))
    mass_residual = abs(mass_after - mass_before) / abs(mass_before)

    conserve = result.evidence.fields[1]
    reported_before = float(np.sum(np.asarray(conserve.integral_before)))
    reported_after = float(np.sum(np.asarray(conserve.integral_after)))
    left = next(zone for zone in target.zones if zone.name == "left")
    left_area = float(
        np.sum(target_areas[np.isin(target_ids, np.asarray(left.scope.entity_ids))])
    )
    partitions = [
        {
            "rank": partition.rank,
            "partition_id": partition.partition_id,
            "owned_cells": int(np.count_nonzero(np.asarray(partition.cell_owned))),
            "ghost_cells": int(np.count_nonzero(np.asarray(partition.cell_ghosts))),
            "owned_vertices": int(np.count_nonzero(np.asarray(partition.vertex_owned))),
            "ghost_vertices": int(np.count_nonzero(np.asarray(partition.vertex_ghosts))),
        }
        for partition in result.partitions
    ]
    owned = [
        int(np.count_nonzero(np.asarray(partition.cell_owned)))
        for partition in result.partitions
    ]
    target_metric = result.metric
    if target_metric is None:
        raise RuntimeError(
            "Omega_h metric adaptation omitted its gathered target metric."
        )
    checks = {
        "audit": target.audit.passed,
        "positive_cells": bool(np.all(target_areas > 0.0)),
        "domain_area": bool(np.isclose(np.sum(target_areas), 1.0, rtol=0.0, atol=1e-12)),
        "refined": target_ids.size > cell_ids.size,
        "lineage_unknown": result.lineage_status == "unknown",
        "zone_area": bool(np.isclose(left_area, 0.5, rtol=0.0, atol=1e-12)),
        "linear_reproduction": linear_error <= 1e-12,
        "conservation": mass_residual <= 1e-12,
        "reported_conservation": np.isclose(
            reported_after, reported_before, rtol=1e-12, atol=0.0
        ),
        "ownership": sum(owned) == target_ids.size and min(owned) > 0,
        "ghosts": ranks == 1
        or all(
            np.count_nonzero(np.asarray(partition.cell_ghosts)) > 0
            for partition in result.partitions
        ),
        "ranks": result.evidence.ranks == ranks and len(partitions) == ranks,
        "distribution": (result.distribution is None) == (ranks == 1),
        "metric": bool(np.all(np.linalg.eigvalsh(np.asarray(target_metric.values)) > 0)),
    }
    failed = sorted(name for name, passed in checks.items() if not passed)
    if failed:
        raise RuntimeError(f"Omega_h qualification failed checks: {failed}.")
    record = {
        "status": "passed",
        "source": _result_identity(source),
        "target": {
            **_result_identity(target),
            "omega_h_result_id": result.result_id,
            "lineage_status": result.lineage_status,
        },
        "runtime": {
            **_runtime_identity(),
            "provider_version": result.provider.version,
            "actual_version": result.runtime.actual_version,
            "worker_executable": executable,
            "worker_identity": result.evidence.identity_id,
            "worker_session": result.evidence.session_id,
            "ranks": result.evidence.ranks,
        },
        "quality": {
            "before": _quality_summary(source.quality),
            "after": _quality_summary(target.quality),
            "omega_h_metric_quality": [
                result.evidence.minimum_quality,
                result.evidence.maximum_quality,
            ],
            "omega_h_metric_length": [
                result.evidence.minimum_length,
                result.evidence.maximum_length,
            ],
            "iterations": result.evidence.iterations,
        },
        "transfer": {
            "methods": {value.name: value.method for value in result.evidence.fields},
            "linear_reproduction_error": linear_error,
        },
        "conservation": {
            "integral_before": mass_before,
            "integral_after": mass_after,
            "relative_residual": mass_residual,
            "omega_h_integral_before": reported_before,
            "omega_h_integral_after": reported_after,
        },
        "classification": {"left_zone_area": left_area, "zones": len(target.zones)},
        "partitions": partitions,
        "checks_passed": sorted(checks),
        "resources": {
            "certification": certify_stage,
            "adaptation": adapt_stage,
            "worker_peak_rss_bytes": result.evidence.peak_rss_bytes,
            "target_retained_bytes": _distribution_retained_bytes(target),
        },
    }

    if result.distribution is not None:
        distribution = result.distribution.evidence
        record["distribution"] = {
            "distribution_id": result.distribution.distribution_id,
            "provenance": distribution.provenance,
            "part_weights": np.asarray(distribution.part_weights).tolist(),
            "imbalance": float(distribution.imbalance),
            "edge_cut": int(distribution.edge_cut),
            "halo_replicas": int(distribution.halo_replicas),
        }
    return record


def qualify_omega_h(worker: str | None) -> dict[str, object]:
    return _qualify_omega_h_ranks(worker, 1)


def qualify_omega_h_distributed(worker: str | None) -> dict[str, object]:
    return _qualify_omega_h_ranks(worker, 2)


def _metric_lattice(
    count: int, lower: float, upper: float, /
) -> tuple[np.ndarray, np.ndarray]:
    """Vertices and counterclockwise triangles of a ``count x count`` square lattice."""
    axis = np.linspace(lower, upper, count + 1)
    points = np.stack(np.meshgrid(axis, axis, indexing="ij"), axis=-1).reshape((-1, 2))
    index = np.arange((count + 1) ** 2, dtype=np.int32).reshape((count + 1, count + 1))
    first, second = index[:-1, :-1].ravel(), index[1:, :-1].ravel()
    third, fourth = index[1:, 1:].ravel(), index[:-1, 1:].ravel()
    triangles = np.concatenate(
        (
            np.stack((first, second, third), axis=1),
            np.stack((first, third, fourth), axis=1),
        )
    )
    return points, triangles


def _layer_metric_tensors(points: np.ndarray, /) -> np.ndarray:
    """Diagonal internal-layer metric: size 0.04 across x = 1/2 growing to 0.3.

    Every other ambient axis (along the layer, and the normal of an embedded
    planar face) requests size 0.25.
    """
    sizes = np.full(points.shape, 0.25, dtype=np.float64)
    sizes[:, 0] = 0.04 + 0.52 * np.abs(points[:, 0] - 0.5)
    return np.eye(points.shape[1], dtype=np.float64) * sizes[:, None, :] ** -2


def _vertex_scope_rows(mesh: phx.discretization.CellMesh, /) -> np.ndarray:
    """Vertex rows in the sorted global-ID row order of a vertex scope."""
    return np.argsort(np.asarray(mesh.vertex_global_ids), kind="stable")


def _layer_metric(mesh: phx.discretization.CellMesh, /) -> phx.meshing.MeshMetricField:
    rows = _vertex_scope_rows(mesh)
    return phx.meshing.MeshMetricField(
        _mesh_scope(mesh, 0, np.asarray(mesh.vertex_global_ids, dtype=np.int64)),
        _layer_metric_tensors(np.asarray(mesh.coordinates, dtype=np.float64)[rows]),
        minimum_size=0.04,
        maximum_size=0.31,
        maximum_anisotropy=6.5,
    )


def _triangle_areas(points: np.ndarray, cells: np.ndarray, /) -> np.ndarray:
    spatial = np.pad(points, ((0, 0), (0, 3 - points.shape[1])))
    first = spatial[cells[:, 1]] - spatial[cells[:, 0]]
    second = spatial[cells[:, 2]] - spatial[cells[:, 0]]
    return 0.5 * np.linalg.norm(np.cross(first, second), axis=1)


def _mesh_triangles(mesh: phx.discretization.CellMesh, /) -> np.ndarray:
    return np.concatenate([np.asarray(block.vertices) for block in mesh.blocks])


def _vertex_dual_areas(mesh: phx.discretization.CellMesh, /) -> np.ndarray:
    """Barycentric dual areas: exact P1 integration weights of the vertex rows."""
    points = np.asarray(mesh.coordinates, dtype=np.float64)
    cells = _mesh_triangles(mesh)
    areas = np.zeros((points.shape[0],), dtype=np.float64)
    shares = np.repeat(_triangle_areas(points, cells)[:, None] / 3.0, 3, axis=1)
    np.add.at(areas, cells, shares)
    return areas


def _metric_unit_measurements(
    mesh: phx.discretization.CellMesh, metric: phx.meshing.MeshMetricField, /
) -> dict[str, object]:
    """Riemannian edge lengths and metric mean-ratio quality of a planar mesh."""
    rows = _vertex_scope_rows(mesh)
    inverse = np.empty_like(rows)
    inverse[rows] = np.arange(rows.shape[0])
    points = np.asarray(mesh.coordinates, dtype=np.float64)[rows]
    values = np.asarray(metric.values, dtype=np.float64)
    connectivity = mesh.connectivity
    if not isinstance(connectivity, phx.discretization.PolygonalConnectivity):
        raise TypeError("Planar metric qualification requires polygonal connectivity.")
    lengths = np.asarray(
        phx.meshing.metric_edge_lengths(
            values, points, inverse[np.asarray(connectivity.edges)]
        )
    )
    cells = inverse[_mesh_triangles(mesh)]
    cell_metric = np.asarray(
        phx.meshing.interpolate_mesh_metric(
            values[cells], np.full(cells.shape, 1.0 / 3.0, dtype=np.float64)
        )
    )
    corners = points[cells]
    sides = corners[:, (1, 2, 0)] - corners
    stretched = (cell_metric[:, None] @ sides[..., None])[..., 0]
    squared = np.sum(sides * stretched, axis=(1, 2))
    determinant = cell_metric[:, 0, 0] * cell_metric[:, 1, 1] - cell_metric[:, 0, 1] ** 2
    areas = _triangle_areas(points, cells)
    quality = 4.0 * np.sqrt(3.0) * areas * np.sqrt(determinant) / squared
    unit = (lengths >= 1.0 / np.sqrt(2.0)) & (lengths <= np.sqrt(2.0))
    return {
        "edges": lengths.shape[0],
        "minimum_length": float(np.min(lengths)),
        "mean_length": float(np.mean(lengths)),
        "maximum_length": float(np.max(lengths)),
        "unit_fraction": float(np.mean(unit)),
        "minimum_metric_quality": float(np.min(quality)),
        "mean_metric_quality": float(np.mean(quality)),
    }


def _linear_probe(points: np.ndarray, /) -> np.ndarray:
    return 2.0 + 3.0 * points[:, 0] - 1.5 * points[:, 1]


def _adaptation_transfer_evidence(
    adaptation: phx.meshing.MeshAdaptationResult, /
) -> dict[str, object]:
    """Measured constant/linear reproduction and P1 integrals of the P1 transfer."""
    transfer = adaptation.transfer
    if transfer is None:
        raise RuntimeError(f"The {adaptation.route.value} adaptation has no transfer.")
    source = adaptation.source.mesh
    target = adaptation.target.mesh
    source_points = np.asarray(source.coordinates, dtype=np.float64)
    target_points = np.asarray(target.coordinates, dtype=np.float64)
    source_values = _linear_probe(source_points)
    transferred = np.asarray(transfer.apply(jnp.asarray(source_values)))
    constant = np.asarray(
        transfer.apply(jnp.ones((source_points.shape[0],), dtype=jnp.float64))
    )
    source_area = _vertex_dual_areas(source)
    target_area = _vertex_dual_areas(target)
    return {
        "transfer_id": transfer.transfer_id,
        "preserves_constants": transfer.preserves_constants,
        "preserves_linear": transfer.preserves_linear,
        "conservative": transfer.conservative,
        "positivity_preserving": transfer.positivity_preserving,
        "constant_error": float(np.max(np.abs(constant - 1.0))),
        "linear_error": float(np.max(np.abs(transferred - _linear_probe(target_points)))),
        "area_residual": abs(float(np.sum(target_area) - np.sum(source_area))),
        "linear_integral_residual": abs(
            float(np.dot(target_area, transferred) - np.dot(source_area, source_values))
        ),
    }


def _metric_operation_evidence(
    evidence: phx.meshing.LocalMetricEvidence | phx.meshing.DeviceMetricEvidence, /
) -> dict[str, object]:
    """Fields shared by `LocalMetricEvidence` and `DeviceMetricEvidence`."""
    return {
        "evidence_id": evidence.evidence_id,
        "passes": evidence.passes,
        "splits": evidence.splits,
        "collapses": evidence.collapses,
        "flips": evidence.flips,
        "relocations": evidence.relocations,
        "rejected_uncertain": evidence.rejected_uncertain,
        "rejected_invalid": evidence.rejected_invalid,
        "converged": evidence.converged,
        "stalled": evidence.stalled,
        "measured_edges": evidence.measured_edges,
        "out_of_range_edges": evidence.out_of_range_edges,
        "minimum_metric_length": evidence.minimum_metric_length,
        "maximum_metric_length": evidence.maximum_metric_length,
        "unit_fraction": evidence.unit_fraction,
        "minimum_metric_quality": evidence.minimum_metric_quality,
    }


def qualify_metric_adaptation() -> dict[str, object]:
    points, triangles = _metric_lattice(6, 0.0, 1.0)
    source, certify_record = _measured(
        lambda: phx.meshing.certify_cell_mesh(
            phx.discretization.CellMesh.from_triangles(points, triangles), _contract()
        )
    )

    metric = _layer_metric(source.mesh)
    request = phx.meshing.MetricMeshAdaptation(metric)
    native_policy = phx.meshing.MeshAdaptationPolicy(
        phx.meshing.MeshAdaptationRoute.NATIVE_METRIC_2D
    )
    native, native_record = _measured(
        lambda: phx.meshing.execute_mesh_adaptation(
            phx.meshing.prepare_mesh_adaptation(source, request, policy=native_policy)
        )
    )
    device_policy = phx.meshing.MeshAdaptationPolicy(
        phx.meshing.MeshAdaptationRoute.DEVICE_METRIC_2D,
        device_policy=phx.discretization.AdaptiveSimplexPolicy(
            vertex_capacity=256, cell_capacity=512
        ),
    )
    prepared, prepare_record = _measured(
        lambda: phx.meshing.prepare_device_metric_adaptation(
            source,
            request,
            policy=device_policy,
        )
    )
    update, adapt_record = _measured(
        lambda: jax.block_until_ready(
            phx.meshing.adapt_device_metric(prepared.layout, prepared.state)
        )
    )

    report = jax.device_get(update.report)
    device, commit_record = _measured(
        lambda: phx.meshing.commit_device_metric_adaptation(prepared, update.state)
    )
    relocation, relocation_record = _measured(
        lambda: phx.meshing.execute_mesh_adaptation(
            phx.meshing.prepare_mesh_adaptation(
                source,
                phx.meshing.RelocationMeshAdaptation(metric),
                policy=native_policy,
            )
        )
    )
    native_evidence, device_evidence = native.evidence, device.evidence
    relocation_evidence = relocation.evidence
    if not isinstance(native_evidence, phx.meshing.LocalMetricEvidence):
        raise RuntimeError(
            "Native metric qualification requires local metric operation evidence."
        )
    if not isinstance(device_evidence, phx.meshing.DeviceMetricEvidence):
        raise RuntimeError(
            "Device metric qualification requires device metric operation evidence."
        )
    if not isinstance(relocation_evidence, phx.meshing.LocalMetricEvidence):
        raise RuntimeError(
            "Native relocation qualification requires local metric operation evidence."
        )
    route_evidence = {"native": native_evidence, "device": device_evidence}
    adapted = {"native": native, "device": device}

    if any(result.metric is None for result in (*adapted.values(), relocation)):
        raise RuntimeError("A metric adaptation did not bind its metric to the target.")

    before = _metric_unit_measurements(source.mesh, metric)
    after = {}
    target_metrics = {}
    for name, result in adapted.items():
        target_metric = result.metric
        if target_metric is None:
            raise RuntimeError(
                "A metric adaptation did not bind its metric to the target."
            )
        target_metrics[name] = target_metric
        after[name] = _metric_unit_measurements(result.target.mesh, target_metric)
    relocation_metric = relocation.metric
    if relocation_metric is None:
        raise RuntimeError("A metric adaptation did not bind its metric to the target.")
    target_metrics["relocation"] = relocation_metric
    relocated = _metric_unit_measurements(relocation.target.mesh, relocation_metric)
    transfer = {
        name: _adaptation_transfer_evidence(result) for name, result in adapted.items()
    }
    relocation_transfer = _adaptation_transfer_evidence(relocation)
    checks = {
        "native target audited": native.target.audit.passed,
        "device target audited": device.target.audit.passed,
        "relocation target audited": relocation.target.audit.passed,
        "device passes did not fail": not bool(report.failed),
        "relocation kept the topology": (
            relocation.target.mesh.topology_id == source.mesh.topology_id
            and relocation_evidence.relocations > 0
            and relocation_evidence.splits == relocation_evidence.collapses == 0
        ),
    }
    for name, result in adapted.items():
        checks[f"{name} moved toward the unit mesh"] = (
            _record_float(after[name]["unit_fraction"], "Adapted metric unit fraction")
            > _record_float(before["unit_fraction"], "Source metric unit fraction")
            and route_evidence[name].unit_fraction >= 0.9
        )
        checks[f"{name} transfer reproduces linear fields"] = (
            transfer[name]["preserves_linear"]
            and _record_float(transfer[name]["linear_error"], "Linear transfer error")
            <= 1.0e-12
            and _record_float(transfer[name]["constant_error"], "Constant transfer error")
            <= 1.0e-12
        )
        checks[f"{name} target covers the source area"] = (
            _record_float(transfer[name]["area_residual"], "Transfer area residual")
            <= 1.0e-12
        )
    failed = [name for name, passed in checks.items() if not passed]
    if failed:
        raise RuntimeError(f"Metric adaptation qualification failed: {failed}.")
    return {
        "status": "passed",
        "checks": sorted(checks),
        "source": {**_result_identity(source), "metric_id": metric.metric_id},
        "target": {
            name: {
                **_result_identity(result.target),
                "metric_id": target_metrics[name].metric_id,
            }
            for name, result in (*adapted.items(), ("relocation", relocation))
        },
        "runtime": {
            **_runtime_identity(),
            "native_predicate_mode": native_evidence.predicate_mode.value,
            "device_layout_id": prepared.layout.signature_id,
        },
        "quality": {
            "before": {**_quality_summary(source.quality), "metric": before},
            "after": {
                name: {**_quality_summary(result.target.quality), "metric": after[name]}
                for name, result in adapted.items()
            },
            "relocation": {
                **_quality_summary(relocation.target.quality),
                "metric": relocated,
            },
        },
        "transfer": {**transfer, "relocation": relocation_transfer},
        "conservation": {
            name: {
                "area_residual": record["area_residual"],
                "linear_integral_residual": record["linear_integral_residual"],
            }
            for name, record in (*transfer.items(), ("relocation", relocation_transfer))
        },
        "routes": {
            "native": {
                "adaptation_status": native.status.value,
                "evidence": _metric_operation_evidence(native_evidence),
            },
            "device": {
                "adaptation_status": device.status.value,
                "evidence": {
                    **_metric_operation_evidence(device_evidence),
                    "rejected_cavity": device_evidence.rejected_cavity,
                    "status_flags": int(device_evidence.status),
                    "status_names": device_evidence.status.name,
                },
                "report": {
                    "status_flags": int(report.status),
                    "passes": int(report.passes),
                    "unit_fraction": float(report.unit_fraction),
                },
            },
            "relocation": {
                "adaptation_status": relocation.status.value,
                "evidence": _metric_operation_evidence(relocation_evidence),
            },
        },
        "resources": {
            "certify": certify_record,
            "native_adaptation": native_record,
            "device_prepare": prepare_record,
            "device_adapt_cold": adapt_record,
            "device_commit": commit_record,
            "relocation": relocation_record,
            "device_capacity": {
                "vertices": prepared.layout.vertex_capacity,
                "cells": prepared.layout.cell_capacity,
            },
            "device_state_bytes": sum(
                leaf.nbytes for leaf in jax.tree.leaves(prepared.state)
            ),
        },
    }


def _gmsh_metric_run(
    square: Any, control: phx.meshing.BackgroundMetricControl, options: Any, /
) -> tuple[phx.meshing.CellMeshingResult, dict[str, object]]:
    provider = phx.meshing.GmshProvider(options)
    scope = provider.whole_scope(square, 2)
    specification = phx.meshing.SurfaceMeshingSpec(
        phx.meshing.CellMeshingTarget(
            2, 3, phx.meshing.CellFamilyPolicy(required=("triangle",))
        ),
        scope,
        size_controls=(phx.meshing.UniformSizeControl(scope, 0.5),),
        background_metric=control,
    )
    plan, plan_record = _measured(lambda: provider.plan(square, specification))

    result, execute_record = _measured(plan.execute)

    if not result.audit.passed or not result.compliance.passed:
        raise RuntimeError(f"Gmsh {control.mode.value} metric mesh failed its audit.")
    prefix = f"background_metric:{control.control_id}:"
    compliance = {
        key.removeprefix(prefix): value
        for key, value in result.compliance.achieved
        if key.startswith(prefix)
    }
    if sorted(compliance) != [
        "maximum_edge_length",
        "mean_edge_length",
        "minimum_edge_length",
        "unit_edge_fraction",
    ]:
        raise RuntimeError("Gmsh compliance lacks the background metric edge lengths.")

    points = np.asarray(result.mesh.coordinates, dtype=np.float64)

    connectivity = result.mesh.connectivity
    if not isinstance(connectivity, phx.discretization.PolygonalConnectivity):
        raise TypeError(
            "The Gmsh surface metric qualifier requires triangle connectivity."
        )
    edges = np.asarray(connectivity.edges)
    vectors = points[edges[:, 1]] - points[edges[:, 0]]
    midpoints = 0.5 * (points[edges[:, 0]] + points[edges[:, 1]])
    diagonal = np.diagonal(_layer_metric_tensors(midpoints), axis1=1, axis2=2)
    analytic = np.sqrt(np.sum(vectors**2 * diagonal, axis=1))

    area = float(np.sum(_triangle_areas(points, _mesh_triangles(result.mesh))))
    extent = np.mean(np.abs(vectors), axis=0)
    return result, {
        "mode": control.mode.value,
        "control_id": control.control_id,
        "plan_id": plan.plan_id,
        "algorithm_2d": options.algorithm_2d.value,
        "compliance_metric_edge_lengths": compliance,
        "analytic_metric_edge_lengths": {
            "minimum": float(np.min(analytic)),
            "mean": float(np.mean(analytic)),
            "maximum": float(np.max(analytic)),
            "unit_fraction": float(
                np.mean((analytic >= 1.0 / np.sqrt(2.0)) & (analytic <= np.sqrt(2.0)))
            ),
        },
        "mean_edge_extent_y_over_x": float(extent[1] / extent[0]),
        "area": area,
        "resources": {"plan": plan_record, "execute": execute_record},
    }


def qualify_gmsh_metric() -> dict[str, object]:
    from importlib.util import find_spec

    if find_spec("gmsh") is None:
        return _missing_dependency(
            "gmsh",
            "Install the optional Gmsh Python package: "
            "pip install 'phydrax[meshing-gmsh]'.",
        )
    from OCP.BRepBuilderAPI import BRepBuilderAPI_MakeFace, BRepBuilderAPI_MakePolygon
    from OCP.gp import gp_Pnt

    contract = _contract()
    grid, triangles = _metric_lattice(8, -0.01, 1.01)
    background = phx.discretization.CellMesh(
        np.concatenate((grid, np.zeros((grid.shape[0], 1), dtype=np.float64)), axis=1),
        (phx.discretization.CellBlock("triangles", "triangle", triangles),),
    )
    metric = _layer_metric(background)
    certified_background, background_record = _measured(
        lambda: phx.meshing.certify_cell_mesh(background, contract)
    )
    controls = {
        mode: phx.meshing.BackgroundMetricControl(
            background, metric, contract, mode=mode, maximum_metric_edge_length=2.0
        )
        for mode in phx.meshing.BackgroundMetricMode
    }
    polygon = BRepBuilderAPI_MakePolygon()
    for x, y in ((0.0, 0.0), (1.0, 0.0), (1.0, 1.0), (0.0, 1.0)):
        polygon.Add(gp_Pnt(x, y, 0.0))
    polygon.Close()
    face = BRepBuilderAPI_MakeFace(polygon.Wire()).Face()
    with TemporaryDirectory(prefix="phydrax-gmsh-metric-") as temporary:
        square = phx.interchange.persist_occt_shape(
            face,
            Path(temporary) / "square.brep",
            coordinate_contract=contract,
            linear_deflection=0.01,
            angular_deflection=0.2,
        )
        isotropic, isotropic_record = _gmsh_metric_run(
            square,
            controls[phx.meshing.BackgroundMetricMode.ISOTROPIC],
            phx.meshing.GmshOptions(),
        )
        anisotropic, anisotropic_record = _gmsh_metric_run(
            square,
            controls[phx.meshing.BackgroundMetricMode.ANISOTROPIC],
            phx.meshing.GmshOptions(algorithm_2d=phx.meshing.GmshSurfaceAlgorithm.BAMG),
        )
    results = {"isotropic": isotropic, "anisotropic": anisotropic}
    records = {"isotropic": isotropic_record, "anisotropic": anisotropic_record}
    edge_record = _record_mapping(
        anisotropic_record["compliance_metric_edge_lengths"], "Gmsh metric edge lengths"
    )
    unit = _record_float(edge_record["unit_edge_fraction"], "Gmsh unit edge fraction")
    checks = {
        "background certified": certified_background.audit.passed,
        "isotropic mode refines every direction": (
            isotropic.mesh.entity_set(2).count > anisotropic.mesh.entity_set(2).count
        ),
        "anisotropic cells stretch along the layer": (
            _record_float(
                anisotropic_record["mean_edge_extent_y_over_x"],
                "Gmsh anisotropic edge extent",
            )
            > 1.5
        ),
        "anisotropic mesh is near unit": unit >= 0.8,
    }
    for name, record in records.items():
        checks[f"{name} mesh covers the face"] = (
            abs(_record_float(record["area"], "Gmsh area") - 1.0) <= 1.0e-12
        )
    failed = [name for name, passed in checks.items() if not passed]
    if failed:
        raise RuntimeError(f"Gmsh metric qualification failed: {failed}.")
    return {
        "status": "passed",
        "checks": sorted(checks),
        "source": {
            "brep_source_revision": square.source_revision,
            "background": _result_identity(certified_background),
            "metric_id": metric.metric_id,
        },
        "target": {name: _result_identity(result) for name, result in results.items()},
        "runtime": {
            **_runtime_identity(),
            "provider": anisotropic.provider.name,
            "provider_version": anisotropic.runtime.actual_version,
        },
        "quality": {
            "before": _quality_summary(certified_background.quality),
            "after": {
                name: _quality_summary(result.quality) for name, result in results.items()
            },
        },
        "conservation": {
            name: {
                "area": record["area"],
                "area_residual": abs(_record_float(record["area"], "Gmsh area") - 1.0),
            }
            for name, record in records.items()
        },
        "routes": {
            name: {key: value for key, value in record.items() if key != "resources"}
            for name, record in records.items()
        },
        "resources": {
            "background_certify": background_record,
            **{name: record["resources"] for name, record in records.items()},
        },
    }


def _layer_wall_mesh(points: np.ndarray, triangles: np.ndarray, /) -> Any:
    return phx.discretization.CellMesh(
        np.asarray(points, dtype=np.float64),
        (
            phx.discretization.CellBlock(
                "wall",
                "triangle",
                np.asarray(triangles, dtype=np.int64),
                global_ids=np.arange(triangles.shape[0], dtype=np.int64),
            ),
        ),
    )


def _layer_box_wall(half_width: float, count: int, /) -> Any:
    """Outward-oriented structured triangulation of a centered box surface."""
    grid = np.linspace(-half_width, half_width, count + 1)
    u, v = (value.ravel() for value in np.meshgrid(grid, grid, indexing="ij"))
    lower = (np.arange(count)[:, None] * (count + 1) + np.arange(count)).ravel()
    quads = np.stack((lower, lower + count + 1, lower + count + 2, lower + 1), axis=1)
    local = np.concatenate((quads[:, (0, 1, 2)], quads[:, (0, 2, 3)]))
    points = []
    triangles = []
    for axis in range(3):
        tangent = [value for value in range(3) if value != axis]
        for bound in (-half_width, half_width):
            face = np.empty((u.size, 3), dtype=np.float64)
            face[:, axis] = bound
            face[:, tangent[0]] = u
            face[:, tangent[1]] = v
            triangles.append(local + len(points) * u.size)
            points.append(face)
    coordinates, inverse = np.unique(
        np.round(np.concatenate(points), 12), axis=0, return_inverse=True
    )
    triangles = inverse.reshape(-1)[np.concatenate(triangles)]
    corners = coordinates[triangles]
    normals = np.cross(corners[:, 1] - corners[:, 0], corners[:, 2] - corners[:, 0])
    inward = np.sum(normals * corners.mean(axis=1), axis=1) < 0.0
    triangles[inward] = triangles[inward][:, ::-1]
    return _layer_wall_mesh(coordinates, triangles)


def _layer_plate(count: int, height: float, /, *, flip: bool) -> Any:
    """Unit-square plate at ``height`` growing along +z (or -z when flipped)."""
    grid = np.linspace(0.0, 1.0, count + 1)
    x, y = (value.ravel() for value in np.meshgrid(grid, grid, indexing="ij"))
    points = np.stack((x, y, np.full(x.size, height)), axis=1)
    lower = (np.arange(count)[:, None] * (count + 1) + np.arange(count)).ravel()
    quads = np.stack((lower, lower + count + 1, lower + count + 2, lower + 1), axis=1)
    triangles = np.concatenate((quads[:, (0, 1, 2)], quads[:, (0, 2, 3)]))
    return points, triangles[:, ::-1] if flip else triangles


def _advancing_layer_control(wall: Any, schedule: Any, /, **options: Any) -> Any:
    cells = wall.entity_set(2)
    return phx.meshing.BoundaryLayerControl(
        phx.meshing.MeshingScope(
            wall.mesh_id,
            wall.numeric_version,
            phx.meshing.MeshingEntityKind.MESH,
            2,
            cells.entity_set_id,
            cells.entity_ids,
        ),
        schedule,
        route=phx.meshing.BoundaryLayerRoute.ADVANCING,
        **options,
    )


def _layer_enclosed_volume(points: np.ndarray, triangles: np.ndarray, /) -> float:
    """Divergence-theorem volume enclosed by outward-oriented triangles."""
    corners = points[triangles]
    return float(np.sum(corners[:, 0] * np.cross(corners[:, 1], corners[:, 2])) / 6.0)


def _layer_block_rows(mesh: Any, /) -> np.ndarray:
    return np.concatenate(
        [np.asarray(block.vertices, dtype=np.int64) for block in mesh.blocks]
    )


def _layer_retained_bytes(tree: Any, /) -> int:
    leaves = {
        id(leaf): leaf for leaf in jax.tree.leaves(tree) if isinstance(leaf, jax.Array)
    }
    return sum(leaf.nbytes for leaf in leaves.values())


def _layer_entity_rows(identifiers: Any, requested: Any, /) -> np.ndarray:
    """Rows of the unique ``identifiers`` holding every ``requested`` ID."""
    values = np.asarray(identifiers, dtype=np.int64)
    wanted = np.asarray(requested, dtype=np.int64)
    order = np.argsort(values, kind="stable")
    rows = order[np.searchsorted(values[order], wanted).clip(0, values.size - 1)]
    if not np.array_equal(values[rows], wanted):
        raise RuntimeError("Requested entity IDs are absent from the mesh.")
    return rows


def _layer_evidence(evidence: Any, /) -> dict[str, object]:
    return {
        "evidence_id": evidence.evidence_id,
        "requested_thicknesses": list(evidence.requested_thicknesses),
        "measured_thicknesses": np.asarray(evidence.achieved_thicknesses).tolist(),
        "minimum_thicknesses": np.asarray(evidence.minimum_thicknesses).tolist(),
        "maximum_thicknesses": np.asarray(evidence.maximum_thicknesses).tolist(),
        "measured_growth_rates": np.asarray(evidence.achieved_growth_rates).tolist(),
        "layer_active": np.asarray(evidence.layer_active).tolist(),
        "columns": evidence.column_count,
        "fan_columns": evidence.fan_column_count,
        "corner_patches": evidence.corner_patch_count,
        "convex_ridges": evidence.convex_ridge_count,
        "concave_ridges": evidence.concave_ridge_count,
        "rim_vertices": evidence.rim_vertex_count,
        "minimum_visibility": evidence.minimum_visibility,
        "maximum_stretch": evidence.maximum_stretch,
        "unconverged_visibility": evidence.unconverged_visibility_count,
        "collision_policy": evidence.collision_policy.value,
        "predicted_collision_vertices": evidence.predicted_collision_vertex_count,
        "detected_collisions": evidence.detected_collision_count,
        "resolution_iterations": evidence.resolution_iterations,
        "reduced_vertices": evidence.reduced_vertex_count,
        "terminated_vertices": evidence.terminated_vertex_count,
        "merged_vertices": evidence.merged_vertex_count,
        "minimum_scale": evidence.minimum_scale,
        "cell_counts": dict(evidence.cell_counts),
        "certified_valid_cells": evidence.certified_valid_count,
    }


def _layer_certificate_counts(certificate: Any, /) -> dict[str, object]:
    return {
        "certificate_id": certificate.certificate_id,
        "cells": certificate.status.shape[0],
        "certified_valid": certificate.certified_valid_count,
        "invalid": certificate.invalid_count,
        "unresolved": certificate.unresolved_count,
    }


def _layer_quality(mesh: Any, /) -> Any:
    return phx.meshing.summarize_cell_quality(phx.meshing.evaluate_cell_quality(mesh))


def qualify_boundary_layer() -> dict[str, object]:
    if not meshcore_available():
        return _missing_dependency(
            "meshcore",
            "Exact layer certification requires the native meshcore library; build "
            "it and set PHYDRAX_MESHCORE_LIBRARY to the shared library path.",
        )
    schedule = phx.meshing.LayerSchedule.geometric(3, 0.01, growth_rate=1.2)
    wall = _layer_box_wall(0.3, 2)
    control = _advancing_layer_control(
        wall,
        schedule,
        collision=phx.meshing.BoundaryLayerCollisionPolicy.FAIL,
        corner=phx.meshing.BoundaryLayerCornerPolicy.FAN,
    )
    layers, prepare = _measured(
        lambda: phx.meshing.prepare_boundary_layers(wall, control)
    )
    before, wall_quality = _measured(lambda: _layer_quality(wall))

    after, layer_quality = _measured(lambda: _layer_quality(layers.mesh))
    certificate, certification = _measured(
        lambda: phx.discretization.certify_cell_geometry_validity(layers.mesh)
    )

    cap = layers.cap
    if cap is None:
        raise RuntimeError(
            "Closed boundary-layer qualification did not publish its cap mesh."
        )
    evidence = layers.evidence

    cells = sum(block.cell_count for block in layers.mesh.blocks)
    requested = np.asarray(schedule.thicknesses, dtype=np.float64)
    measured = np.stack(
        (
            np.asarray(evidence.achieved_thicknesses),
            np.asarray(evidence.minimum_thicknesses),
            np.asarray(evidence.maximum_thicknesses),
        )
    )
    thickness_error = float(np.max(np.abs(measured - requested) / requested))
    growth_error = float(np.max(np.abs(np.asarray(evidence.achieved_growth_rates) - 1.2)))

    layer_volume = float(np.sum(np.asarray(after.evaluation.measures)))
    enclosed = _layer_enclosed_volume(
        np.asarray(cap.coordinates),
        _layer_block_rows(cap),
    ) - _layer_enclosed_volume(np.asarray(wall.coordinates), _layer_block_rows(wall))
    volume_residual = abs(layer_volume - enclosed) / enclosed
    if (
        not layers.closed_cap
        or layers.validity.certified_valid_count != cells
        or certificate.certified_valid_count != cells
        or evidence.convex_ridge_count != 24
        or evidence.corner_patch_count != 8
        or evidence.detected_collision_count != 0
        or thickness_error > 1.0e-9
        or growth_error > 1.0e-9
        or after.sampled_invalid_count != 0
        or volume_residual > 1.0e-10
    ):
        raise RuntimeError(
            "Native layers missed the schedule, certification, or volume closure."
        )

    gap = 0.05
    lower, lower_triangles = _layer_plate(4, 0.0, flip=False)
    upper, upper_triangles = _layer_plate(4, gap, flip=True)
    channel = _layer_wall_mesh(
        np.concatenate((lower, upper)),
        np.concatenate((lower_triangles, upper_triangles + lower.shape[0])),
    )
    reduction = _advancing_layer_control(
        channel,
        schedule,
        collision=phx.meshing.BoundaryLayerCollisionPolicy.REDUCE_THICKNESS,
        corner=phx.meshing.BoundaryLayerCornerPolicy.FAN,
        minimum_thickness_fraction=0.2,
    )
    reduced, reduce = _measured(
        lambda: phx.meshing.prepare_boundary_layers(channel, reduction)
    )
    reduced_certificate, reduced_certification = _measured(
        lambda: phx.discretization.certify_cell_geometry_validity(reduced.mesh)
    )
    # The cap faces away from its layers: lower-front faces point along +z.

    reduced_cap = reduced.cap
    if reduced_cap is None:
        raise RuntimeError("Reduced boundary layers lost their actual cap.")
    cap_points = np.asarray(reduced_cap.coordinates)

    cap_corners = cap_points[_layer_block_rows(reduced_cap)]
    upward = (
        np.cross(
            cap_corners[:, 1] - cap_corners[:, 0], cap_corners[:, 2] - cap_corners[:, 0]
        )[:, 2]
        > 0.0
    )
    clearance = float(
        np.min(cap_corners[~upward][..., 2]) - np.max(cap_corners[upward][..., 2])
    )

    reduced_evidence = reduced.evidence

    reduced_cells = sum(block.cell_count for block in reduced.mesh.blocks)
    if (
        reduced_evidence.predicted_collision_vertex_count != 50
        or reduced_evidence.reduced_vertex_count != 50
        or not 0.2 <= reduced_evidence.minimum_scale < 1.0
        or clearance <= 0.0
        or np.max(np.abs(np.asarray(reduced_evidence.achieved_growth_rates) - 1.2))
        > 1.0e-9
        or reduced_certificate.certified_valid_count != reduced_cells
    ):
        raise RuntimeError("REDUCE_THICKNESS did not resolve the narrow-gap collision.")
    return {
        "status": "passed",
        "source": {
            "wall_mesh_id": wall.mesh_id,
            "topology_id": wall.topology_id,
            "vertices": wall.coordinates.shape[0],
            "cells": wall.blocks[0].cell_count,
            "control_id": control.control_id,
            "schedule_id": schedule.schedule_id,
        },
        "target": {
            "result_id": layers.result_id,
            "mesh_id": layers.mesh.mesh_id,
            "topology_id": layers.mesh.topology_id,
            "vertices": layers.mesh.coordinates.shape[0],
            "cells": cells,
            "cap_mesh_id": cap.mesh_id,
            "closed_cap": layers.closed_cap,
        },
        "runtime": _runtime_identity(),
        "quality": {
            "before": _quality_summary(before),
            "after": _quality_summary(after),
        },
        "conservation": {
            "layer_cell_volume": layer_volume,
            "cap_minus_wall_enclosed_volume": enclosed,
            "relative_volume_residual": volume_residual,
        },
        "certificates": {
            "layer_generation": _layer_certificate_counts(layers.validity),
            "independent": _layer_certificate_counts(certificate),
        },
        "boundary_layer": {
            **_layer_evidence(evidence),
            "maximum_relative_thickness_error": thickness_error,
            "maximum_growth_rate_error": growth_error,
        },
        "collision": {
            "gap": gap,
            "wall_faces": channel.blocks[0].cell_count,
            "result_id": reduced.result_id,
            "front_clearance": clearance,
            "certificate": _layer_certificate_counts(reduced_certificate),
            **_layer_evidence(reduced_evidence),
        },
        "resources": {
            "prepare_boundary_layers": prepare,
            "wall_quality": wall_quality,
            "layer_quality": layer_quality,
            "independent_certification": certification,
            "collision_prepare_boundary_layers": reduce,
            "collision_certification": reduced_certification,
            "retained_boundary_layer_bytes": _layer_retained_bytes(layers),
        },
    }


def _gmsh_layered_route(
    provider: Any, source: Any, route: Any, corner: Any, schedule: Any, tolerance: Any, /
) -> Any:
    """Plan, execute, and independently audit one layered Gmsh volume route."""
    points = np.asarray(source.mesh_vertices)
    face_ids = np.asarray(source.triangle_face_ids)
    inner = np.all(np.linalg.norm(points[np.asarray(source.mesh_faces)], axis=2) < 0.5, 1)
    wall_faces = tuple(source.face_ids[index] for index in np.unique(face_ids[inner]))
    whole = provider.whole_scope(source, 3)
    control = phx.meshing.BoundaryLayerControl(
        provider.entity_scope(source, wall_faces),
        schedule,
        route=route,
        volume_scope=whole,
        corner=corner,
    )
    specification = phx.meshing.VolumeMeshingSpec(
        phx.meshing.CellMeshingTarget(
            3,
            3,
            phx.meshing.CellFamilyPolicy(
                required=("prism", "tetrahedron"),
                allowed_transitions=("pyramid", "hexahedron"),
                allow_mixed=True,
            ),
        ),
        whole,
        phx.meshing.VolumeFillStrategy.SIMPLEX,
        size_controls=(
            phx.meshing.UniformSizeControl(whole, 0.25, maximum_growth_rate=10.0),
        ),
        layer_controls=(control,),
    )
    plan, planning = _measured(lambda: provider.plan(source, specification))

    result, execution = _measured(plan.execute)
    certificate, certification = _measured(
        lambda: phx.discretization.certify_cell_geometry_validity(result.mesh)
    )

    mesh = result.mesh
    connectivity = mesh.connectivity
    owners = np.asarray(connectivity.face_owner, dtype=np.int64)
    neighbors = np.asarray(connectivity.face_neighbor, dtype=np.int64)
    offsets = np.asarray(connectivity.face_vertex_offsets, dtype=np.int64)
    values = np.asarray(connectivity.face_vertex_values, dtype=np.int64)
    face_entities = mesh.entity_set(2).entity_ids
    patches = {
        patch.name: _layer_entity_rows(face_entities, patch.scope.entity_ids)
        for patch in result.patches
    }

    zones = {zone.name: zone.scope.entity_ids for zone in result.zones}
    if set(zones) != {"boundary-layer", "core"} or set(patches) != {
        "wall",
        "layer-core-interface",
        "outer",
    }:
        raise RuntimeError("Layered Gmsh result lost its zones or patches.")
    cell_entities = mesh.entity_set(3).entity_ids
    zone_of = np.full((cell_entities.shape[0],), -1, dtype=np.int8)
    zone_of[_layer_entity_rows(cell_entities, zones["boundary-layer"])] = 0
    zone_of[_layer_entity_rows(cell_entities, zones["core"])] = 1

    cell_face_offsets = np.asarray(connectivity.cell_face_offsets, dtype=np.int64)
    entry_cells = np.repeat(np.arange(zone_of.size), np.diff(cell_face_offsets))
    entry_faces = np.asarray(connectivity.cell_face_values, dtype=np.int64)
    entry_signs = np.asarray(connectivity.cell_face_sign_values, dtype=np.float64)

    def triangles(faces: Any, zones: Any) -> Any:
        """Triangles of ``faces`` oriented out of their incident cells in ``zones``."""
        selected = np.isin(entry_faces, faces) & np.isin(zone_of[entry_cells], zones)
        rows = entry_faces[selected]
        if rows.size != faces.size or np.any(offsets[rows + 1] - offsets[rows] != 3):
            raise RuntimeError("Layered Gmsh wall and interface faces must be triangles.")
        vertices = values[offsets[rows][:, None] + np.arange(3)]
        return np.where(entry_signs[selected][:, None] > 0.0, vertices, vertices[:, ::-1])

    interface = patches["layer-core-interface"]
    boundary = np.flatnonzero(neighbors < 0)
    conforming = (
        np.all(zone_of >= 0)
        and np.array_equal(
            np.sort(
                np.stack((zone_of[owners[interface]], zone_of[neighbors[interface]]), 1),
                1,
            ),
            np.tile((0, 1), (interface.size, 1)),
        )
        and np.array_equal(
            np.sort(np.concatenate((patches["wall"], patches["outer"]))), boundary
        )
    )
    coordinates = np.asarray(mesh.coordinates)

    evaluation = result.quality.evaluation
    measures = np.asarray(evaluation.measures)
    measure_rows = _layer_entity_rows(evaluation.cell_global_ids, cell_entities)
    cell_measures = measures[measure_rows]
    domain_volume = float(np.sum(cell_measures))
    boundary_volume = _layer_enclosed_volume(
        coordinates,
        triangles(np.concatenate((patches["wall"], patches["outer"])), (0, 1)),
    )
    wall_triangles = triangles(patches["wall"], (0,))
    layer_volume = float(np.sum(cell_measures[zone_of == 0]))
    layer_enclosed = _layer_enclosed_volume(
        coordinates, np.concatenate((wall_triangles, triangles(interface, (0,))))
    )
    domain_residual = abs(domain_volume - boundary_volume) / boundary_volume
    layer_residual = abs(layer_volume - layer_enclosed) / layer_enclosed
    wall_vertices, wall_inverse = np.unique(wall_triangles, return_inverse=True)
    before = _layer_quality(
        _layer_wall_mesh(coordinates[wall_vertices], wall_inverse.reshape((-1, 3)))
    )
    key = f"layer:{control.control_id}:"
    achieved = {
        name.removeprefix(key): value
        for name, value in result.compliance.achieved
        if name.startswith(key)
        or name in ("fixed_boundary_bitwise", "layer_interface_compliance")
    }
    requested_values = np.asarray(schedule.thicknesses, dtype=np.float64)
    thickness_error = float(
        np.max(
            np.abs(
                np.asarray(
                    [
                        achieved[f"thickness:{index}"]
                        for index in range(schedule.layer_count)
                    ]
                )
                - requested_values
            )
            / requested_values
        )
    )
    growth_error = float(
        np.max(
            np.abs(
                np.asarray(
                    [
                        achieved[f"growth:{index}"]
                        for index in range(1, schedule.layer_count)
                    ]
                )
                - np.asarray(schedule.growth_rates)
            )
        )
    )
    cells = sum(block.cell_count for block in mesh.blocks)
    if (
        not result.audit.passed
        or not result.compliance.passed
        or not all(association.complete for association in result.associations)
        or not conforming
        or achieved["fixed_boundary_bitwise"] != 1.0
        or achieved["layer_interface_compliance"] != 1.0
        or achieved["layer_count"] != schedule.layer_count
        or thickness_error > tolerance
        or growth_error > tolerance * schedule.growth_rates[0]
        or certificate.certified_valid_count != cells
        or result.quality.sampled_invalid_count != 0
        or domain_residual > 1.0e-10
        or layer_residual > 1.0e-10
    ):
        raise RuntimeError(f"Gmsh {route.value} layers failed audit or compliance.")
    return {
        "plan_id": plan.plan_id,
        "control_id": control.control_id,
        "target": _result_identity(result),
        "provider": {
            "version": result.runtime.actual_version,
            "runtime_id": result.runtime.runtime_id,
            "deterministic": result.runtime.deterministic,
        },
        "stages": {
            stage.stage.value: stage.status.value for stage in result.trace.stages
        },
        "cell_counts": {block.cell_kind: block.cell_count for block in mesh.blocks},
        "zone_cells": {name: ids.shape[0] for name, ids in zones.items()},
        "patch_faces": {name: rows.size for name, rows in patches.items()},
        "organization_conforming": bool(conforming),
        "compliance": {
            **achieved,
            "maximum_relative_thickness_error": thickness_error,
            "maximum_growth_rate_error": growth_error,
            "tolerance": tolerance,
        },
        "certificate": _layer_certificate_counts(certificate),
        "quality": {
            "before": _quality_summary(before),
            "after": _quality_summary(result.quality),
        },
        "conservation": {
            "domain_cell_volume": domain_volume,
            "domain_boundary_enclosed_volume": boundary_volume,
            "domain_relative_residual": domain_residual,
            "layer_cell_volume": layer_volume,
            "layer_boundary_enclosed_volume": layer_enclosed,
            "layer_relative_residual": layer_residual,
        },
        "resources": {
            "plan": planning,
            "execute": execution,
            "independent_certification": certification,
            "retained_mesh_bytes": _layer_retained_bytes(mesh),
        },
    }


def qualify_gmsh_boundary_layer() -> dict[str, object]:
    from importlib.util import find_spec

    if find_spec("gmsh") is None:
        return _missing_dependency(
            "gmsh",
            "Install the optional provider: pip install 'phydrax[meshing-gmsh]'.",
        )
    if find_spec("OCP") is None:
        return _missing_dependency(
            "OCP", "Install OpenCascade bindings (cadquery-ocp) for B-Rep persistence."
        )
    if not meshcore_available():
        return _missing_dependency(
            "meshcore",
            "Exact layer certification requires the native meshcore library; build "
            "it and set PHYDRAX_MESHCORE_LIBRARY to the shared library path.",
        )
    from OCP.BRepAlgoAPI import BRepAlgoAPI_Cut
    from OCP.BRepPrimAPI import BRepPrimAPI_MakeBox, BRepPrimAPI_MakeSphere
    from OCP.gp import gp_Pnt

    schedule = phx.meshing.LayerSchedule.geometric(3, 0.02, growth_rate=1.25)
    provider = phx.meshing.GmshProvider()
    with TemporaryDirectory(prefix="phydrax-gmsh-boundary-layer-") as temporary:
        box = BRepPrimAPI_MakeBox(gp_Pnt(-1.0, -1.0, -1.0), 2.0, 2.0, 2.0).Shape()
        ball = BRepPrimAPI_MakeSphere(gp_Pnt(0.0, 0.0, 0.0), 0.4).Shape()
        source = phx.interchange.persist_occt_shape(
            BRepAlgoAPI_Cut(box, ball).Shape(),
            Path(temporary) / "ball-in-box.brep",
            coordinate_contract=_contract(),
            linear_deflection=0.01,
            angular_deflection=0.1,
        )
        routes = {
            "advancing": _gmsh_layered_route(
                provider,
                source,
                phx.meshing.BoundaryLayerRoute.ADVANCING,
                phx.meshing.BoundaryLayerCornerPolicy.FAN,
                schedule,
                1.0e-6,
            ),
            "provider": _gmsh_layered_route(
                provider,
                source,
                phx.meshing.BoundaryLayerRoute.PROVIDER,
                phx.meshing.BoundaryLayerCornerPolicy.SMOOTH,
                schedule,
                2.0e-2,
            ),
        }
    sections = ("quality", "conservation", "resources")
    return {
        "status": "passed",
        "source": {
            "model_id": source.model_id,
            "source_id": source.report.source_id,
            "source_revision": source.report.source_revision,
            "faces": len(source.face_ids),
            "schedule_id": schedule.schedule_id,
        },
        "target": {name: record["target"] for name, record in routes.items()},
        "runtime": {
            **_runtime_identity(),
            "provider_version": routes["advancing"]["provider"]["version"],
        },
        "quality": {
            "before": {
                name: record["quality"]["before"] for name, record in routes.items()
            },
            "after": {
                name: record["quality"]["after"] for name, record in routes.items()
            },
        },
        "conservation": {name: record["conservation"] for name, record in routes.items()},
        "resources": {name: record["resources"] for name, record in routes.items()},
        "routes": {
            name: {key: value for key, value in record.items() if key not in sections}
            for name, record in routes.items()
        },
    }


_MESHCORE_DETAIL = "Set PHYDRAX_MESHCORE_LIBRARY or install phydrax[meshcore]."


def _unit_lattice_cells(
    cells_per_axis: int, dimension: int, /
) -> tuple[np.ndarray, np.ndarray]:
    """Unit square/cube lattice points and quadrilateral/hexahedron corners."""
    from tools.meshing_benchmarks import _HEXAHEDRON_CORNERS

    count = cells_per_axis
    axis = np.linspace(0.0, 1.0, count + 1)
    points = np.stack(np.meshgrid(*(axis,) * dimension, indexing="ij"), axis=-1).reshape(
        (-1, dimension)
    )
    index = np.arange((count + 1) ** dimension, dtype=np.int32).reshape(
        (count + 1,) * dimension
    )
    offsets = np.unique(_HEXAHEDRON_CORNERS[:, :dimension], axis=0, return_index=True)[1]
    corners = _HEXAHEDRON_CORNERS[np.sort(offsets), :dimension]
    cells = np.stack(
        [
            index[tuple(slice(start, start + count) for start in corner)].reshape((-1,))
            for corner in corners
        ],
        axis=1,
    )
    return points, cells


def _jittered_cube_tetrahedra(
    cells_per_axis: int, seed: int, /
) -> phx.discretization.CellMesh:
    """Kuhn tetrahedra of the unit cube with interior vertices jittered in place."""
    from tools.meshing_benchmarks import _kuhn_tetrahedra

    points, tetrahedra = _kuhn_tetrahedra(cells_per_axis)
    interior = np.all((points > 0.0) & (points < 1.0), axis=1)
    jitter = np.random.default_rng(seed).uniform(-0.1, 0.1, points.shape)
    points[interior] += jitter[interior] / cells_per_axis
    return phx.discretization.CellMesh.from_tetrahedra(points, tetrahedra)


def _supermesh_case(
    source: phx.discretization.CellMesh, target: phx.discretization.CellMesh, /
) -> dict[str, object]:
    """Certify one common refinement and recount its measure and moment ledgers."""
    contract = _contract()
    source_result, source_certify = _measured(
        lambda: phx.meshing.certify_cell_mesh(source, contract)
    )
    target_result, target_certify = _measured(
        lambda: phx.meshing.certify_cell_mesh(target, contract)
    )
    policy = phx.geometry.CommonRefinementPolicy(overlap_simplices=True)
    refinement, refinement_record = _measured(
        lambda: phx.geometry.prepare_common_refinement(source, target, policy=policy)
    )

    evidence = refinement.evidence

    if not refinement.succeeded:
        raise RuntimeError(
            f"Common refinement failed: {refinement.status.name}: {evidence.reason}."
        )

    dimension = refinement.dimension

    volumes = np.asarray(refinement.volumes, dtype=np.float64)

    moments = np.asarray(refinement.first_moments, dtype=np.float64)
    ledgers = {}
    for role, cells, measures, first in (
        (
            "source",
            refinement.source_cells,
            refinement.source_measures,
            refinement.source_first_moments,
        ),
        (
            "target",
            refinement.target_cells,
            refinement.target_measures,
            refinement.target_first_moments,
        ),
    ):
        cells = np.asarray(cells, dtype=np.int64)
        measures = np.asarray(measures, dtype=np.float64)
        first = np.asarray(first, dtype=np.float64)
        covered = np.zeros_like(measures)
        np.add.at(covered, cells, volumes)
        covered_moments = np.zeros_like(first)
        np.add.at(covered_moments, cells, moments)
        total = float(np.sum(measures))
        ledgers[role] = {
            "measure": total,
            "total_measure_relative_defect": abs(float(np.sum(volumes)) - total) / total,
            "maximum_cell_measure_relative_defect": float(
                np.max(np.abs(covered - measures) / measures)
            ),
            # Cell centroid integrals: the overlap first moments of each cell sum
            # to the cell's own first moment.
            "maximum_cell_first_moment_relative_defect": float(
                np.max(np.abs(covered_moments - first)) / np.max(np.abs(first))
            ),
        }
    # The unit square/cube has measure one and centroid (1/2, ..., 1/2).
    domain = {
        "measure_defect": abs(float(np.sum(volumes)) - 1.0),
        "first_moment_defect": float(np.max(np.abs(np.sum(moments, axis=0) - 0.5))),
    }

    offsets = np.asarray(refinement.simplex_offsets, dtype=np.int64)

    simplices = np.asarray(refinement.simplices, dtype=np.float64)
    signed = np.linalg.det(simplices[:, 1:] - simplices[:, :1]) / np.prod(
        np.arange(1, dimension + 1)
    )
    partition = np.zeros_like(volumes)
    np.add.at(partition, np.repeat(np.arange(volumes.size), np.diff(offsets)), signed)
    partition_defect = float(np.max(np.abs(partition - volumes) / volumes))
    defects = (
        *(
            value
            for ledger in ledgers.values()
            for key, value in ledger.items()
            if key != "measure"
        ),
        *domain.values(),
        partition_defect,
        evidence.maximum_relative_source_defect,
        evidence.maximum_relative_target_defect,
    )
    if (
        max(defects) > 1.0e-12
        or evidence.source_gap_count
        or evidence.target_gap_count
        or evidence.source_double_count
        or evidence.target_double_count
        or evidence.uncertain_predicate_count
        or evidence.invalid_cell_count
        or evidence.intersection_failure_count
        or not (source_result.audit.passed and target_result.audit.passed)
    ):
        raise RuntimeError(
            f"Common refinement ledgers failed: {ledgers}, {domain}, "
            f"partition {partition_defect}, evidence {evidence.reason}."
        )
    return {
        "source": {**_result_identity(source_result), "mesh_id": source.mesh_id},
        "target": {**_result_identity(target_result), "mesh_id": target.mesh_id},
        "identities": {
            "refinement_id": refinement.refinement_id,
            "evidence_id": evidence.evidence_id,
            "policy_id": policy.policy_id,
            "source_topology_id": refinement.source_topology_id,
            "target_topology_id": refinement.target_topology_id,
        },
        "quality": {
            "source": _quality_summary(source_result.quality),
            "target": _quality_summary(target_result.quality),
        },
        "coverage": {
            "status": refinement.status.name,
            "reason": evidence.reason,
            "maximum_relative_source_defect": evidence.maximum_relative_source_defect,
            "maximum_relative_target_defect": evidence.maximum_relative_target_defect,
            "source_gap_count": evidence.source_gap_count,
            "target_gap_count": evidence.target_gap_count,
            "source_double_count": evidence.source_double_count,
            "target_double_count": evidence.target_double_count,
        },
        "conservation": {
            **ledgers,
            "unit_domain": domain,
            "simplex_partition_maximum_relative_defect": partition_defect,
        },
        "pairs": {
            "candidate": evidence.candidate_pair_count,
            "accepted": evidence.accepted_pair_count,
            "piece_pairs": evidence.piece_pair_count,
            "entries": refinement.entry_count,
            "overlap_simplices": simplices.shape[0],
        },
        "predicates": {
            "mode": policy.predicate_mode.value,
            "uncertain": evidence.uncertain_predicate_count,
            "invalid_cells": evidence.invalid_cell_count,
            "intersection_failures": evidence.intersection_failure_count,
        },
        "resources": {
            "source_certify": source_certify,
            "target_certify": target_certify,
            "common_refinement": refinement_record,
            "retained_bytes": evidence.retained_bytes,
            "working_bytes": evidence.working_bytes,
        },
    }


def qualify_supermesh() -> dict[str, object]:
    if not meshcore_available():
        return _missing_dependency("phydrax-meshcore", _MESHCORE_DETAIL)
    from tools.meshing_benchmarks import _jittered_unit_square_triangles

    square_points, quadrilaterals = _unit_lattice_cells(5, 2)
    cube_points, hexahedra = _unit_lattice_cells(2, 3)
    meshes = {
        "triangles-quadrilaterals-2d": (
            _jittered_unit_square_triangles(6, 1),
            phx.discretization.CellMesh(
                square_points,
                (phx.discretization.CellBlock("quads", "quadrilateral", quadrilaterals),),
            ),
        ),
        "triangles-triangles-2d": (
            _jittered_unit_square_triangles(6, 1),
            _jittered_unit_square_triangles(5, 2),
        ),
        "tetrahedra-tetrahedra-3d": (
            _jittered_cube_tetrahedra(3, 3),
            _jittered_cube_tetrahedra(2, 4),
        ),
        "hexahedra-tetrahedra-3d": (
            phx.discretization.CellMesh(
                cube_points,
                (phx.discretization.CellBlock("hexahedra", "hexahedron", hexahedra),),
            ),
            _jittered_cube_tetrahedra(3, 3),
        ),
    }
    cases = {name: _supermesh_case(*pair) for name, pair in meshes.items()}
    sections = ("source", "target", "quality", "conservation", "resources")
    return {
        "status": "passed",
        "source": {name: case["source"] for name, case in cases.items()},
        "target": {name: case["target"] for name, case in cases.items()},
        "runtime": _runtime_identity(),
        "quality": {
            "before": {
                name: _record_mapping(case["quality"], "Supermesh quality")["source"]
                for name, case in cases.items()
            },
            "after": {
                name: _record_mapping(case["quality"], "Supermesh quality")["target"]
                for name, case in cases.items()
            },
        },
        "conservation": {name: case["conservation"] for name, case in cases.items()},
        "resources": {name: case["resources"] for name, case in cases.items()},
        "cases": {
            name: {key: value for key, value in case.items() if key not in sections}
            for name, case in cases.items()
        },
    }


def _remap_cell_averages(discretization: Any, function: Any, /) -> np.ndarray:
    """Quadrature cell averages of ``function`` on one FV discretization."""
    weights = np.where(
        np.asarray(discretization.cell_quadrature_valid),
        np.asarray(discretization.cell_quadrature_weights),
        0.0,
    )
    values = function(np.asarray(discretization.cell_quadrature_points))
    return np.sum(weights * values, axis=1) / np.sum(weights, axis=1)


def _remap_linear(points: np.ndarray, /) -> np.ndarray:
    return 0.5 + 2.0 * points[..., 0] - 3.0 * points[..., 1]


def qualify_remap_p1() -> dict[str, object]:
    if not meshcore_available():
        return _missing_dependency("phydrax-meshcore", _MESHCORE_DETAIL)
    from tools.meshing_benchmarks import _jittered_unit_square_triangles, _remap_field

    discretization = phx.discretization
    contract = _contract()
    points, quadrilaterals = _unit_lattice_cells(6, 2)
    triangles = _jittered_unit_square_triangles(5, 3)
    source, source_record = _measured(
        lambda: discretization.UnstructuredFiniteVolumePlan(
            points, quadrilaterals=quadrilaterals
        ).prepare()
    )
    target, target_record = _measured(
        lambda: discretization.UnstructuredFiniteVolumePlan(
            np.asarray(triangles.coordinates),
            triangles=np.asarray(triangles.blocks[0].vertices),
        ).prepare()
    )

    source_result = phx.meshing.certify_cell_mesh(source.mesh, contract)

    target_result = phx.meshing.certify_cell_mesh(target.mesh, contract)
    prepared, refinement_record = _measured(
        lambda: discretization.prepare_unstructured_conservative_remap(
            source,
            target,
            provenance="qualification-remap-p1",
        )
    )

    if not prepared.succeeded:
        raise RuntimeError(f"P0 remap preparation failed: {prepared.reason}.")
    conservative_plan, common_refinement = prepared.plan, prepared.refinement
    if conservative_plan is None or common_refinement is None:
        raise RuntimeError(
            "Successful P0 remap preparation lacks its plan or refinement."
        )
    if not isinstance(prepared.evidence, CommonRefinementEvidence):
        raise RuntimeError(
            "Affine P1 remap qualification requires affine common-refinement evidence."
        )
    limited_plan, limited_record = _measured(
        lambda: discretization.UnstructuredSecondOrderRemapPlan(
            conservative_plan,
            common_refinement,
            source,
        )
    )
    unlimited_plan, unlimited_record = _measured(
        lambda: discretization.UnstructuredSecondOrderRemapPlan(
            conservative_plan,
            common_refinement,
            source,
            limiter=discretization.UnstructuredRemapLimiter.NONE,
        )
    )

    source_volumes = np.asarray(source.cell_volumes, dtype=np.float64)

    target_volumes = np.asarray(target.cell_volumes, dtype=np.float64)
    smooth = jnp.asarray(_remap_cell_averages(source, _remap_field))
    smooth_exact = _remap_cell_averages(target, _remap_field)
    linear = jnp.asarray(_remap_cell_averages(source, _remap_linear))
    linear_exact = _remap_cell_averages(target, _remap_linear)

    centers = np.asarray(source.cell_centers)
    step = jnp.asarray(np.where(centers[:, 0] + 0.3 * centers[:, 1] > 0.55, 2.0, -1.0))
    constant = jnp.ones_like(smooth)

    def relative_l1(values: Any, exact: Any) -> Any:
        return float(
            np.sum(target_volumes * np.abs(np.asarray(values) - exact))
            / np.sum(target_volumes * np.abs(exact))
        )

    def mass_residual(source_values: Any, target_values: Any) -> Any:
        return abs(
            float(np.sum(target_volumes * np.asarray(target_values)))
            - float(np.sum(source_volumes * np.asarray(source_values)))
        ) / float(np.sum(source_volumes * np.abs(np.asarray(source_values))))

    apply_p0 = conservative_plan.apply
    p0, p0_record = _measured(
        lambda: jax.block_until_ready(
            {
                name: apply_p0(values)
                for name, values in (
                    ("constant", constant),
                    ("smooth", smooth),
                    ("linear", linear),
                    ("step", step),
                )
            }
        )
    )
    p1, p1_record = _measured(
        lambda: jax.block_until_ready(
            {
                name: limited_plan.apply(values)
                for name, values in (
                    ("constant", constant),
                    ("smooth", smooth),
                    ("linear", linear),
                    ("step", step),
                )
            }
        )
    )

    unlimited_linear = unlimited_plan.apply(linear)
    p0_defect = conservative_plan.conservation_defect(smooth, p0["smooth"])
    fv = {
        "p0": {
            "constant_error": float(np.max(np.abs(np.asarray(p0["constant"]) - 1.0))),
            "smooth_mass_residual": mass_residual(smooth, p0["smooth"]),
            "step_mass_residual": mass_residual(step, p0["step"]),
            "plan_conservation_defect": float(np.max(np.abs(np.asarray(p0_defect)))),
            "smooth_relative_l1_error": relative_l1(p0["smooth"], smooth_exact),
            "linear_relative_l1_error": relative_l1(p0["linear"], linear_exact),
            "step_bounds": [float(jnp.min(p0["step"])), float(jnp.max(p0["step"]))],
        },
        "limited_p1": {
            "constant_error": float(
                np.max(np.abs(np.asarray(p1["constant"].values) - 1.0))
            ),
            "smooth_mass_residual": mass_residual(smooth, p1["smooth"].values),
            "step_mass_residual": mass_residual(step, p1["step"].values),
            "step_conservation_residual_after": float(
                np.abs(np.asarray(p1["step"].conservation_residual_after))
            ),
            "step_restored": bool(p1["step"].restored),
            "smooth_relative_l1_error": relative_l1(p1["smooth"].values, smooth_exact),
            "linear_relative_l1_error": relative_l1(p1["linear"].values, linear_exact),
            "step_bounds": [
                float(jnp.min(p1["step"].values)),
                float(jnp.max(p1["step"].values)),
            ],
            "step_limited_cells": int(p1["step"].limited_count),
            "step_minimum_limiter_factor": float(p1["step"].minimum_limiter_factor),
            "gradient_minimum_rank": int(np.min(np.asarray(limited_plan.gradient_rank))),
            "gradient_maximum_condition": float(
                np.max(np.asarray(limited_plan.gradient_condition))
            ),
        },
        "unlimited_p1": {
            "linear_maximum_error": float(
                np.max(np.abs(np.asarray(unlimited_linear.values) - linear_exact))
            ),
            "linear_mass_residual": mass_residual(linear, unlimited_linear.values),
        },
    }
    step_bounds = fv["limited_p1"]["step_bounds"]
    if (
        max(
            fv["p0"]["constant_error"],
            fv["p0"]["smooth_mass_residual"],
            fv["p0"]["step_mass_residual"],
            fv["limited_p1"]["constant_error"],
            fv["limited_p1"]["smooth_mass_residual"],
            fv["limited_p1"]["step_mass_residual"],
            fv["unlimited_p1"]["linear_maximum_error"],
            fv["unlimited_p1"]["linear_mass_residual"],
        )
        > 1.0e-12
        or step_bounds[0] < -1.0 - 1.0e-12
        or step_bounds[1] > 2.0 + 1.0e-12
        or not fv["limited_p1"]["step_restored"]
        or fv["limited_p1"]["step_limited_cells"] == 0
        or fv["limited_p1"]["smooth_relative_l1_error"]
        >= fv["p0"]["smooth_relative_l1_error"]
    ):
        raise RuntimeError(f"Finite-volume remap qualification failed: {fv}.")

    # FEM L2 projection of a continuous P1 field between jittered triangle meshes.
    fem_source_mesh = _jittered_unit_square_triangles(7, 1)
    fem_target_mesh = _jittered_unit_square_triangles(5, 2)

    def p1_space(mesh: Any) -> Any:
        return discretization.FiniteElementPlan(
            mesh,
            discretization.FiniteElementFieldSpec(
                "u", discretization.lagrange_element("triangle", 1)
            ),
        ).prepare()

    fem_source, fem_target = p1_space(fem_source_mesh), p1_space(fem_target_mesh)
    fem_refinement, fem_refinement_record = _measured(
        lambda: phx.geometry.prepare_common_refinement(
            fem_source_mesh,
            fem_target_mesh,
            policy=phx.geometry.CommonRefinementPolicy(overlap_simplices=True),
        )
    )

    if not fem_refinement.succeeded:
        raise RuntimeError(f"L2 projection refinement failed: {fem_refinement.status}.")
    prepared_target, target_record = _measured(
        lambda: discretization.prepare_l2_projection_target(fem_target, field_name="u")
    )
    transfer, transfer_record = _measured(
        lambda: discretization.prepare_l2_projection_transfer(
            fem_source,
            prepared_target,
            fem_refinement,
            field_name="u",
        )
    )
    source_dofs = np.asarray(fem_source.dof_maps[0].dof_coordinates)
    target_dofs = np.asarray(fem_target.dof_maps[0].dof_coordinates)
    source_weights = np.asarray(
        fem_source.mass.mv(jnp.ones((fem_source.dof_maps[0].global_dof_count,)))
    )
    target_weights = np.asarray(
        fem_target.mass.mv(jnp.ones((fem_target.dof_maps[0].global_dof_count,)))
    )
    fem_smooth = _remap_field(source_dofs)
    projected, projection_record = _measured(
        lambda: jax.block_until_ready(
            (
                transfer.apply(jnp.ones_like(jnp.asarray(fem_smooth))),
                transfer.apply(jnp.asarray(_remap_linear(source_dofs))),
                transfer.apply(jnp.asarray(fem_smooth)),
            )
        )
    )
    source_integral = float(np.dot(source_weights, fem_smooth))
    fem = {
        "flags": {
            "preserves_constants": transfer.preserves_constants,
            "preserves_linear": transfer.preserves_linear,
            "conservative": transfer.conservative,
            "positivity_preserving": transfer.positivity_preserving,
        },
        "constant_error": float(np.max(np.abs(np.asarray(projected[0]) - 1.0))),
        "linear_maximum_error": float(
            np.max(np.abs(np.asarray(projected[1]) - _remap_linear(target_dofs)))
        ),
        "smooth_integral_relative_residual": abs(
            float(np.dot(target_weights, np.asarray(projected[2]))) - source_integral
        )
        / abs(source_integral),
        "smooth_nodal_maximum_error": float(
            np.max(np.abs(np.asarray(projected[2]) - _remap_field(target_dofs)))
        ),
        "target_mass_condition": float(prepared_target.mass_condition.value),
        "factorization_status": int(prepared_target.factorization.status),
    }
    if (
        not (
            transfer.preserves_constants
            and transfer.preserves_linear
            and transfer.conservative
        )
        or transfer.positivity_preserving
        or max(
            fem["constant_error"],
            fem["linear_maximum_error"],
            fem["smooth_integral_relative_residual"],
        )
        > 1.0e-10
    ):
        raise RuntimeError(f"L2 projection qualification failed: {fem}.")

    evidence = prepared.evidence
    return {
        "status": "passed",
        "source": {
            "finite_volume": {
                **_result_identity(source_result),
                "prepared_id": source.prepared_id,
                "geometry_id": source.geometry_id,
            },
            "finite_element": {
                "mesh_id": fem_source_mesh.mesh_id,
                "topology_id": fem_source_mesh.topology_id,
                "prepared_id": fem_source.prepared_id,
                "dofs": source_dofs.shape[0],
            },
        },
        "target": {
            "finite_volume": {
                **_result_identity(target_result),
                "prepared_id": target.prepared_id,
                "geometry_id": target.geometry_id,
            },
            "finite_element": {
                "mesh_id": fem_target_mesh.mesh_id,
                "topology_id": fem_target_mesh.topology_id,
                "prepared_id": fem_target.prepared_id,
                "dofs": target_dofs.shape[0],
            },
        },
        "identities": {
            "refinement_id": common_refinement.refinement_id,
            "remap_id": prepared.remap_id,
            "p0_plan_id": conservative_plan.plan_id,
            "limited_p1_plan_id": limited_plan.plan_id,
            "unlimited_p1_plan_id": unlimited_plan.plan_id,
            "l2_refinement_id": fem_refinement.refinement_id,
            "l2_transfer_id": transfer.transfer_id,
        },
        "runtime": _runtime_identity(),
        "quality": {
            "before": _quality_summary(source_result.quality),
            "after": _quality_summary(target_result.quality),
        },
        "conservation": {
            "finite_volume": fv,
            "coverage": {
                "maximum_relative_source_defect": evidence.maximum_relative_source_defect,
                "maximum_relative_target_defect": evidence.maximum_relative_target_defect,
                "entries": common_refinement.entry_count,
            },
        },
        "transfer": {"l2_projection": fem},
        "resources": {
            "source_prepare": source_record,
            "target_prepare": target_record,
            "refinement_and_p0_plan": refinement_record,
            "limited_p1_plan": limited_record,
            "unlimited_p1_plan": unlimited_record,
            "p0_apply": p0_record,
            "limited_p1_apply": p1_record,
            "l2_refinement": fem_refinement_record,
            "l2_target_prepare": target_record,
            "l2_transfer_prepare": transfer_record,
            "l2_apply": projection_record,
            "refinement_retained_bytes": evidence.retained_bytes,
            "refinement_working_bytes": evidence.working_bytes,
            "l2_refinement_retained_bytes": fem_refinement.evidence.retained_bytes,
            "l2_refinement_working_bytes": fem_refinement.evidence.working_bytes,
        },
    }


def _bisection_meshes() -> dict[str, phx.discretization.CellMesh]:
    """A 4 x 4 right-triangle lattice of the unit square and 2^3 Kuhn cubes."""
    from tools.meshing_benchmarks import _kuhn_tetrahedra, _planar_triangles

    axis = np.linspace(0.0, 1.0, 5)
    points = np.stack(np.meshgrid(axis, axis, indexing="ij"), axis=-1).reshape((-1, 2))
    spatial, tetrahedra = _kuhn_tetrahedra(2)
    return {
        "triangles": phx.discretization.CellMesh.from_triangles(
            points, _planar_triangles(4)
        ),
        "tetrahedra": phx.discretization.CellMesh.from_tetrahedra(spatial, tetrahedra),
    }


def _bisection_cell_ids(mesh: phx.discretization.CellMesh, /) -> np.ndarray:
    return np.asarray(mesh.blocks[0].global_ids, dtype=np.int64)


def _bisection_corner_cells(mesh: phx.discretization.CellMesh, /) -> np.ndarray:
    """Cells touching the vertex nearest the origin (repeated local refinement)."""
    corner = np.argmin(np.linalg.norm(np.asarray(mesh.coordinates), axis=1))
    touching = np.any(np.asarray(mesh.blocks[0].vertices) == corner, axis=1)
    return np.sort(_bisection_cell_ids(mesh)[touching])


def _bisection_adapt(
    route: phx.meshing.MeshAdaptationRoute,
    source: phx.meshing.CellMeshingResult,
    refine: np.ndarray,
    coarsen: np.ndarray,
    hierarchy: Any,
    /,
    *,
    device_policy: phx.discretization.AdaptiveSimplexPolicy | None = None,
) -> tuple[phx.meshing.MeshAdaptationResult, dict[str, dict[str, float]]]:
    request = phx.meshing.MarkedMeshAdaptation(
        np.asarray(refine, dtype=np.int64),
        np.asarray(coarsen, dtype=np.int64),
        hierarchy=hierarchy,
    )
    policy = phx.meshing.MeshAdaptationPolicy(route, device_policy=device_policy)
    prepared, preparation = _measured(
        lambda: phx.meshing.prepare_mesh_adaptation(source, request, policy=policy)
    )
    result, execution = _measured(lambda: phx.meshing.execute_mesh_adaptation(prepared))

    if not result.target.audit.passed:
        raise RuntimeError(f"{route.name} produced a target that failed its audit.")
    return result, {"prepare": preparation, "execute": execution}


def _bisection_retained_bytes(tree: Any, /) -> int:
    """Bytes of the distinct array leaves an adaptation artifact retains."""
    leaves = {
        id(leaf): leaf
        for leaf in jax.tree.leaves(tree)
        if isinstance(leaf, (jax.Array, np.ndarray))
    }
    return sum(leaf.nbytes for leaf in leaves.values())


def _bisection_lineage(result: phx.meshing.MeshAdaptationResult, /) -> dict[str, object]:
    """Every entity is an identity, a lineage relation, or created/deleted."""
    source, target = result.source.mesh, result.target.mesh
    lineage = result.lineage
    if lineage is None:
        raise RuntimeError("Bisection qualification requires complete entity lineage.")
    dimensions = tuple(record.dimension for record in lineage.entities)
    width = np.asarray(source.blocks[0].vertices).shape[1]
    complete = (
        dimensions == tuple(range(width))
        and lineage.source_topology_id == source.topology_id
        and lineage.target_topology_id == target.topology_id
    )
    relations = {}

    for record in lineage.entities:
        before = np.asarray(source.entity_set(record.dimension).entity_ids)
        after = np.asarray(target.entity_set(record.dimension).entity_ids)
        created = np.asarray(record.created_target_ids)
        deleted = np.asarray(record.deleted_source_ids)
        covered_after = np.concatenate(
            (before, np.asarray(record.target_global_ids), created)
        )
        covered_before = np.concatenate(
            (after, np.asarray(record.source_global_ids), deleted)
        )
        complete = complete and bool(
            np.all(np.isin(after, covered_after))
            and np.all(np.isin(before, covered_before))
            and np.all(np.isin(created, after) & ~np.isin(created, before))
            and np.all(np.isin(deleted, before) & ~np.isin(deleted, after))
        )
        relations[f"dimension_{record.dimension}"] = {
            "relations": record.relation_kinds.shape[0],
            "created": created.shape[0],
            "deleted": deleted.shape[0],
        }
    if not complete:
        raise RuntimeError("Bisection lineage does not account for every entity.")

    return {"lineage_id": lineage.lineage_id, "complete": complete, **relations}


def _bisection_evidence(evidence: Any, /) -> dict[str, object]:
    return {
        "evidence_id": evidence.evidence_id,
        "requested_refinements": evidence.requested_refinements,
        "accepted_refinements": evidence.accepted_refinements,
        "rejected_refinements": evidence.rejected_refinement_ids.shape[0],
        "admissibility_tests": evidence.admissibility_tests,
        "bisections": evidence.bisections,
        "closure_iterations": evidence.closure_iterations,
        "created_vertices": evidence.created_vertices,
        "maximum_generation": evidence.maximum_generation,
        "initially_compatible": evidence.initially_compatible,
        "incompatible_facets": evidence.incompatible_facets,
        "uniform_refinement_applied": evidence.uniform_refinement_applied,
        "requested_coarsenings": evidence.requested_coarsenings,
        "coarsened_vertices": evidence.coarsened_vertices,
        "coarsening_passes": evidence.coarsening_passes,
        "restored_cells": evidence.restored_cells,
        "rejected_coarsenings": evidence.rejected_coarsening_ids.shape[0],
    }


def _bisection_p1_integral(mesh: phx.discretization.CellMesh, values: Any, /) -> float:
    """Exact integral of the P1 interpolant of vertex values."""
    match mesh.topological_dimension:
        case 2:
            kind = "triangle"
        case 3:
            kind = "tetrahedron"
        case _:
            raise ValueError("P1 inventory requires triangle or tetrahedron blocks.")
    if any(block.cell_kind != kind for block in mesh.blocks):
        raise ValueError(
            "P1 inventory requires compatible simplex blocks throughout the mesh."
        )
    cells = (
        np.asarray(mesh.blocks[0].vertices)
        if len(mesh.blocks) == 1
        else np.concatenate([np.asarray(block.vertices) for block in mesh.blocks])
    )
    measures = np.abs(_simplex_measures(np.asarray(mesh.coordinates), cells))
    return float(np.sum(measures * np.mean(np.asarray(values)[cells], axis=1)))


def _bisection_transfer(result: phx.meshing.MeshAdaptationResult, /) -> dict[str, object]:
    """Claims, P1 linear reproduction, and P1 integral change of one transfer."""
    transfer = result.transfer
    if transfer is None:
        raise RuntimeError(
            "Bisection qualification requires a finite-element topology transfer."
        )
    source = np.asarray(result.source.mesh.coordinates)
    target = np.asarray(result.target.mesh.coordinates)
    slope = np.linspace(0.5, 1.5, source.shape[1])

    linear = np.asarray(transfer.apply(source @ slope + 0.25))
    reproduction = float(np.max(np.abs(linear - (target @ slope + 0.25))))

    constant = np.asarray(transfer.apply(np.ones((source.shape[0],))))
    smooth = np.sin(3.0 * source[:, 0]) * np.cos(2.0 * source[:, -1])

    moved = np.asarray(transfer.apply(smooth))
    residual = _bisection_p1_integral(result.target.mesh, moved) - _bisection_p1_integral(
        result.source.mesh, smooth
    )
    if (
        not transfer.preserves_constants
        or not transfer.preserves_linear
        or reproduction > 1.0e-12
        or float(np.max(np.abs(constant - 1.0))) > 1.0e-14
    ):
        raise RuntimeError("The bisection transfer does not reproduce P1 fields.")
    return {
        "transfer_id": transfer.transfer_id,
        "preserves_constants": transfer.preserves_constants,
        "preserves_linear": transfer.preserves_linear,
        "conservative": transfer.conservative,
        "positivity_preserving": transfer.positivity_preserving,
        "linear_reproduction_error": reproduction,
        "constant_reproduction_error": float(np.max(np.abs(constant - 1.0))),
        "p1_integral_residual": residual,
        "retained_bytes": _bisection_retained_bytes(transfer),
    }


def _bisection_shape_classes(
    source: phx.meshing.CellMeshingResult, rounds: int, cycles: int, /
) -> dict[str, object]:
    """Uniform class bound, then repeated corner refinement against it.

    Newest-vertex (Maubach) bisection generates finitely many similarity
    classes; the first uniform generations visit them all, so locally refined
    meshes never fall below the uniform bound.
    """
    route = phx.meshing.MeshAdaptationRoute.NATIVE_BISECTION
    angle = source.quality.minimum_angle
    mean_ratio = source.quality.minimum_mean_ratio
    current, hierarchy = source, None
    for _ in range(rounds):
        cells = np.sort(_bisection_cell_ids(current.mesh))
        result, _ = _bisection_adapt(
            route, current, cells, np.empty((0,), dtype=np.int64), hierarchy
        )
        current, hierarchy = result.target, result.hierarchy
        angle = min(angle, current.quality.minimum_angle)
        mean_ratio = min(mean_ratio, current.quality.minimum_mean_ratio)
    current, hierarchy = source, None
    angles, ratios = [], []
    for _ in range(cycles):
        marks = _bisection_corner_cells(current.mesh)
        result, _ = _bisection_adapt(
            route, current, marks, np.empty((0,), dtype=np.int64), hierarchy
        )
        current, hierarchy = result.target, result.hierarchy
        angles.append(current.quality.minimum_angle)
        ratios.append(current.quality.minimum_mean_ratio)
    bounded = min(angles) >= angle * (1.0 - 1.0e-9) and min(ratios) >= 0.999 * mean_ratio

    evidence = result.evidence
    if not isinstance(evidence, phx.meshing.BisectionEvidence):
        raise RuntimeError(
            "Bisection shape-class qualification lacks its native evidence."
        )
    if not bounded or evidence.maximum_generation < cycles:
        raise RuntimeError("Repeated bisection left the uniform shape-class bound.")
    return {
        "uniform_rounds": rounds,
        "uniform_minimum_angle_bound": angle,
        "uniform_minimum_mean_ratio_bound": mean_ratio,
        "corner_cycles": cycles,
        "corner_minimum_angles": angles,
        "corner_minimum_mean_ratios": ratios,
        "minimum_angle_ratio_to_source": min(angles) / source.quality.minimum_angle,
        "minimum_mean_ratio_ratio_to_source": min(ratios)
        / source.quality.minimum_mean_ratio,
        "maximum_generation": evidence.maximum_generation,
        "final_cells": current.mesh.blocks[0].cell_count,
        "bounded": bounded,
    }


def _bisection_round_trip(
    mesh: phx.discretization.CellMesh, rounds: int, cycles: int, /
) -> dict[str, object]:
    route = phx.meshing.MeshAdaptationRoute.NATIVE_BISECTION
    source, certification = _measured(
        lambda: phx.meshing.certify_cell_mesh(mesh, _contract())
    )
    marks = np.sort(_bisection_cell_ids(mesh))[::3]
    first, first_stages = _bisection_adapt(
        route, source, marks, np.empty((0,), dtype=np.int64), None
    )
    corner = _bisection_corner_cells(first.target.mesh)
    second, second_stages = _bisection_adapt(
        route,
        first.target,
        corner,
        np.empty((0,), dtype=np.int64),
        first.hierarchy,
    )
    everything = np.sort(_bisection_cell_ids(second.target.mesh))
    restored, restore_stages = _bisection_adapt(
        route,
        second.target,
        np.empty((0,), dtype=np.int64),
        everything,
        second.hierarchy,
    )
    back = restored.target.mesh
    identical = (
        back.topology_id == mesh.topology_id
        and np.array_equal(np.asarray(back.coordinates), np.asarray(mesh.coordinates))
        and np.array_equal(
            np.asarray(back.vertex_global_ids), np.asarray(mesh.vertex_global_ids)
        )
        and np.array_equal(_bisection_cell_ids(back), _bisection_cell_ids(mesh))
    )
    statuses = (first.status, second.status, restored.status)
    complete = phx.meshing.MeshAdaptationStatus.COMPLETE
    if not identical or first.status is not complete or second.status is not complete:
        raise RuntimeError("The bisection refine/coarsen round trip is not exact.")
    refinement = _bisection_transfer(first)
    if (
        not refinement["conservative"]
        or abs(
            _record_float(
                refinement["p1_integral_residual"], "Bisection P1 integral residual"
            )
        )
        > 1e-13
    ):
        raise RuntimeError("Refinement transfer does not conserve P1 integrals.")
    hierarchy = second.hierarchy
    if not isinstance(hierarchy, phx.meshing.BisectionHierarchy):
        raise RuntimeError("Bisection round trip did not retain its owning hierarchy.")
    return {
        "source": _result_identity(source),
        "refined": _result_identity(second.target),
        "target": _result_identity(restored.target),
        "statuses": [status.value for status in statuses],
        "restores_source_topology": identical,
        "quality": {
            "before": _quality_summary(source.quality),
            "refined": _quality_summary(second.target.quality),
            "after": _quality_summary(restored.target.quality),
        },
        "transfer": {
            "refinement": refinement,
            "local_refinement": _bisection_transfer(second),
            "coarsening": _bisection_transfer(restored),
        },
        "lineage": {
            "refinement": _bisection_lineage(first),
            "local_refinement": _bisection_lineage(second),
            "coarsening": _bisection_lineage(restored),
        },
        "evidence": {
            "refinement": _bisection_evidence(first.evidence),
            "local_refinement": _bisection_evidence(second.evidence),
            "coarsening": _bisection_evidence(restored.evidence),
        },
        "hierarchy_id": hierarchy.hierarchy_id,
        "shape_classes": _bisection_shape_classes(source, rounds, cycles),
        "resources": {
            "certify": certification,
            "refinement": first_stages,
            "local_refinement": second_stages,
            "coarsening": restore_stages,
            "hierarchy_retained_bytes": _bisection_retained_bytes(second.hierarchy),
            "target_mesh_retained_bytes": _bisection_retained_bytes(second.target.mesh),
        },
    }


def qualify_bisection() -> dict[str, object]:
    """NATIVE_BISECTION refine/coarsen round trips of triangles and tetrahedra."""
    meshes = _bisection_meshes()
    dimensions = {
        "triangles": _bisection_round_trip(meshes["triangles"], 4, 12),
        "tetrahedra": _bisection_round_trip(meshes["tetrahedra"], 3, 6),
    }
    return {
        "status": "passed",
        "route": phx.meshing.MeshAdaptationRoute.NATIVE_BISECTION.value,
        "source": {name: record["source"] for name, record in dimensions.items()},
        "target": {name: record["target"] for name, record in dimensions.items()},
        "quality": {
            name: {
                "before": _record_mapping(record["quality"], "Bisection quality")[
                    "before"
                ],
                "after": _record_mapping(record["quality"], "Bisection quality")["after"],
            }
            for name, record in dimensions.items()
        },
        "transfer": {name: record["transfer"] for name, record in dimensions.items()},
        "conservation": {
            name: {
                stage: _record_mapping(values, "Bisection transfer")[
                    "p1_integral_residual"
                ]
                for stage, values in _record_mapping(
                    record["transfer"], "Bisection transfers"
                ).items()
            }
            for name, record in dimensions.items()
        },
        "resources": {name: record["resources"] for name, record in dimensions.items()},
        "dimensions": dimensions,
        "runtime": _runtime_identity(),
    }


def _bisection_target_bytes(
    result: phx.meshing.MeshAdaptationResult, /
) -> dict[str, object]:
    """Committed arrays and identities compared byte for byte across routes."""
    mesh = result.target.mesh
    block = mesh.blocks[0]
    lineage, stencil, transfer = result.lineage, result.stencil, result.transfer
    hierarchy, evidence = result.hierarchy, result.evidence
    if (
        lineage is None
        or stencil is None
        or transfer is None
        or not isinstance(hierarchy, phx.meshing.BisectionHierarchy)
        or not isinstance(evidence, phx.meshing.BisectionEvidence)
    ):
        raise RuntimeError(
            "Bisection parity requires its complete committed lineage, hierarchy, and transfer evidence."
        )
    return {
        "status": result.status.value,
        "topology_id": mesh.topology_id,
        "coordinates": np.asarray(mesh.coordinates).tobytes(),
        "vertex_global_ids": np.asarray(mesh.vertex_global_ids).tobytes(),
        "cells": np.asarray(block.vertices).tobytes(),
        "cell_global_ids": np.asarray(block.global_ids).tobytes(),
        "lineage_id": lineage.lineage_id,
        "hierarchy_id": hierarchy.hierarchy_id,
        "stencil_id": stencil.stencil_id,
        "transfer_id": transfer.transfer_id,
        "rejected_coarsening_ids": np.asarray(evidence.rejected_coarsening_ids).tobytes(),
    }


def _bisection_same_target(host: Any, device: Any, /) -> list[str]:
    first, second = _bisection_target_bytes(host), _bisection_target_bytes(device)
    differences = [key for key in first if first[key] != second[key]]
    if differences:
        raise RuntimeError(
            f"DEVICE_BISECTION differs from NATIVE_BISECTION: {differences}"
        )
    return list(first)


def _bisection_simplex_report(report: Any, /) -> dict[str, object]:
    status = phx.discretization.AdaptiveSimplexStatus(int(report.status))
    return {
        "status": int(status),
        "flags": [
            flag.name
            for flag in phx.discretization.AdaptiveSimplexStatus
            if flag & status
        ],
        "failed": bool(report.failed),
        "requested": int(report.requested),
        "accepted": int(report.accepted),
        "rejected": int(np.count_nonzero(np.asarray(report.rejected))),
        "operations": int(report.operations),
        "iterations": int(report.iterations),
        "vertices": int(report.vertices),
        "uncertain_cells": int(report.uncertain_cells),
        "invalid_cells": int(report.invalid_cells),
        "minimum_quality": float(report.minimum_quality),
    }


def _bisection_device_parity(
    mesh: phx.discretization.CellMesh,
    capacity: tuple[int, int],
    /,
) -> dict[str, object]:
    """Host and device routes for the same marks, plus one explicit device epoch."""
    host_route = phx.meshing.MeshAdaptationRoute.NATIVE_BISECTION
    device_route = phx.meshing.MeshAdaptationRoute.DEVICE_BISECTION
    device_policy = phx.discretization.AdaptiveSimplexPolicy(
        vertex_capacity=capacity[0], cell_capacity=capacity[1]
    )
    source = phx.meshing.certify_cell_mesh(mesh, _contract())
    marks = np.sort(_bisection_cell_ids(mesh))[::3]
    host, host_first = _bisection_adapt(
        host_route, source, marks, np.empty((0,), dtype=np.int64), None
    )
    device, device_first = _bisection_adapt(
        device_route,
        source,
        marks,
        np.empty((0,), dtype=np.int64),
        None,
        device_policy=device_policy,
    )
    compared = _bisection_same_target(host, device)
    refine = _bisection_corner_cells(host.target.mesh)
    coarsen = np.setdiff1d(np.sort(_bisection_cell_ids(host.target.mesh))[-24:], refine)
    host_second, host_stages = _bisection_adapt(
        host_route, host.target, refine, coarsen, host.hierarchy
    )
    device_second, device_stages = _bisection_adapt(
        device_route,
        device.target,
        refine,
        coarsen,
        device.hierarchy,
        device_policy=device_policy,
    )
    _bisection_same_target(host_second, device_second)
    policy = phx.meshing.MeshAdaptationPolicy(device_route, device_policy=device_policy)
    hierarchy = device.hierarchy
    if not isinstance(hierarchy, phx.meshing.BisectionHierarchy):
        raise RuntimeError("Device bisection did not retain its owning hierarchy.")
    epoch, preparation = _measured(
        lambda: phx.meshing.prepare_adaptive_simplex(
            device.target,
            policy=policy,
            hierarchy=hierarchy,
        )
    )

    layout = epoch.layout
    refined, refinement = _measured(
        lambda: jax.block_until_ready(
            phx.discretization.refine_adaptive_simplex(
                layout,
                epoch.state,
                epoch.cell_marks(refine),
            )
        )
    )
    coarsened, coarsening = _measured(
        lambda: jax.block_until_ready(
            phx.discretization.coarsen_adaptive_simplex(
                layout,
                refined.state,
                epoch.cell_marks(coarsen),
            )
        )
    )
    committed, commit = _measured(
        lambda: phx.meshing.commit_adaptive_simplex(epoch, coarsened.state)
    )
    _bisection_same_target(host_second, committed)
    reports = {
        "refine": _bisection_simplex_report(refined.report),
        "coarsen": _bisection_simplex_report(coarsened.report),
    }
    if any(report["failed"] for report in reports.values()):
        raise RuntimeError("The explicit device epoch refused an operation.")
    return {
        "source": _result_identity(source),
        "target": _result_identity(device_second.target),
        "statuses": {
            "first": [host.status.value, device.status.value],
            "second": [host_second.status.value, device_second.status.value],
            "explicit_epoch": committed.status.value,
        },
        "byte_identical_fields": compared,
        "quality": {
            "before": _quality_summary(source.quality),
            "after": _quality_summary(device_second.target.quality),
        },
        "transfer": {
            "first": _bisection_transfer(device),
            "second": _bisection_transfer(device_second),
        },
        "lineage": _bisection_lineage(device_second),
        "evidence": {
            "host": _bisection_evidence(host_second.evidence),
            "device": _bisection_evidence(device_second.evidence),
        },
        "device_reports": reports,
        "layout": {
            "signature_id": layout.signature_id,
            "dimension": layout.dimension,
            "vertex_capacity": layout.vertex_capacity,
            "cell_capacity": layout.cell_capacity,
            "protected_edge_capacity": layout.protected_edge_capacity,
            "maximum_closure_iterations": layout.maximum_closure_iterations,
            "maximum_coarsening_passes": layout.maximum_coarsening_passes,
        },
        "resources": {
            "host_first": host_first,
            "device_first": device_first,
            "host_second": host_stages,
            "device_second": device_stages,
            "epoch_prepare": preparation,
            "epoch_refine": refinement,
            "epoch_coarsen": coarsening,
            "epoch_commit": commit,
            "epoch_state_bytes": _bisection_retained_bytes(coarsened.state),
            "transfer_retained_bytes": _bisection_retained_bytes(device_second.transfer),
        },
    }


def _bisection_metric_measurements(
    evidence: phx.meshing.LocalMetricEvidence | phx.meshing.DeviceMetricEvidence, /
) -> dict[str, object]:
    return {
        "evidence_id": evidence.evidence_id,
        "passes": evidence.passes,
        "splits": evidence.splits,
        "collapses": evidence.collapses,
        "flips": evidence.flips,
        "relocations": evidence.relocations,
        "rejected_uncertain": evidence.rejected_uncertain,
        "rejected_invalid": evidence.rejected_invalid,
        "converged": evidence.converged,
        "stalled": evidence.stalled,
        "measured_edges": evidence.measured_edges,
        "out_of_range_edges": evidence.out_of_range_edges,
        "minimum_metric_length": evidence.minimum_metric_length,
        "maximum_metric_length": evidence.maximum_metric_length,
        "unit_fraction": evidence.unit_fraction,
        "minimum_metric_quality": evidence.minimum_metric_quality,
    }


def _bisection_metric_comparison(
    mesh: phx.discretization.CellMesh, /
) -> dict[str, object]:
    """Host and device planar metric adaptation toward one isotropic size 0.2."""
    source = phx.meshing.certify_cell_mesh(mesh, _contract())
    vertices = np.asarray(source.mesh.entity_set(0).entity_ids)
    metric = phx.meshing.MeshMetricField(
        _mesh_scope(source.mesh, 0, vertices),
        np.broadcast_to(np.eye(2) / 0.2**2, (vertices.shape[0], 2, 2)),
        minimum_size=1.0e-3,
        maximum_size=10.0,
    )
    request = phx.meshing.MetricMeshAdaptation(metric)
    native_policy = phx.meshing.MeshAdaptationPolicy(
        phx.meshing.MeshAdaptationRoute.NATIVE_METRIC_2D
    )
    native, native_seconds = _measured(
        lambda: phx.meshing.execute_mesh_adaptation(
            phx.meshing.prepare_mesh_adaptation(source, request, policy=native_policy)
        )
    )
    device_policy = phx.meshing.MeshAdaptationPolicy(
        phx.meshing.MeshAdaptationRoute.DEVICE_METRIC_2D,
        device_policy=phx.discretization.AdaptiveSimplexPolicy(
            vertex_capacity=256, cell_capacity=512
        ),
    )
    prepared, preparation = _measured(
        lambda: phx.meshing.prepare_device_metric_adaptation(
            source, request, policy=device_policy
        )
    )
    update, adaptation = _measured(
        lambda: jax.block_until_ready(
            phx.meshing.adapt_device_metric(prepared.layout, prepared.state)
        )
    )

    report = jax.device_get(update.report)
    device, commit = _measured(
        lambda: phx.meshing.commit_device_metric_adaptation(prepared, update.state)
    )
    native_evidence, device_evidence = native.evidence, device.evidence
    if not isinstance(native_evidence, phx.meshing.LocalMetricEvidence):
        raise RuntimeError(
            "Native metric comparison requires local metric operation evidence."
        )
    if not isinstance(device_evidence, phx.meshing.DeviceMetricEvidence):
        raise RuntimeError(
            "Device metric comparison requires device metric operation evidence."
        )
    complete = phx.meshing.MeshAdaptationStatus.COMPLETE
    if (
        bool(report.failed)
        or device.status is not complete
        or not device_evidence.converged
        or not native.target.audit.passed
        or not device.target.audit.passed
    ):
        raise RuntimeError("DEVICE_METRIC_2D did not reach a certified unit mesh.")
    status = phx.discretization.AdaptiveSimplexStatus(int(report.status))
    return {
        "source": _result_identity(source),
        "target": {
            "native": _result_identity(native.target),
            "device": _result_identity(device.target),
        },
        "statuses": {"native": native.status.value, "device": device.status.value},
        "quality": {
            "before": _quality_summary(source.quality),
            "after": {
                "native": _quality_summary(native.target.quality),
                "device": _quality_summary(device.target.quality),
            },
        },
        "measurements": {
            "native": _bisection_metric_measurements(native_evidence),
            "device": _bisection_metric_measurements(device_evidence),
        },
        "device_report": {
            "status": int(status),
            "flags": [
                flag.name
                for flag in phx.discretization.AdaptiveSimplexStatus
                if flag & status
            ],
            "passes": int(report.passes),
            "splits": int(report.splits),
            "collapses": int(report.collapses),
            "flips": int(report.flips),
            "relocations": int(report.relocations),
            "rejected_cavity": int(report.rejected_cavity),
            "unit_fraction": float(report.unit_fraction),
            "minimum_metric_quality": float(report.minimum_metric_quality),
        },
        "layout": {
            "signature_id": prepared.layout.signature_id,
            "vertex_capacity": prepared.layout.vertex_capacity,
            "cell_capacity": prepared.layout.cell_capacity,
            "record_capacity": prepared.layout.record_capacity,
            "ball_width": prepared.layout.ball_width,
        },
        "transfer": {
            "native": _bisection_transfer(native),
            "device": _bisection_transfer(device),
        },
        "resources": {
            "native_adaptation": native_seconds,
            "device_prepare": preparation,
            "device_adapt": adaptation,
            "device_commit": commit,
            "device_state_bytes": _bisection_retained_bytes(update.state),
        },
    }


def qualify_device_adaptation() -> dict[str, object]:
    """DEVICE_BISECTION commits NATIVE_BISECTION byte for byte; metric routes agree."""
    meshes = _bisection_meshes()
    bisection = {
        "triangles": _bisection_device_parity(meshes["triangles"], (256, 512)),
        "tetrahedra": _bisection_device_parity(meshes["tetrahedra"], (256, 1024)),
    }
    metric = _bisection_metric_comparison(meshes["triangles"])
    return {
        "status": "passed",
        "source": {
            **{name: record["source"] for name, record in bisection.items()},
            "metric": metric["source"],
        },
        "target": {
            **{name: record["target"] for name, record in bisection.items()},
            "metric": metric["target"],
        },
        "quality": {
            **{name: record["quality"] for name, record in bisection.items()},
            "metric": metric["quality"],
        },
        "transfer": {
            **{name: record["transfer"] for name, record in bisection.items()},
            "metric": metric["transfer"],
        },
        "resources": {
            **{name: record["resources"] for name, record in bisection.items()},
            "metric": metric["resources"],
        },
        "bisection": bisection,
        "metric": metric,
        "runtime": _runtime_identity(),
    }


_CAD_CURVING_ASSOCIATION = phx.meshing.AssociationPropagationPolicy(
    classification_tolerance=1.0e-8
)


def _cad_curving_volume(mesh: Any, geometry: Any) -> float:
    """Volume of mapped P1/P2/P3 tetrahedra.

    The degree-aware finite-element rule integrates their polynomial Jacobian
    determinant exactly.
    """
    field = phx.discretization.FiniteElementFieldSpec(
        "x", phx.discretization.lagrange_element("tetrahedron", 1)
    )
    discretization = phx.discretization.FiniteElementPlan(
        mesh, field, coordinate_spec=geometry
    ).prepare()
    blocks = discretization.evaluate_geometry("x", geometry.coordinates)
    return float(sum(jnp.sum(block.measure) for block in blocks))


def _cad_curving_certificate(certificate: Any) -> dict[str, object]:
    lower = np.asarray(certificate.determinant_lower)
    upper = np.asarray(certificate.determinant_upper)
    return {
        "certificate_id": certificate.certificate_id,
        "certified_valid": certificate.certified_valid_count,
        "invalid": certificate.invalid_count,
        "unresolved": certificate.unresolved_count,
        "minimum_determinant_lower_bound": float(np.min(lower)),
        "minimum_lower_to_upper_ratio": float(np.min(lower / upper)),
        "depth_histogram": np.bincount(np.asarray(certificate.depth)).tolist(),
        "retained_bytes": sum(
            array.nbytes
            for array in (
                certificate.status,
                certificate.determinant_lower,
                certificate.determinant_upper,
                certificate.depth,
            )
        ),
    }


def _cad_curving_association(mesh: Any, projection: Any) -> Any:
    """Vertex association plus completeness and ambiguity of every entity level."""
    vertices, vertex_record = _measured(
        lambda: phx.meshing.associate_mesh_vertices(
            mesh, projection, policy=_CAD_CURVING_ASSOCIATION
        )
    )
    entities, entity_record = _measured(
        lambda: tuple(
            phx.meshing.associate_mesh_entities(
                mesh,
                vertices,
                projection,
                dimension,
                policy=_CAD_CURVING_ASSOCIATION,
            )
            for dimension in (1, 2, 3)
        )
    )
    counts = {
        str(dimension): {
            "association_id": association.association_id,
            "rows": association.target_global_ids.shape[0],
            "resolved": int(np.count_nonzero(np.asarray(association.resolved))),
            "ambiguous": int(np.count_nonzero(np.asarray(association.ambiguous))),
            "maximum_residual": float(np.max(np.asarray(association.residuals))),
        }
        for dimension, association in enumerate((vertices, *entities))
    }
    if any(
        entry["resolved"] != entry["rows"] or entry["ambiguous"]
        for entry in counts.values()
    ):
        raise RuntimeError("cad-curving: a mesh entity has no unique B-Rep class.")
    tolerance = _CAD_CURVING_ASSOCIATION.classification_tolerance
    maximum_residual = counts["0"]["maximum_residual"]
    if not isinstance(maximum_residual, float):
        raise TypeError("CAD vertex association residual must be a measured scalar.")
    if maximum_residual > tolerance:
        raise RuntimeError("cad-curving: a mesh vertex lies off its B-Rep class.")
    return vertices, counts, {"vertices": vertex_record, "entities": entity_record}


def _cad_curving_degree(
    mesh: Any, association: Any, projection: Any, degree: Any, exact_volume: Any
) -> Any:
    """Curve, independently certify, and measure one geometry degree."""
    policy = phx.meshing.HighOrderCurvingPolicy(degree=degree)
    curved, curving_record = _measured(
        lambda: phx.meshing.curve_cell_mesh(mesh, association, projection, policy=policy)
    )

    if curved.status is not phx.meshing.HighOrderCurvingStatus.CURVED:
        raise RuntimeError(f"cad-curving: P{degree} ended with {curved.status}.")
    certificate, certification_record = _measured(
        lambda: phx.discretization.certify_cell_geometry_validity(
            curved.geometry,
            mesh=mesh,
        )
    )
    valid = phx.discretization.CellValidityStatus.CERTIFIED_VALID

    if not np.all(np.asarray(certificate.status) == valid):
        raise RuntimeError(f"cad-curving: a P{degree} cell is not certified valid.")

    if certificate.certificate_id != curved.evidence.certificate.certificate_id:
        raise RuntimeError("cad-curving: recertification differs from curving evidence.")

    if curved.evidence.maximum_residual > policy.residual_tolerance:
        raise RuntimeError(f"cad-curving: P{degree} nodes lie off the B-Rep.")
    straight = phx.meshing.verify_curved_geometry(
        curved.straight,
        mesh,
        association,
        projection,
        policy=policy,
    )
    if straight.accepted:
        raise RuntimeError("cad-curving: straight nodes lie on the curved B-Rep.")
    volumes, volume_record = _measured(
        lambda: (
            _cad_curving_volume(mesh, curved.straight),
            _cad_curving_volume(mesh, curved.geometry),
        )
    )
    errors = tuple(abs(volume - exact_volume) / exact_volume for volume in volumes)
    if not errors[1] < 0.25 * errors[0]:
        raise RuntimeError(f"cad-curving: P{degree} did not reduce the volume error.")

    geometry = curved.geometry
    return {
        "target": {
            "result_id": curved.result_id,
            "geometry_layout_id": geometry.geometry_layout_id,
            "evidence_id": curved.evidence.evidence_id,
            "geometry_nodes": geometry.coordinates.shape[0],
        },
        "quality": {
            "before": {
                "minimum_scaled_jacobian": straight.minimum_scaled_jacobian,
                "maximum_distortion": straight.maximum_distortion,
                "certificate": _cad_curving_certificate(straight.certificate),
            },
            "after": {
                "minimum_scaled_jacobian": curved.evidence.minimum_scaled_jacobian,
                "maximum_distortion": curved.evidence.maximum_distortion,
                "certificate": _cad_curving_certificate(certificate),
            },
        },
        "conservation": {
            "exact_volume": exact_volume,
            "straight_volume": volumes[0],
            "curved_volume": volumes[1],
            "straight_relative_error": errors[0],
            "curved_relative_error": errors[1],
            "straight_node_residual": straight.maximum_residual,
            "curved_node_residual": curved.evidence.maximum_residual,
            "residual_tolerance": policy.residual_tolerance,
        },
        "curving": {
            "status": curved.status.value,
            "policy_id": policy.policy_id,
            "relaxation_rounds": len(curved.minimizations),
            "constrained_nodes": int(np.count_nonzero(curved.evidence.constrained)),
        },
        "resources": {
            "curving": curving_record,
            "certification": certification_record,
            "volume": volume_record,
            "geometry_retained_bytes": geometry.coordinates.nbytes
            + sum(routes.nbytes for routes in geometry.geometry_dofs),
        },
    }


def _cad_curving_solid(
    name: Any, shape: Any, exact_volume: Any, size: Any, directory: Path
) -> Any:
    """Gmsh P1 tetrahedra of one OCCT solid curved to P2 and P3 on its B-Rep."""
    contract = phx.SpatialCoordinateContract.si()
    path = directory / f"{name}.brep"
    phx.interchange.persist_occt_shape(shape, path, coordinate_contract=contract)
    model = phx.interchange.import_occt_brep(
        path, coordinate_contract=contract, linear_deflection=0.05, angular_deflection=0.2
    )
    source = phx.geometry.BRepSource(model)
    provider = phx.meshing.GmshProvider()
    scope = provider.whole_scope(source, 3)
    specification = phx.meshing.VolumeMeshingSpec(
        phx.meshing.CellMeshingTarget(
            3, 3, phx.meshing.CellFamilyPolicy(required=("tetrahedron",))
        ),
        scope,
        phx.meshing.VolumeFillStrategy.SIMPLEX,
        size_controls=(
            phx.meshing.UniformSizeControl(
                scope, size, strength=phx.meshing.SizeControlStrength.SOFT
            ),
        ),
    )
    result, meshing_record = _measured(
        lambda: provider.plan(source, specification).execute()
    )

    if not result.audit.passed:
        raise RuntimeError(f"cad-curving: the Gmsh {name} mesh failed its audit.")
    projection, projection_record = _measured(
        lambda: phx.geometry.prepare_brep_projection(model)
    )
    association, counts, association_records = _cad_curving_association(
        result.mesh,
        projection,
    )

    straight_certificate = phx.discretization.certify_cell_geometry_validity(result.mesh)
    degrees = {
        f"P{degree}": _cad_curving_degree(
            result.mesh,
            association,
            projection,
            degree,
            exact_volume,
        )
        for degree in (2, 3)
    }
    return {
        "source": {
            "source_id": model.source_id,
            "source_revision": model.source_revision,
            "source_digest": model.source_digest,
            "model_id": model.model_id,
            "projection_id": projection.projection_id,
            "brep_entity_counts": list(projection.entity_counts),
            "straight": _result_identity(result),
        },
        "target": {key: record["target"] for key, record in degrees.items()},
        "quality": {
            "before": {
                **_quality_summary(result.quality),
                "certificate": _cad_curving_certificate(straight_certificate),
            },
            "after": {key: record["quality"] for key, record in degrees.items()},
        },
        "association": counts,
        "conservation": {key: record["conservation"] for key, record in degrees.items()},
        "curving": {key: record["curving"] for key, record in degrees.items()},
        "resources": {
            "meshing": meshing_record,
            "projection": projection_record,
            "association": association_records,
            **{key: record["resources"] for key, record in degrees.items()},
        },
        "provider": {
            "provider": result.provider.name,
            "version": result.runtime.actual_version,
        },
    }


def qualify_cad_curving() -> dict[str, object]:
    """Certified P2/P3 curving of Gmsh tetrahedra onto OCCT cylinder and sphere B-Reps."""
    from importlib.util import find_spec

    if find_spec("OCP") is None:
        return _missing_dependency(
            "OCP",
            "This explicit CAD comparison requires phydrax[cad-occt-interop].",
        )
    if find_spec("gmsh") is None:
        return _missing_dependency(
            "gmsh",
            "Install the optional Gmsh Python package: "
            "pip install 'phydrax[meshing-gmsh]'.",
        )
    from OCP.BRepPrimAPI import BRepPrimAPI_MakeCylinder, BRepPrimAPI_MakeSphere

    with TemporaryDirectory(prefix="phydrax-cad-curving-") as temporary:
        directory = Path(temporary)
        solids = {
            "cylinder": _cad_curving_solid(
                "cylinder",
                BRepPrimAPI_MakeCylinder(1.0, 2.0).Shape(),
                2.0 * np.pi,
                0.7,
                directory,
            ),
            "sphere": _cad_curving_solid(
                "sphere",
                BRepPrimAPI_MakeSphere(1.0).Shape(),
                4.0 / 3.0 * np.pi,
                0.6,
                directory,
            ),
        }
    fields = ("source", "target", "quality", "association", "conservation", "curving")
    return {
        "status": "passed",
        **{
            field: {name: solid[field] for name, solid in solids.items()}
            for field in fields
        },
        "resources": {name: solid["resources"] for name, solid in solids.items()},
        "runtime": {
            **_runtime_identity(),
            "providers": {name: solid["provider"] for name, solid in solids.items()},
        },
    }


_PREDICATE_ARITY = {"orient2d": 3, "orient3d": 4, "incircle": 4, "insphere": 5}
_PREDICATE_OFFSET = 2.0**40


def _predicate_integers(arrays: tuple[np.ndarray, ...], /) -> tuple[np.ndarray, ...]:
    """Float64 coordinates as exact Python integers on one common binary scale."""
    mantissas, exponents = [], []
    for array in arrays:
        fraction, exponent = np.frexp(array)
        mantissas.append(np.ldexp(fraction, 53).astype(np.int64))
        exponents.append(exponent.astype(np.int64) - 53)
    scale = min(
        np.min(np.where(mantissa != 0, exponent, np.iinfo(np.int64).max))
        for mantissa, exponent in zip(mantissas, exponents, strict=True)
    )
    return tuple(
        np.left_shift(
            mantissa.astype(np.object_),
            np.where(mantissa != 0, exponent - scale, 0).astype(np.object_),
        )
        for mantissa, exponent in zip(mantissas, exponents, strict=True)
    )


def _integer_determinant(rows: list[list[np.ndarray]], /) -> np.ndarray:
    """Laplace expansion of a small matrix whose entries are integer object arrays."""
    if len(rows) == 1:
        return rows[0][0]
    total = np.zeros(rows[0][0].shape, dtype=np.object_)
    for column, entry in enumerate(rows[0]):
        minor = [row[:column] + row[column + 1 :] for row in rows[1:]]
        term = entry * _integer_determinant(minor)
        total = total + term if column % 2 == 0 else total - term
    return total


def _reference_predicate_signs(
    name: str, arrays: tuple[np.ndarray, ...], /
) -> np.ndarray:
    """Predicate signs in the phydrax convention from exact integer arithmetic."""
    points = _predicate_integers(arrays)
    width = arrays[0].shape[-1]
    match name:
        case "orient2d" | "orient3d":
            # det[b - a, c - a(, d - a)]
            determinant = _integer_determinant(
                [
                    [point[:, axis] - points[0][:, axis] for axis in range(width)]
                    for point in points[1:]
                ]
            )
        case "incircle" | "insphere":
            # Lifted rows (p - q, |p - q|^2) against the query q; insphere is
            # positive inside the sphere of a positively oriented tetrahedron.
            rows = [
                [point[:, axis] - points[-1][:, axis] for axis in range(width)]
                for point in points[:-1]
            ]
            determinant = _integer_determinant(
                [row + [sum(value * value for value in row)] for row in rows]
            )
            if name == "insphere":
                determinant = -determinant
        case _:
            raise ValueError(f"Unknown predicate {name!r}.")
    return (determinant > 0).astype(np.int8) - (determinant < 0).astype(np.int8)


def _ulp_steps(values: np.ndarray, steps: np.ndarray, /) -> np.ndarray:
    """Move each coordinate by ``steps`` in {-1, 0, 1} units in the last place."""
    return np.where(
        steps > 0,
        np.nextafter(values, np.inf),
        np.where(steps < 0, np.nextafter(values, -np.inf), values),
    )


def _integer_shell(radius: int, dimension: int, /) -> np.ndarray:
    """Integer points on the circle/sphere of an integer radius, by polar angle."""
    axis = np.arange(-radius, radius + 1)
    grid = np.stack(np.meshgrid(*(axis,) * dimension, indexing="ij"), axis=-1)
    grid = grid.reshape((-1, dimension))
    shell = grid[np.sum(grid * grid, axis=1) == radius * radius].astype(np.float64)
    return shell[np.argsort(np.arctan2(shell[:, 1], shell[:, 0]), kind="stable")]


def _shell_rows(
    shell: np.ndarray,
    simplices: np.ndarray,
    offset: float,
    rng: np.random.Generator,
    /,
) -> tuple[np.ndarray, ...]:
    """Every shell point queried against every simplex, queries moved by one ulp.

    The shell is translated by ``offset``; every coordinate is then nonzero, so a
    one-ulp move never creates a subnormal outside the meshcore exact domain.
    """
    count = shell.shape[0]
    corners = np.repeat(simplices, count, axis=0)
    query = shell[np.tile(np.arange(count), simplices.shape[0])] + offset
    query = _ulp_steps(query, rng.integers(-1, 2, size=query.shape))
    return tuple(
        shell[corners[:, index]] + offset for index in range(simplices.shape[1])
    ) + (query,)


def _predicate_families(
    rng: np.random.Generator, /
) -> dict[str, dict[str, tuple[np.ndarray, ...]]]:
    """Random rows plus adversarial near-degenerate rows for every predicate."""

    def random(arity: int, width: int) -> tuple[np.ndarray, ...]:
        return tuple(rng.standard_normal((2048, width)) for _ in range(arity))

    # Kettner et al.: points near the line y = x and the plane z = y, moved by
    # single ulps of 0.5.
    steps = np.arange(16) * 2.0**-53
    near_line = 0.5 + np.stack(np.meshgrid(steps, steps, indexing="ij"), axis=-1)
    near_line = near_line.reshape((-1, 2))
    steps = np.arange(8) * 2.0**-53
    near_plane = 0.5 + np.stack(np.meshgrid(steps, steps, steps, indexing="ij"), axis=-1)
    near_plane = near_plane.reshape((-1, 3))
    # Exactly collinear/coplanar integer points far from the origin; the last point
    # moves by at most one ulp of 2**40.
    line = rng.integers(-64, 65, size=(3, 512))
    far_line = _PREDICATE_OFFSET + np.stack((line, 2 * line + 1), axis=-1).astype(
        np.float64
    )
    far_line[2, :, 1] = _ulp_steps(far_line[2, :, 1], rng.integers(-1, 2, size=512))
    plane = rng.integers(-64, 65, size=(4, 512, 2))
    far_plane = _PREDICATE_OFFSET + np.concatenate(
        (plane, plane[..., :1] + 2 * plane[..., 1:] + 3), axis=-1
    ).astype(np.float64)
    far_plane[3, :, 2] = _ulp_steps(far_plane[3, :, 2], rng.integers(-1, 2, size=512))
    # Cocircular lattice: every counterclockwise triple of the 12 integer points of
    # the circle of radius 5. Cospherical lattice: positively oriented tetrahedra
    # of the 30 integer points of the sphere of radius 3.
    circle = _integer_shell(5, 2)
    index = np.arange(circle.shape[0])
    first, second, third = np.meshgrid(index, index, index, indexing="ij")
    ordered = (first < second) & (second < third)
    triples = np.stack((first[ordered], second[ordered], third[ordered]), axis=1)
    sphere = _integer_shell(3, 3)
    tetrahedra = np.argsort(rng.random((128, sphere.shape[0])), axis=1)[:, :4]
    orientation = _reference_predicate_signs(
        "orient3d", tuple(sphere[tetrahedra[:, index]] for index in range(4))
    )
    tetrahedra = np.where(
        (orientation < 0)[:, None], tetrahedra[:, (1, 0, 2, 3)], tetrahedra
    )[orientation != 0]
    return {
        "orient2d": {
            "random": random(3, 2),
            "collinear_ulp": (
                near_line,
                np.broadcast_to(np.asarray((12.0, 12.0)), near_line.shape),
                np.broadcast_to(np.asarray((24.0, 24.0)), near_line.shape),
            ),
            "large_offset": tuple(far_line),
        },
        "orient3d": {
            "random": random(4, 3),
            "coplanar_ulp": (
                np.broadcast_to(np.asarray((1.0, 12.0, 12.0)), near_plane.shape),
                np.broadcast_to(np.asarray((24.0, 24.0, 24.0)), near_plane.shape),
                np.broadcast_to(np.asarray((-7.0, 3.0, 3.0)), near_plane.shape),
                near_plane,
            ),
            "large_offset": tuple(far_plane),
        },
        "incircle": {
            "random": random(4, 2),
            "cocircular_lattice": _shell_rows(circle, triples, 0.5, rng),
            "large_offset": _shell_rows(circle, triples, _PREDICATE_OFFSET, rng),
        },
        "insphere": {
            "random": random(5, 3),
            "cospherical_lattice": _shell_rows(sphere, tetrahedra, 0.5, rng),
            "large_offset": _shell_rows(sphere, tetrahedra, _PREDICATE_OFFSET, rng),
        },
    }


def _predicate_family_record(
    routes: dict[str, tuple[np.ndarray, np.ndarray]],
    reference: np.ndarray,
    perturbed: np.ndarray,
    /,
) -> dict[str, object]:
    """Certainty, correctness, agreement, and degeneracy counts of one family."""
    rows = reference.size
    exact = routes["exact"][0]
    record: dict[str, object] = {"rows": rows}
    for route, (signs, certain) in routes.items():
        record[route] = {
            "certain": int(np.count_nonzero(certain)),
            "uncertain_fraction": 1.0 - int(np.count_nonzero(certain)) / rows,
            "certified_zeros": int(np.count_nonzero(certain & (signs == 0))),
            "wrong_certain_signs": int(np.count_nonzero(certain & (signs != reference))),
        }
    pairs = (("filtered", "device"), ("filtered", "exact"), ("device", "exact"))
    record["certain_disagreements"] = {
        f"{first}_{second}": int(
            np.count_nonzero(
                routes[first][1]
                & routes[second][1]
                & (routes[first][0] != routes[second][0])
            )
        )
        for first, second in pairs
    }
    record["exact_signs"] = {
        "negative": int(np.count_nonzero(exact == -1)),
        "zero": int(np.count_nonzero(exact == 0)),
        "positive": int(np.count_nonzero(exact == 1)),
    }
    record["reference_zeros"] = int(np.count_nonzero(reference == 0))
    record["symbolic"] = {
        "zeros": int(np.count_nonzero(perturbed == 0)),
        "changed_strict_signs": int(
            np.count_nonzero((exact != 0) & (perturbed != exact))
        ),
    }
    return record


def _qualify_predicate(
    name: str, families: dict[str, tuple[np.ndarray, ...]], /
) -> tuple[dict[str, object], dict[str, object], np.ndarray, int]:
    """Evaluate one predicate in every mode on all families against the reference."""
    from phydrax._meshcore import (
        symbolic_incircle,
        symbolic_insphere,
        symbolic_orient2d,
        symbolic_orient3d,
    )

    function = {
        "orient2d": phx.geometry.orient2d,
        "orient3d": phx.geometry.orient3d,
        "incircle": phx.geometry.incircle,
        "insphere": phx.geometry.insphere,
    }[name]
    mode = phx.geometry.PredicateMode
    arity = _PREDICATE_ARITY[name]
    arrays = tuple(
        np.concatenate([rows[index] for rows in families.values()])
        for index in range(arity)
    )
    bounds = np.cumsum([0, *(rows[0].shape[0] for rows in families.values())])
    filtered, filtered_stage = _measured(lambda: function(*arrays, mode=mode.FILTERED))
    device_entry = jax.jit(lambda *values: function(*values, mode=mode.FILTERED_DEVICE))
    device_arrays = tuple(jnp.asarray(array) for array in arrays)
    _, device_cold = _measured(
        lambda: jax.block_until_ready(device_entry(*device_arrays))
    )
    device, device_warm = _measured(
        lambda: jax.block_until_ready(device_entry(*device_arrays))
    )
    exact, exact_stage = _measured(lambda: function(*arrays, mode=mode.EXACT))
    reference, reference_stage = _measured(
        lambda: np.concatenate(
            [_reference_predicate_signs(name, rows) for rows in families.values()]
        )
    )
    swapped = function(arrays[1], arrays[0], *arrays[2:], mode=mode.EXACT).signs
    # Distinct ids: the index-ordered perturbation used inside the triangulations.
    identifiers = np.arange(arity, dtype=np.int64)
    match name:
        case "orient2d":
            perturbed = symbolic_orient2d(arrays[0], arrays[1], arrays[2], identifiers)
        case "orient3d":
            perturbed = symbolic_orient3d(
                arrays[0], arrays[1], arrays[2], arrays[3], identifiers
            )
        case "incircle":
            perturbed = symbolic_incircle(
                arrays[0], arrays[1], arrays[2], arrays[3], identifiers
            )
        case "insphere":
            perturbed = symbolic_insphere(
                arrays[0], arrays[1], arrays[2], arrays[3], arrays[4], identifiers
            )
        case _:
            raise ValueError(f"Unknown predicate qualification: {name}.")
    routes: dict[str, tuple[np.ndarray, np.ndarray]] = {
        "filtered": (np.asarray(filtered.signs), np.asarray(filtered.certain)),
        "device": (np.asarray(device.signs), np.asarray(device.certain)),
        "exact": (np.asarray(exact.signs), np.asarray(exact.certain)),
    }
    records: dict[str, object] = {
        family: _predicate_family_record(
            {
                route: (signs[start:stop], certain[start:stop])
                for route, (signs, certain) in routes.items()
            },
            reference[start:stop],
            perturbed[start:stop],
        )
        for family, start, stop in zip(families, bounds[:-1], bounds[1:], strict=True)
    }
    resources: dict[str, object] = {
        "filtered": filtered_stage,
        "device_cold": device_cold,
        "device_warm": device_warm,
        "exact": exact_stage,
        "exact_native_rows": int(np.count_nonzero(~filtered.certain)),
        "integer_reference": reference_stage,
    }
    return (
        records,
        resources,
        np.asarray(exact.signs),
        int(np.count_nonzero(swapped != -exact.signs)),
    )


def _predicate_failures(name: str, family: str, record: dict, /) -> list[str]:
    """Failed checks of one family record (empty when the family qualifies)."""
    routes = ("filtered", "device", "exact")
    failures = [
        f"{route} certified {record[route]['wrong_certain_signs']} wrong signs"
        for route in routes
        if record[route]["wrong_certain_signs"]
    ]
    failures += [
        f"{pair} disagree on {count} certain rows"
        for pair, count in record["certain_disagreements"].items()
        if count
    ]
    if record["exact"]["certain"] != record["rows"]:
        failures.append("EXACT left uncertain rows")
    if record["exact_signs"]["zero"] != record["reference_zeros"]:
        failures.append("EXACT zeros differ from the exact degeneracies")
    if record["symbolic"]["zeros"] or record["symbolic"]["changed_strict_signs"]:
        failures.append("symbolic perturbation left ties or changed a strict sign")
    if family == "random":
        if min(record["filtered"]["certain"], record["device"]["certain"]) < (
            0.9 * record["rows"]
        ):
            failures.append("filters left more than 10% of random rows uncertain")
    elif min(record["exact_signs"].values()) == 0:
        failures.append("adversarial rows miss an exact zero or a strict sign")
    return [f"{name}/{family}: {failure}" for failure in failures]


def qualify_predicates() -> dict[str, object]:
    if not meshcore_available():
        return _missing_dependency(
            "meshcore",
            "EXACT predicates and the symbolic tie-breaking require the native "
            "meshcore library; install phydrax[meshcore] or set "
            "PHYDRAX_MESHCORE_LIBRARY to the shared library path.",
        )
    from phydrax._meshcore import meshcore_exact_domain

    families = _predicate_families(np.random.default_rng(20260926))
    records, resources, exact_signs, antisymmetry = {}, {}, {}, {}
    for name, rows in families.items():
        records[name], resources[name], exact_signs[name], antisymmetry[name] = (
            _qualify_predicate(name, rows)
        )
    failures = [
        failure
        for name, per_family in records.items()
        for family, record in per_family.items()
        for failure in _predicate_failures(name, family, record)
    ]
    failures += [
        f"{name}: {count} exact signs are not antisymmetric under argument exchange"
        for name, count in antisymmetry.items()
        if count
    ]
    if failures:
        raise RuntimeError("Predicate qualification failed: " + "; ".join(failures))
    flat = [record for per_family in records.values() for record in per_family.values()]
    rows = sum(record["rows"] for record in flat)

    def total(route: str, key: str) -> int:
        return sum(record[route][key] for record in flat)

    return {
        "status": "passed",
        "source": {
            "inputs_id": canonical_fingerprint(families),
            "rows": {
                name: {family: record["rows"] for family, record in per_family.items()}
                for name, per_family in records.items()
            },
        },
        "target": {"exact_signs_id": canonical_fingerprint(exact_signs), "rows": rows},
        "runtime": {
            **_runtime_identity(),
            "meshcore_exact_exponent_range": list(meshcore_exact_domain()),
        },
        "quality": {
            "before": {
                "filtered_certain_fraction": total("filtered", "certain") / rows,
                "device_certain_fraction": total("device", "certain") / rows,
            },
            "after": {
                "exact_certain_fraction": total("exact", "certain") / rows,
                "exact_wrong_signs": total("exact", "wrong_certain_signs"),
            },
        },
        "conservation": {
            "antisymmetry_violations": antisymmetry,
            "wrong_certain_signs": {
                route: total(route, "wrong_certain_signs")
                for route in ("filtered", "device", "exact")
            },
            "certain_disagreements": sum(
                sum(record["certain_disagreements"].values()) for record in flat
            ),
        },
        "degeneracy_semantics": {
            # EXACT reports exact zeros; only the triangulations break ties, by
            # index-ordered symbolic perturbation.
            "exact_mode": "exact-zero",
            "triangulation_ties": "index-ordered-symbolic-perturbation",
            "exact_zero_rows": sum(record["exact_signs"]["zero"] for record in flat),
            "reference_zero_rows": sum(record["reference_zeros"] for record in flat),
            "symbolic_zero_rows": sum(record["symbolic"]["zeros"] for record in flat),
        },
        "resources": resources,
        "predicates": records,
    }


def _simplex_measures(points: np.ndarray, simplices: np.ndarray, /) -> np.ndarray:
    """Signed planar area/volume; positive area for immersed triangles."""
    edges = points[simplices[:, 1:]] - points[simplices[:, :1]]
    if points.shape[1] == 2:
        return 0.5 * (edges[:, 0, 0] * edges[:, 1, 1] - edges[:, 0, 1] * edges[:, 1, 0])
    if simplices.shape[1] == 3:
        return 0.5 * np.linalg.norm(np.cross(edges[:, 0], edges[:, 1]), axis=1)
    return np.sum(edges[:, 0] * np.cross(edges[:, 1], edges[:, 2]), axis=1) / 6.0


def _delaunay_record(points: np.ndarray, /) -> dict[str, object]:
    """Exact orientation, empty-ball, hull-coverage, and repeat checks of one set."""
    from scipy.spatial import ConvexHull

    exact = phx.geometry.PredicateMode.EXACT
    triangulation, stage = _measured(lambda: phx.geometry.DelaunayTriangulation(points))

    simplices = triangulation.simplices
    corners = tuple(points[simplices[:, index]] for index in range(simplices.shape[1]))
    # Every (simplex, point) pair.
    balls = tuple(corner[:, None, :] for corner in corners)
    if points.shape[1] == 2:
        orientation = phx.geometry.orient2d(*corners, mode=exact)
        inside = phx.geometry.incircle(
            balls[0], balls[1], balls[2], points[None], mode=exact
        )
    else:
        orientation = phx.geometry.orient3d(*corners, mode=exact)
        inside = phx.geometry.insphere(
            balls[0], balls[1], balls[2], balls[3], points[None], mode=exact
        )
    hull = ConvexHull(points).volume
    measure = float(np.sum(_simplex_measures(points, simplices)))
    repeated = phx.geometry.DelaunayTriangulation(points)

    evidence = triangulation.evidence
    record = {
        "points": points.shape[0],
        "simplices": simplices.shape[0],
        "simplices_id": canonical_fingerprint(simplices),
        "evidence_id": evidence.evidence_id,
        "route": evidence.route,
        "status": evidence.status,
        "predicate_mode": evidence.predicate_mode.value,
        "positive_orientations": int(np.count_nonzero(orientation.signs == 1)),
        "in_ball_checks": inside.signs.size,
        "empty_ball_violations": int(np.count_nonzero(inside.signs > 0)),
        # Zero signs beyond each simplex's own vertices are cocircular/cospherical ties.
        "cospherical_ties": int(np.count_nonzero(inside.signs == 0)) - simplices.size,
        "hull_measure": hull,
        "measure": measure,
        "relative_hull_residual": abs(measure - hull) / hull,
        "repeat_equal": bool(
            np.array_equal(repeated.simplices, simplices)
            and repeated.evidence.evidence_id == evidence.evidence_id
        ),
        "resources": stage,
    }
    if (
        not (np.all(orientation.certain) and np.all(inside.certain))
        or record["positive_orientations"] != simplices.shape[0]
        or record["empty_ball_violations"]
        or record["relative_hull_residual"] > 1.0e-12
        or not record["repeat_equal"]
        or evidence.status != "ok"
    ):
        raise RuntimeError(f"{evidence.route} verification failed: {record}")
    return record


def _duplicate_record(rng: np.random.Generator, dimension: int, /) -> dict[str, object]:
    """Duplicated points map to their first copy and never become vertices or cells."""
    count, copies = 48, 8
    base = rng.random((count, dimension))
    chosen = np.sort(rng.choice(count, size=copies, replace=False))
    points = np.concatenate((base, base[chosen]))
    triangulation = phx.geometry.DelaunayTriangulation(points)
    unique = phx.geometry.DelaunayTriangulation(base)
    voronoi = phx.geometry.VoronoiDiagram(
        points,
        box_lower=np.zeros((dimension,), dtype=np.float64),
        box_upper=np.ones((dimension,), dtype=np.float64),
    )
    measures = voronoi.cells.measures
    record = {
        "input_points": points.shape[0],
        "duplicate_count": triangulation.evidence.duplicate_count,
        "vertex_count": triangulation.evidence.vertex_count,
        "vertex_map_to_first_copy": bool(
            np.array_equal(
                triangulation.vertex_map, np.concatenate((np.arange(count), chosen))
            )
        ),
        "duplicates_in_simplices": int(
            np.count_nonzero(triangulation.simplices >= count)
        ),
        "simplices_equal_unique_input": bool(
            np.array_equal(triangulation.simplices, unique.simplices)
        ),
        "voronoi_duplicate_count": voronoi.evidence.duplicate_count,
        "voronoi_duplicate_measure": float(np.sum(measures[count:])),
        "voronoi_measure_sum": float(np.sum(measures)),
    }
    if (
        record["duplicate_count"] != copies
        or record["voronoi_duplicate_count"] != copies
        or not record["vertex_map_to_first_copy"]
        or record["duplicates_in_simplices"]
        or not record["simplices_equal_unique_input"]
        or record["voronoi_duplicate_measure"] != 0.0
        or abs(record["voronoi_measure_sum"] - 1.0) > 1.0e-12
    ):
        raise RuntimeError(f"{dimension}D duplicate handling failed: {record}")
    return record


def _segment_conformity(
    triangulation: phx.geometry.ConstrainedDelaunayTriangulation,
    segments: np.ndarray,
    /,
) -> dict[str, object]:
    """Exact collinearity and length coverage of the edges carrying each segment."""
    points, triangles = triangulation.points, triangulation.triangles
    cells, corners = np.nonzero(triangulation.segment_ids >= 0)
    edges = np.sort(
        np.stack(
            (triangles[cells, (corners + 1) % 3], triangles[cells, (corners + 2) % 3]),
            axis=1,
        ),
        axis=1,
    )
    carried = np.unique(
        np.column_stack((triangulation.segment_ids[cells, corners], edges)), axis=0
    )
    owner, first, second = carried.T
    start, stop = points[segments[owner, 0]], points[segments[owner, 1]]
    on_line = phx.geometry.orient2d(
        np.concatenate((start, start)),
        np.concatenate((stop, stop)),
        np.concatenate((points[first], points[second])),
        mode=phx.geometry.PredicateMode.EXACT,
    )
    lengths = np.linalg.norm(points[second] - points[first], axis=1)
    covered = np.bincount(owner, weights=lengths, minlength=segments.shape[0])
    expected = np.linalg.norm(points[segments[:, 1]] - points[segments[:, 0]], axis=1)
    return {
        "segments": segments.shape[0],
        "carried_edges": carried.shape[0],
        "uncovered_segments": int(np.count_nonzero(covered == 0.0)),
        "off_segment_endpoints": int(np.count_nonzero(on_line.signs != 0)),
        "maximum_relative_length_defect": float(
            np.max(np.abs(covered - expected) / expected)
        ),
    }


def _constrained_record() -> tuple[
    dict[str, object], phx.meshing.CellMeshingResult, phx.meshing.CellMeshingResult
]:
    """Plate with a hole and an interior crack: CDT, refinement, and certification."""
    points = np.asarray(
        (
            (0.0, 0.0),
            (2.0, 0.0),
            (2.0, 2.0),
            (0.0, 2.0),
            (0.75, 0.75),
            (1.25, 0.75),
            (1.25, 1.25),
            (0.75, 1.25),
            (0.25, 0.4),
            (1.75, 0.4),
        )
    )
    loop = np.arange(4, dtype=np.int32)
    ring = np.stack((loop, (loop + 1) % 4), axis=1)
    segments = np.concatenate((ring, 4 + ring, np.asarray(((8, 9),), dtype=np.int32)))
    holes = np.asarray(((1.0, 1.0),))
    min_angle, max_area = 28.0, 0.02

    def triangulate(max_steiner: int, refine: bool) -> Any:
        return phx.geometry.ConstrainedDelaunayTriangulation(
            points,
            segments,
            holes=holes,
            min_angle=min_angle if refine else 0.0,
            max_area=max_area if refine else np.inf,
            max_steiner=max_steiner,
        )

    unrefined, unrefined_stage = _measured(lambda: triangulate(0, False))
    refined, refined_stage = _measured(lambda: triangulate(4000, True))
    limited = triangulate(1, True)
    repeated = triangulate(4000, True)

    areas = _simplex_measures(refined.points, refined.triangles)
    orientation = phx.geometry.orient2d(
        *(refined.points[refined.triangles[:, index]] for index in range(3)),
        mode=phx.geometry.PredicateMode.EXACT,
    )

    def certify(triangulation: Any) -> Any:
        return phx.meshing.certify_cell_mesh(
            phx.discretization.CellMesh.from_triangles(
                triangulation.points, triangulation.triangles
            ),
            _contract(),
        )

    before, before_stage = _measured(lambda: certify(unrefined))
    after, after_stage = _measured(lambda: certify(refined))
    plate_area = 4.0 - 0.25
    record = {
        "status": refined.evidence.status,
        "route": refined.evidence.route,
        "predicate_mode": refined.evidence.predicate_mode.value,
        "requested_minimum_angle_degrees": min_angle,
        "minimum_angle_degrees": refined.evidence.minimum_angle_degrees,
        "unrefined_minimum_angle_degrees": unrefined.evidence.minimum_angle_degrees,
        "certified_minimum_angle_degrees": float(np.degrees(after.quality.minimum_angle)),
        "requested_maximum_area": max_area,
        "maximum_area": float(np.max(areas)),
        "relative_area_residual": abs(float(np.sum(areas)) - plate_area) / plate_area,
        "positive_orientations": int(np.count_nonzero(orientation.signs == 1)),
        "triangles": refined.triangles.shape[0],
        "unrefined_triangles": unrefined.triangles.shape[0],
        "steiner_points": refined.evidence.steiner_count,
        "conformity": _segment_conformity(refined, segments),
        "unrefined_conformity": _segment_conformity(unrefined, segments),
        "limited_status": limited.evidence.status,
        "limited_steiner_points": limited.evidence.steiner_count,
        "evidence_id": refined.evidence.evidence_id,
        "repeat_equal": bool(
            repeated.evidence.evidence_id == refined.evidence.evidence_id
            and np.array_equal(repeated.points, refined.points)
            and np.array_equal(repeated.triangles, refined.triangles)
        ),
        "resources": {
            "unrefined": unrefined_stage,
            "refined": refined_stage,
            "certify_unrefined": before_stage,
            "certify_refined": after_stage,
        },
    }
    conformity = (record["conformity"], record["unrefined_conformity"])
    if (
        record["status"] != "ok"
        or record["minimum_angle_degrees"] < min_angle
        or record["maximum_area"] > max_area
        or record["relative_area_residual"] > 1.0e-12
        or record["positive_orientations"] != record["triangles"]
        or any(
            item["uncovered_segments"]
            or item["off_segment_endpoints"]
            or _record_float(
                item["maximum_relative_length_defect"], "CDT segment length defect"
            )
            > 1.0e-12
            for item in conformity
        )
        or record["limited_status"] != "refinement_limit"
        or record["limited_steiner_points"] > 1
        or not record["repeat_equal"]
        or not (before.audit.passed and after.audit.passed)
        or record["certified_minimum_angle_degrees"] < min_angle * (1.0 - 1.0e-12)
    ):
        raise RuntimeError(f"Constrained Delaunay qualification failed: {record}")
    return record, before, after


def _reciprocal_faces(cells: phx.geometry.DiagramCells, /) -> bool:
    """Every interior face (owner, neighbor) has the opposite face (neighbor, owner)."""
    owners = np.repeat(np.arange(cells.cell_count), np.diff(cells.cell_face_offsets))
    interior = cells.face_labels >= 0
    forward = np.unique(
        np.stack((owners[interior], cells.face_labels[interior]), axis=1), axis=0
    )
    return bool(np.array_equal(forward, np.unique(forward[:, ::-1], axis=0)))


def _diagram_record(
    diagram: Any, repeated: Any, lower: np.ndarray, upper: np.ndarray, stage: dict, /
) -> dict[str, object]:
    """Box coverage, reciprocity, centroid, and repeat checks of one diagram."""
    cells, evidence = diagram.cells, diagram.evidence
    box = float(np.prod(upper - lower))
    total = float(np.sum(cells.measures))
    occupied = cells.measures > 0.0
    centroids = cells.centroids[occupied]
    record = {
        "route": evidence.route,
        "predicate_mode": evidence.predicate_mode.value,
        "evidence_id": evidence.evidence_id,
        "measures_id": canonical_fingerprint(cells.measures),
        "cells": cells.cell_count,
        "empty_cells": int(np.count_nonzero(~occupied)),
        "redundant_generators": evidence.redundant_count,
        "dual_simplices": evidence.simplex_count,
        "box_measure": box,
        "measure_sum": total,
        "relative_box_residual": abs(total - box) / box,
        "reciprocal_faces": _reciprocal_faces(cells),
        "centroids_inside_box": bool(np.all((centroids >= lower) & (centroids <= upper))),
        "repeat_equal": bool(
            repeated.evidence.evidence_id == evidence.evidence_id
            and np.array_equal(repeated.cells.vertices, cells.vertices)
        ),
        "resources": stage,
    }
    if (
        record["relative_box_residual"] > 1.0e-12
        or np.any(cells.measures < 0.0)
        or not record["reciprocal_faces"]
        or not record["centroids_inside_box"]
        or not record["repeat_equal"]
    ):
        raise RuntimeError(f"{evidence.route} qualification failed: {record}")
    return record


def _diagram_pair(
    rng: np.random.Generator, dimension: int, count: int, /
) -> dict[str, dict[str, object]]:
    """Voronoi and weighted power diagrams of one generator set in a box."""
    lower = np.zeros((dimension,), dtype=np.float64)
    upper = np.asarray((1.0, 2.0, 1.0)[:dimension], dtype=np.float64)
    generators = lower + (upper - lower) * rng.random((count, dimension))
    weights = 0.01 * rng.random(count)
    voronoi, voronoi_stage = _measured(
        lambda: phx.geometry.VoronoiDiagram(generators, box_lower=lower, box_upper=upper)
    )
    power, power_stage = _measured(
        lambda: phx.geometry.PowerDiagram(
            generators, weights, box_lower=lower, box_upper=upper
        )
    )
    unweighted = phx.geometry.PowerDiagram(
        generators,
        np.zeros((count,), dtype=np.float64),
        box_lower=lower,
        box_upper=upper,
    )
    voronoi_record = _diagram_record(
        voronoi,
        phx.geometry.VoronoiDiagram(generators, box_lower=lower, box_upper=upper),
        lower,
        upper,
        voronoi_stage,
    )

    deviation = float(np.max(np.abs(unweighted.cells.measures - voronoi.cells.measures)))
    voronoi_record["unweighted_power_maximum_deviation"] = deviation

    if deviation > 1.0e-10 * float(np.max(voronoi.cells.measures)):
        raise RuntimeError("Unweighted power cells differ from the Voronoi cells.")
    return {
        f"voronoi_{dimension}d": voronoi_record,
        f"power_{dimension}d": _diagram_record(
            power,
            phx.geometry.PowerDiagram(
                generators, weights, box_lower=lower, box_upper=upper
            ),
            lower,
            upper,
            power_stage,
        ),
    }


def qualify_triangulation() -> dict[str, object]:
    if not meshcore_available():
        return _missing_dependency(
            "meshcore",
            "Exact triangulations and diagrams require the native meshcore library; "
            "install phydrax[meshcore] or set PHYDRAX_MESHCORE_LIBRARY to the shared "
            "library path.",
        )
    rng = np.random.default_rng(20260927)
    lattice_2d = np.stack(np.meshgrid(*(np.arange(6.0),) * 2, indexing="ij"), axis=-1)
    lattice_3d = np.stack(np.meshgrid(*(np.arange(4.0),) * 3, indexing="ij"), axis=-1)
    delaunay = {
        "random_2d": _delaunay_record(rng.random((200, 2))),
        "lattice_2d": _delaunay_record(lattice_2d.reshape((-1, 2))),
        "random_3d": _delaunay_record(rng.random((60, 3))),
        "lattice_3d": _delaunay_record(lattice_3d.reshape((-1, 3))),
    }
    duplicates = {
        f"{dimension}d": _duplicate_record(rng, dimension) for dimension in (2, 3)
    }
    constrained, unrefined, refined = _constrained_record()
    diagrams = {**_diagram_pair(rng, 2, 64), **_diagram_pair(rng, 3, 40)}
    # A zero-weight generator inside the heavy triangle is redundant: no cell.
    hidden = phx.geometry.PowerDiagram(
        np.asarray(((0.2, 0.2), (0.8, 0.2), (0.5, 0.8), (0.5, 0.4))),
        np.asarray((1.0, 1.0, 1.0, 0.0)),
        box_lower=(0.0, 0.0),
        box_upper=(1.0, 1.0),
    )
    dual_vertex_map = hidden.dual_vertex_map
    if dual_vertex_map is None:
        raise RuntimeError(
            "Redundant-generator qualification requires its regular-triangulation vertex map."
        )
    redundant = {
        "redundant_count": hidden.evidence.redundant_count,
        "dual_vertex_map": dual_vertex_map.tolist(),
        "redundant_measure": float(hidden.cells.measures[3]),
        "measure_sum": float(np.sum(hidden.cells.measures)),
    }
    if (
        redundant["redundant_count"] != 1
        or redundant["dual_vertex_map"][3] != -1
        or redundant["redundant_measure"] != 0.0
        or abs(redundant["measure_sum"] - 1.0) > 1.0e-12
    ):
        raise RuntimeError(f"Redundant power generator was not hidden: {redundant}")
    resources = {
        **{
            f"delaunay_{name}": record.pop("resources")
            for name, record in delaunay.items()
        },
        **{
            f"constrained_{name}": stage
            for name, stage in _record_mapping(
                constrained.pop("resources"), "Constrained triangulation resources"
            ).items()
        },
        **{name: record.pop("resources") for name, record in diagrams.items()},
    }
    return {
        "status": "passed",
        "source": {
            "constrained_unrefined": _result_identity(unrefined),
            "delaunay_simplices": {
                name: record["simplices_id"] for name, record in delaunay.items()
            },
        },
        "target": {
            "constrained_refined": _result_identity(refined),
            "evidence": {
                **{name: record["evidence_id"] for name, record in delaunay.items()},
                "constrained": constrained["evidence_id"],
                **{name: record["evidence_id"] for name, record in diagrams.items()},
            },
        },
        "runtime": _runtime_identity(),
        "quality": {
            "before": _quality_summary(unrefined.quality),
            "after": _quality_summary(refined.quality),
        },
        "conservation": {
            "delaunay_relative_hull_residual": {
                name: record["relative_hull_residual"]
                for name, record in delaunay.items()
            },
            "constrained_relative_area_residual": constrained["relative_area_residual"],
            "diagram_relative_box_residual": {
                name: record["relative_box_residual"] for name, record in diagrams.items()
            },
        },
        "determinism": {
            **{name: record["repeat_equal"] for name, record in delaunay.items()},
            "constrained": constrained["repeat_equal"],
            **{name: record["repeat_equal"] for name, record in diagrams.items()},
        },
        "resources": resources,
        "delaunay": delaunay,
        "duplicates": duplicates,
        "constrained": constrained,
        "diagrams": diagrams,
        "redundant_power_generator": redundant,
    }


def _corpus_domain(case: MeshingCase) -> Any:
    """Independently describe the analytic domain, not the generated boundary."""
    payload = source_payload(case)
    if case.name in ("plc-nonconvex", "plc-thin-channel"):
        # Independent cuboid decomposition, not a fan of the concave source cap.
        from tools._meshing_cases import _box_union_payload

        payload = _box_union_payload(case)
    if case.dimension == 2:
        facets = [
            (loop[i], loop[(i + 1) % len(loop)])
            for loop in payload["loops"]
            for i in range(len(loop))
        ]
        pairs = [(0, -1)] * len(facets)
    else:
        facets = []
        pairs = []
        for polygon, facet in zip(payload["polygons"], payload["facets"], strict=True):
            for i in range(1, len(polygon) - 1):
                facets.append((polygon[0], polygon[i], polygon[i + 1]))
                # PLC incidence is (positive, negative); the coverage owner uses
                # normal direction from its first region into its second.
                pairs.append(payload["facet_regions"][facet][::-1])
    return phx.geometry.PiecewiseLinearDomain(
        np.asarray(payload["vertices"], dtype=np.float64),
        np.asarray(facets, dtype=np.int64),
        np.asarray(pairs, dtype=np.int64),
        tuple(name for name, _ in case.expected_regions),
        source_id=str(corpus_identity(case)["source_revision"]),
    )


def _embedded_feature_coverage(
    case: MeshingCase,
    mesh: phx.discretization.CellMesh,
) -> dict[str, object]:
    payload = source_payload(case)
    if case.dimension == 2:
        features = np.asarray(payload["embedded"], dtype=np.float64)
        segments = (
            features[None, :, :]
            if features.size
            else np.empty((0, 2, 2), dtype=np.float64)
        )
    else:
        segments = np.asarray(payload["vertices"], dtype=np.float64)[payload["segments"]]
    points = np.asarray(mesh.coordinates, dtype=np.float64)
    connectivity = mesh.connectivity
    if not isinstance(
        connectivity,
        (
            phx.discretization.PolygonalConnectivity,
            phx.discretization.TetrahedralConnectivity,
        ),
    ):
        raise TypeError(
            "Corpus feature coverage requires triangle or tetrahedral connectivity."
        )
    edges = points[np.asarray(connectivity.edges)]
    failures = []
    for index, segment in enumerate(segments):
        direction = segment[1] - segment[0]
        length_squared = np.sum(direction * direction)
        parameters = ((edges - segment[0]) @ direction) / length_squared
        projected = segment[0] + parameters[..., None] * direction
        on_source = np.all(np.linalg.norm(edges - projected, axis=-1) <= 1.0e-12, axis=1)
        contained = np.all(
            (parameters >= -1.0e-12) & (parameters <= 1.0 + 1.0e-12), axis=1
        )
        intervals = np.sort(parameters[on_source & contained], axis=1)
        intervals = intervals[np.argsort(intervals[:, 0], kind="stable")]
        endpoint = 0.0
        for lower, upper in intervals:
            if abs(lower - endpoint) > 1.0e-12 or upper <= lower:
                failures.append(index)
                break
            endpoint = float(upper)
        if abs(endpoint - 1.0) > 1.0e-12:
            failures.append(index)
    return {
        "passed": not failures,
        "source_segments": segments.shape[0],
        "uncovered_or_multiply_covered_segments": sorted(set(failures)),
    }


def _material_semantics(
    case: MeshingCase,
    result: phx.meshing.CellMeshingResult,
    regions: np.ndarray,
) -> dict[str, object]:
    """Recount declared material assignments and the shared interface scope."""
    mesh = result.mesh
    zones = {
        zone.name: zone
        for zone in result.zones
        if zone.role is phx.meshing.MeshZoneRole.REGION
    }
    expected = {name for name, _ in case.expected_regions}
    passed = set(zones) == expected
    identifiers = np.concatenate([np.asarray(block.global_ids) for block in mesh.blocks])
    for index, (name, _) in enumerate(case.expected_regions):
        if name not in zones:
            passed = False
            continue
        zone = zones[name]
        passed = passed and (
            zone.material_id == f"{name}-material"
            and zone.region_role is phx.meshing.RegionRole.SOLID
            and np.array_equal(
                np.sort(zone.scope.entity_ids), np.sort(identifiers[regions == index])
            )
        )
    connectivity = mesh.connectivity
    if not isinstance(connectivity, phx.discretization.TetrahedralConnectivity):
        raise TypeError("The material cavity corpus requires tetrahedral connectivity.")
    points = np.asarray(mesh.coordinates, dtype=np.float64)
    corners = points[np.asarray(connectivity.faces)]
    payload = source_payload(case)
    patches = {patch.name: patch for patch in result.patches}
    face_ids = np.asarray(mesh.entity_set(2).entity_ids)
    patch_passed = True
    area = 0.0
    for facet, pair in enumerate(payload["facet_regions"]):
        if min(pair) < 0:
            continue
        selected_polygons = [
            polygon
            for polygon, identity in zip(
                payload["polygons"], payload["facets"], strict=True
            )
            if identity == facet
        ]
        selected = np.zeros(corners.shape[0], dtype=bool)
        expected_area = 0.0
        for polygon in selected_polygons:
            reference = np.asarray(payload["vertices"], dtype=np.float64)[polygon]
            normal = np.cross(reference[1] - reference[0], reference[2] - reference[0])
            norm = np.linalg.norm(normal)
            normal /= norm
            coplanar = np.all(
                np.abs((corners - reference[0]) @ normal) <= 1.0e-12, axis=1
            )
            bounded = np.all(
                (corners >= reference.min(axis=0) - 1.0e-12)
                & (corners <= reference.max(axis=0) + 1.0e-12),
                axis=(1, 2),
            )
            selected |= coplanar & bounded
            expected_area += sum(
                0.5
                * np.linalg.norm(
                    np.cross(reference[i] - reference[0], reference[i + 1] - reference[0])
                )
                for i in range(1, len(reference) - 1)
            )
        measured_area = float(
            0.5
            * np.linalg.norm(
                np.cross(
                    corners[selected, 1] - corners[selected, 0],
                    corners[selected, 2] - corners[selected, 0],
                ),
                axis=1,
            ).sum()
        )
        area += measured_area
        name = (
            "left-right-interface"
            if case.name == "plc-material-cavity"
            else f"interface-{facet}"
        )
        patch = patches.get(name)
        adjacent = {
            zones[case.expected_regions[index][0]].zone_id
            for index in pair
            if case.expected_regions[index][0] in zones
        }
        patch_passed = patch_passed and (
            patch is not None
            and np.array_equal(
                np.sort(patch.scope.entity_ids), np.sort(face_ids[selected])
            )
            and set(patch.adjacent_zone_ids) == adjacent
            and abs(measured_area - expected_area) <= 1.0e-11
        )
    return {
        "passed": bool(passed and patch_passed),
        "interface_area": float(area),
        "interface_scope_passed": bool(patch_passed),
        "missing_regions": sorted(expected - set(zones)),
        "unexpected_regions": sorted(set(zones) - expected),
        "materials": {name: zone.material_id for name, zone in sorted(zones.items())},
    }


def _corpus_acceptance(
    case: MeshingCase,
    result: phx.meshing.CellMeshingResult,
    specification: Any,
) -> dict[str, object]:
    """Identical independent geometry/quality checks for every engine."""
    from phydrax.meshing.providers._native_publication import simplex_entity_limits

    mesh = result.mesh
    points = np.asarray(mesh.coordinates, dtype=np.float64)
    cells = np.concatenate([np.asarray(block.vertices) for block in mesh.blocks])
    simplex_entity_limits(
        points,
        cells,
        specification.limits,
        phx.meshing.MeshingStageKind.GEOMETRY_AUDIT,
        cell_kind=mesh.blocks[0].cell_kind,
    )
    corners = points[cells]
    if case.dimension == 2:
        measures = _simplex_measures(points, cells)
        regions = np.zeros(cells.shape[0], dtype=np.int64)
    else:
        measures = np.linalg.det(corners[:, 1:] - corners[:, :1]) / 6.0
        regions = analytic_region_indices(case, corners.mean(axis=1))
    embedding = phx.geometry.certify_global_embedding(
        mesh, result.geometry, result.audit.validity
    )
    coverage = phx.geometry.certify_domain_coverage(
        mesh, result.geometry, _corpus_domain(case), regions, embedding=embedding
    )
    features = _embedded_feature_coverage(case, mesh)
    measured = {
        name: float(np.sum(measures[regions == index]))
        for index, (name, _) in enumerate(case.expected_regions)
    }
    residual = max(
        abs(measured[name] - expected) for name, expected in case.expected_regions
    )
    semantics = (
        _material_semantics(case, result, regions)
        if case.dimension == 3
        else {"passed": True, "status": "not-requested"}
    )
    connectivity = mesh.connectivity
    if not isinstance(
        connectivity,
        (
            phx.discretization.PolygonalConnectivity,
            phx.discretization.TetrahedralConnectivity,
        ),
    ):
        raise TypeError(
            "Corpus acceptance requires triangle or tetrahedral connectivity."
        )
    lengths = np.linalg.norm(
        points[np.asarray(connectivity.edges)[:, 1]]
        - points[np.asarray(connectivity.edges)[:, 0]],
        axis=1,
    )
    control = specification.size_controls[0]
    tolerance = specification.size_compliance.relative_tolerance
    p50 = float(np.quantile(lengths, 0.5))
    max_edge = float(np.max(lengths))
    size_passed = "hard-size" not in case.controls or (
        abs(p50 - control.target_size) <= tolerance * control.target_size
        and max_edge <= control.maximum_size * (1.0 + tolerance)
    )
    quality_passed = (
        result.quality.minimum_angle >= specification.quality_target.minimum_angle
        if case.dimension == 2
        else "minimum-quality" not in case.controls
        or result.quality.minimum_mean_ratio >= 0.05
    )
    fixed_passed = True
    if "fixed-boundary" in case.controls:
        faces = np.concatenate(
            [
                cells[:, list(face)]
                for face in ((1, 2, 3), (0, 2, 3), (0, 1, 3), (0, 1, 2))
            ]
        )
        keys, counts = np.unique(np.sort(faces, axis=1), axis=0, return_counts=True)
        published = {tuple(sorted(map(tuple, points[row]))) for row in keys[counts == 1]}
        payload = source_payload(case)
        source_points = np.asarray(payload["vertices"], dtype=np.float64)
        declared = {
            tuple(sorted(map(tuple, source_points[list(face)])))
            for face in payload["polygons"]
        }
        fixed_passed = published == declared
    minimum_dihedral = None
    if "dihedral-25" in case.controls:
        normals = []
        for face in ((1, 2, 3), (0, 3, 2), (0, 1, 3), (0, 2, 1)):
            triangle = corners[:, face, :]
            normal = np.cross(
                triangle[:, 1] - triangle[:, 0], triangle[:, 2] - triangle[:, 0]
            )
            normals.append(normal / np.linalg.norm(normal, axis=1)[:, None])
        angles = [
            np.arccos(np.clip(-np.sum(normals[i] * normals[j], axis=1), -1.0, 1.0))
            for i in range(4)
            for j in range(i + 1, 4)
        ]
        minimum_dihedral = float(np.min(angles))
        quality_passed = quality_passed and minimum_dihedral >= np.deg2rad(25.0)
    required_limits = {
        "vertices",
        "edges",
        "faces",
        "cells",
        "connectivity_entries",
        "data_bytes",
        "scratch_bytes",
        "work_units",
        "wall_seconds",
        "cavity_cells",
        "geometry_queries",
    }
    resource_passed = case.dimension != 3 or (
        not result.runtime.unenforced_limits
        and required_limits <= set(result.runtime.enforced_limits)
    )
    passed = bool(
        result.audit.passed
        and embedding.status == "certified"
        and coverage.status == "certified"
        and np.all(measures > 0.0)
        and residual <= 1.0e-11
        and size_passed
        and quality_passed
        and fixed_passed
        and features["passed"]
        and semantics["passed"]
        and resource_passed
    )
    return {
        "passed": passed,
        "embedding_certificate": embedding.certificate_id,
        "coverage_certificate": coverage.certificate_id,
        "embedding_status": embedding.status,
        "coverage_status": coverage.status,
        "region_measures": measured,
        "maximum_measure_residual": residual,
        "minimum_signed_cell_measure": float(np.min(measures)),
        "size_passed": size_passed,
        "quality_passed": bool(quality_passed),
        "fixed_boundary_passed": fixed_passed,
        "independent_minimum_dihedral": minimum_dihedral,
        "median_edge": p50,
        "maximum_edge": max_edge,
        "embedded_features": features,
        "material_semantics": semantics,
        "resource_guarantees": {
            "passed": resource_passed,
            "enforced_limits": list(result.runtime.enforced_limits),
            "unenforced_limits": list(result.runtime.unenforced_limits),
            "missing_limits": sorted(
                required_limits - set(result.runtime.enforced_limits)
            )
            if case.dimension == 3
            else [],
            "scope": "Declared owning execution guarantees; no missing guarantee inferred from success.",
        },
        "quality": _quality_summary(result.quality),
    }


def _manufactured_value(points: Any) -> Any:
    return jnp.sum(points * points, axis=-1)


def _manufactured_source(points: Any, parameters: Any) -> Any:
    del parameters
    return jnp.full(points.shape[:-1], -2.0 * points.shape[-1], dtype=points.dtype)


def _material_manufactured_value(points: Any) -> Any:
    x = points[..., 0]
    return jnp.where(x <= 1.0, x * x, 0.5 * x * x + 0.5)


def _material_manufactured_source(points: Any, context: Any) -> Any:
    del context
    return jnp.full(points.shape[:-1], -2.0, dtype=points.dtype)


def _prepare_corpus_solver(
    result: phx.meshing.CellMeshingResult, *, material_x: bool = True
) -> tuple[Any, Any, Any]:
    mesh = result.mesh
    family = "triangle" if mesh.topological_dimension == 2 else "tetrahedron"
    space = phx.discretization.FiniteElementPlan(
        mesh,
        phx.discretization.FiniteElementFieldSpec(
            "u", phx.discretization.lagrange_element(family, 1)
        ),
        coordinate_spec=result.geometry,
    ).prepare()
    if mesh.topological_dimension == 3 and material_x:
        zones = {
            zone.name: zone
            for zone in result.zones
            if zone.role is phx.meshing.MeshZoneRole.REGION
        }
        if set(zones) != {"left", "right"}:
            raise RuntimeError(
                "The material diffusion consumer requires both source regions."
            )
        diffusion = tuple(
            phx.equations.DiffusionAction(
                "u",
                conductivity,
                domain=space.integration_domain(
                    "cell", phx.meshing.resolve_mesh_scope(mesh, zones[name].scope)
                ),
            )
            for name, conductivity in (("left", 1.0), ("right", 2.0))
        )
        forcing = _material_manufactured_source
        exact = _material_manufactured_value
        coefficient_id = "material-flux-continuous-quadratic"
    else:
        diffusion = (phx.equations.DiffusionAction("u", 1.0),)
        forcing = _manufactured_source
        exact = _manufactured_value
        coefficient_id = "quadratic-exact-laplacian"
    form = phx.equations.FiniteElementForm(
        "native-corpus-manufactured-diffusion",
        "u",
        (
            *diffusion,
            phx.equations.SourceAction(
                "u", phx.equations.coefficient(forcing, coefficient_id=coefficient_id)
            ),
        ),
    )
    constraint = phx.discretization.dirichlet_constraint(space, "u")
    problem = phx.equations.compile_finite_element_problem(
        form, space, constraint=constraint, dirichlet_values=exact
    )
    return space, problem, constraint.free_dofs


@eqx.filter_jit
def _solve_corpus_problem(
    problem: Any,
    seed: Any,
    policy: phx.linalg.LinearSolvePolicy | None = None,
) -> tuple[Any, Any]:
    system, rhs = problem.linear_system()
    residual = rhs - system.operator.mv(seed)
    solved = phx.linalg.solve(system, residual, policy=policy)
    return problem.expand(seed + solved.value), solved


def _physical_error(
    mesh: phx.discretization.CellMesh,
    values: Any,
    *,
    material_x: bool = False,
) -> float:
    """Independent exact P1-versus-quadratic L2 integral on affine simplices."""
    points = np.asarray(mesh.coordinates, dtype=np.float64)
    cells = np.concatenate([np.asarray(block.vertices) for block in mesh.blocks])
    corners = points[cells]
    d = mesh.topological_dimension
    measures = _simplex_measures(points, cells)
    # u_h - |x|² is a barycentric polynomial of degree two. The normalized
    # Dirichlet(1,...,1) moments integrate its square exactly, without sharing
    # FEM quadrature, tabulation or assembly.
    nodal = np.asarray(values)[cells]
    if material_x:
        right = corners.mean(axis=1)[:, 0] > 1.0
        gram = corners[:, :, 0, None] * corners[:, None, :, 0]
        gram = (
            gram * np.where(right, 0.5, 1.0)[:, None, None]
            + np.where(right, 0.5, 0.0)[:, None, None]
        )
    else:
        gram = corners @ np.swapaxes(corners, -1, -2)
    coefficient = -gram
    coefficient += 0.5 * (nodal[:, :, None] + nodal[:, None, :])
    n = d + 1
    integral = np.zeros(cells.shape[0], dtype=np.float64)
    denominator = math.factorial(d + 4) / math.factorial(d)
    for i in range(n):
        for j in range(n):
            for k in range(n):
                for l in range(n):
                    exponents = np.bincount((i, j, k, l), minlength=n)
                    moment = (
                        np.prod([math.factorial(int(e)) for e in exponents]) / denominator
                    )
                    integral += coefficient[:, i, j] * coefficient[:, k, l] * moment
    return float(np.sqrt(max(0.0, float(np.sum(measures * integral)))))


def _compiled_solver_stages(
    problem: Any,
    seed: Any,
    repeats: int,
    *,
    policy: phx.linalg.LinearSolvePolicy | None = None,
) -> tuple[Any, dict[str, object], dict[str, float]]:
    entry = _solve_corpus_problem
    if not isinstance(entry, _CorpusJitEntry):
        raise TypeError(
            "The filtered corpus solver must expose its compiled lowering boundary."
        )
    lowered, lowering = _measured(lambda: entry.lower(problem, seed, policy))
    compiled, compilation = _measured(lowered.compile)
    memory = compiled.compiled.memory_analysis()
    first, first_stage = _measured(
        lambda: jax.block_until_ready(compiled(problem, seed, policy))
    )
    warm = []
    for _ in range(repeats):
        _, stage = _measured(
            lambda: jax.block_until_ready(compiled(problem, seed, policy))
        )
        warm.append(stage["wall_seconds"])
    values, solved = first
    condition = np.asarray(solved.diagnostics.condition_estimate)
    condition_available = bool(np.all(np.isfinite(condition)))
    successful = bool(np.all(np.asarray(solved.successful)))
    compiler = {
        "temporary_bytes": None if memory is None else memory.temp_size_in_bytes,
        "output_bytes": None if memory is None else memory.output_size_in_bytes,
        "argument_bytes": None if memory is None else memory.argument_size_in_bytes,
        "generated_code_bytes": None
        if memory is None
        else memory.generated_code_size_in_bytes,
        "memory_status": "unavailable" if memory is None else "measured",
        "compilation_count": 1,
        "warm_samples_seconds": warm,
        "compilation_count_scope": "explicit-AOT-compile-invocations",
        "warm_recompilation_count": 0,
        "solver": {
            "successful": successful,
            "status": np.asarray(solved.status).tolist(),
            "iterations": np.asarray(solved.diagnostics.iterations).tolist(),
            "residual_norm": np.asarray(solved.diagnostics.residual_norm).tolist(),
            "relative_residual": np.asarray(
                solved.diagnostics.relative_residual
            ).tolist(),
            "rank": np.asarray(solved.diagnostics.rank).tolist(),
            "condition_estimate": condition.tolist() if condition_available else None,
            "condition_status": "reported" if condition_available else "unavailable",
        },
    }
    stages = {
        "solver_lowering": lowering["wall_seconds"],
        "solver_compile": compilation["wall_seconds"],
        "solver_first_execution": first_stage["wall_seconds"],
        "solver_warm_execution": float(np.median(warm)),
    }
    if not successful:
        raise RuntimeError(
            json.dumps(
                {
                    "kind": "native-solver-failure",
                    "message": "Manufactured diffusion solver did not converge.",
                    "compiler": compiler,
                    "stages_seconds": stages,
                },
                sort_keys=True,
            )
        )
    return values, compiler, stages


def _triangle_comparison(
    case: MeshingCase,
    specification: Any,
) -> phx.meshing.CellMeshingResult:
    """Explicit optional Triangle algorithm; never called by a native route."""
    import triangle

    payload = source_payload(case)
    points = np.asarray(payload["vertices"], dtype=np.float64)
    segments = [
        (loop[i], loop[(i + 1) % len(loop)])
        for loop in payload["loops"]
        for i in range(len(loop))
    ]
    embedded = np.asarray(payload["embedded"], dtype=np.float64)
    if embedded.size:
        segments.append((points.shape[0], points.shape[0] + 1))
        points = np.concatenate((points, embedded))
    source = {"vertices": points, "segments": np.asarray(segments, dtype=np.int32)}
    if len(payload["loops"]) > 1:
        source["holes"] = np.asarray(((1.0, 1.0),), dtype=np.float64)
    size = specification.size_controls[0].target_size
    angle = np.degrees(specification.quality_target.minimum_angle)
    output = triangle.triangulate(source, f"pq{angle}a{0.25 * size * size}")
    return phx.meshing.certify_cell_mesh(
        phx.discretization.CellMesh.from_triangles(
            output["vertices"], output["triangles"]
        ),
        phx.SpatialCoordinateContract.si(),
    )


def _corpus_native_consumer[T](
    result: phx.meshing.CellMeshingResult,
    specification: Any,
    call: Callable[[], T],
    *,
    native: bool,
    target: Callable[[T], phx.meshing.CellMeshingResult] | None = None,
) -> tuple[phx.meshing.CellMeshingResult, T]:
    """Continue the actual latest ended root, without resetting original limits."""
    if not native:
        value = call()
        return result if target is None else target(value), value
    from time import monotonic

    from phydrax.meshing._volume_generation import native_volume_source_execution_budget
    from phydrax.meshing.providers._native_publication import bind_native_execution_result

    receipt = result.execution_evidence
    if receipt is None or receipt.owner_id is None:
        raise RuntimeError(
            "Native corpus consumer requires its actual owner-bound ended root receipt."
        )
    receipt.require_valid()
    started = monotonic() - float(np.asarray(receipt.total_elapsed_seconds))
    with native_volume_source_execution_budget(
        specification.limits,
        receipt,
        receipt.owner_id,
    ) as budget:
        value = call()
    if budget.evidence is None:
        raise RuntimeError(
            "Native corpus consumer did not retain its actual ended scope."
        )
    bound = bind_native_execution_result(
        result if target is None else target(value),
        budget.evidence,
        specification.limits,
        started,
        preparation_evidence=receipt,
    )
    return bound, value


def _corpus_cold_worker(
    path: str,
    content_id: str,
    expected: tuple[str, ...],
    repeats: int,
    target_error: float,
) -> dict[str, object]:
    """Restore every actual accepted field epoch and continue its original PDE."""
    from phydrax._array_archive import ArrayArchiveLimits
    from phydrax._fingerprint import array_tree_fingerprint
    from phydrax.lifecycle._meshing_sources import read_meshing_source_closure

    restored = read_meshing_source_closure(
        Path(path), expected_content_id=content_id, limits=ArrayArchiveLimits()
    )
    source, result, specification, options, name, history = (
        restored[key]
        for key in (
            "source",
            "result",
            "specification",
            "options",
            "case_name",
            "history",
        )
    )
    if (
        not isinstance(result, phx.meshing.CellMeshingResult)
        or not isinstance(name, str)
        or not isinstance(history, tuple)
        or not history
        or (
            source.binding_id,
            result.result_id,
            specification.specification_id,
            options.options_id,
            array_tree_fingerprint(
                (source, specification, options, name, restored["engine"])
            ),
            array_tree_fingerprint(history),
        )
        != expected
    ):
        raise RuntimeError(
            "Cold corpus closure changed original source, controls or accepted field histories."
        )
    case = meshing_case(name)
    bound, cold = _corpus_native_consumer(
        result,
        specification,
        lambda: _corpus_cold_fields(
            case, result, specification, history, repeats, target_error
        ),
        native=restored["engine"] == "native",
    )
    return {**cold, "continued_result": _result_identity(bound)}


def _corpus_cold_fields(
    case: MeshingCase,
    result: phx.meshing.CellMeshingResult,
    specification: Any,
    history: tuple[Any, ...],
    repeats: int,
    target_error: float,
) -> dict[str, object]:
    name = case.name

    accepted = []
    for publication, fields, original_error in history:
        acceptance = _corpus_acceptance(case, publication, specification)
        if not acceptance["passed"]:
            raise RuntimeError(
                "Cold accepted corpus epoch failed independent original source acceptance."
            )
        if not isinstance(fields, tuple) or len(fields) != 3:
            raise RuntimeError(
                "Cold corpus epoch lost a declared solved, density or history field."
            )
        space, _, _ = _prepare_corpus_solver(
            publication, material_x=name == "plc-material-cavity"
        )
        error = _physical_error(
            publication.mesh, fields[0], material_x=name == "plc-material-cavity"
        )
        if error != original_error:
            raise RuntimeError(
                "Cold accepted field changed its original independent physical error."
            )
        density_error = float(jnp.max(jnp.abs(fields[1] - 2.0)))
        history_error = float(
            jnp.max(jnp.abs(fields[2] - (space.dof_maps[0].dof_coordinates[:, 0] + 0.5)))
        )
        if density_error > 1.0e-12 or history_error > 1.0e-12:
            raise RuntimeError(
                "Cold corpus density/history failed independent authored field oracles."
            )
        accepted.append(
            {
                "result": _result_identity(publication),
                "acceptance": acceptance,
                "physical_error": error,
                "density_max_defect": density_error,
                "history_max_defect": history_error,
            }
        )
    if history[-1][0].result_id != result.result_id:
        raise RuntimeError(
            "Cold final corpus fields belong to a different accepted publication."
        )
    _, problem, free = _prepare_corpus_solver(
        result, material_x=name == "plc-material-cavity"
    )
    values, compiler, timings = _compiled_solver_stages(
        problem, jnp.asarray(history[-1][1][0])[free], repeats
    )
    error = _physical_error(result.mesh, values, material_x=name == "plc-material-cavity")
    if not np.isfinite(error) or error > target_error:
        raise RuntimeError(
            "Cold continued corpus PDE missed the original final physical error target."
        )
    return {
        "passed": True,
        "process_id": os.getpid(),
        "runtime": _runtime_identity(),
        "accepted_epochs": accepted,
        "field_names": ["u", "density", "history"],
        "accepted_fields_bitwise_preserved": True,
        "prepared_fe_caches_serialized": False,
        "continued_physical_error": error,
        "compiler": compiler,
        "solver_seconds": timings,
        "seed_origin": "actual-restored-final-accepted-u",
    }


def _corpus_cold_reanalysis(
    source: Any,
    result: phx.meshing.CellMeshingResult,
    specification: Any,
    options: Any,
    case: MeshingCase,
    history: tuple[Any, ...],
    repeats: int,
    target_error: float,
    timeout: float,
    started: float,
    record: dict[str, Any],
) -> None:
    import subprocess

    from phydrax._array_archive import ArrayArchiveLimits
    from phydrax._fingerprint import array_tree_fingerprint
    from phydrax.lifecycle._meshing_sources import write_meshing_source_closure

    limits = ArrayArchiveLimits()
    records = {
        "source": source,
        "result": result,
        "specification": specification,
        "options": options,
        "case_name": case.name,
        "history": history,
        "engine": record["engine"],
    }
    with TemporaryDirectory(prefix="phydrax-native-corpus-source-") as directory:
        receipt, measured = _measured(
            lambda: write_meshing_source_closure(
                Path(directory) / "corpus.checkpoint.zip", records, limits=limits
            )
        )
        record["stages_seconds"]["allfield_history_checkpoint_publication"] = measured[
            "wall_seconds"
        ]
        expected = (
            source.binding_id,
            result.result_id,
            specification.specification_id,
            options.options_id,
            array_tree_fingerprint(
                (source, specification, options, case.name, record["engine"])
            ),
            array_tree_fingerprint(history),
        )
        remaining = timeout - (perf_counter() - started)
        if remaining <= 0.0:
            raise TimeoutError(
                "Original corpus wall allowance expired before cold continued solve."
            )
        code = (
            "import json,sys; from tools.meshing_qualification import _corpus_cold_worker; "
            "print(json.dumps(_corpus_cold_worker(sys.argv[1],sys.argv[2],"
            "tuple(json.loads(sys.argv[3])),int(sys.argv[4]),float(sys.argv[5]))))"
        )
        try:
            completed, measured = _measured(
                lambda: subprocess.run(
                    [
                        sys.executable,
                        "-c",
                        code,
                        str(receipt.path),
                        receipt.content_id,
                        json.dumps(expected),
                        str(repeats),
                        str(target_error),
                    ],
                    capture_output=True,
                    text=True,
                    timeout=remaining,
                    check=False,
                )
            )
        except subprocess.TimeoutExpired as failure:
            raise TimeoutError(
                "Cold corpus process exhausted the original remaining wall allowance."
            ) from failure
        record["stages_seconds"]["fresh_process_allfield_history_continued_PDE"] = (
            measured["wall_seconds"]
        )
        if completed.returncode:
            record["cold_process_refusal"] = {
                "returncode": completed.returncode,
                "stdout": completed.stdout,
                "stderr": completed.stderr,
            }
            raise RuntimeError(
                f"Cold corpus child refused ({completed.returncode}): {completed.stderr}"
            )
        cold = json.loads(completed.stdout)
        if (
            not isinstance(cold, dict)
            or cold.get("passed") is not True
            or cold.get("process_id") == os.getpid()
        ):
            raise RuntimeError(
                "Corpus cold evidence did not originate in an independent process."
            )
        record["checkpoint"] = {
            **cold,
            "content_id": receipt.content_id,
            "container_bytes": receipt.path.stat().st_size,
            "archive_limits": {
                "members": limits.max_members,
                "nesting": limits.max_manifest_nesting,
                "rank": limits.max_array_rank,
            },
            "source_authority_stripped": False,
        }


def qualify_native_lifecycle(
    case_name: str,
    *,
    resolution: int = 4,
    capacity: int = 20000,
    timeout: float = 120.0,
    repeats: int = 3,
    target_error: float = 0.05,
    adaptation_rounds: int = 1,
    engine: str = "native",
) -> dict[str, object]:
    """Native geometry → certification → transfer → solve with fixed targets."""
    from importlib.util import find_spec

    case = meshing_case(case_name)
    started = perf_counter()
    record: dict[str, Any] = {
        "scenario": "native-lifecycle",
        "engine": engine,
        "case": corpus_identity(case),
        "runtime": _runtime_identity(),
        "status": "failed",
        "expected_admission": case.expected_admission,
        "control_capacities": {
            "resolution": resolution,
            "entity_capacity": capacity,
            "adaptation_rounds": adaptation_rounds,
            "solver_warm_repeats": repeats,
        },
        "targets": {"l2_error": target_error, "wall_seconds": timeout},
        "adaptation_engine": "native-bisection",
        "time_to_target_error_seconds": None,
        "stages_seconds": {},
        "epochs": [],
        "release_evidence": "unassessed",
        "leadership_evidence": "unassessed",
    }
    if (
        repeats < 1
        or adaptation_rounds < 0
        or not np.isfinite(target_error)
        or target_error <= 0.0
    ):
        raise ValueError("Repeats and target error must be positive; rounds nonnegative.")
    if engine == "triangle" and find_spec("triangle") is None:
        return {**record, "status": "missing-dependency", "dependency": "triangle"}
    if engine == "triangle" and (
        case.dimension != 2 or case.expected_admission != "positive"
    ):
        return {
            **record,
            "status": "ineligible-comparison",
            "detail": "Triangle cannot match this source/admission contract.",
        }
    stages = record["stages_seconds"]
    native_phases: list[NativeMeshingPhaseMeasurement] = []
    phase = "source_preparation"
    source = None
    source_fingerprint = None
    try:
        prepared_case, measured = _measured(
            lambda: prepare_case(case, resolution, capacity, timeout)
        )
        source, specification, options = prepared_case
        from phydrax._fingerprint import array_tree_fingerprint

        source_fingerprint = array_tree_fingerprint(source)
        stages[phase] = measured["wall_seconds"]
        record["request_id"] = specification.specification_id
        record["source_binding_id"] = source.binding_id
        record["limits_id"] = specification.limits.limits_id
        record["frozen_request"] = frozen_request_record(source, specification, options)
        phase = "geometry_constraint_preparation"
        if engine == "native":
            provider = phx.meshing.NativeMeshingProvider(options)
            plan, measured = _measured(
                lambda: provider.plan(
                    source,
                    specification,
                    coordinate_contract=phx.SpatialCoordinateContract.si(),
                    record_phase=native_phases.append,
                )
            )
            stages[phase] = measured["wall_seconds"]
            record["prepared_id"] = plan.plan_id
            phase = "generation_publication_certification"
            result, measured = _measured(
                lambda: plan.execute(record_phase=native_phases.append)
            )
        elif engine == "triangle":
            record["phase_availability"] = {
                "geometry_constraint_preparation": "included-in-comparison-generation-no-reusable-plan"
            }
            phase = "comparison_generation_publication"
            result, measured = _measured(
                lambda: _triangle_comparison(case, specification)
            )
        else:
            raise ValueError("Engine must be native or triangle.")
        stages[phase] = measured["wall_seconds"]
        if case.expected_admission == "refusal":
            record["failure"] = "Deliberate refusal case was accepted."
            return record
        phase = "independent_acceptance"
        accepted, measured = _measured(
            lambda: _corpus_native_consumer(
                result,
                specification,
                lambda: _corpus_acceptance(case, result, specification),
                native=engine == "native",
            )
        )
        result, acceptance = accepted
        stages[phase] = measured["wall_seconds"]
        record["independent_acceptance"] = acceptance
        record["generation"] = _result_identity(result)
        if not acceptance["passed"]:
            record["failure"] = "Independent source/control acceptance failed."
            record["failure_phase"] = phase
            return record
        record["native_certification_id"] = (
            None if result.certification is None else result.certification.report_id
        )
        association_transfer = None
        if isinstance(source, phx.meshing.NativePlcSource):
            from phydrax.meshing._volume_generation import prepare_plc_source

            phase = "authoritative_source_association_preparation"

            def inspect_source() -> Any:
                prepared_source = prepare_plc_source(
                    source.complex,
                    source.source_id,
                    source.source_revision,
                    result.coordinate_contract,
                    limits=specification.limits,
                    record_phase=native_phases.append,
                )
                prepared_source.association_transfer.source_associations(result)
                return prepared_source

            inspected, measured = _measured(
                lambda: _corpus_native_consumer(
                    result, specification, inspect_source, native=engine == "native"
                )
            )
            result, bound_source = inspected
            stages[phase] = measured["wall_seconds"]
            association_transfer = bound_source.association_transfer
            record["source_association_prepared_id"] = bound_source.prepared_id
            record["source_association_transfer_id"] = association_transfer.transfer_id
            record["source_association_counters"] = dict(
                bound_source.preparation_counters
            )
            record["source_association_memory_evidence"] = bound_source.memory_evidence
        previous_values = None
        previous_auxiliary = None
        accepted_history = []
        for epoch in range(adaptation_rounds + 1):

            def solve_epoch() -> tuple[Any, Any, Any, Any, float]:
                nonlocal phase
                phase = f"solver_prepare_epoch_{epoch}"
                solver, measured = _measured(
                    lambda: _prepare_corpus_solver(
                        result, material_x=case.name == "plc-material-cavity"
                    )
                )
                space, problem, free_dofs = solver
                stages[phase] = measured["wall_seconds"]
                phase = f"solver_execution_epoch_{epoch}"
                seed = (
                    jnp.zeros((free_dofs.size,), dtype=result.mesh.coordinates.dtype)
                    if previous_values is None
                    else jnp.asarray(previous_values)[free_dofs]
                )
                values, compiler, timings = _compiled_solver_stages(
                    problem, seed, repeats
                )
                stages.update(
                    {f"{key}_epoch_{epoch}": value for key, value in timings.items()}
                )
                error = _physical_error(
                    result.mesh, values, material_x=case.name == "plc-material-cavity"
                )
                return space, problem, values, compiler, error

            result, solved = _corpus_native_consumer(
                result, specification, solve_epoch, native=engine == "native"
            )
            space, problem, values, compiler, error = solved
            if previous_auxiliary is None:
                previous_auxiliary = (
                    jnp.full(values.shape, 2.0, dtype=values.dtype),
                    space.dof_maps[0].dof_coordinates[:, 0] + 0.5,
                )
            accepted_history.append((result, (values, *previous_auxiliary), error))
            if error <= target_error and record["time_to_target_error_seconds"] is None:
                record["time_to_target_error_seconds"] = perf_counter() - started
            record["epochs"].append(
                {
                    "epoch": epoch,
                    "result": _result_identity(result),
                    "l2_error": error,
                    "dofs": space.dof_maps[0].global_dof_count,
                    "compiler": compiler,
                    "retained_bytes": _bisection_retained_bytes(
                        (
                            source,
                            specification,
                            options,
                            tuple(accepted_history),
                            space,
                            problem,
                        )
                    ),
                    "transferred_state_l2_error": (
                        None
                        if previous_values is None
                        else _physical_error(
                            result.mesh,
                            previous_values,
                            material_x=case.name == "plc-material-cavity",
                        )
                    ),
                }
            )
            if epoch == adaptation_rounds:
                break
            phase = f"adaptation_prepare_epoch_{epoch}"
            identifiers = np.concatenate(
                [
                    np.asarray(block.global_ids, dtype=np.int64)
                    for block in result.mesh.blocks
                ]
            )
            request = phx.meshing.MarkedMeshAdaptation(
                identifiers, np.empty((0,), dtype=np.int64)
            )
            policy = phx.meshing.MeshAdaptationPolicy(
                phx.meshing.MeshAdaptationRoute.NATIVE_BISECTION,
                limits=specification.limits,
                association_transfer=association_transfer,
                audit_policy=phx.meshing.CellMeshAuditPolicy(
                    require_complete_association=True,
                    watertight_boundary=phx.meshing.CellMeshAuditDisposition.REJECT,
                ),
            )

            def adapt_fields() -> tuple[Any, Any, Any, Any]:
                nonlocal phase
                prepared, measured = _measured(
                    lambda: phx.meshing.prepare_mesh_adaptation(
                        result, request, policy=policy
                    )
                )
                stages[phase] = measured["wall_seconds"]
                phase = f"adaptation_execute_epoch_{epoch}"
                candidate, measured = _measured(
                    lambda: phx.meshing.execute_mesh_adaptation(prepared)
                )
                stages[phase] = measured["wall_seconds"]
                if candidate.transfer is None:
                    raise RuntimeError(
                        "Native lifecycle adaptation lacks its required FE state transfer."
                    )
                phase = f"field_transfer_epoch_{epoch}"
                transitioned, measured = _measured(
                    lambda: _envelope_qualification_state_transition(
                        result, candidate, problem, values, epoch, previous_auxiliary
                    )
                )
                stages[phase] = measured["wall_seconds"]
                return candidate, *transitioned

            bound_target, transitioned = _corpus_native_consumer(
                result,
                specification,
                adapt_fields,
                native=engine == "native",
                target=lambda value: value[0].target,
            )
            adaptation, previous_values, previous_auxiliary, state_transfer = transitioned
            record["epochs"][-1]["transfer"] = _bisection_transfer(adaptation)
            record["epochs"][-1]["solver_state_transfer"] = state_transfer
            before = _bisection_p1_integral(adaptation.source.mesh, values)
            after = _bisection_p1_integral(adaptation.target.mesh, previous_values)
            record["epochs"][-1]["state_inventory"] = {
                "source": before,
                "target": after,
                "defect": after - before,
            }
            if abs(after - before) > 1.0e-10 * max(1.0, abs(before)):
                raise RuntimeError(
                    "Actual transferred solver-state inventory was not conserved."
                )
            if abs(record["epochs"][-1]["transfer"]["p1_integral_residual"]) > 1.0e-10:
                raise RuntimeError("Transferred P1 inventory was not conserved.")
            result = bound_target
            phase = f"independent_acceptance_epoch_{epoch + 1}"
            accepted, measured = _measured(
                lambda: _corpus_native_consumer(
                    result,
                    specification,
                    lambda: _corpus_acceptance(case, result, specification),
                    native=engine == "native",
                )
            )
            result, acceptance = accepted
            stages[phase] = measured["wall_seconds"]
            record["epochs"][-1]["target_acceptance"] = acceptance
            if not acceptance["passed"]:
                raise RuntimeError(
                    "Adapted target violated the frozen source/control contract."
                )
        phase = "allfield_history_source_checkpoint_and_cold_continued_PDE"
        _corpus_cold_reanalysis(
            source,
            result,
            specification,
            options,
            case,
            tuple(accepted_history),
            repeats,
            target_error,
            timeout,
            started,
            record,
        )
        elapsed = perf_counter() - started
        final_error = record["epochs"][-1]["l2_error"]
        record["physical_target_first_reached_seconds"] = record[
            "time_to_target_error_seconds"
        ]
        if final_error <= target_error:
            record["time_to_target_error_seconds"] = elapsed
        record.update(
            {
                "status": "passed"
                if final_error <= target_error and elapsed <= timeout
                else "failed",
                "target_error_reached": final_error <= target_error,
                "physical_error": final_error,
                "end_to_end_seconds": elapsed,
                "peak_process_resident_bytes": resource.getrusage(
                    resource.RUSAGE_SELF
                ).ru_maxrss
                * (1 if sys.platform == "darwin" else 1024),
                "independent_scientific_certification": "passed",
                "mandatory_workflow_completion": "incomplete",
                "case_contract_completion": "complete"
                if final_error <= target_error and elapsed <= timeout
                else "incomplete",
                "nonclaims": [
                    "This routine corpus case is not the entire W15 mandatory workflow.",
                    "No release or performance leadership is inferred from this run.",
                ],
            }
        )
        if elapsed > timeout:
            record["status"] = "timeout"
    except phx.meshing.MeshingFailure as failure:
        evidence = failure.evidence
        expected = {
            "planar-capacity-refusal": phx.meshing.MeshingFailureCategory.RESOURCE_EXHAUSTED,
            "planar-stale-revision": phx.meshing.MeshingFailureCategory.SCOPE_RESOLUTION_FAILED,
            "plc-incompatible-constraints": phx.meshing.MeshingFailureCategory.INVALID_SOURCE,
            "plc-stale-revision": phx.meshing.MeshingFailureCategory.SCOPE_RESOLUTION_FAILED,
        }.get(case.name)
        if case.expected_admission == "refusal" and case.workflow == "resource-boundary":
            expected = phx.meshing.MeshingFailureCategory.RESOURCE_EXHAUSTED
        source_unchanged = (
            source is not None
            and source_fingerprint is not None
            and array_tree_fingerprint(source) == source_fingerprint
        )
        record.update(
            {
                "status": (
                    "expected-refusal"
                    if failure.category is expected and source_unchanged
                    else "timeout"
                    if failure.category is phx.meshing.MeshingFailureCategory.TIMED_OUT
                    else "failed"
                ),
                "failure_phase": phase,
                "failure": str(failure),
                "failure_category": failure.category.value,
                "failure_evidence_id": evidence.evidence_id,
                "failing_entities": list(evidence.entity_ids),
                "requested": dict(evidence.requested),
                "achieved": dict(evidence.achieved),
                "native_stage": evidence.stage,
                "provider_code": evidence.provider_code,
                "locations": [list(location) for location in evidence.locations],
                "checkpoint_id": evidence.checkpoint_id,
                "source_bits_preserved": source_unchanged,
                "mandatory_workflow_completion": "incomplete",
                "end_to_end_seconds": perf_counter() - started,
            }
        )
    except TimeoutError as failure:
        record.update(
            {
                "status": "timeout",
                "failure_phase": phase,
                "failure": str(failure),
                "failure_type": type(failure).__name__,
                "mandatory_workflow_completion": "incomplete",
                "end_to_end_seconds": perf_counter() - started,
            }
        )
    except (RuntimeError, ValueError, TypeError) as failure:
        # This is an evidence boundary: failures are preserved, never replaced
        # by another algorithm or silently removed from campaign statistics.
        record.update(
            {
                "failure_phase": phase,
                "failure": str(failure),
                "failure_type": type(failure).__name__,
                "end_to_end_seconds": perf_counter() - started,
            }
        )
    finally:
        record["native_phases"] = _phase_recordings(native_phases)
        record["end_to_end_seconds"] = perf_counter() - started
        record["peak_process_resident_bytes"] = resource.getrusage(
            resource.RUSAGE_SELF
        ).ru_maxrss * (1 if sys.platform == "darwin" else 1024)
        record["process_peak_scope"] = "process-lifetime"
        devices = []
        for device in jax.local_devices():
            statistics = device.memory_stats()
            devices.append(
                {
                    "device_id": device.id,
                    "platform": device.platform,
                    "device_kind": device.device_kind,
                    "peak_bytes": None
                    if statistics is None
                    else statistics.get("peak_bytes_in_use"),
                    "memory_statistics": statistics,
                    "status": "unavailable" if statistics is None else "backend-reported",
                }
            )
        record["device_memory"] = devices
    return record


def _surface_forcing(points: Any, context: Any) -> Any:
    del context
    return 2.0 * points[..., 0] / jnp.linalg.norm(points, axis=-1)


def _prepare_surface_solver(
    result: phx.meshing.CellMeshingResult,
) -> tuple[Any, Any, Any]:
    from examples.native_surface_meshing import zero_mean_constraint

    space = phx.discretization.FiniteElementPlan(
        result.mesh,
        phx.discretization.FiniteElementFieldSpec(
            "u", phx.discretization.lagrange_element("triangle", 1)
        ),
        coordinate_spec=result.geometry,
    ).prepare()
    constraint, weights = zero_mean_constraint(space)
    form = phx.equations.FiniteElementForm(
        "sphere-laplace-beltrami",
        "u",
        (
            phx.equations.DiffusionAction("u", 1.0),
            phx.equations.SourceAction(
                "u",
                phx.equations.coefficient(
                    _surface_forcing, coefficient_id="unit-sphere-degree-one-harmonic"
                ),
            ),
        ),
    )
    problem = phx.equations.compile_finite_element_problem(
        form, space, constraint=constraint
    )
    return space, problem, weights


class _SurfaceLaw(TypedDict):
    name: str
    area: float
    curvature: float
    closed: bool
    euler: int


def _surface_qualification_requirements() -> dict[str, object]:
    """Original source profiles and their distinct physical PDE obligations."""
    return {
        "required_arguments": {
            "surface_case": {
                "choices": (
                    "sphere",
                    "torus",
                    "capped_cylinder",
                    "annulus",
                    "cylinder_sheet",
                    "folded_plates",
                ),
                "default": "sphere",
            }
        },
        "evidence_sections": (
            "generation",
            "epochs",
            "source_acceptance",
            "checkpoint",
            "physical_error",
            "mandatory_workflow_completion",
        ),
        "profiles": {
            "sphere": {
                "source": "unit-sphere-seam-and-poles",
                "pde": "zero-mean-Laplace-Beltrami",
            },
            "torus": {
                "source": "original-double-periodic-torus",
                "pde": "toroidal-height-reaction-diffusion",
            },
            "capped_cylinder": {
                "source": "original-shared-periodic-rims",
                "pde": "seam-C1-axial-quartic-reaction-diffusion",
            },
            "annulus": {
                "source": "original-exact-period-hole",
                "pde": "affine-planar-Dirichlet-diffusion",
            },
            "cylinder_sheet": {
                "source": "original-open-quarter-cylinder",
                "pde": "axial-Dirichlet-diffusion",
            },
            "folded_plates": {
                "source": "original-shared-sharp-interface",
                "pde": "interface-flux-continuous-Dirichlet-diffusion",
            },
        },
    }


def _surface_qualification_prepare(
    args: argparse.Namespace,
) -> tuple[Any, Any, Any, _SurfaceLaw]:
    from examples import _native_surface_sources as originals

    name = args.surface_case
    if not isinstance(name, str):
        raise TypeError("Surface case must be a registered profile name.")
    if name == "sphere":
        source, request, options = prepare_sphere_case(
            args.resolution, args.capacity, args.timeout
        )
        law = _SurfaceLaw(
            name=name, area=float(4.0 * np.pi), curvature=1.0, closed=True, euler=2
        )
        return source, request, options, law
    factories = {
        "torus": (originals.torus, 0.45, 1.0 / 0.6),
        "capped_cylinder": (originals.capped_cylinder, 0.3, 1.0 / 0.8),
        "annulus": (originals.annulus, 0.2, 1.0 / 0.4),
        "cylinder_sheet": (originals.cylinder_sheet, 0.25, 1.0),
        "folded_plates": (originals.folded_plates, 0.3, 0.0),
    }
    factory, size, curvature = factories[name]
    original = factory()
    domain = original.domain
    source = phx.meshing.NativeSurfaceSource(domain)
    scope = phx.meshing.MeshingScope(
        source.source_id,
        source.source_revision,
        phx.meshing.MeshingEntityKind.GEOMETRY,
        2,
        domain.entity_set_id(2),
        np.asarray(domain.scope_indices(2), dtype=np.int64),
    )
    limits = phx.meshing.MeshingLimits(
        maximum_vertices=args.capacity,
        maximum_cells=8 * args.capacity,
        maximum_edges=8 * args.capacity,
        maximum_faces=8 * args.capacity,
        maximum_connectivity_entries=64 * args.capacity,
        maximum_data_bytes=1024 * args.capacity,
        maximum_work_units=32 * args.capacity,
        maximum_cavity_cells=args.capacity,
        maximum_geometry_queries=64 * args.capacity,
        maximum_scratch_bytes=4096 * args.capacity,
        maximum_wall_seconds=args.timeout,
    )
    options = phx.meshing.NativeMeshingOptions("parametric_surface")
    request = phx.meshing.SurfaceMeshingSpec(
        phx.meshing.CellMeshingTarget(
            2, 3, phx.meshing.CellFamilyPolicy(required=("triangle",))
        ),
        scope,
        size_controls=(
            phx.meshing.UniformSizeControl(
                scope, size, strength=phx.meshing.SizeControlStrength.SOFT
            ),
        ),
        limits=limits,
    )
    euler = original.euler_characteristic
    if euler is None:
        raise ValueError("Authoritative surface fixture requires an Euler reference.")
    law = _SurfaceLaw(
        name=name,
        area=original.area,
        curvature=curvature,
        closed=original.closed,
        euler=euler,
    )
    return source, request, options, law


def _surface_qualification_value(points: Any, name: str) -> Any:
    if name == "sphere":
        return points[..., 0] / jnp.linalg.norm(points, axis=-1)
    if name in ("torus", "cylinder_sheet"):
        return points[..., 2]
    if name == "capped_cylinder":
        z = points[..., 2]
        return z * z * (1.5 - z) ** 2
    if name == "annulus":
        return points[..., 0]
    if name == "folded_plates":
        return points[..., 1]
    raise ValueError("Unknown authoritative surface PDE profile.")


def _surface_qualification_solver(
    result: Any, law: _SurfaceLaw
) -> tuple[Any, Any, np.ndarray, Any]:
    name = str(law["name"])
    if name == "sphere":
        space, problem, weights = _prepare_surface_solver(result)
        free = np.flatnonzero(np.arange(weights.size) != int(np.argmax(weights)))
        return space, problem, free, weights
    space = phx.discretization.FiniteElementPlan(
        result.mesh,
        phx.discretization.FiniteElementFieldSpec(
            "u", phx.discretization.lagrange_element("triangle", 1)
        ),
        coordinate_spec=result.geometry,
    ).prepare()

    def exact(points: Any) -> Any:
        return _surface_qualification_value(points, name)

    def forcing(points: Any, context: Any) -> Any:
        del context
        if name == "torus":
            rho = jnp.linalg.norm(points[..., :2], axis=-1)
            z = points[..., 2]
            return z * (1.0 + (2.0 * rho - 2.0) / (0.6**2 * rho))
        if name == "capped_cylinder":
            z = points[..., 2]
            second = 2.0 * 1.5**2 - 12.0 * 1.5 * z + 12.0 * z * z
            # Caps carry u=0. The lateral quartic has zero conormal derivative
            # at each authored rim, so no unrepresented interface load is used.
            return jnp.where((z == 0.0) | (z == 1.5), 0.0, exact(points) - second)
        return jnp.zeros(points.shape[:-1], dtype=points.dtype)

    closed = bool(law["closed"])
    actions = [phx.equations.DiffusionAction("u", 1.0)]
    if closed:
        actions.append(phx.equations.MassAction("u", 1.0))
    actions.append(
        phx.equations.SourceAction(
            "u",
            phx.equations.coefficient(
                forcing, coefficient_id=f"original-{name}-manufactured-source"
            ),
        )
    )
    form = phx.equations.FiniteElementForm(
        f"original-{name}-physical-surface", "u", tuple(actions)
    )
    if closed:
        problem = phx.equations.compile_finite_element_problem(form, space)
        free = np.arange(space.field_spaces[0].layout.size)
    else:
        constraint = phx.discretization.dirichlet_constraint(space, "u")
        problem = phx.equations.compile_finite_element_problem(
            form, space, constraint=constraint, dirichlet_values=exact
        )
        free = np.asarray(constraint.free_dofs)
    return space, problem, free, None


def _surface_qualification_error(space: Any, values: Any, law: _SurfaceLaw) -> float:
    if law["name"] == "sphere":
        from examples.native_surface_meshing import sphere_error

        return sphere_error(space, values)
    rule = phx.integration.ReferenceTriangleRule(phx.integration.GaussLegendreRule(5))
    data = phx.integration.reference_rule_data(rule)
    total = 0.0
    for index, _ in enumerate(space.mesh.blocks):
        geometry = space.evaluate_block_geometry(
            "u", index, space.default_runtime.coordinates, data.points, data.weights
        )
        routes = np.asarray(space.dof_maps[0].cell_dofs[index])
        approximate = np.einsum(
            "ql,cl->cq", np.asarray(geometry.basis_values), np.asarray(values)[routes]
        )
        exact = np.asarray(
            _surface_qualification_value(geometry.physical_points, str(law["name"]))
        )
        total += float(
            np.sum(np.asarray(geometry.physical_weights) * (approximate - exact) ** 2)
        )
    return float(np.sqrt(total))


def _surface_qualification_fields(result: Any) -> Any:
    fields = tuple(
        phx.discretization.FiniteElementFieldSpec(
            name, phx.discretization.lagrange_element("triangle", 1)
        )
        for name in ("u", "density", "history")
    )
    fields += (
        phx.discretization.FiniteElementFieldSpec(
            "curl",
            phx.discretization.form_element(
                "triangle", 1, 1, family="trimmed", proxy="circulation", twist="untwisted"
            ),
        ),
        phx.discretization.FiniteElementFieldSpec(
            "flux",
            phx.discretization.form_element(
                "triangle", 1, 1, family="trimmed", proxy="flux", twist="twisted"
            ),
        ),
    )
    return phx.discretization.FiniteElementPlan(
        result.mesh, fields, coordinate_spec=result.geometry
    ).prepare()


def _surface_qualification_content(space: Any, name: str, values: Any) -> float:
    index = next(
        i for i, field in enumerate(space.construction_plan.fields) if field.name == name
    )
    total = 0.0
    for block, geometry in enumerate(
        space.evaluate_geometry(name, space.default_runtime.coordinates)
    ):
        routes = np.asarray(space.dof_maps[index].cell_dofs[block])
        sampled = np.einsum(
            "ql,cl->cq", np.asarray(geometry.basis_values), np.asarray(values)[routes]
        )
        total += float(np.sum(sampled * np.asarray(geometry.physical_weights)))
    return total


def _surface_qualification_vector_norm(space: Any, name: str, values: Any) -> float:
    data = phx.integration.reference_rule_data(
        phx.integration.ReferenceTriangleRule(phx.integration.GaussLegendreRule(5))
    )
    total = 0.0
    for index, block in enumerate(space.mesh.blocks):
        geometry = space.evaluate_block_geometry(
            name, index, space.default_runtime.coordinates, data.points, data.weights
        )
        physical = np.asarray(space.reconstruct(name, values, block.name, data.points))
        total += float(
            np.sum(
                np.asarray(geometry.physical_weights)
                * np.sum(physical * physical, axis=-1)
            )
        )
    return float(np.sqrt(total))


def _surface_qualification_curl_seed(points: Any, context: Any) -> Any:
    del context
    return jnp.stack(
        (
            1.0 + 0.2 * points[..., 0],
            -0.4 + 0.1 * points[..., 1],
            0.3 + 0.15 * points[..., 2],
        ),
        axis=-1,
    )


def _surface_qualification_flux_seed(points: Any, context: Any) -> Any:
    del context
    return jnp.stack(
        (
            0.7 + 0.1 * points[..., 1],
            0.8 + 0.2 * points[..., 2],
            -0.2 + 0.05 * points[..., 0],
        ),
        axis=-1,
    )


def _surface_qualification_initial_fields(result: Any, scalar: Any) -> tuple[Any, ...]:
    space = _surface_qualification_fields(result)
    return (
        scalar,
        jnp.full((space.field_spaces[1].layout.size,), 2.0, dtype=scalar.dtype),
        space.dof_maps[2].dof_coordinates[:, 0] + 0.5,
        space.project("curl", _surface_qualification_curl_seed),
        space.project("flux", _surface_qualification_flux_seed),
    )


def _surface_qualification_material_initial(
    result: Any,
) -> phx.equations.MaterialTransaction:
    """Author nonzero cell history on the actual accepted physical FV owner."""
    owner = phx.discretization.UnstructuredFiniteVolumePlan.from_cell_mesh(
        result.mesh,
        field_name="surface-history",
        component_names=("surface-history",),
    ).prepare(cell_geometry=result.geometry)
    history = (1.0 + owner.cell_centers[:, 0] ** 2)[:, None]
    return phx.equations.MaterialTransaction(
        (
            phx.equations.MaterialState(
                phx.equations.MaterialSiteId("surface-history"),
                "surface-history",
                history,
            ),
        )
    )


def _surface_qualification_material_transport(
    sourceResult: Any,
    adaptation: Any,
    materials: phx.equations.MaterialTransaction,
    limits: Any,
    *,
    source_workspace: Any,
) -> tuple[phx.solver.MaterialTopologyTransferResult, dict[str, object]]:
    """Carry committed Kelvin history through the actual native chart remap."""
    from phydrax._fingerprint import array_tree_fingerprint

    source = phx.discretization.UnstructuredFiniteVolumePlan.from_cell_mesh(
        sourceResult.mesh,
        field_name="surface-history",
        component_names=("surface-history",),
    ).prepare(cell_geometry=sourceResult.geometry)
    target = phx.discretization.UnstructuredFiniteVolumePlan.from_cell_mesh(
        adaptation.target.mesh,
        field_name="surface-history",
        component_names=("surface-history",),
    ).prepare(cell_geometry=adaptation.target.geometry)
    source_workspace.retain_owner(
        (source, target, materials, materials.state("surface-history").committed)
    )
    remap = phx.discretization.prepare_unstructured_conservative_remap(
        source,
        target,
        provenance="surface-history",
        policy=phx.geometry.CommonRefinementPolicy(
            maximum_exact_work=limits.maximum_work_units,
            maximum_memory_bytes=limits.maximum_scratch_bytes,
        ),
        source_geometry=sourceResult.geometry,
        target_geometry=adaptation.target.geometry,
        surface_chart_deformation=adaptation.geometry_transition.chart_deformation,
        adaptation=adaptation,
        source_workspace=source_workspace,
    )
    evidence = remap.evidence
    if (
        not remap.succeeded
        or remap.plan is None
        or not isinstance(
            evidence, phx.discretization.finite_volume.MappedSurfaceChartRemapEvidence
        )
        or not evidence.passed
    ):
        raise RuntimeError(
            f"Actual surface material remap refused publication: {remap.reason}"
        )
    state = materials.state("surface-history")
    source_history = state.committed
    if source_history.shape != (source.cell_count, 1):
        raise ValueError(
            "Surface material history must have actual cell-by-one Kelvin payload."
        )
    target_history = remap.plan.apply(source_history)
    defect = np.asarray(remap.plan.conservation_defect(source_history, target_history))
    source_terms = np.asarray(remap.plan.source_volumes)[:, None] * np.asarray(
        source_history
    )
    target_terms = np.asarray(remap.plan.target_volumes)[:, None] * np.asarray(
        target_history
    )
    source_inventory = np.sum(source_terms, axis=0)
    target_inventory = np.sum(target_terms, axis=0)
    coverage_error = float(
        np.asarray(remap.plan.report.total_source_coverage_error_bound)
    ) * np.max(np.abs(np.asarray(source_history)), axis=0)
    publication_roundoff = (
        64.0
        * np.finfo(np.asarray(target_history).dtype).eps
        * (np.sum(np.abs(source_terms), axis=0) + np.sum(np.abs(target_terms), axis=0))
    )
    allowance = coverage_error + publication_roundoff
    if not np.all(np.isfinite(defect)) or np.any(np.abs(defect) > allowance):
        raise RuntimeError(
            "Surface material remap exceeds declared physical coverage and publication roundoff."
        )
    carried = phx.equations.MaterialTransaction(
        (
            phx.equations.MaterialState(
                state.site_id,
                state.model_id,
                target_history,
                state_version=state.state_version + 1,
            ),
        )
    )
    return phx.solver.MaterialTopologyTransferResult(carried, (remap,)), {
        "site": "surface-history",
        "value_units": ["Kelvin"],
        "source_result_id": sourceResult.result_id,
        "source_owner_id": source.prepared_id,
        "target_owner_id": target.prepared_id,
        "source_material_state_id": state.state_id,
        "target_material_state_id": carried.state("surface-history").state_id,
        "remap_id": remap.remap_id,
        "plan_id": remap.plan.plan_id,
        "evidence_id": array_tree_fingerprint(evidence),
        "chart_deformation_id": array_tree_fingerprint(
            adaptation.geometry_transition.chart_deformation
        ),
        "source_physical_inventory": source_inventory.tolist(),
        "target_physical_inventory": target_inventory.tolist(),
        "conservation_defect": defect.tolist(),
        "source_coverage_error_bound": coverage_error.tolist(),
        "publication_roundoff_bound": publication_roundoff.tolist(),
        "passed": bool(
            remap.succeeded and evidence.passed and np.all(np.abs(defect) <= allowance)
        ),
    }


def _surface_qualification_acceptance(
    source: Any, result: Any, request: Any, law: _SurfaceLaw
) -> dict[str, object]:
    certification = result.certification
    if certification is None or certification.fidelity is None:
        raise RuntimeError(
            "Surface publication lost its actual original source fidelity graph."
        )
    fidelity = certification.fidelity
    fidelity.binding.require(result.mesh, result.geometry)
    charts = result.surface_source
    if charts is None:
        raise RuntimeError(
            "Surface publication lost its original SCI-ordered native source chart premise."
        )
    charts.require_bound(result.mesh, result.geometry, certification.request.source)
    if charts._source_identity(charts.domain) != charts._source_identity(source.domain):
        raise RuntimeError(
            "Surface publication changed original source coefficient/stratum/control banks."
        )
    if (fidelity.binding.source_id, fidelity.binding.source_revision) != (
        source.source_id,
        source.source_revision,
    ):
        raise RuntimeError(
            "Surface publication source certification changed original authority."
        )
    coordinates = np.asarray(result.mesh.coordinates)
    cells = np.concatenate([np.asarray(block.vertices) for block in result.mesh.blocks])
    edges, uses = np.unique(
        np.sort(
            np.concatenate((cells[:, (0, 1)], cells[:, (1, 2)], cells[:, (2, 0)])), axis=1
        ),
        axis=0,
        return_counts=True,
    )
    euler = np.unique(cells).size - edges.shape[0] + cells.shape[0]
    space = _surface_qualification_fields(result)
    one = jnp.ones((space.field_spaces[0].layout.size,), dtype=coordinates.dtype)
    area = _surface_qualification_content(space, "u", one)
    size = request.size_controls[0].target_size
    bound = float(law["area"]) * max(
        0.25 * (float(law["curvature"]) * size) ** 2, 1.0e-12
    )
    passed = bool(
        result.audit.passed
        and result.compliance.passed
        and certification.passed
        and fidelity.status == "certified"
        and fidelity.chart_coverage is not None
        and fidelity.chart_coverage.complete
        and all(item.complete for item in result.associations)
        and np.all((uses == 1) | (uses == 2))
        and (not law["closed"] or np.all(uses == 2))
        and euler == law["euler"]
        and abs(area - float(law["area"])) <= bound
    )
    return {
        "passed": passed,
        "source_binding_id": source.binding_id,
        "original_source_chart_id": charts.source_chart_id,
        "original_source_mesh_topology_id": charts.mesh.topology_id,
        "original_source_boundary_scope_id": charts.boundary_source.source_scope_id,
        "fidelity_certificate_id": fidelity.certificate_id,
        "chart_coverage_id": None
        if fidelity.chart_coverage is None
        else fidelity.chart_coverage.cover_id,
        "physical_area": area,
        "independent_source_area": law["area"],
        "area_error_bound": bound,
        "euler_characteristic": euler,
        "complete_source_associations": all(
            item.complete for item in result.associations
        ),
        "result": _result_identity(result),
    }


def _surface_qualification_transition(
    source: Any,
    adaptation: Any,
    problem: Any,
    values: Any,
    auxiliary: tuple[Any, ...],
    epoch: int,
    law: _SurfaceLaw,
    materials: Any,
    limits: Any,
) -> tuple[Any, tuple[Any, ...], Any, dict[str, object]]:
    from phydrax.lifecycle import CompositionRebind

    full = _surface_qualification_fields(source)
    fields = full.construction_plan.fields
    accepted = phx.solver.FiniteElementAcceptedState(
        (values, *auxiliary),
        0.0,
        epoch,
        source.mesh.topology_id,
        full.prepared_id,
        problem.compilation_id,
        state_version=epoch,
        materials=materials,
    )
    source_density = _surface_qualification_content(full, "density", auxiliary[0])
    target_space = _surface_qualification_fields(adaptation.target)
    rebinds: list[CompositionRebind] = []
    material_evidence: list[dict[str, object]] = []

    def transfer_material(
        original: Any, lineage: object, context: object, *, source_workspace: Any
    ) -> Any:
        del lineage, context
        if original.transaction_id != materials.transaction_id:
            raise ValueError(
                "Surface material transport received a different accepted source epoch."
            )
        transfer, evidence = _surface_qualification_material_transport(
            source, adaptation, original, limits, source_workspace=source_workspace
        )
        material_evidence.append(evidence)
        return transfer

    def capture(rebind: CompositionRebind) -> CompositionRebind:
        rebinds.append(rebind)
        return rebind

    def certify(
        mesh: Any,
        moved: tuple[Any, ...],
        candidate_materials: object,
        lineage: object,
        context: object,
    ) -> bool:
        del lineage, context
        if mesh.topology_id != adaptation.target.mesh.topology_id:
            return False
        if (
            not isinstance(candidate_materials, phx.equations.MaterialTransaction)
            or candidate_materials.state("surface-history").state_version
            != materials.state("surface-history").state_version + 1
        ):
            return False
        content = _surface_qualification_content(target_space, "density", moved[1])
        return (
            all(bool(jnp.all(jnp.isfinite(item))) for item in moved)
            and abs(content - source_density) <= 1.0e-10 * max(1.0, abs(source_density))
            and _surface_qualification_vector_norm(target_space, "curl", moved[3]) > 0.0
            and _surface_qualification_vector_norm(target_space, "flux", moved[4]) > 0.0
        )

    def impossible_density(
        mesh: Any,
        moved: tuple[Any, ...],
        materials: object,
        lineage: object,
        context: object,
    ) -> bool:
        del mesh, materials, lineage, context
        return _surface_qualification_content(target_space, "density", moved[1]) <= 0.0

    semantics: dict[str, phx.discretization.SourceRealizationFieldSemantics] = {
        "u": "intensive",
        "density": "conservative-density",
        "history": "intensive",
        "curl": "material-compatible",
        "flux": "material-compatible",
    }
    rejected = phx.solver.FiniteElementTopologyTransaction(
        impossible_density,
        fields=fields,
        surface_chart_semantics=semantics,
        material_transfer=transfer_material,
        callback_owners=(full, target_space, materials, accepted.fields),
    ).execute(accepted, source.mesh, adaptation)
    if (
        bool(rejected.committed)
        or rejected.receipt is None
        or rejected.receipt.published
        or rejected.state is not accepted
        or rejected.mesh is not source.mesh
        or rejected.state.materials is not accepted.materials
        or any(
            not np.array_equal(np.asarray(a), np.asarray(b))
            for a, b in zip(rejected.state.fields, accepted.fields, strict=True)
        )
    ):
        raise RuntimeError(
            "Rejected physical surface transaction changed its accepted source epoch."
        )
    transaction = phx.solver.FiniteElementTopologyTransaction(
        certify,
        fields=fields,
        surface_chart_semantics=semantics,
        composition_rebind=capture,
        material_transfer=transfer_material,
        callback_owners=(full, target_space, materials, accepted.fields),
    ).execute(accepted, source.mesh, adaptation)
    if (
        not bool(transaction.committed)
        or transaction.receipt is None
        or not transaction.receipt.published
        or not rebinds
        or not all(item.evidence.passed for item in transaction.transfers)
    ):
        raise RuntimeError(
            f"Physical surface CompositionRebind refused: {transaction.diagnostics}"
        )
    target_density = _surface_qualification_content(
        target_space, "density", transaction.state.fields[1]
    )
    scalar, _, _, _ = _surface_qualification_solver(adaptation.target, law)
    return (
        transaction.state.fields[0],
        transaction.state.fields[1:],
        transaction.state.materials,
        {
            "receipt_id": transaction.receipt.receipt_id,
            "source_composition_id": rebinds[-1].source.composition_id,
            "target_composition_id": transaction.receipt.composition.composition_id,
            "field_names": [field.name for field in fields],
            "surface_chart_semantics": semantics,
            "source_density_content": source_density,
            "target_density_content": target_density,
            "density_content_defect": target_density - source_density,
            "material_transport": material_evidence[-1],
            "remapped_physical_error": _surface_qualification_error(
                scalar, transaction.state.fields[0], law
            ),
            "field_transfers": [
                {
                    "transfer_id": item.transfer_id,
                    "passed": item.evidence.passed,
                    "defects": dict(item.evidence.defects),
                    "bounds": dict(item.evidence.bounds),
                }
                for item in transaction.transfers
            ],
            "rollback": {
                "passed": True,
                "requested_density_content_upper": 0.0,
                "receipt_id": rejected.receipt.receipt_id,
                "diagnostics": rejected.diagnostics,
            },
        },
    )


def _surface_qualification_checkpoint(
    source: Any,
    result: Any,
    request: Any,
    options: Any,
    law: Any,
    history: Any,
    adaptations: Any,
    args: argparse.Namespace,
    record: dict[str, Any],
    started: float,
) -> None:
    """Publish each atomic accepted epoch with its exact native source closure."""
    import os
    import subprocess
    import sys
    from dataclasses import asdict

    from phydrax._array_archive import DEFAULT_ARRAY_ARCHIVE_LIMITS
    from phydrax._differentiation import BranchDifferentiationPolicy
    from phydrax._fingerprint import array_tree_fingerprint
    from phydrax._frozendict import frozendict
    from phydrax.discretization._views import FieldTracePolicy
    from phydrax.lifecycle._meshing_field_records import (
        MeshingFieldDeclaration,
        MeshingFieldStateRole,
        prepare_meshing_field_index_binding,
    )
    from phydrax.lifecycle._meshing_sources import write_meshing_source_closure

    if not history or history[-1]["result"].result_id != result.result_id:
        raise RuntimeError(
            "Surface checkpoint requires the actual complete accepted history."
        )
    limits = DEFAULT_ARRAY_ARCHIVE_LIMITS
    policy = asdict(limits)
    policy["allowed_dtype_kinds"] = sorted(limits.allowed_dtype_kinds)
    evidence = {
        "archive_limits": policy,
        "prepared_fe_caches_serialized": False,
        "archives": [],
    }
    record["checkpoint"] = evidence
    names = ("u", "density", "history", "curl", "flux")
    with TemporaryDirectory(prefix="phydrax-native-surface-epochs-") as directory:
        publications = []
        for epoch, accepted in enumerate(history):
            carrier = accepted["result"]
            owner = _surface_qualification_fields(carrier)
            spaces = {space.name: space for space in owner.field_spaces}
            values = dict(zip(names, accepted["fields"], strict=True))
            arrays = {f"surface:{name}": values[name] for name in names}
            roles = [
                MeshingFieldStateRole(
                    f"surface:{name}",
                    name,
                    "coefficients",
                    tuple(values[name].shape),
                    np.dtype(values[name].dtype),
                    epoch,
                    index_binding=prepare_meshing_field_index_binding(
                        carrier, "field/global_coefficient_ids", field_space=spaces[name]
                    ),
                )
                for name in names
            ]
            arrays["surface:accepted-epoch"] = np.asarray(epoch, dtype=np.int64)
            roles.append(
                MeshingFieldStateRole(
                    "surface:accepted-epoch",
                    "u",
                    "state-epoch",
                    (),
                    np.dtype(np.int64),
                    epoch,
                )
            )
            material = accepted["material"]
            material_identity = None
            if material is not None:
                state = material.state("surface-history")
                if len(material.states) != 1 or state.model_id != "surface-history":
                    raise RuntimeError(
                        "Surface material checkpoint requires its authored site declaration."
                    )
                arrays["surface:material"] = state.committed
                arrays["surface:material-trial"] = state.trial
                for entry in ("surface:material", "surface:material-trial"):
                    roles.append(
                        MeshingFieldStateRole(
                            entry,
                            "history",
                            "material-history",
                            tuple(arrays[entry].shape),
                            np.dtype(arrays[entry].dtype),
                            epoch,
                            value_units=(phx.units.KELVIN,),
                            index_binding=prepare_meshing_field_index_binding(
                                carrier, "mesh/cell_ids"
                            ),
                        )
                    )
                material_identity = {
                    "state_version": state.state_version,
                    "transaction_id": material.transaction_id,
                }
            declaration = MeshingFieldDeclaration(
                part_name="generation",
                owner="finite_element",
                topology_id=carrier.mesh.topology_id,
                geometry_layout_id=carrier.geometry.geometry_layout_id,
                field_space_ids=frozendict(
                    {name: spaces[name].field_space_id for name in names}
                ),
                value_units=frozendict({name: (phx.units.ONE,) for name in names}),
                maximum_derivative_orders=frozendict({name: 1 for name in names}),
                branch_policy=BranchDifferentiationPolicy.FROZEN_DECISION,
                trace_policy=FieldTracePolicy("cell-sided"),
                state_roles=tuple(roles),
                history_policy="accepted-state",
                numeric_version=owner.numeric_version,
                finite_element_fields=owner.construction_plan.fields,
                precision_policy=owner.construction_plan.precision_policy,
            )
            records = {
                "certification_inputs": carrier.certification.request,
                "report": carrier.certification,
                "associations": carrier.associations,
                "generation_part": phx.meshing.MeshPart(
                    "generation", carrier, coordinate_contract=carrier.coordinate_contract
                ),
                "generation_source": source,
                "generation_specification": request,
                "generation_options": options,
                "field_declarations": {"generation": declaration},
                "accepted_data": {
                    "fields": arrays,
                    "adaptation_results": tuple(adaptations[:epoch]),
                },
            }
            record["active_phase"] = f"surface_checkpoint_epoch_{epoch}"
            receipt = write_meshing_source_closure(
                Path(directory) / f"epoch-{epoch}.zip", records, limits=limits
            )
            physical = {
                "error": accepted["error"],
                "density_content": accepted["density_content"],
                "history_content": _surface_qualification_content(
                    owner, "history", values["history"]
                ),
                "curl_norm": _surface_qualification_vector_norm(
                    owner, "curl", values["curl"]
                ),
                "flux_norm": _surface_qualification_vector_norm(
                    owner, "flux", values["flux"]
                ),
            }
            publication = {
                "path": str(receipt.path),
                "content_id": receipt.content_id,
                "fingerprint": array_tree_fingerprint(records),
                "physical": physical,
                "material": material_identity,
            }
            publications.append(publication)
            evidence["archives"].append(
                {
                    "epoch": epoch,
                    "content_id": receipt.content_id,
                    "container_bytes": receipt.path.stat().st_size,
                    "fingerprint": publication["fingerprint"],
                }
            )
        payload = Path(directory) / "cold-input.json"
        payload.write_text(
            json.dumps(
                {
                    "publications": publications,
                    "law": law,
                    "repeats": args.repeats,
                    "target_error": args.target_error,
                }
            )
        )
        remaining = args.timeout - (perf_counter() - started)
        if remaining <= 0.0:
            raise TimeoutError("Surface publication exhausted its original wall budget.")
        script = (
            "import json,sys; from tools.meshing_qualification import "
            "_surface_qualification_cold_worker; p=json.load(open(sys.argv[1])); "
            "print(json.dumps(_surface_qualification_cold_worker(**p)))"
        )
        record["active_phase"] = "surface_checkpoint_fresh_process_restart"
        try:
            child = subprocess.run(
                [sys.executable, "-c", script, str(payload)],
                capture_output=True,
                text=True,
                timeout=remaining,
                check=False,
            )
        except subprocess.TimeoutExpired as failure:
            evidence.update(
                {
                    "timeout_seconds": remaining,
                    "stdout": failure.stdout,
                    "stderr": failure.stderr,
                }
            )
            raise TimeoutError(
                "Surface cold restart exhausted the original wall budget."
            ) from failure
        evidence.update(
            {
                "returncode": child.returncode,
                "stdout": child.stdout,
                "stderr": child.stderr,
            }
        )
        if child.returncode:
            raise RuntimeError(
                "Surface cold restart refused; actual child output retained."
            )
        cold = json.loads(child.stdout)
        if cold["process_id"] == os.getpid():
            raise RuntimeError("Surface restart did not use an independent process.")
        evidence["cold_restart"] = cold
        continuation = cold["continued_solver_epoch"]
        continuation["epoch"] = len(record["epochs"])
        record["epochs"].append(continuation)
        if (
            continuation["l2_error"] <= args.target_error
            and record["time_to_target_error_seconds"] is None
        ):
            record["time_to_target_error_seconds"] = perf_counter() - started


def _surface_qualification_cold_worker(
    publications: list[dict[str, Any]],
    law: _SurfaceLaw,
    repeats: int,
    target_error: float,
) -> dict[str, Any]:
    """Renew every retained native map and continue the final accepted PDE state."""
    import os

    from phydrax._array_archive import DEFAULT_ARRAY_ARCHIVE_LIMITS
    from phydrax._fingerprint import array_tree_fingerprint
    from phydrax.lifecycle._meshing_field_records import prepare_meshing_field_owner
    from phydrax.lifecycle._meshing_sources import (
        read_meshing_source_closure,
        recertify_restored_meshing_source,
    )

    renewed = []
    names = ("u", "density", "history", "curl", "flux")
    for epoch, publication in enumerate(publications):
        restored = read_meshing_source_closure(
            Path(publication["path"]),
            expected_content_id=publication["content_id"],
            limits=DEFAULT_ARRAY_ARCHIVE_LIMITS,
        )
        if array_tree_fingerprint(restored) != publication["fingerprint"]:
            raise RuntimeError(
                "Surface cold closure changed source, controls, result or field bits."
            )
        carrier = restored["generation_part"].carrier
        report = recertify_restored_meshing_source(
            restored["certification_inputs"],
            carrier.mesh,
            carrier.geometry,
            carrier.audit,
            archive_limits=DEFAULT_ARRAY_ARCHIVE_LIMITS,
        )
        report.require_passed()
        if report.report_id != restored["report"].report_id:
            raise RuntimeError(
                "Surface source renewal changed the accepted certification theorem."
            )
        owner, _ = prepare_meshing_field_owner(
            restored["field_declarations"]["generation"], carrier
        )
        arrays = restored["accepted_data"]["fields"]
        if int(np.asarray(arrays["surface:accepted-epoch"])) != epoch:
            raise RuntimeError("Surface restored accepted epoch changed.")
        values = tuple(jnp.asarray(arrays[f"surface:{name}"]) for name in names)
        scalar, problem, free, weights = _surface_qualification_solver(carrier, law)
        physical = {
            "error": _surface_qualification_error(scalar, values[0], law),
            "density_content": _surface_qualification_content(
                owner, "density", values[1]
            ),
            "history_content": _surface_qualification_content(
                owner, "history", values[2]
            ),
            "curl_norm": _surface_qualification_vector_norm(owner, "curl", values[3]),
            "flux_norm": _surface_qualification_vector_norm(owner, "flux", values[4]),
        }
        if physical != publication["physical"]:
            raise RuntimeError(
                "Surface restored physical error, inventory or mapped vector norm changed."
            )
        material = publication["material"]
        if material is not None:
            transaction = phx.equations.MaterialTransaction(
                (
                    phx.equations.MaterialState(
                        phx.equations.MaterialSiteId("surface-history"),
                        "surface-history",
                        arrays["surface:material"],
                        trial=arrays["surface:material-trial"],
                        state_version=material["state_version"],
                    ),
                )
            )
            if transaction.transaction_id != material["transaction_id"]:
                raise RuntimeError("Surface cold material primitive state changed.")
        renewed.append(
            {
                "epoch": epoch,
                "result": _result_identity(carrier),
                "report_id": report.report_id,
                "physical": physical,
            }
        )
    if not renewed:
        raise RuntimeError("Surface cold continuation has no accepted epoch.")
    solved, compiler, stages = _compiled_solver_stages(problem, values[0][free], repeats)
    if weights is not None:
        solved = solved - jnp.sum(weights * solved) / jnp.sum(weights)
    error = _surface_qualification_error(scalar, solved, law)
    return {
        "process_id": os.getpid(),
        "runtime": _runtime_identity(),
        "accepted_fields_bitwise_preserved": True,
        "prepared_fe_caches_serialized": False,
        "renewed_epochs": renewed,
        "continued_solver_epoch": {
            "result": _result_identity(carrier),
            "l2_error": error,
            "target_error": target_error,
            "target_error_met": error <= target_error,
            "seed_origin": "actual-cold-restored-accepted-u-free",
            "compiler": compiler,
            "stages_seconds": stages,
        },
    }


def _surface_qualification_adapt(result: Any, initial: Any, request: Any) -> Any:
    from phydrax.geometry._surface_source_support import PreparedSurfaceSourceSupport
    from phydrax.meshing._association import SurfaceAssociationTransfer

    charts = initial.surface_source
    if (
        charts is None
        or initial.certification is None
        or initial.certification.fidelity is None
    ):
        raise RuntimeError(
            "Surface adaptation requires the actual retained original native chart and fidelity premise."
        )
    charts.require_root(initial.mesh, initial.geometry)
    support = PreparedSurfaceSourceSupport(
        charts.domain,
        initial,
        charts.root_parameters,
        charts.boundary_source,
        maximum_support_queries=charts.maximum_support_queries,
    )
    vertices = result.mesh.entity_set(0)
    scope = phx.meshing.MeshingScope(
        result.mesh.mesh_id,
        result.mesh.numeric_version,
        phx.meshing.MeshingEntityKind.MESH,
        0,
        vertices.entity_set_id,
        vertices.entity_ids,
    )
    size = request.size_controls[0].target_size / 2.0
    metric = phx.meshing.MeshMetricField(
        scope,
        np.broadcast_to(np.eye(3) / size**2, (result.mesh.coordinates.shape[0], 3, 3)),
        minimum_size=size,
        maximum_size=size,
    )
    policy = phx.meshing.MeshAdaptationPolicy(
        phx.meshing.MeshAdaptationRoute.NATIVE_SURFACE_METRIC,
        limits=request.limits,
        association_transfer=SurfaceAssociationTransfer(support),
        geometry_transition=phx.discretization.CellGeometryTransitionPolicy(
            reconstruction="bounded_chart_deformation",
            reconstruction_tolerance=initial.certification.fidelity.tolerance,
            maximum_evaluations=request.limits.maximum_work_units,
        ),
        audit_policy=phx.meshing.CellMeshAuditPolicy(require_complete_association=True),
    )
    adaptation = phx.meshing.execute_mesh_adaptation(
        phx.meshing.prepare_mesh_adaptation(
            result,
            phx.meshing.MetricMeshAdaptation(
                metric, coordinate_contract=result.coordinate_contract
            ),
            policy=policy,
        )
    )
    if (
        adaptation.status is not phx.meshing.MeshAdaptationStatus.COMPLETE
        or adaptation.target.mesh.topology_id == result.mesh.topology_id
    ):
        raise RuntimeError(
            f"Original source surface adaptation did not complete a genuine topology transition: {adaptation.status.value}."
        )
    return adaptation


def _surface_qualification_state_inventory(
    result: Any, fields: tuple[Any, ...], material: Any
) -> tuple[Any, float, dict[str, float]]:
    actual_material = (
        _surface_qualification_material_initial(result) if material is None else material
    )
    owner = _surface_qualification_fields(result)
    density = _surface_qualification_content(owner, "density", fields[1])
    norms = {
        name: _surface_qualification_vector_norm(owner, name, fields[index])
        for name, index in (("curl", 3), ("flux", 4))
    }
    return actual_material, density, norms


def _surface_qualification_lifecycle(args: argparse.Namespace) -> dict[str, object]:
    started = perf_counter()
    record: dict[str, Any] = {
        "scenario": "native-surface-pde",
        "surface_case": args.surface_case,
        "status": "failed",
        "runtime": _runtime_identity(),
        "targets": {"physical_error": args.target_error, "wall_seconds": args.timeout},
        "control_capacities": {
            "resolution": args.resolution,
            "entity_capacity": args.capacity,
        },
        "stages_seconds": {},
        "epochs": [],
        "mandatory_workflow_completion": "incomplete",
        "time_to_target_error_seconds": None,
        "release_evidence": "unassessed",
        "leadership_evidence": "unassessed",
    }
    phases: list[NativeMeshingPhaseMeasurement] = []
    phase = "original_source_request_preparation"
    try:
        prepared, timing = _measured(lambda: _surface_qualification_prepare(args))
        source, request, options, law = prepared
        record["stages_seconds"][phase] = timing["wall_seconds"]
        record.update(
            {
                "source_id": source.source_id,
                "source_revision": source.source_revision,
                "source_binding_id": source.binding_id,
                "request_id": request.specification_id,
                "limits_id": request.limits.limits_id,
                "profile_law": law,
            }
        )
        phase = "original_native_source_preparation"
        provider = phx.meshing.NativeMeshingProvider(options)
        plan, timing = _measured(
            lambda: provider.plan(
                source,
                request,
                coordinate_contract=phx.SpatialCoordinateContract.si(),
                record_phase=phases.append,
            )
        )
        record["stages_seconds"][phase] = timing["wall_seconds"]
        phase = "original_public_surface_publication"
        result, timing = _measured(lambda: plan.execute(record_phase=phases.append))
        record["stages_seconds"][phase] = timing["wall_seconds"]
        initial = result
        record["generation"] = _result_identity(initial)
        accepted_history: list[dict[str, object]] = []
        adaptations = []
        previous = None
        for epoch in range(args.adaptation_rounds + 1):
            phase = f"source_acceptance_epoch_{epoch}"
            result, acceptance = _corpus_native_consumer(
                result,
                request,
                lambda: _surface_qualification_acceptance(source, result, request, law),
                native=True,
            )
            if not acceptance["passed"]:
                raise RuntimeError(
                    "Actual surface publication failed the original source, physical measure or topology oracle."
                )
            phase = f"physical_solver_epoch_{epoch}"

            def solve_epoch() -> tuple[
                Any,
                tuple[Any, ...],
                dict[str, object],
                dict[str, float],
                float,
                float | None,
            ]:
                space, problem, free, weights = _surface_qualification_solver(result, law)
                seed = (
                    problem.state_space.zeros()
                    if previous is None
                    else jnp.asarray(previous[0])[free]
                )
                values, compiler, timings = _compiled_solver_stages(
                    problem, seed, args.repeats
                )
                fields = (
                    _surface_qualification_initial_fields(result, values)
                    if previous is None
                    else (values, *previous[1:])
                )
                error = _surface_qualification_error(space, values, law)
                mean = (
                    None
                    if weights is None
                    else float(weights @ np.asarray(values) / np.sum(weights))
                )
                return problem, fields, compiler, timings, error, mean

            result, solved = _corpus_native_consumer(
                result, request, solve_epoch, native=True
            )
            problem, fields, compiler, timings, error, mean = solved
            if not np.isfinite(error) or (
                law["name"] == "sphere" and (mean is None or abs(mean) > 1.0e-10)
            ):
                raise RuntimeError(
                    "Actual physical surface PDE failed its independent error/zero-mean oracle."
                )
            result, inventory = _corpus_native_consumer(
                result,
                request,
                lambda: _surface_qualification_state_inventory(
                    result, fields, None if previous is None else previous_material
                ),
                native=True,
            )
            material, density, vector_norms = inventory
            if density <= 0.0 or any(
                value <= 0.0 or not np.isfinite(value) for value in vector_norms.values()
            ):
                raise RuntimeError(
                    "Physical surface fields lost their authored nonzero density or compatible moments."
                )
            accepted_history.append(
                {
                    "result": result,
                    "fields": fields,
                    "material": material,
                    "error": error,
                    "density_content": density,
                }
            )
            record["epochs"].append(
                {
                    "epoch": epoch,
                    "result": _result_identity(result),
                    "source_acceptance": acceptance,
                    "physical_error": error,
                    "surface_mean": mean,
                    "density_content": density,
                    "compatible_physical_norms": vector_norms,
                    "compiler": compiler,
                    "seed_origin": "authored-initial-state"
                    if previous is None
                    else "actual-carried-u",
                }
            )
            record["stages_seconds"].update(
                {f"{name}_epoch_{epoch}": value for name, value in timings.items()}
            )
            if epoch == args.adaptation_rounds:
                break
            phase = f"original_source_metric_adaptation_epoch_{epoch}"
            result, adaptation = _corpus_native_consumer(
                result,
                request,
                lambda: _surface_qualification_adapt(result, initial, request),
                native=True,
            )
            adaptations.append(adaptation)
            phase = f"allphysical_history_composition_epoch_{epoch}"
            moved, auxiliary, previous_material, transition = (
                _surface_qualification_transition(
                    adaptation.source,
                    adaptation,
                    problem,
                    fields[0],
                    fields[1:],
                    epoch,
                    law,
                    material,
                    request.limits,
                )
            )
            previous = (moved, *auxiliary)
            record["epochs"][-1].update(
                {
                    "state_transition": transition,
                    "adaptation": {
                        "status": adaptation.status.value,
                        "source_result_id": adaptation.source.result_id,
                        "target": _result_identity(adaptation.target),
                    },
                }
            )
            result = adaptation.target
        phase = "default_allfield_accepted_history_checkpoint_cold_continuation"
        _surface_qualification_checkpoint(
            source,
            result,
            request,
            options,
            law,
            tuple(accepted_history),
            tuple(adaptations),
            args,
            record,
            started,
        )
        elapsed = perf_counter() - started
        final_error = _record_float(
            accepted_history[-1]["error"], "Surface physical error"
        )
        completed = final_error <= args.target_error and elapsed <= args.timeout
        record.update(
            {
                "status": "passed"
                if completed
                else "timeout"
                if elapsed > args.timeout
                else "failed",
                "physical_error": final_error,
                "target_error_reached": final_error <= args.target_error,
                "independent_scientific_certification": (
                    "passed" if final_error <= args.target_error else "failed"
                ),
                "mandatory_workflow_completion": "complete"
                if completed
                else "incomplete",
                "source_acceptance": acceptance,
                "time_to_target_error_seconds": elapsed if completed else None,
                "field_names": ["u", "density", "history", "curl", "flux"],
            }
        )
    except phx.meshing.MeshingFailure as failure:
        record.update(
            {
                "failure": str(failure),
                "failure_phase": phase,
                "failure_category": failure.category.value,
                "requested": dict(failure.evidence.requested),
                "achieved": dict(failure.evidence.achieved),
                "failure_evidence_id": failure.evidence.evidence_id,
            }
        )
    except (RuntimeError, ValueError, TypeError, TimeoutError) as failure:
        record.update(
            {
                "failure": str(failure),
                "failure_type": type(failure).__name__,
                "failure_phase": phase,
            }
        )
    finally:
        record["native_phases"] = _phase_recordings(phases)
        record["end_to_end_seconds"] = perf_counter() - started
        record["peak_process_resident_bytes"] = resource.getrusage(
            resource.RUSAGE_SELF
        ).ru_maxrss * (1 if sys.platform == "darwin" else 1024)
    return record


def qualify_native_surface(args: argparse.Namespace) -> dict[str, object]:
    """Exercise the original source, all physical states and cold continued PDE."""
    return _surface_qualification_lifecycle(args)


def qualify_native_image(args: argparse.Namespace) -> dict[str, object]:
    """Consume the genuine generated-region Neurofluid transport scenario."""
    from tools.neurofluid_qualification import native_transport

    record = native_transport(
        size=args.image_size,
        repeats=args.repeats,
        steps=args.transport_steps,
        dt=args.transport_dt,
        target_error=args.target_error,
        balance_tolerance=args.balance_tolerance,
        maximum_cells=args.capacity,
        maximum_vertices=args.capacity,
        oracle_capacity=args.oracle_capacity,
    )
    successful = record["successful"]
    if not isinstance(successful, bool):
        raise TypeError(
            "Neurofluid qualification must retain its Boolean success status."
        )
    result: dict[str, Any] = {
        **record,
        "scenario": "native-image-lifecycle",
        "status": "passed" if successful else "failed",
        "runtime": _runtime_identity(),
        "mandatory_workflow_completion": "incomplete",
        "case_contract_completion": "incomplete",
        "independent_scientific_certification": "unassessed",
        "release": "unassessed",
        "leadership": "unassessed",
    }
    if successful:
        identities = _record_mapping(record["identities"], "Neurofluid identities")
        invariants = _record_mapping(record["invariants"], "Neurofluid invariants")
        timing = _record_mapping(record["timing"], "Neurofluid timing")
        memory = _record_mapping(record["memory"], "Neurofluid memory")
        lifecycle = _record_mapping(
            record["lifecycle"], "Neurofluid complete physical lifecycle"
        )
        cold = _record_mapping(
            lifecycle["cold"], "Neurofluid fresh source/allfield continuation"
        )
        elapsed = _record_float(
            timing["end_to_end_seconds"], "Neurofluid end-to-end time"
        )
        complete = (
            lifecycle["passed"] is True
            and cold["passed"] is True
            and elapsed <= args.timeout
        )
        result["status"] = "passed" if complete else "failed"
        result["case_contract_completion"] = "complete" if complete else "incomplete"
        result["independent_scientific_certification"] = (
            "passed"
            if lifecycle["passed"] is True and cold["passed"] is True
            else "failed"
        )
        result.update(
            {
                "request_id": identities["request_id"],
                "physical_error": invariants["physical_error"],
                "end_to_end_seconds": timing["end_to_end_seconds"],
                "time_to_target_error_seconds": timing["end_to_end_seconds"],
                "peak_process_resident_bytes": memory["process_peak_resident_bytes"],
            }
        )
    return result


def _corpus_contract_choices(
    contract: dict[str, object], argument: str | None
) -> tuple[str, ...]:
    if argument is None:
        choices = contract["parser_choices"]
    else:
        arguments = _record_mapping(contract["required_arguments"], "Profile arguments")
        choices = _record_mapping(arguments[argument], f"{argument} contract")["choices"]
    if not isinstance(choices, (tuple, list)) or not all(
        isinstance(value, str) for value in choices
    ):
        raise TypeError("Canonical profile choices must be declared strings.")
    return tuple(choices)


def _scenario_source_reference(
    scenario: str,
    controls: dict[str, str | int | float | tuple[float, ...]],
) -> dict[str, object]:
    """Identity of an owning generated source descriptor, not generated mesh output."""
    if scenario == "native-cad-lifecycle":
        fixture = load_cad_fixture()
        return {
            "kind": "reviewed-cad-corpus-source",
            "source_digest": fixture["file_sha256"],
            "source_revision": fixture["record_id"],
            "source_artifact": {
                "locator": "tests/data/cad/native_authored_boxes.json",
                "media_type": "application/json",
                "sha256": fixture["file_sha256"],
                "record_id": fixture["record_id"],
                "license": fixture["license"],
            },
            "source_provenance": fixture["provenance"],
            "independent_reference": fixture["independent_reference"],
        }
    if scenario == "native-hybrid-lifecycle":
        profile = controls.get("hybrid_profile")
        roles = {
            "curved-periodic-layer-core": "positive",
            "original-curved-periodic-refusal": "negative-refusal",
        }
        if isinstance(profile, str) and profile in roles:
            registration = load_curved_periodic_source_registration()
            sources = registration["sources"]
            if not isinstance(sources, list):
                raise TypeError(
                    "Curved periodic source registration must contain records."
                )
            matches = [
                source
                for source in sources
                if isinstance(source, dict) and source.get("role") == roles[profile]
            ]
            if len(matches) != 1:
                raise ValueError(
                    "Curved periodic profile has no unique source registration."
                )
            source = matches[0]
            return {
                "kind": "reviewed-curved-periodic-layer-source",
                "source_id": source["source_id"],
                "source_digest": source["source_digest"],
                "source_revision": source["source_revision"],
                "source_artifact": source["source_artifact"],
                "source_provenance": {
                    "author": "PHYDRA, Inc.",
                    "license": "LicenseRef-PHYDRA-Proprietary",
                    "origin": source["upper_construction"],
                    "redistribution": "repository-internal",
                },
                "independent_reference": {
                    "kind": "exact-periodic-source-expression-trace",
                    "periodic_trace": source["periodic_trace"],
                    "orbit_ids": source["orbit_ids"],
                },
                "registration_id": registration["registration_id"],
            }
    descriptor = {
        "kind": "owning-scenario-source-descriptor",
        "scenario": scenario,
        "controls": [[name, controls[name]] for name in sorted(controls)],
        "driver": f"tools/meshing_qualification.py::{scenario}",
    }
    digest = canonical_fingerprint(descriptor)
    return {
        **descriptor,
        "source_digest": digest,
        "source_revision": digest,
        "source_artifact": {
            "locator": f"tools/meshing_qualification.py::{scenario}",
            "media_type": "text/x-python",
            "descriptor_sha256": digest,
            "license": "LicenseRef-PHYDRA-Proprietary",
        },
        "source_provenance": {
            "author": "PHYDRA, Inc.",
            "license": "LicenseRef-PHYDRA-Proprietary",
            "origin": "Owning deterministic qualification source factory",
            "redistribution": "repository-internal",
        },
        "independent_reference": {
            "kind": "scenario-owned-independent-acceptance",
            "owner": f"tools/meshing_qualification.py::{scenario}",
        },
    }


def _corpus_profiles() -> dict[str, dict[str, Any]]:
    """Enumerate real owning routes; selection never removes mandatory obligations."""
    load_corpus_registration()
    profiles: dict[str, dict[str, Any]] = {
        case.name: {
            "case_name": case.name,
            "workflow": case.workflow,
            "scenario": None,
            "controls": {},
            "full_workflow": False,
            "expected_outcome": "passed"
            if case.expected_admission == "positive"
            else "expected-refusal",
            "source_reference": corpus_identity(case),
        }
        for case in CORPUS
    }
    profiles["sphere-feature-surface"] = {
        "case_name": "sphere-feature-surface",
        "workflow": "planar-features",
        "scenario": None,
        "controls": {},
        "expected_outcome": "passed",
        "full_workflow": False,
        "source_reference": corpus_identity(meshing_case("sphere-feature-surface")),
    }
    for name in POLYHEDRAL_CASE_NAMES:
        profiles[name] = {
            "case_name": name,
            "workflow": "polyhedral-system",
            "scenario": None,
            "controls": {},
            "expected_outcome": "passed",
            "full_workflow": True,
            "source_reference": polyhedral_identity(name),
        }
    workflows: dict[str, str] = {
        "implicit-domain": "native-implicit-lifecycle",
        "labeled-image": "native-image-lifecycle",
        "imperfect-surface": "native-envelope-lifecycle",
        "native-cad": "native-cad-lifecycle",
        "periodic-system": "native-periodic-lifecycle",
        "hybrid-layers": "native-hybrid-lifecycle",
        "general-quads-hexes": "native-family-lifecycle",
        "distributed-lifecycle": "native-distributed-lifecycle",
        "moving-overset": "native-overset-lifecycle",
        "design-learned-loop": "native-design-lifecycle",
        "planar-features": "native-surface-pde",
    }
    surface_contract = _surface_qualification_requirements()
    hybrid_contract = _hybrid_qualification_requirements()
    choices: dict[str, tuple[str, tuple[str, ...]]] = {
        "native-cad-lifecycle": (
            "cad_format",
            _corpus_contract_choices(_cad_qualification_requirements(), "cad_format"),
        ),
        "native-periodic-lifecycle": (
            "periodic_case",
            _corpus_contract_choices(
                _periodic_qualification_requirements(), "periodic_case"
            ),
        ),
        "native-family-lifecycle": (
            "family_case",
            _corpus_contract_choices(_family_qualification_requirements(), None),
        ),
        "native-surface-pde": (
            "surface_case",
            _corpus_contract_choices(surface_contract, "surface_case"),
        ),
        "native-hybrid-lifecycle": (
            "hybrid_profile",
            _corpus_contract_choices(hybrid_contract, "hybrid_profile"),
        ),
    }
    for workflow, scenario in workflows.items():
        variants = choices.get(scenario)
        selections: tuple[dict[str, str | int | float | tuple[float, ...]], ...] = (
            ({},)
            if variants is None
            else tuple({variants[0]: value} for value in variants[1])
        )
        for controls in selections:
            name = (
                scenario
                if not controls
                else f"{scenario}:{next(iter(controls.values()))}"
            )
            if scenario == "native-surface-pde" and controls["surface_case"] == "sphere":
                name = "sphere-feature-surface"
            contract: dict[str, object] = {}
            if scenario == "native-hybrid-lifecycle":
                profile_name = controls.get("hybrid_profile")
                if not isinstance(profile_name, str):
                    raise TypeError("Hybrid corpus profile name must be a string.")
                contract = _record_mapping(
                    _record_mapping(
                        hybrid_contract["profile_contracts"], "Hybrid profile contracts"
                    )[profile_name],
                    "Hybrid profile",
                )
                if profile_name == "curved-periodic-layer-core":
                    controls = {
                        **controls,
                        "layer_count": 2,
                        "first_thickness": 0.01,
                        "layer_growth": 1.0,
                        "geometry_order": 2,
                    }
            source_reference = (
                profiles[name]["source_reference"]
                if name in profiles
                else _scenario_source_reference(scenario, controls)
            )
            profiles[name] = {
                "case_name": scenario,
                "workflow": workflow,
                "scenario": scenario,
                "controls": controls,
                "expected_outcome": "passed",
                "source_reference": source_reference,
                **contract,
            }
    return profiles


def _corpus_profile_assessment(
    profile: dict[str, Any],
    sample: dict[str, Any] | None,
) -> dict[str, Any]:
    """Keep execution, scientific, workflow and release facts distinct."""
    if sample is None:
        return {
            "execution": "not-run",
            "scientific_certification": "unassessed",
            "mandatory_positive_completion": "incomplete",
            "positive_completion": False,
            "refusal_certified": False,
            "qualification_eligible": False,
            "release": "unassessed",
            "leadership": "unassessed",
            "blocking_status": "not-run",
        }
    matched = sample.get("status") == profile["expected_outcome"]
    refusal = profile["expected_outcome"] == "expected-refusal"
    refusal_evidence = (
        matched
        and refusal
        and (
            isinstance(sample.get("failure_evidence_id"), str)
            and bool(sample["failure_evidence_id"])
            and isinstance(sample.get("requested"), dict)
            and isinstance(sample.get("achieved"), dict)
            and sample.get("source_bits_preserved") is True
        )
    )
    epochs = sample.get("epochs", [])
    phase_missing = []
    for index, epoch in enumerate(epochs):
        compiler = epoch.get("compiler", {})
        for field in (
            "temporary_bytes",
            "output_bytes",
            "generated_code_bytes",
            "warm_samples_seconds",
        ):
            if (
                compiler.get(field) is None
                or field == "warm_samples_seconds"
                and not compiler[field]
            ):
                phase_missing.append(f"epoch-{index}:{field}")
        if epoch.get("retained_bytes") is None:
            phase_missing.append(f"epoch-{index}:logical_retained_bytes")
    full_workflow = profile.get("full_workflow", True) is True
    if not epochs and full_workflow and not refusal:
        phase_missing.append("accepted-epoch-phase-measurements")
    publications = []
    if isinstance(sample.get("generation"), dict):
        publications.append(sample["generation"])
    publications.extend(
        epoch["result"] for epoch in epochs if isinstance(epoch.get("result"), dict)
    )
    checkpoint = sample.get("checkpoint")
    if isinstance(checkpoint, dict) and isinstance(
        checkpoint.get("continued_result"), dict
    ):
        publications.append(checkpoint["continued_result"])
    resource_missing = []
    required_limits = {
        "vertices",
        "edges",
        "faces",
        "cells",
        "connectivity_entries",
        "data_bytes",
        "scratch_bytes",
        "work_units",
        "wall_seconds",
        "cavity_cells",
        "geometry_queries",
    }
    for index, publication in enumerate(publications):
        guarantees = publication.get("resource_guarantees", {})
        resource_missing.extend(
            f"publication-{index}:missing-{name}"
            for name in sorted(required_limits - set(guarantees.get("enforced", ())))
        )
        resource_missing.extend(
            f"publication-{index}:unenforced-{name}"
            for name in guarantees.get("unenforced", ())
        )
        receipt = publication.get("execution_evidence")
        if not isinstance(receipt, dict) or not receipt.get("phases"):
            resource_missing.append(f"publication-{index}:actual-ended-native-receipt")
        elif any(phase.get("status_name") != "OK" for phase in receipt["phases"]):
            resource_missing.append(f"publication-{index}:native-phase-status")
    if not publications and full_workflow and not refusal:
        resource_missing.append("accepted-publication-runtime-and-receipt")
    acceptance = sample.get("independent_acceptance")
    scientific = sample.get("independent_scientific_certification") == "passed" or (
        isinstance(acceptance, dict) and acceptance.get("passed") is True
    )
    completion = sample.get("mandatory_workflow_completion", "incomplete")
    case_completion = sample.get("case_contract_completion", completion)
    positive_case = (
        not refusal
        and matched
        and scientific
        and case_completion == "complete"
        and not phase_missing
        and not resource_missing
    )
    eligible = refusal_evidence or positive_case
    mandatory_positive = positive_case and full_workflow and completion == "complete"
    return {
        "deliberate_refusal_certification": (
            "passed" if refusal_evidence else "not-established"
        ),
        "refusal_certified": refusal_evidence,
        "phase_measurement_gaps": phase_missing,
        "resource_evidence_gaps": resource_missing,
        "positive_case_completion": case_completion,
        "case_certified": positive_case,
        "positive_completion": mandatory_positive,
        "execution": sample.get("status", "unmeasured"),
        "expected_outcome_matched": matched,
        "scientific_certification": "passed" if scientific else "unassessed",
        "mandatory_positive_completion": completion,
        "qualification_eligible": eligible,
        "release": sample.get("release_evidence", "unassessed"),
        "leadership": sample.get("leadership_evidence", "unassessed"),
        "blocking_status": None if eligible else sample.get("status", "unmeasured"),
    }


def _mandatory_result(
    name: str,
    profile: dict[str, Any],
    assessment: dict[str, Any],
) -> dict[str, object]:
    """Canonical result schema; certified refusals can never complete positives."""
    expected = (
        "refusal" if profile["expected_outcome"] == "expected-refusal" else "positive"
    )
    positive = assessment["positive_completion"] is True and expected == "positive"
    case_certified = assessment.get("case_certified") is True and expected == "positive"
    refusal = assessment["refusal_certified"] is True and expected == "refusal"
    status = (
        "positive-complete"
        if positive
        else "case-certified"
        if case_certified
        else "refusal-certified"
        if refusal
        else "not-run"
        if assessment["execution"] == "not-run"
        else "blocked"
    )
    body: dict[str, object] = {
        "kind": "mandatory-meshing-workflow-result",
        "profile": name,
        "workflow": profile["workflow"],
        "scenario": profile["scenario"],
        "expected_admission": expected,
        "observed_status": assessment["execution"],
        "status": status,
        "positive_completion": positive,
        "case_certified": case_certified,
        "refusal_certified": refusal,
        "scientific_certification": assessment["scientific_certification"],
        "phase_measurement_gaps": assessment.get("phase_measurement_gaps", []),
        "resource_evidence_gaps": assessment.get("resource_evidence_gaps", []),
        "blocking_status": assessment["blocking_status"],
        "release": assessment["release"],
        "leadership": assessment["leadership"],
        "source_reference_id": canonical_fingerprint(profile["source_reference"]),
    }
    if positive and refusal:
        raise RuntimeError("A mandatory result cannot be both positive and a refusal.")
    if expected == "refusal" and positive:
        raise RuntimeError(
            "A refusal profile cannot complete a mandatory positive workflow."
        )
    return {**body, "result_id": canonical_fingerprint(body)}


def qualify_native_corpus(args: argparse.Namespace) -> dict[str, object]:
    from tools.meshing_benchmarks import _native_campaign_sample, _native_driver_controls

    profiles = _corpus_profiles()
    arguments = vars(args)
    requested_profiles = arguments["corpus_profile"]
    selected = (
        tuple(profiles) if requested_profiles is None else tuple(requested_profiles)
    )
    unknown = set(selected) - profiles.keys()
    if unknown:
        raise ValueError(f"Unknown corpus profiles: {sorted(unknown)}")
    if len(selected) != len(set(selected)):
        raise ValueError(
            "Duplicate corpus profiles must use the declared repeat control instead."
        )
    samples = []
    by_profile = {}
    missing_inputs = {}
    for name in selected:
        profile = profiles[name]
        missing = [
            key for key in profile.get("prerequisites", ()) if arguments.get(key) is None
        ]
        if missing:
            missing_inputs[name] = missing
            continue
        scenario = profile["scenario"]
        controls = {} if scenario is None else _native_driver_controls(scenario, args)
        controls.update(profile["controls"])
        rounds = (
            0
            if name in POLYHEDRAL_CASE_NAMES and name != "polyhedral-periodic-cube"
            else args.adaptation_rounds
        )
        sample = _native_campaign_sample(
            profile["case_name"],
            args.resolution,
            args.capacity,
            args.timeout,
            args.repeats,
            args.target_error,
            rounds,
            "native",
            scenario_override=scenario,
            controls=controls,
        )
        sample = {
            **sample,
            "corpus_profile": name,
            "mandatory_workflow": profile["workflow"],
        }
        samples.append(sample)
        by_profile[name] = sample
    statuses = [sample["status"] for sample in samples]
    assessments = {
        name: _corpus_profile_assessment(profile, by_profile.get(name))
        for name, profile in profiles.items()
    }
    mandatory_results = {
        name: _mandatory_result(name, profiles[name], assessments[name])
        for name in sorted(profiles)
    }
    workflow_results = {}
    for workflow in MANDATORY_WORKFLOWS:
        names = sorted(
            name for name, profile in profiles.items() if profile["workflow"] == workflow
        )
        positive_names = [
            name
            for name in names
            if profiles[name]["expected_outcome"] == "passed"
            and profiles[name].get("full_workflow", True) is True
        ]
        case_names = [
            name
            for name in names
            if profiles[name]["expected_outcome"] == "passed"
            and profiles[name].get("full_workflow", True) is not True
        ]
        completed = [
            name
            for name in positive_names
            if mandatory_results[name]["positive_completion"] is True
        ]
        cases_certified = [
            name
            for name in case_names
            if mandatory_results[name]["case_certified"] is True
        ]
        refusals = [
            name for name in names if mandatory_results[name]["refusal_certified"] is True
        ]
        workflow_results[workflow] = {
            "completion": (
                "complete"
                if positive_names
                and len(completed) == len(positive_names)
                and len(cases_certified) == len(case_names)
                else "incomplete"
            ),
            "positive_profiles": positive_names,
            "positive_profiles_completed": completed,
            "routine_case_profiles": case_names,
            "routine_case_profiles_certified": cases_certified,
            "certified_refusal_profiles": refusals,
            "refusals_count_as_positive_completion": False,
        }
    outcome_names = (
        "passed",
        "expected-refusal",
        "failed",
        "timeout",
        "missing-dependency",
        "ineligible-comparison",
    )
    counts = {status: statuses.count(status) for status in outcome_names}
    counts.update(
        {
            status: statuses.count(status)
            for status in sorted(set(statuses) - set(outcome_names))
        }
    )
    counts["positive_completed"] = sum(
        result["positive_completion"] is True for result in mandatory_results.values()
    )
    counts["case_certified"] = sum(
        result["case_certified"] is True for result in mandatory_results.values()
    )
    counts["refusal_certified"] = sum(
        result["refusal_certified"] is True for result in mandatory_results.values()
    )
    registration = load_corpus_registration()
    record: dict[str, object] = {
        "kind": "native-meshing-corpus-result",
        "scenario": "native-corpus",
        "runtime": _runtime_identity(),
        "corpus_registration_id": registration["registration_id"],
        "samples": samples,
        "counts": counts,
        "mandatory_workflow_results": mandatory_results,
        "mandatory_workflows": workflow_results,
        "mandatory_workflows_incomplete": [
            workflow
            for workflow, result in workflow_results.items()
            if result["completion"] != "complete"
        ],
        "selected_profiles": list(selected),
        "selected_profiles_missing_inputs": missing_inputs,
        "unqualified_selected_profiles": [
            name for name in selected if not assessments[name]["qualification_eligible"]
        ],
        "qualification_dependencies": {
            name: {
                **profile,
                **assessments[name],
                "missing_original_source_inputs": missing_inputs.get(name, []),
                "prerequisites": [
                    "current native source/binary/configuration identity",
                    "all original root resource guarantees",
                    "independent geometry/semantics/physical/state acceptance",
                    "original capacity phase/scaling campaign",
                ],
            }
            for name, profile in profiles.items()
        },
        "reviewed_hybrid_layer_sources": registration["hybrid_layer_sources"],
        "preserved_source_incompatibilities": {
            "original-curved-layer-exact-period-x1": {
                "disposition": "immutable-negative-regression",
                "source_id": "curved-periodic-narrow-gap",
                "source_revision": (
                    "fadef789744332ba906c2bf1b82231d331e7cc7f4128997191b2d97cb9301e4f"
                ),
                "required_period_x": 1,
                "original_top_trace_x_residuals": (
                    "-101121/2361183241434822606848",
                    "-6620711477/77371252455336267181195264",
                ),
                "proof_origin": "tests/data/meshing/curved_periodic_sources.json",
                "reviewed_record": "tests/data/meshing/curved_periodic_sources.json",
                "evidence_scope": (
                    "Original mathematical source incompatibility; the corrected "
                    "positive owns a different source ID, digest, and revision."
                ),
                "rerun_profile": "original-curved-periodic-refusal",
            },
        },
        "research_gates": {
            "general-all-hex": "incomplete",
            "singular-cad-arrangements": "incomplete",
            "underspecified-defective-surface-reconstruction": "incomplete",
        },
        "release": "unassessed",
        "leadership": "unassessed",
    }
    return {**record, "result_id": canonical_fingerprint(record)}


def _polyhedral_acceptance(
    result: phx.meshing.CellMeshingResult,
    case: MeshingCase,
) -> tuple[np.ndarray, dict[str, object]]:
    """Read independently certified domain coverage and exact canonical labels."""
    certification = result.certification
    if (
        certification is None
        or not certification.passed
        or not result.audit.passed
        or not result.compliance.passed
    ):
        raise RuntimeError(
            "Polyhedral publication lacks independent scientific certification."
        )
    if any(block.cell_kind != "polyhedron" for block in result.mesh.blocks):
        raise RuntimeError("Polyhedral request published a different cell family.")
    coverage = certification.coverage
    if coverage is None or coverage.status != "certified":
        raise RuntimeError(
            "Polyhedral publication lacks certified source/material coverage."
        )
    expected = dict(case.expected_regions)
    measured = dict(
        zip(coverage.region_ids, coverage.achieved_region_measures, strict=True)
    )
    if set(measured) != set(expected):
        raise RuntimeError(
            "Independent polyhedral material measures disagree with analytic voxels."
        )
    for name, wanted in expected.items():
        achieved = measured[name]
        if achieved is None or abs(achieved - wanted) > 1e-10 * max(1.0, wanted):
            raise RuntimeError(
                "Independent polyhedral material measures disagree with analytic voxels."
            )
    connectivity = result.mesh.connectivity
    if not isinstance(connectivity, phx.discretization.PolyhedralConnectivity):
        raise TypeError(
            "Polyhedral qualification requires canonical polyhedral connectivity."
        )
    identifiers = np.asarray(connectivity.cell_global_ids)
    regions = np.full(identifiers.size, -1, dtype=np.int64)
    zones = {
        zone.name: zone
        for zone in result.zones
        if zone.role is phx.meshing.MeshZoneRole.REGION
    }
    if set(zones) != set(expected):
        raise RuntimeError(
            "Polyhedral result lost its authoritative material organization."
        )
    for index, (name, _) in enumerate(case.expected_regions):
        zone = zones[name]
        selected = np.isin(identifiers, np.asarray(zone.scope.entity_ids))
        periodic = "periodic-quotient" in case.controls
        material_id = None if periodic else f"{name}-material"
        role = None if periodic else phx.meshing.RegionRole.SOLID
        if (
            zone.material_id != material_id
            or zone.region_role is not role
            or not np.any(selected)
            or np.any(regions[selected] >= 0)
            or np.count_nonzero(selected) != len(zone.scope.entity_ids)
        ):
            raise RuntimeError(
                f"Polyhedral region {name} has invalid material or cell ownership."
            )
        regions[selected] = index
    if np.any(regions < 0):
        raise RuntimeError(
            "Polyhedral material zones do not assign every canonical cell."
        )
    certified_regions = certification.request.cell_regions
    if certified_regions is None or not np.array_equal(
        regions, np.asarray(certified_regions)
    ):
        raise RuntimeError(
            "Polyhedral material organization disagrees with certified cell regions."
        )
    return regions, {
        "passed": True,
        "certification_id": certification.report_id,
        "coverage_id": coverage.certificate_id,
        "coverage_status": coverage.status,
        "expected_region_measures": expected,
        "achieved_region_measures": measured,
        "source_facets": coverage.source_facet_count,
        "covered_source_facets": coverage.covered_source_facet_count,
        "material_organization": "exclusive canonical cell IDs with requested material IDs",
    }


@eqx.filter_jit
def _solve_polyhedral_system(system: Any, rhs: Any, seed: Any) -> tuple[Any, Any, Any]:
    solved = phx.linalg.solve(
        system,
        rhs - system.operator.mv(seed),
        policy=phx.linalg.LinearSolvePolicy(phx.linalg.ConjugateGradient()),
    )
    return seed + solved.value, solved.successful, solved.diagnostics


def _compiled_polyhedral_stages(
    system: Any,
    rhs: Any,
    seed: Any,
    repeats: int,
) -> tuple[Any, dict[str, object], dict[str, float]]:
    """Measure the owning prepared linear system, not a copied VEM/FV algorithm."""
    entry = _solve_polyhedral_system
    if not isinstance(entry, _PolyhedralJitEntry):
        raise TypeError(
            "The filtered polyhedral solver must expose its compiled lowering boundary."
        )
    lowered, lowering = _measured(lambda: entry.lower(system, rhs, seed))
    compiled, compilation = _measured(lowered.compile)
    memory = compiled.compiled.memory_analysis()
    first, execution = _measured(
        lambda: jax.block_until_ready(compiled(system, rhs, seed))
    )
    warm = []
    for _ in range(repeats):
        _, stage = _measured(lambda: jax.block_until_ready(compiled(system, rhs, seed)))
        warm.append(stage["wall_seconds"])
    values, successful, diagnostics = first
    if not bool(np.all(np.asarray(successful))):
        raise RuntimeError("Polyhedral prepared VEM/FV solver did not converge.")
    return (
        values,
        {
            "successful": True,
            "temporary_bytes": None if memory is None else memory.temp_size_in_bytes,
            "iterations": np.asarray(diagnostics.iterations).tolist(),
            "residual_norm": np.asarray(diagnostics.residual_norm).tolist(),
            "relative_residual": np.asarray(diagnostics.relative_residual).tolist(),
            "finite": bool(np.all(np.asarray(diagnostics.finite))),
            "output_bytes": None if memory is None else memory.output_size_in_bytes,
            "argument_bytes": None if memory is None else memory.argument_size_in_bytes,
            "generated_code_bytes": None
            if memory is None
            else memory.generated_code_size_in_bytes,
            "memory_status": "unavailable" if memory is None else "measured",
            "compilation_count": 1,
            "warm_samples_seconds": warm,
            "logical_retained_bytes": _bisection_retained_bytes((system, rhs, seed)),
        },
        {
            "lowering": lowering["wall_seconds"],
            "compile": compilation["wall_seconds"],
            "first_execution": execution["wall_seconds"],
            "warm_execution": float(np.median(warm)),
        },
    )


def _polyhedral_remap(
    source: Any,
    target: Any,
    source_regions: np.ndarray,
    target_regions: np.ndarray,
    policy: Any,
) -> tuple[Any, np.ndarray, dict[str, object]]:
    common = phx.geometry.prepare_common_refinement(
        source.mesh,
        target.mesh,
        policy=policy,
        source_geometry=source.geometry,
        target_geometry=target.geometry,
    )
    if common.status is not phx.geometry.CommonRefinementStatus.SUCCESS:
        raise RuntimeError(
            f"Polyhedral common refinement failed: {common.evidence.reason}"
        )
    values = np.where(source_regions == 0, 2.0, 5.0)
    source_rows, target_rows = (
        np.asarray(common.source_cells),
        np.asarray(common.target_cells),
    )
    volumes = np.asarray(common.volumes)
    if np.any(source_regions[source_rows] != target_regions[target_rows]):
        raise RuntimeError(
            "Polyhedral overlap transfers inventory across material interfaces."
        )
    masses = np.bincount(
        target_rows,
        weights=volumes * values[source_rows],
        minlength=target.mesh.connectivity.cell_count,
    )
    transferred = masses / np.asarray(common.target_measures)
    inventories = {}
    for region, name in enumerate(("left", "right")):
        before = float(
            np.dot(
                values[source_regions == region],
                np.asarray(common.source_measures)[source_regions == region],
            )
        )
        after = float(
            np.dot(
                transferred[target_regions == region],
                np.asarray(common.target_measures)[target_regions == region],
            )
        )
        if abs(before - after) > 1e-10 * max(1.0, abs(before)):
            raise RuntimeError(f"Polyhedral conservative remap loses {name} inventory.")
        inventories[name] = {
            "before": before,
            "after": after,
            "absolute_defect": abs(before - after),
        }
    if not np.all(np.isfinite(transferred)) or np.any(transferred <= 0.0):
        raise RuntimeError(
            "Polyhedral remap did not preserve positive finite material state."
        )
    return (
        common,
        transferred,
        {
            "status": "success",
            "semantics": "common-refinement overlap-volume cell averages",
            "policy_id": policy.policy_id,
            "maximum_candidate_pairs": policy.maximum_candidate_pairs,
            "maximum_accepted_pairs": policy.maximum_accepted_pairs,
            "maximum_memory_bytes": policy.maximum_memory_bytes,
            "overlap_pieces": volumes.size,
            "material_inventories": inventories,
            "maximum_relative_source_defect": common.evidence.maximum_relative_source_defect,
            "maximum_relative_target_defect": common.evidence.maximum_relative_target_defect,
            "consumed_by": "target mimetic diffusion integrated cell source",
        },
    )


def _polyhedral_physics(
    result: Any,
    remapped: np.ndarray,
    repeats: int,
    stages: dict[str, float],
    source: Any,
    common: Any,
    source_regions: np.ndarray,
) -> tuple[dict[str, object], float, tuple[Any, ...]]:
    from examples.native_polyhedral_meshing import (
        prepare_fv,
        prepare_vem,
        rebind_inventory_history,
    )

    mesh, geometry = result.mesh, result.geometry

    prepared, measured = _measured(lambda: prepare_vem(mesh, geometry))
    vem, operator, mass = prepared
    stages["vem_preparation"] = measured["wall_seconds"]
    values, vem_compiler, timings = _compiled_polyhedral_stages(
        phx.linalg.LinearSystem(operator), mass, jnp.zeros_like(mass), repeats
    )
    stages.update({f"vem_{name}": value for name, value in timings.items()})
    vem_error = float(jnp.max(jnp.abs(values - 1.0)))
    prepared, measured = _measured(lambda: prepare_fv(mesh, geometry))
    fv, diffusion, tensor, boundary = prepared
    stages["fv_preparation"] = measured["wall_seconds"]
    rebound, measured = _measured(
        lambda: rebind_inventory_history(
            source, result, common, fv, np.where(source_regions == 0, 2.0, 5.0)
        )
    )
    receipt, remapped = rebound
    stages["canonical_physical_history_rebind"] = measured["wall_seconds"]
    system_rhs, measured = _measured(lambda: diffusion.linear_system(tensor, boundary))
    system, rhs = system_rhs
    stages["fv_system_preparation"] = measured["wall_seconds"]
    initial, fv_compiler, timings = _compiled_polyhedral_stages(
        system, rhs, jnp.zeros_like(rhs), repeats
    )
    stages.update({f"fv_{name}": value for name, value in timings.items()})
    exact = 1.0 + fv.cell_centers @ jnp.asarray((1.0, 2.0, 3.0), dtype=jnp.float64)
    fv_error = float(jnp.max(jnp.abs(initial[: diffusion.cell_count] - exact)))
    integrated_source = jnp.asarray(remapped) * fv.cell_volumes
    system_rhs, measured = _measured(
        lambda: diffusion.linear_system(tensor, boundary, source=integrated_source)
    )
    update_system, update_rhs = system_rhs
    stages["fv_transferred_system_preparation"] = measured["wall_seconds"]
    updated, update_compiler, timings = _compiled_polyhedral_stages(
        update_system, update_rhs, initial, repeats
    )
    stages.update({f"fv_transferred_{name}": value for name, value in timings.items()})
    residual = diffusion.residual(
        updated[: diffusion.cell_count],
        updated[diffusion.cell_count :],
        tensor,
        boundary,
        source=integrated_source,
    )
    residual_error = float(jnp.max(jnp.abs(residual)))
    response = float(
        jnp.max(
            jnp.abs(updated[: diffusion.cell_count] - initial[: diffusion.cell_count])
        )
    )
    normals = np.asarray(fv.area_vectors)
    offsets, faces = (
        np.asarray(mesh.connectivity.cell_face_offsets),
        np.asarray(mesh.connectivity.cell_face_values),
    )
    rank_margin = min(
        float(
            np.linalg.svd(
                normals[faces[a:b]] / float(fv.cell_volumes[cell]), compute_uv=False
            )[-1]
        )
        for cell, (a, b) in enumerate(zip(offsets[:-1], offsets[1:], strict=True))
    )
    if (
        vem.evidence.minimum_rank_margin <= 0.0
        or rank_margin <= 0.0
        or vem.evidence.maximum_reproduction_defect > 1e-7
        or response <= 1e-10
        or not np.isfinite(response)
    ):
        raise RuntimeError(
            "Polyhedral consumer rank or transferred-source physics response failed."
        )
    retained = (
        vem,
        operator,
        mass,
        values,
        fv,
        diffusion,
        tensor,
        boundary,
        system,
        rhs,
        update_system,
        update_rhs,
        initial,
        updated,
        integrated_source,
        receipt,
    )
    return (
        {
            "canonical_state_rebind": {
                "published": receipt.published,
                "receipt_id": receipt.receipt_id,
                "roles": ("physical-state", "history"),
                "target_result_id": result.result_id,
            },
            "vem": {
                "compiler": vem_compiler,
                "constant_solution_error": vem_error,
                "minimum_rank_margin": vem.evidence.minimum_rank_margin,
                "maximum_reproduction_defect": vem.evidence.maximum_reproduction_defect,
            },
            "fv": {
                "compiler": fv_compiler,
                "linear_solution_error": fv_error,
                "domain_measure": float(jnp.sum(fv.cell_volumes)),
                "minimum_normal_rank_margin": rank_margin,
                "maximum_nonorthogonality_degrees": float(
                    fv.quality.maximum_nonorthogonality_degrees
                ),
                "maximum_closure_residual": float(fv.quality.maximum_closure_residual),
                "transferred_update_compiler": update_compiler,
                "transferred_source_residual": residual_error,
                "transferred_source_integral": float(jnp.sum(integrated_source)),
                "transferred_state_physical_response": response,
            },
        },
        max(vem_error, fv_error, residual_error),
        retained,
    )


def _polyhedral_qualification_halfcell_solution(x: Any, amplitude: float) -> np.ndarray:
    """Independent periodic solution of -u''=(-a,+a), before gauge shift."""
    x = np.mod(np.asarray(x, dtype=np.float64), 1.0)
    right = x - 0.5
    return np.where(
        x <= 0.5,
        amplitude * (0.5 * x * x - 0.25 * x),
        amplitude * (-0.5 * right * right + 0.25 * right),
    )


def _polyhedral_qualification_source_quadrature(
    result: Any,
) -> tuple[
    np.ndarray,
    tuple[np.ndarray, ...],
    tuple[np.ndarray, ...],
    tuple[np.ndarray, ...],
]:
    """Degree-four volume quadrature from the actual source coefficient bank.

    The canonical source-face triangulation and oriented cell incidences form
    star tetrahedra. Four-point Gauss/Duffy is exact for degree-four Cartesian
    polynomials. No rounded mesh coordinate is used as source authority.
    """
    from phydrax.geometry._exact_polyhedral_geometry import determinant3, star_tetrahedra

    mesh, geometry = result.mesh, result.geometry
    if geometry is None or mesh.periodic_topology is None:
        raise ValueError("Periodic physics requires actual periodic source geometry.")
    exact = geometry.source_coordinates()
    points = np.asarray(exact, dtype=np.float64)
    connectivity = mesh.connectivity
    exact_points = np.asarray(exact, dtype=object)
    tetrahedra = star_tetrahedra(mesh, exact_points, require_positive=False)
    vertex_offsets = np.asarray(connectivity.cell_vertex_offsets, dtype=np.int64)
    vertices = np.asarray(connectivity.cell_vertex_values, dtype=np.int64)
    nodes, weights = np.polynomial.legendre.leggauss(4)
    nodes, weights = (nodes + 1.0) / 2.0, weights / 2.0
    r, s, t = np.meshgrid(nodes, nodes, nodes, indexing="ij")
    wr, ws, wt = np.meshgrid(weights, weights, weights, indexing="ij")
    r, s, t = r.ravel(), s.ravel(), t.ravel()
    reference_weights = (wr * ws * wt).ravel() * (1 - r) ** 2 * (1 - s)
    barycentric = np.stack(
        (
            1 - r - (1 - r) * s - (1 - r) * (1 - s) * t,
            r,
            (1 - r) * s,
            (1 - r) * (1 - s) * t,
        ),
        axis=1,
    )
    cell_points, cell_weights, cell_vertices = [], [], []
    for cell in range(connectivity.cell_count):
        ids = vertices[vertex_offsets[cell] : vertex_offsets[cell + 1]]
        local_points, local_weights = [], []
        for tetrahedron in tetrahedra[cell]:
            center, *corners_exact = tetrahedron
            columns = tuple(
                tuple(value - base for value, base in zip(corner, center, strict=True))
                for corner in corners_exact
            )
            determinant = float(determinant3(*columns))
            if not np.isfinite(determinant) or determinant <= 0:
                raise RuntimeError(
                    "Source cell is not positively star-visible under exact source-face orientation."
                )
            corners = np.asarray(tetrahedron, dtype=np.float64)
            local_points.append(barycentric @ corners)
            local_weights.append(reference_weights * determinant)
        cell_points.append(np.concatenate(local_points))
        cell_weights.append(np.concatenate(local_weights))
        cell_vertices.append(ids)
    return points, tuple(cell_vertices), tuple(cell_points), tuple(cell_weights)


def _polyhedral_qualification_field_history(
    fields: dict[str, Any], name: str, value: Any
) -> jax.Array:
    """Retain three actual successive states, without modifying physical histories."""
    value = jnp.asarray(value)
    old = fields.get(name + "_history")
    if old is None:
        # Initial history is the admitted starting seed, not the newly solved state.
        seed = jnp.asarray(fields.get(name, jnp.zeros_like(value)), dtype=value.dtype)
        old = jnp.broadcast_to(seed, (3,) + value.shape)
    old = jnp.asarray(old)
    if old.shape != (3,) + value.shape or old.dtype != value.dtype:
        raise ValueError(
            f"{name} history must retain three states with the field dtype/shape."
        )
    return jnp.concatenate((old[1:], value[None]), axis=0)


def _polyhedral_qualification_operator_evidence(
    operator: Any, rhs: Any, solution: Any
) -> dict[str, float]:
    residual = operator.mv(solution) - rhs
    size = solution.size
    left = jnp.sin(jnp.arange(size, dtype=solution.dtype) + 0.3)
    right = jnp.cos(jnp.arange(size, dtype=solution.dtype) + 0.7)
    transpose_defect = abs(
        float(
            jnp.vdot(left, operator.mv(right))
            - jnp.vdot(operator.transpose_mv(left), right)
        )
    )
    return {
        "maximum_algebraic_residual": float(jnp.max(jnp.abs(residual))),
        "raw_transpose_pairing_defect": transpose_defect,
    }


def _polyhedral_qualification_reprepare_fv_seed(
    diffusion: Any,
    tensor: Any,
    boundary: Any,
    fields: dict[str, Any],
    repeats: int,
    stages: dict[str, float],
) -> tuple[jax.Array, jax.Array, dict[str, Any]]:
    """Reprepare current and three historical traces from transported cell states.

    Full restored seeds are handled by the caller without reconstruction.
    On a topology change, each fixed-cell trace RHS comes from the owning
    mimetic stationarity equations, never a nodal/face interpolation.
    """
    cell_seed = jnp.asarray(fields["fv_cell_solution"])
    cell_history = jnp.asarray(fields["fv_cell_solution_history"])
    if (
        cell_seed.shape != (diffusion.cell_count,)
        or cell_history.shape != (3, diffusion.cell_count)
        or cell_history.dtype != cell_seed.dtype
    ):
        raise ValueError(
            "Transferred FV cell seed/history must retain actual cell shape/dtype."
        )
    all_cells = (cell_seed, *tuple(cell_history[index] for index in range(3)))
    full_values, evidence = [], []
    prepared, measured = _measured(
        lambda: diffusion.trace_reconstruction_operators(tensor, boundary)
    )
    stages["periodic_fv_trace_reprepare_preparation"] = measured["wall_seconds"]
    system, cell_rhs_action, rhs_offset = prepared
    for index, cells in enumerate(all_cells):
        rhs, measured = _measured(
            lambda cells=cells: jax.block_until_ready(
                cell_rhs_action.mv(cells) + rhs_offset
            )
        )
        stages[f"periodic_fv_trace_reprepare_{index}_rhs"] = measured["wall_seconds"]
        trace, compiler, timings = _compiled_polyhedral_stages(
            system, rhs, jnp.zeros_like(rhs), repeats
        )
        stages.update(
            {
                f"periodic_fv_trace_reprepare_{index}_{name}": value
                for name, value in timings.items()
            }
        )
        full_values.append(jnp.concatenate((cells.astype(trace.dtype), trace)))
        local = diffusion.local_fluxes(cells, trace, tensor)
        evidence.append(
            {
                "state": "current" if index == 0 else f"history-{index - 1}",
                "compiler": compiler,
                **_polyhedral_qualification_operator_evidence(
                    system.operator, rhs, trace
                ),
                "maximum_face_stationarity_residual": float(
                    jnp.max(
                        jnp.abs(
                            boundary.face_residual(
                                trace, diffusion.continuity_residual(local)
                            )
                        )
                    )
                ),
            }
        )
    return (
        full_values[0],
        jnp.stack(full_values[1:]),
        {
            "authority": "HybridMimeticDiffusion.trace_reconstruction_operators fixed-cell physical stationarity",
            "coefficient_preparation_count": 1,
            "current_and_history": evidence,
            "facet_interpolation_used": False,
        },
    )


def _polyhedral_qualification_periodic_physics(
    result: Any,
    fields: dict[str, Any],
    repeats: int,
    stages: dict[str, float],
    *,
    seeds: dict[str, Any] | None = None,
) -> tuple[dict[str, Any], float, dict[str, Any]]:
    """Actual source -> quotient FV/VEM -> native CG -> all retained values.

    fields: conserved[N,7] (rho,mom3,total-energy,species2),
    conserved_history[3,N,7], pressure[N], temperature[N], plus optional
    fv_solution[N+F], vem_solution[Q] and their three-state histories.
    seeds optionally overrides fv_solution/vem_solution; it never alters force.
    Returns (JSON-safe physics_record, physical_error, updated_fields).
    Geometry/SCI restoration and ALLfield transfer remain the caller's owners.
    """
    from phydrax.discretization.finite_volume import (
        HybridDiffusionBoundary,
        HybridMimeticDiffusion,
        UnstructuredFiniteVolumePlan,
    )
    from phydrax.discretization.vem import prepare_polyhedral_h1_virtual_element_3d

    if repeats < 1:
        raise ValueError("Periodic physics requires positive original repeat count.")
    seeds = {} if seeds is None else seeds
    updated = dict(fields)
    conserved = jnp.asarray(fields["conserved"])
    history = jnp.asarray(fields["conserved_history"])
    count = result.mesh.connectivity.cell_count
    if (
        conserved.shape != (count, 7)
        or history.shape != (3, count, 7)
        or history.dtype != conserved.dtype
    ):
        raise ValueError(
            "ALLfield conserved state/history has wrong canonical shape or dtype."
        )
    if not np.all(np.isfinite(np.asarray(conserved))) or np.any(
        np.asarray(conserved[:, 0]) <= 0
    ):
        raise ValueError("Conserved state requires finite positive physical density.")
    for name in ("pressure", "temperature"):
        value = np.asarray(fields[name])
        if (
            value.shape != (count,)
            or not np.all(np.isfinite(value))
            or np.any(value <= 0)
        ):
            raise ValueError(
                f"{name} must retain finite positive derived physical values."
            )
    fv, measured = _measured(
        lambda: UnstructuredFiniteVolumePlan.from_cell_mesh(
            result.mesh, field_name="state", component_names=("value",)
        ).prepare(cell_geometry=result.geometry)
    )
    stages["periodic_fv_preparation"] = measured["wall_seconds"]
    diffusion, boundary = HybridMimeticDiffusion(fv), HybridDiffusionBoundary(fv)
    tensor = jnp.eye(3, dtype=fv.cell_volumes.dtype)
    volumes = np.asarray(fv.cell_volumes)
    density = np.asarray(conserved[:, 0])
    mean = float(np.dot(density, volumes) / np.sum(volumes))
    force = jnp.asarray(density - mean, dtype=fv.cell_volumes.dtype)
    integrated_source = force * fv.cell_volumes
    source_data, measured = _measured(
        lambda: _polyhedral_qualification_source_quadrature(result)
    )
    stages["periodic_independent_source_quadrature"] = measured["wall_seconds"]
    source_vertices, cell_vertices, quadrature_points, quadrature_weights = source_data
    source_volumes = np.asarray([np.sum(w) for w in quadrature_weights])
    volume_defect = float(np.max(np.abs(source_volumes - volumes)))
    if volume_defect > 1e-10:
        raise RuntimeError(
            "Prepared FV volume disagrees with independent source-volume quadrature."
        )
    sides = []
    for ids in cell_vertices:
        xs = source_vertices[ids, 0]
        if np.max(xs) <= 0.5:
            sides.append(False)
        elif np.min(xs) >= 0.5:
            sides.append(True)
        else:
            raise RuntimeError(
                "Independent halfcell force requires actual source cells split at x=0.5."
            )
    sides = np.asarray(sides, dtype=bool)
    if not np.any(sides) or np.all(sides):
        raise RuntimeError("Actual source must retain both physical density halfcells.")
    amplitude = float(
        (
            np.average(density[sides], weights=volumes[sides])
            - np.average(density[~sides], weights=volumes[~sides])
        )
        / 2
    )
    force_defect = float(
        np.max(np.abs(np.asarray(force) - np.where(sides, amplitude, -amplitude)))
    )
    if amplitude == 0 or not np.isfinite(amplitude) or force_defect > 1e-10:
        raise RuntimeError(
            "Transported density is not the compatible nonconstant physical halfcell state."
        )
    analytic_averages = np.asarray(
        [
            np.dot(w, _polyhedral_qualification_halfcell_solution(p[:, 0], amplitude))
            / np.sum(w)
            for p, w in zip(quadrature_points, quadrature_weights, strict=True)
        ]
    )
    fv_gauge = float(analytic_averages[0])
    system_rhs, measured = _measured(
        lambda: diffusion.pinned_linear_system(
            tensor, boundary, source=integrated_source, pin_cell=0, pin_value=0.0
        )
    )
    stages["periodic_fv_system_preparation"] = measured["wall_seconds"]
    system, rhs = system_rhs
    seed_fields = {**fields, **seeds}
    trace_repreparation = None
    if "fv_solution" not in seed_fields and "fv_cell_solution" in seed_fields:
        full, histories, trace_repreparation = (
            _polyhedral_qualification_reprepare_fv_seed(
                diffusion, tensor, boundary, seed_fields, repeats, stages
            )
        )
        seed_fields["fv_solution"], seed_fields["fv_solution_history"] = full, histories
        seed_fields["fv_trace_solution_history"] = histories[:, count:]
    fv_seed = jnp.asarray(
        seed_fields.get("fv_solution", jnp.zeros_like(rhs)), dtype=rhs.dtype
    )
    if fv_seed.shape != rhs.shape:
        raise ValueError(
            "Restored FV seed must match the reprepared quotient cell/trace system."
        )
    fv_solution, fv_compiler, timings = _compiled_polyhedral_stages(
        system, rhs, fv_seed, repeats
    )
    stages.update({"periodic_fv_" + key: value for key, value in timings.items()})
    cells, traces = fv_solution[:count], fv_solution[count:]
    physical_residual = diffusion.residual(
        cells, traces, tensor, boundary, source=integrated_source
    )
    local_fluxes = diffusion.local_fluxes(cells, traces, tensor)
    owner_rates = diffusion.owner_rates(local_fluxes)
    continuity = diffusion.continuity_residual(local_fluxes)
    balance = diffusion.cell_divergence(owner_rates) - integrated_source
    fv_squared_error = sum(
        float(
            np.dot(
                w,
                (
                    float(cells[cell])
                    - (
                        _polyhedral_qualification_halfcell_solution(p[:, 0], amplitude)
                        - fv_gauge
                    )
                )
                ** 2,
            )
        )
        for cell, (p, w) in enumerate(
            zip(quadrature_points, quadrature_weights, strict=True)
        )
    )
    fv_error = float(np.sqrt(fv_squared_error / np.sum(source_volumes)))
    fv_average_error = float(
        np.max(np.abs(np.asarray(cells) - (analytic_averages - fv_gauge)))
    )
    vem, measured = _measured(
        lambda: prepare_polyhedral_h1_virtual_element_3d(
            result.mesh, cell_geometry=result.geometry
        )
    )
    stages["periodic_vem_preparation"] = measured["wall_seconds"]
    load = vem.assemble_cellwise_constant_load(force)
    # Preserve the original strict compatibility requirement; no force correction.
    compatibility_tolerance = 0.0
    pinned_load = vem.compatible_pinned_load(
        load, 0, compatibility_tolerance=compatibility_tolerance
    )
    operator = vem.pinned_diffusion_operator(0)
    vem_seed = jnp.asarray(
        seeds.get(
            "vem_solution",
            fields.get(
                "vem_solution", jnp.zeros((vem.dof_count,), dtype=pinned_load.dtype)
            ),
        ),
        dtype=pinned_load.dtype,
    )
    if vem_seed.shape != (vem.dof_count,):
        raise ValueError("Restored VEM seed must match actual quotient nodal DOFs.")
    free = jnp.arange(1, vem.dof_count, dtype=jnp.int32)
    solved_free, vem_compiler, timings = _compiled_polyhedral_stages(
        phx.linalg.LinearSystem(operator), pinned_load, vem_seed[free], repeats
    )
    stages.update({"periodic_vem_" + key: value for key, value in timings.items()})
    vem_solution = jnp.zeros_like(vem_seed).at[free].set(solved_free)
    representatives = np.asarray(
        result.mesh.periodic_topology.orbit_representatives(0), dtype=np.int64
    )
    exact_nodal = _polyhedral_qualification_halfcell_solution(
        source_vertices[representatives, 0], amplitude
    )
    vem_gauge = float(exact_nodal[0])
    exact_nodal -= vem_gauge
    nodal_weights = np.zeros((vem.dof_count,), dtype=np.float64)
    route = np.asarray(result.mesh.periodic_topology.orbits(0)[0], dtype=np.int64)
    for ids, volume in zip(cell_vertices, source_volumes, strict=True):
        np.add.at(nodal_weights, route[ids], volume / len(ids))
    vem_error = float(
        np.sqrt(
            np.dot(nodal_weights, (np.asarray(vem_solution) - exact_nodal) ** 2)
            / np.sum(source_volumes)
        )
    )
    vem_physical_residual = vem.mv(vem_solution) - load
    fv_response = float(np.ptp(np.asarray(cells)))
    vem_response = float(np.ptp(np.asarray(vem_solution)))
    vem_load_nonzero = bool(np.any(np.asarray(pinned_load) != 0))
    if (
        fv_response <= 1e-10
        or (vem_load_nonzero and vem_response <= 1e-10)
        or not np.all(np.isfinite(np.asarray(fv_solution)))
        or not np.all(np.isfinite(np.asarray(vem_solution)))
    ):
        raise RuntimeError(
            "Actual quotient physical solve did not retain its required finite physical response."
        )
    for name, value in (("fv_solution", fv_solution), ("vem_solution", vem_solution)):
        updated[name + "_history"] = _polyhedral_qualification_field_history(
            seed_fields, name, value
        )
        updated[name] = value
    updated.update(
        physical_force=force,
        physical_source_load=integrated_source,
        fv_cell_solution=cells,
        fv_trace_solution=traces,
        fv_owner_flux=owner_rates,
        fv_local_flux=local_fluxes,
        fv_physical_residual=physical_residual,
        fv_flux_balance=balance,
        vem_physical_load=load,
        vem_physical_residual=vem_physical_residual,
        fv_analytic_cell_average=jnp.asarray(analytic_averages - fv_gauge),
        vem_analytic_nodal=jnp.asarray(exact_nodal),
    )
    for name in (
        "physical_force",
        "physical_source_load",
        "fv_cell_solution",
        "fv_trace_solution",
        "fv_owner_flux",
        "fv_local_flux",
        "fv_physical_residual",
        "fv_flux_balance",
        "vem_physical_load",
        "vem_physical_residual",
    ):
        updated[name + "_history"] = _polyhedral_qualification_field_history(
            seed_fields, name, updated[name]
        )
    fv_evidence = _polyhedral_qualification_operator_evidence(
        system.operator, rhs, fv_solution
    )
    vem_evidence = _polyhedral_qualification_operator_evidence(
        operator, pinned_load, solved_free
    )
    physical_defects = [
        float(np.max(np.abs(np.asarray(value))))
        for value in (physical_residual, continuity, balance, vem_physical_residual)
    ]
    physical_error = max(
        fv_error,
        vem_error,
        *physical_defects,
        fv_evidence["raw_transpose_pairing_defect"],
        vem_evidence["raw_transpose_pairing_defect"],
    )
    inventories = np.asarray(conserved).T @ source_volumes
    history_inventories = np.einsum("tnk,n->tk", np.asarray(history), source_volumes)
    record = {
        "source_result_id": result.result_id,
        "source_authority": "actual CellGeometrySpec.source_coordinates and canonical source-face triangulation",
        "numerical_authority": "prepared quotient HybridMimeticDiffusion / polyhedral H1 VEM native CG",
        "physical_force": {
            "law": "transported density minus volume-weighted mean",
            "density_mean": mean,
            "halfcell_amplitude": amplitude,
            "maximum_halfcell_force_defect": force_defect,
            "integrated_source": float(jnp.sum(integrated_source)),
            "independent_source_integral": float(
                np.dot(np.asarray(force), source_volumes)
            ),
        },
        "independent_analytic_solution": {
            "law": "periodic halfcell piecewise quadratic -u''=(-a,+a)",
            "fv_gauge": fv_gauge,
            "vem_gauge": vem_gauge,
            "quadrature": "source-star tetrahedra, tensor Gauss4 Duffy; degree-four exact",
            "domain_measure": float(np.sum(source_volumes)),
            "maximum_volume_defect": volume_defect,
        },
        "inventories": {
            "conserved_columns": [
                "density",
                "momentum_x",
                "momentum_y",
                "momentum_z",
                "total_energy",
                "species_0",
                "species_1",
            ],
            "conserved": inventories.tolist(),
            "conserved_history": history_inventories.tolist(),
            "pressure_volume_integral": float(
                np.dot(np.asarray(fields["pressure"]), source_volumes)
            ),
            "temperature_volume_integral": float(
                np.dot(np.asarray(fields["temperature"]), source_volumes)
            ),
        },
        "fv": {
            "compiler": fv_compiler,
            **fv_evidence,
            "physical_response": fv_response,
            "source_volume_l2_error": fv_error,
            "maximum_cell_average_error": fv_average_error,
            "maximum_original_physical_residual": physical_defects[0],
            "maximum_reciprocal_flux_continuity_defect": physical_defects[1],
            "maximum_cell_flux_balance_defect": physical_defects[2],
            "total_outward_integrated_flux": float(
                jnp.sum(diffusion.cell_divergence(owner_rates))
            ),
            "restored_seed_consumed": "fv_solution" in seeds or "fv_solution" in fields,
            "transferred_cell_seed_consumed": trace_repreparation is not None,
            "trace_repreparation": trace_repreparation,
            "pin_cell": 0,
            "pin_value": 0.0,
        },
        "vem": {
            "compiler": vem_compiler,
            **vem_evidence,
            "physical_response": vem_response,
            "projected_physical_load_nonzero": vem_load_nonzero,
            "response_requirement": "nonzero for nonzero actual weak load; coarse zero projection is retained honestly",
            "source_volume_vertex_lumped_l2_error": vem_error,
            "error_semantics": "actual quotient nodal values, source-volume vertex lumping; not reconstructed interior VEM error",
            "maximum_original_physical_residual": physical_defects[3],
            "compatibility_tolerance": compatibility_tolerance,
            "total_physical_load": float(jnp.sum(load)),
            "minimum_rank_margin": vem.evidence.minimum_rank_margin,
            "maximum_reproduction_defect": vem.evidence.maximum_reproduction_defect,
            "restored_seed_consumed": "vem_solution" in seeds or "vem_solution" in fields,
            "pin_dof": 0,
            "pin_value": 0.0,
        },
        "retained_field_names": sorted(updated),
        "prepared_solver_archived": False,
    }
    return record, physical_error, updated


def _polyhedral_qualification_periodic_archive_evidence(
    root: Any,
) -> dict[str, Any]:
    """Byte-exact public owner and allfield evidence, independent of archive IDs."""
    import hashlib

    from phydrax._fingerprint import array_tree_fingerprint

    source, request, options, epochs = root
    records = []
    for result, pairs in epochs:
        certification = result.certification
        if (
            certification is None
            or not certification.passed
            or not result.audit.passed
            or not result.compliance.passed
        ):
            raise RuntimeError(
                "Cold periodic epoch lacks accepted canonical certification."
            )
        fields = {}
        from phydrax.discretization.finite_volume import UnstructuredFiniteVolumePlan

        prepared = UnstructuredFiniteVolumePlan.from_cell_mesh(
            result.mesh, field_name="state", component_names=("value",)
        ).prepare(cell_geometry=result.geometry)
        volumes = np.asarray(prepared.cell_volumes)
        accepted_fields = dict(pairs)
        inventories = {
            "conserved": np.einsum(
                "nk,n->k", np.asarray(accepted_fields["conserved"]), volumes
            ).tolist(),
            "conserved_history": np.einsum(
                "tnk,n->tk", np.asarray(accepted_fields["conserved_history"]), volumes
            ).tolist(),
            "pressure": float(np.dot(np.asarray(accepted_fields["pressure"]), volumes)),
            "temperature": float(
                np.dot(np.asarray(accepted_fields["temperature"]), volumes)
            ),
        }
        for name, value in pairs:
            array = np.asarray(value)
            fields[name] = {
                "shape": list(array.shape),
                "dtype": array.dtype.str,
                "bytes": array.nbytes,
                "sha256": hashlib.sha256(array.tobytes(order="C")).hexdigest(),
            }
        records.append(
            {
                "result": _result_identity(result),
                "result_fingerprint": array_tree_fingerprint(result),
                "geometry_fingerprint": array_tree_fingerprint(result.geometry),
                "domain_fingerprint": array_tree_fingerprint(
                    certification.request.domain
                ),
                "certification_id": certification.report_id,
                "certification_fingerprint": array_tree_fingerprint(certification),
                "inventories": inventories,
                "fields": fields,
            }
        )
    return {
        "source_fingerprint": array_tree_fingerprint(source),
        "request_fingerprint": array_tree_fingerprint(request),
        "options_fingerprint": array_tree_fingerprint(options),
        "request_id": request.specification_id,
        "epochs": records,
    }


def _polyhedral_qualification_periodic_cold_process(
    path: str,
    content_id: str,
    expected_path: str,
    repeats: int,
    target_error: float,
) -> dict[str, Any]:
    import json
    import os

    from phydrax._array_archive import DEFAULT_ARRAY_ARCHIVE_LIMITS
    from phydrax.lifecycle._meshing_sources import read_meshing_source_closure

    root = read_meshing_source_closure(
        path, expected_content_id=content_id, limits=DEFAULT_ARRAY_ARCHIVE_LIMITS
    )
    with open(expected_path, encoding="utf-8") as stream:
        expected = json.load(stream)
    evidence = _polyhedral_qualification_periodic_archive_evidence(root)
    if evidence != expected:
        raise RuntimeError(
            "Fresh periodic restore changed source bytes, SCI, controls, certification or allfields."
        )
    continued = []
    for result, pairs in root[3]:
        fields = dict(pairs)
        timings = {}
        physics, error, updated = _polyhedral_qualification_periodic_physics(
            result, fields, repeats, timings, seeds=fields
        )
        if not np.isfinite(error) or error > target_error:
            raise RuntimeError(
                "Restored periodic PDE continuation missed the original physical target."
            )
        continued.append(
            {
                "result_id": result.result_id,
                "physics": physics,
                "physical_error": error,
                "stages_seconds": timings,
                "continued_fields": _polyhedral_qualification_periodic_archive_evidence(
                    (
                        root[0],
                        root[1],
                        root[2],
                        ((result, tuple(sorted(updated.items()))),),
                    )
                )["epochs"][0]["fields"],
            }
        )
    peak = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
    return {
        "status": "passed",
        "restored": evidence,
        "continued_epochs": continued,
        "process_id": os.getpid(),
        "interpreter": sys.executable,
        "runtime": _runtime_identity(),
        "peak_process_resident_bytes": peak * (1 if sys.platform == "darwin" else 1024),
    }


def _polyhedral_qualification_periodic_cold(
    source: Any,
    request: Any,
    options: Any,
    epochs: Any,
    repeats: int,
    target_error: float,
    stages: dict[str, Any],
) -> dict[str, Any]:
    import json
    import os
    import subprocess

    from phydrax._array_archive import DEFAULT_ARRAY_ARCHIVE_LIMITS
    from phydrax.lifecycle._meshing_sources import write_meshing_source_closure

    if "_campaign_started" not in stages:
        raise ValueError(
            "Cold periodic campaign requires the original perf_counter start in stages['_campaign_started']."
        )
    root = (
        source,
        request,
        options,
        tuple((result, tuple(sorted(fields.items()))) for result, fields in epochs),
    )
    expected = _polyhedral_qualification_periodic_archive_evidence(root)
    limits = DEFAULT_ARRAY_ARCHIVE_LIMITS
    record = {
        "status": "failed",
        "archive_limits": {
            "members": limits.max_members,
            "nesting": limits.max_manifest_nesting,
            "rank": limits.max_array_rank,
        },
        "accepted_epochs": len(epochs),
        "source_authority_stripped": False,
    }
    with TemporaryDirectory(prefix="phydrax-poly-periodic-cold-") as directory:
        receipt, timing = _measured(
            lambda: write_meshing_source_closure(
                Path(directory) / "periodic.zip", root, limits=limits
            )
        )
        stages["periodic_checkpoint_publication"] = timing["wall_seconds"]
        expected_path = Path(directory) / "expected.json"
        expected_path.write_text(json.dumps(expected), encoding="utf-8")
        remaining = request.limits.maximum_wall_seconds - (
            perf_counter() - stages["_campaign_started"]
        )
        record.update(
            {
                "content_id": receipt.content_id,
                "container_bytes": receipt.path.stat().st_size,
                "remaining_original_seconds": remaining,
            }
        )
        if remaining <= 0:
            return {
                **record,
                "status": "timeout",
                "failure": "Original campaign deadline expired before cold restore.",
            }
        script = (
            "import json,sys; from tools.meshing_qualification import "
            "_polyhedral_qualification_periodic_cold_process as cold; "
            "print(json.dumps(cold(sys.argv[1],sys.argv[2],sys.argv[3],int(sys.argv[4]),float(sys.argv[5]))))"
        )
        try:
            process, timing = _measured(
                lambda: subprocess.run(
                    (
                        sys.executable,
                        "-c",
                        script,
                        str(receipt.path),
                        receipt.content_id,
                        str(expected_path),
                        str(repeats),
                        str(target_error),
                    ),
                    capture_output=True,
                    text=True,
                    timeout=remaining,
                    check=False,
                )
            )
        except subprocess.TimeoutExpired as failure:
            return {
                **record,
                "status": "timeout",
                "failure_type": type(failure).__name__,
                "stdout": failure.stdout.decode(errors="replace")
                if isinstance(failure.stdout, bytes)
                else failure.stdout,
                "stderr": failure.stderr.decode(errors="replace")
                if isinstance(failure.stderr, bytes)
                else failure.stderr,
            }
        stages["periodic_cold_restore_continued_pde"] = timing["wall_seconds"]
        record.update(
            {
                "returncode": process.returncode,
                "stdout": process.stdout,
                "stderr": process.stderr,
            }
        )
        if process.returncode != 0:
            return record
        restored = json.loads(process.stdout)
        if restored["restored"] != expected or restored["process_id"] == os.getpid():
            raise RuntimeError(
                "Periodic cold evidence does not bind the original source and a fresh process."
            )
        record.update(
            {
                "status": restored["status"],
                "fresh_interpreter": restored,
                "accepted_fields_bitwise_preserved": True,
            }
        )
        return record


def _polyhedral_qualification_periodic_resource_refusals(
    source: Any,
    request: Any,
    options: Any,
    result: Any,
    *,
    campaign_started: float | None = None,
) -> dict[str, Any]:
    """Actual original receipt admission and one-control observed-boundary refusals."""
    import inspect
    from time import monotonic

    from phydrax._fingerprint import array_tree_fingerprint
    from phydrax._meshcore import MeshcoreStatus
    from phydrax.meshing._volume_generation import (
        current_native_execution_budget,
        native_volume_execution_budget,
    )

    if current_native_execution_budget() is not None:
        raise RuntimeError("Resource campaign must run after original native scope ends.")
    receipt = result.execution_evidence
    if receipt is None:
        raise RuntimeError("Original publication has no actual positive native receipt.")
    receipt.require_valid()
    pending, seen, phases = [receipt], set(), []
    while pending:
        phase = pending.pop()
        if id(phase) in seen:
            continue
        seen.add(id(phase))
        if int(np.asarray(phase.status)) != int(MeshcoreStatus.OK):
            raise RuntimeError(
                "Positive admission contains a non-successful native phase receipt."
            )
        phases.append(phase)
        pending.extend(
            item
            for item in (phase.preparation_evidence, phase.consumer_evidence)
            if item is not None
        )
    from phydrax._model._structure import model_array_bytes

    mesh = result.mesh
    observed = {
        "maximum_work_units": int(np.asarray(receipt.total_work_units)),
        "maximum_geometry_queries": int(np.asarray(receipt.total_geometry_queries)),
        "maximum_cavity_cells": max(int(np.asarray(phase.work)[2]) for phase in phases),
        "maximum_scratch_bytes": max(
            int(np.asarray(phase.memory)[2]) for phase in phases
        ),
        "maximum_cells": sum(block.cell_count for block in result.mesh.blocks),
        "maximum_vertices": int(result.mesh.coordinates.shape[0]),
        "maximum_edges": int(mesh.entity_set(1).entity_ids.size),
        "maximum_faces": int(mesh.entity_set(2).entity_ids.size),
        "maximum_connectivity_entries": int(
            sum(block.vertices.size for block in mesh.blocks)
            + sum(
                incidence.relation.source_indices.size
                + incidence.relation.target_indices.size
                for incidence in mesh.topology.incidences
            )
        ),
        "maximum_data_bytes": model_array_bytes(result),
        "maximum_wall_seconds": float(np.asarray(receipt.total_elapsed_seconds)),
    }
    declared = {
        name: getattr(request.limits, name)
        for name in inspect.signature(type(request.limits)).parameters
    }
    enforced = {"maximum_" + name for name in result.runtime.enforced_limits}
    bounds = {}
    for name, limit in declared.items():
        value = observed.get(name)
        bounds[name] = {
            "original_limit": limit,
            "observed": value,
            "runtime_enforced": name in enforced,
            "within_original_bound": None if value is None else value <= limit,
            "observation": "unobserved"
            if value is None
            else "actual native receipt or accepted carrier",
        }
        if value is not None and value > limit:
            raise RuntimeError(f"Original periodic receipt exceeds {name}.")
    original = array_tree_fingerprint((source, request, options, result))

    def rebuild(owner: Any, changes: dict[str, Any]) -> Any:
        args, kwargs = [], {}
        for name, parameter in inspect.signature(type(owner)).parameters.items():
            value = changes[name] if name in changes else getattr(owner, name)
            if parameter.kind is inspect.Parameter.POSITIONAL_ONLY:
                args.append(value)
            else:
                kwargs[name] = value
        return type(owner)(*args, **kwargs)

    # A supplied start is the original perf_counter campaign clock, not a new allowance.
    debit = (
        float(np.asarray(receipt.total_elapsed_seconds))
        if campaign_started is None
        else perf_counter() - campaign_started
    )
    operation_started = monotonic() - debit
    refusals, not_exercised = [], []
    for name, value in observed.items():
        is_clock = name == "maximum_wall_seconds"
        if name not in enforced or value <= (0 if is_clock else 1):
            not_exercised.append(
                {
                    "control": name,
                    "reason": "No positive reducible runtime-enforced observation.",
                }
            )
            continue
        lowered = value * 0.5 if is_clock else value - 1
        reduced_limits = rebuild(request.limits, {name: lowered})
        reduced_request = rebuild(request, {"limits": reduced_limits})
        measurements = []
        try:
            with native_volume_execution_budget(
                reduced_limits, operation_started=operation_started
            ):
                phx.meshing.NativeMeshingProvider(options).plan(
                    source,
                    reduced_request,
                    coordinate_contract=result.coordinate_contract,
                    record_phase=measurements.append,
                ).execute(record_phase=measurements.append)
        except phx.meshing.MeshingFailure as failure:
            expected_category = (
                phx.meshing.MeshingFailureCategory.TIMED_OUT
                if is_clock
                else phx.meshing.MeshingFailureCategory.RESOURCE_EXHAUSTED
            )
            if failure.category is not expected_category:
                raise RuntimeError(
                    f"Reduced {name} did not yield a resource refusal: {failure}"
                ) from failure
            evidence = failure.evidence
            refusals.append(
                {
                    "control": name,
                    "original_limit": declared[name],
                    "reduced_limit": lowered,
                    "limits_id": reduced_limits.limits_id,
                    "category": failure.category.value,
                    "failure": str(failure),
                    "evidence_id": evidence.evidence_id,
                    "stage": evidence.stage,
                    "provider_code": evidence.provider_code,
                    "requested": dict(evidence.requested),
                    "achieved": dict(evidence.achieved),
                    "entity_ids": list(evidence.entity_ids),
                    "locations": list(evidence.locations),
                    "checkpoint_id": evidence.checkpoint_id,
                    "native_phases": _phase_recordings(measurements),
                }
            )
        else:
            raise RuntimeError(
                f"Reduced observed {name} unexpectedly admitted a publication."
            )
        if array_tree_fingerprint((source, request, options, result)) != original:
            raise RuntimeError(
                "Resource campaign mutated original source bytes, SCI or controls."
            )
    if not refusals:
        raise RuntimeError(
            "No genuine observed original resource boundary was exercised."
        )
    missing_gate = [
        name
        for name, item in bounds.items()
        if item["observed"] is None or not item["runtime_enforced"]
    ]
    return {
        "status": "incomplete" if missing_gate else "passed",
        "mandatory_capacity_gate": "incomplete" if missing_gate else "complete",
        "unobserved_or_unenforced_original_bounds": missing_gate,
        "positive": {
            "receipt_fingerprint": array_tree_fingerprint(receipt),
            "owner_id": receipt.owner_id,
            "bounds": bounds,
            "phase_receipt_count": len(phases),
            "source_preparation_queries": int(
                np.asarray(receipt.source_preparation_geometry_queries)
            ),
            "cumulative_queries": int(np.asarray(receipt.total_geometry_queries)),
            "native_primitive_queries_by_phase": [
                int(np.asarray(phase.native_primitive_queries)) for phase in phases
            ],
            "externally_charged_queries_by_phase": [
                int(np.asarray(phase.externally_charged_geometry_queries))
                for phase in phases
            ],
            "retained_live_upper_by_phase": [
                int(np.asarray(phase.host_storage_live_bytes_upper)) for phase in phases
            ],
            "retained_peak_upper_by_phase": [
                int(np.asarray(phase.host_storage_peak_bytes_upper)) for phase in phases
            ],
            "managed_memory_counters_by_phase": [
                np.asarray(phase.memory).tolist() for phase in phases
            ],
        },
        "refusals": refusals,
        "not_exercised": not_exercised,
        "original_source_and_controls_preserved": True,
        "unobserved_enforcement_claimed": False,
        "original_elapsed_debit_seconds": debit,
    }


def _polyhedral_qualification_periodic_initial_fields(
    result: Any,
) -> dict[str, jax.Array]:
    from phydrax.discretization.finite_volume import UnstructuredFiniteVolumePlan

    fv = UnstructuredFiniteVolumePlan.from_cell_mesh(result.mesh).prepare(
        cell_geometry=result.geometry
    )
    density = 2.0 + fv.cell_centers[:, 0]
    velocity = jnp.asarray((0.1, 0.2, -0.1), dtype=density.dtype)
    pressure = jnp.ones_like(density)
    momentum = density[:, None] * velocity
    energy = pressure / 0.4 + 0.5 * density * jnp.vdot(velocity, velocity)
    species = density[:, None] * jnp.asarray((0.2, 0.3), dtype=density.dtype)
    conserved = jnp.concatenate(
        (density[:, None], momentum, energy[:, None], species), axis=1
    )
    history = jnp.stack((0.8 * conserved, 0.9 * conserved, conserved))
    return {
        "conserved": conserved,
        "conserved_history": history,
        "pressure": pressure,
        "temperature": pressure / density,
        "pressure_history": jnp.stack((0.8 * pressure, 0.9 * pressure, pressure)),
        "temperature_history": jnp.stack((pressure / density,) * 3),
    }


def _polyhedral_qualification_periodic_transport(
    adaptation: Any, fields: dict[str, Any], epoch: int
) -> tuple[dict[str, Any], dict[str, Any]]:
    from phydrax.discretization._cell_geometry_validity import cell_geometry_id
    from phydrax.discretization._topology_epoch import FieldEpochTransition, TopologyEpoch
    from phydrax.discretization._transfer import TransferGeometryBinding
    from phydrax.discretization.finite_volume import UnstructuredFiniteVolumePlan
    from phydrax.discretization.finite_volume._unstructured_remap import (
        UnstructuredConservativeRemapPlan,
    )
    from phydrax.discretization.vem import prepare_polyhedral_h1_virtual_element_3d
    from phydrax.lifecycle import (
        commit_composition_rebind,
        Composition,
        CompositionEntry,
        CompositionRebind,
        CompositionRole,
    )

    source, target, common = (
        adaptation.source,
        adaptation.target,
        adaptation.common_refinement,
    )
    if (
        common is None
        or not common.succeeded
        or adaptation.status is not phx.meshing.MeshAdaptationStatus.COMPLETE
    ):
        raise RuntimeError(
            "Periodic accepted transition requires complete canonical overlap and adaptation."
        )
    old_fv = UnstructuredFiniteVolumePlan.from_cell_mesh(source.mesh).prepare(
        cell_geometry=source.geometry
    )
    new_fv = UnstructuredFiniteVolumePlan.from_cell_mesh(target.mesh).prepare(
        cell_geometry=target.geometry
    )
    remap = UnstructuredConservativeRemapPlan(
        old_fv,
        new_fv,
        common.target_offsets,
        common.source_cells,
        common.volumes,
        method="common-refinement",
        provenance=common.refinement_id,
        intersection_error_bounds=common.volume_error_bounds,
    )
    old_epoch = TopologyEpoch(epoch, old_fv.geometry_id, old_fv.topology_id, "serial")
    new_epoch = TopologyEpoch(epoch + 1, new_fv.geometry_id, new_fv.topology_id, "serial")
    transfer = remap.epoch_transition(
        old_fv.cell_space, new_fv.cell_space, old_epoch, new_epoch
    )
    old_topology = CompositionEntry(
        source,
        entry_id="mesh",
        role="topology",
        owner_id="meshing",
        structure_id=old_epoch.epoch_id,
        revision_id=source.result_id,
        semantics_id="original-periodic-power-source",
    )
    new_topology = CompositionEntry(
        target,
        entry_id="mesh",
        role="topology",
        owner_id="meshing",
        structure_id=new_epoch.epoch_id,
        revision_id=target.result_id,
        semantics_id="original-periodic-power-source",
    )
    entries, transports, output = [old_topology], [], {}
    inventory_defects = {}
    nodal_evidence = None
    cell_fields = ("conserved", "pressure", "temperature", "fv_cell_solution")
    for name in cell_fields:
        if name not in fields:
            continue
        field_entries: list[tuple[str, Any, CompositionRole]] = [
            (name, fields[name], "physical-state"),
        ]
        for index, item in enumerate(fields.get(name + "_history", ())):
            field_entries.append((f"{name}-history:{index}", item, "history"))
        for role_name, value, role in field_entries:
            value = jnp.asarray(value)
            target_value = remap.apply(value)
            components = (
                ((role_name, value, target_value),)
                if value.ndim == 1
                else tuple(
                    (
                        f"{role_name}:component{column}",
                        value[:, column],
                        target_value[:, column],
                    )
                    for column in range(value.shape[1])
                )
            )
            for component_name, before_value, after_value in components:
                old_entry = CompositionEntry(
                    before_value,
                    entry_id=component_name,
                    role=role,
                    owner_id="finite-volume",
                    structure_id=old_epoch.epoch_id,
                    revision_id=source.result_id,
                    semantics_id="cell-average",
                    dependencies=(old_topology.binding("structure"),),
                )
                new_entry = CompositionEntry(
                    after_value,
                    entry_id=component_name,
                    role=role,
                    owner_id="finite-volume",
                    structure_id=new_epoch.epoch_id,
                    revision_id=target.result_id,
                    semantics_id="cell-average",
                    dependencies=(new_topology.binding("structure"),),
                )
                entries.append(old_entry)
                transports.append(transfer.composition_transport(old_entry, new_entry))
            before = np.tensordot(
                np.asarray(old_fv.cell_volumes), np.asarray(value), axes=(0, 0)
            )
            after = np.tensordot(
                np.asarray(new_fv.cell_volumes), np.asarray(target_value), axes=(0, 0)
            )
            defect = float(np.max(np.abs(after - before)))
            if defect > 1e-10 * max(1.0, float(np.max(np.abs(before)))):
                raise RuntimeError(
                    f"Actual conservative periodic transfer loses {role_name} inventory."
                )
            inventory_defects[role_name] = defect
            if role == "physical-state":
                output[name] = target_value
        if name + "_history" in fields:
            output[name + "_history"] = jnp.stack(
                tuple(remap.apply(item) for item in fields[name + "_history"])
            )
    if "vem_solution" in fields:
        if adaptation.transfer is None:
            raise RuntimeError(
                "Actual scalar VEM state requires a source-backed canonical vertex stencil."
            )
        old_vem = prepare_polyhedral_h1_virtual_element_3d(
            source.mesh, cell_geometry=source.geometry
        )
        new_vem = prepare_polyhedral_h1_virtual_element_3d(
            target.mesh, cell_geometry=target.geometry
        )
        binding = TransferGeometryBinding(
            cell_geometry_id(source.geometry),
            cell_geometry_id(target.geometry),
            "topology-correspondence",
            source_topology_id=source.mesh.topology_id,
            target_topology_id=target.mesh.topology_id,
            coverage_defect=None,
        )
        nodal = old_vem.vertex_field_transfer(
            new_vem, adaptation.transfer, binding, field_name="temperature-vem"
        )
        source_probe = jnp.sin(
            jnp.arange(old_vem.dof_count, dtype=fields["vem_solution"].dtype) + 0.3
        )
        target_probe = jnp.cos(
            jnp.arange(new_vem.dof_count, dtype=source_probe.dtype) + 0.7
        )
        dual_pullback = nodal.dual_pullback_operator
        if dual_pullback is None:
            raise RuntimeError(
                "Actual quotient VEM transfer omitted its adjoint-paired operator."
            )
        pairing_left = jnp.vdot(target_probe, nodal.primal_operator.mv(source_probe))
        pairing_right = jnp.vdot(dual_pullback.mv(target_probe), source_probe)
        defect = float(jnp.abs(pairing_left - pairing_right))
        bound = float(
            100
            * jnp.finfo(source_probe.dtype).eps
            * jnp.maximum(
                jnp.maximum(jnp.abs(pairing_left), jnp.abs(pairing_right)),
                jnp.finfo(source_probe.dtype).tiny,
            )
        )
        if defect > bound:
            raise RuntimeError(
                "Actual nontrivial quotient VEM edge map has a mismatched raw transpose."
            )
        nodal_evidence = {
            "transfer_id": nodal.transfer_id,
            "source_dofs": old_vem.dof_count,
            "target_dofs": new_vem.dof_count,
            "raw_transpose_defect": defect,
            "storage_roundoff_bound": bound,
            "physical_stencil_present": adaptation.stencil is not None,
            "semantics": nodal.properties.semantics,
        }
        old_nodal_epoch = TopologyEpoch(
            epoch, binding.source_geometry_id, source.mesh.topology_id, "serial"
        )
        new_nodal_epoch = TopologyEpoch(
            epoch + 1, binding.target_geometry_id, target.mesh.topology_id, "serial"
        )
        nodal_epoch = FieldEpochTransition(
            old_nodal_epoch,
            new_nodal_epoch,
            nodal,
            evidence_passed=bool(
                nodal.properties.constant_preserving
                and nodal.properties.positivity_preserving
                and nodal.properties.adjoint_paired
            ),
            evidence_id=nodal.transfer_id,
        )
        nodal_entries: list[tuple[str, Any, CompositionRole]] = [
            ("vem_solution", fields["vem_solution"], "physical-state"),
        ]
        for index, item in enumerate(fields.get("vem_solution_history", ())):
            nodal_entries.append((f"vem_solution-history:{index}", item, "history"))
        for role_name, value, role in nodal_entries:
            target_value = nodal.primal_operator.mv(value)
            old_entry = CompositionEntry(
                value,
                entry_id=role_name,
                role=role,
                owner_id="virtual-element",
                structure_id=old_nodal_epoch.epoch_id,
                revision_id=source.result_id,
                semantics_id="scalar-quotient-vertex-trace",
                dependencies=(old_topology.binding("structure"),),
            )
            new_entry = CompositionEntry(
                target_value,
                entry_id=role_name,
                role=role,
                owner_id="virtual-element",
                structure_id=new_nodal_epoch.epoch_id,
                revision_id=target.result_id,
                semantics_id="scalar-quotient-vertex-trace",
                dependencies=(new_topology.binding("structure"),),
            )
            entries.append(old_entry)
            transports.append(nodal_epoch.composition_transport(old_entry, new_entry))
            if role == "physical-state":
                output["vem_solution"] = target_value
        output["vem_solution_history"] = jnp.stack(
            tuple(
                nodal.primal_operator.mv(item) for item in fields["vem_solution_history"]
            )
        )
    receipt = commit_composition_rebind(
        CompositionRebind(
            Composition(tuple(entries), boundary_id="accepted-periodic-step"),
            reprepare=(new_topology,),
            transports=tuple(transports),
        ),
        accepted_boundary=True,
    )
    if not receipt.published:
        raise RuntimeError(
            "ALL physical/history periodic composition did not publish atomically."
        )
    for name in cell_fields:
        if name in output:
            if output[name].ndim == 1:
                output[name] = jnp.asarray(receipt.composition.value(name))
            else:
                output[name] = jnp.stack(
                    tuple(
                        jnp.asarray(
                            receipt.composition.value(f"{name}:component{column}")
                        )
                        for column in range(output[name].shape[1])
                    ),
                    axis=1,
                )
    if "vem_solution" in output:
        output["vem_solution"] = jnp.asarray(receipt.composition.value("vem_solution"))
    return output, {
        "receipt_id": receipt.receipt_id,
        "published": receipt.published,
        "source_result_id": source.result_id,
        "target_result_id": target.result_id,
        "physical_roles": tuple(
            entry.entry_id for entry in entries if entry.role == "physical-state"
        ),
        "history_roles": tuple(
            entry.entry_id for entry in entries if entry.role == "history"
        ),
        "inventory_defects": inventory_defects,
        "common_refinement_id": common.refinement_id,
        "nodal_semantics": "source-backed scalar edge trace interpolation, not interior nested VEM equality",
        "nodal_transfer": nodal_evidence,
        "derived_geometry_flux_and_residuals": "old accepted epoch retained; target reprepared from transported physical state",
    }


def _polyhedral_qualification_periodic_adapt(
    result: Any, request: Any, limits: Any
) -> Any:
    policy = phx.meshing.MeshAdaptationPolicy(
        phx.meshing.MeshAdaptationRoute.NATIVE_POLYHEDRAL,
        limits=limits,
        audit_policy=phx.meshing.CellMeshAuditPolicy(
            require_complete_association=True,
            watertight_boundary=phx.meshing.CellMeshAuditDisposition.REJECT,
        ),
    )
    return phx.meshing.execute_mesh_adaptation(
        phx.meshing.prepare_mesh_adaptation(result, request, policy=policy)
    )


def _polyhedral_qualification_periodic_inverse_groups(
    adaptation: Any,
) -> tuple[tuple[int, ...], ...]:
    common = adaptation.common_refinement
    if common is None or not common.succeeded:
        raise RuntimeError(
            "Periodic inverse needs actual source/target overlap, not rounded-centroid grouping."
        )
    sources, targets = np.asarray(common.source_cells), np.asarray(common.target_cells)
    ids = np.asarray(adaptation.target.mesh.connectivity.cell_global_ids)
    owner = {}
    groups = {}
    for source, target in zip(sources, targets, strict=True):
        if int(target) in owner and owner[int(target)] != int(source):
            raise RuntimeError(
                "A split child overlaps multiple source parents; it has no simple inverse group."
            )
        owner[int(target)] = int(source)
        groups.setdefault(int(source), set()).add(int(ids[target]))
    if set(owner) != set(range(len(ids))):
        raise RuntimeError("Certified periodic inverse groups omit target cells.")
    return tuple(
        tuple(sorted(values)) for _, values in sorted(groups.items()) if len(values) > 1
    )


def _polyhedral_qualification_periodic_lifecycle(
    args: argparse.Namespace,
) -> dict[str, Any]:
    started = perf_counter()
    stages = {"_campaign_started": started}
    phases = []
    case = polyhedral_case(args.polyhedral_source)
    record = {
        "scenario": "native-polyhedral-lifecycle",
        "case": polyhedral_identity(case.name),
        "status": "failed",
        "engine": "native",
        "runtime": _runtime_identity(),
        "control_capacities": {
            "site_count": 2,
            "requested_resolution": args.resolution,
            "entity_capacity": args.capacity,
        },
        "targets": {
            "maximum_physics_error": args.target_error,
            "wall_seconds": args.timeout,
        },
        "stages_seconds": stages,
        "mandatory_workflow_completion": "incomplete",
        "release": "unassessed",
        "leadership": "unassessed",
    }
    phase = "original_source_preparation"
    try:
        source, request, options = prepare_polyhedral_case(
            case.name, args.resolution, args.capacity, args.timeout, source=True
        )
        if (
            not isinstance(source, phx.meshing.NativePolyhedralSource)
            or len(source.sites) != 2
            or len(request.periodic_constraints) != 3
        ):
            raise RuntimeError(
                "Original periodic lifecycle source or controls were replaced."
            )
        record["source_id"], record["source_revision"] = (
            source.source_id,
            source.source_revision,
        )
        record["request_id"] = request.specification_id
        phase = "source_generation_publication_certification"
        provider = phx.meshing.NativeMeshingProvider(options)
        plan, measured = _measured(
            lambda: provider.plan(
                source,
                request,
                coordinate_contract=phx.SpatialCoordinateContract.si(),
                record_phase=phases.append,
            )
        )
        stages["source_planning"] = measured["wall_seconds"]
        current, measured = _measured(lambda: plan.execute(record_phase=phases.append))
        stages[phase] = measured["wall_seconds"]
        _, record["source_acceptance"] = _polyhedral_acceptance(current, case)
        original = current
        fields = _polyhedral_qualification_periodic_initial_fields(current)
        epochs, physics_records, transfers = [], [], []
        phase = "original_source_quotient_physics"
        physics, error, fields = _polyhedral_qualification_periodic_physics(
            current, fields, args.repeats, stages
        )
        epochs.append((current, fields))
        physics_records.append(physics)
        for cycle in range(args.adaptation_rounds):
            phase = f"round{cycle}_actual_plane_refinement"
            split_request = phx.meshing.PolyhedralMeshAdaptation(
                phx.meshing.PolyhedralAdaptationOperation.PLANE_SPLIT,
                planes=((1.0, 0.0, 0.0, 0.25), (1.0, 0.0, 0.0, 0.75)),
            )
            split, measured = _measured(
                lambda: _polyhedral_qualification_periodic_adapt(
                    current, split_request, request.limits
                )
            )
            stages[phase] = measured["wall_seconds"]
            if (
                split.target.mesh.connectivity.cell_count
                <= current.mesh.connectivity.cell_count
            ):
                raise RuntimeError(
                    "Requested periodic refinement did not perform actual cell subdivision."
                )
            inverse_groups = _polyhedral_qualification_periodic_inverse_groups(split)
            phase = f"round{cycle}_allfield_history_refine_transfer"
            fields, proof = _polyhedral_qualification_periodic_transport(
                split, fields, len(epochs) - 1
            )
            transfers.append(proof)
            current = split.target
            _, proof = _polyhedral_acceptance(current, case)
            phase = f"round{cycle}_refined_quotient_continued_pde"
            physics, target_error, fields = _polyhedral_qualification_periodic_physics(
                current, fields, args.repeats, stages, seeds=fields
            )
            if physics["vem"]["physical_response"] <= 1e-10:
                raise RuntimeError(
                    "Actual refined source did not produce a nonconstant quotient VEM response."
                )
            error = max(error, target_error)
            epochs.append((current, fields))
            physics_records.append(physics)
            phase = f"round{cycle}_actual_inverse_agglomeration"
            coarse_request = phx.meshing.PolyhedralMeshAdaptation(
                phx.meshing.PolyhedralAdaptationOperation.AGGLOMERATE,
                agglomerations=inverse_groups,
            )
            coarse, measured = _measured(
                lambda: _polyhedral_qualification_periodic_adapt(
                    current, coarse_request, request.limits
                )
            )
            stages[phase] = measured["wall_seconds"]
            phase = f"round{cycle}_allfield_history_inverse_transfer"
            fields, proof = _polyhedral_qualification_periodic_transport(
                coarse, fields, len(epochs) - 1
            )
            transfers.append(proof)
            current = coarse.target
            if (
                current.mesh.connectivity.cell_count
                != original.mesh.connectivity.cell_count
            ):
                raise RuntimeError(
                    "Actual periodic inverse failed to restore original cell coverage."
                )
            _polyhedral_acceptance(current, case)
            phase = f"round{cycle}_coarse_quotient_continued_pde"
            physics, target_error, fields = _polyhedral_qualification_periodic_physics(
                current, fields, args.repeats, stages, seeds=fields
            )
            error = max(error, target_error)
            epochs.append((current, fields))
            physics_records.append(physics)
        phase = "original_cumulative_resource_capacity_proof"
        record["resources"] = _polyhedral_qualification_periodic_resource_refusals(
            source, request, options, original, campaign_started=started
        )
        phase = "default_source_allfield_history_fresh_cold_continued_pde"
        record["cold"] = _polyhedral_qualification_periodic_cold(
            source,
            request,
            options,
            tuple(epochs),
            args.repeats,
            args.target_error,
            stages,
        )
        if record["cold"]["status"] != "passed":
            raise RuntimeError("Default cold original-source continuation did not pass.")
        elapsed = perf_counter() - started
        capacity_complete = record["resources"]["mandatory_capacity_gate"] == "complete"
        record.update(
            status="passed"
            if error <= args.target_error
            and elapsed <= args.timeout
            and capacity_complete
            else "failed",
            physical_error=error,
            target_error_reached=error <= args.target_error,
            time_to_target_error_seconds=elapsed if error <= args.target_error else None,
            mandatory_workflow_completion="complete"
            if capacity_complete
            else "incomplete",
            physics=physics_records,
            canonical_adaptation={
                "status": "complete",
                "cycles": args.adaptation_rounds,
                "transfers": transfers,
            },
            accepted_epochs=[_result_identity(result) for result, _ in epochs],
            logical_retained_bytes=_bisection_retained_bytes(
                (source, request, options, epochs)
            ),
            independent_scientific_certification="passed",
        )
        if elapsed > args.timeout:
            record["status"] = "timeout"
    except Exception as failure:
        record.update(
            failure_phase=phase, failure=str(failure), failure_type=type(failure).__name__
        )
        if isinstance(failure, phx.meshing.MeshingFailure):
            record.update(
                failure_category=failure.category.value,
                failure_evidence_id=failure.evidence.evidence_id,
                requested=dict(failure.evidence.requested),
                achieved=dict(failure.evidence.achieved),
                failing_entities=list(failure.evidence.entity_ids),
                native_stage=failure.evidence.stage,
            )
    finally:
        record["end_to_end_seconds"] = perf_counter() - started
        record["native_phases"] = _phase_recordings(phases)
        record["peak_process_resident_bytes"] = resource.getrusage(
            resource.RUSAGE_SELF
        ).ru_maxrss * (1 if sys.platform == "darwin" else 1024)
    return record


def qualify_native_polyhedral(args: argparse.Namespace) -> dict[str, object]:
    """Nonconvex material PLC → power cells → conservative state → VEM/FV."""
    if "periodic-quotient" in polyhedral_case(args.polyhedral_source).controls:
        return _polyhedral_qualification_periodic_lifecycle(args)
    started = perf_counter()
    case = polyhedral_case(args.polyhedral_source)
    stages: dict[str, float] = {}
    native_phases: list[NativeMeshingPhaseMeasurement] = []
    record: dict[str, Any] = {
        "scenario": "native-polyhedral-lifecycle",
        "status": "failed",
        "engine": "native",
        "case": polyhedral_identity(case.name),
        "runtime": _runtime_identity(),
        "control_capacities": {
            "site_count": args.resolution,
            "entity_capacity": args.capacity,
        },
        "targets": {
            "maximum_physics_error": args.target_error,
            "wall_seconds": args.timeout,
        },
        "stages_seconds": stages,
        "time_to_target_error_seconds": None,
        "mandatory_workflow_completion": "incomplete",
        "release": "unassessed",
        "leadership": "unassessed",
        "canonical_adaptation": {"claimed": False, "status": "unassessed"},
        "nonclaims": [
            "Soft size is not a hard size guarantee.",
            "Fixed-topology site derivatives are not claimed.",
            "Routine source/site sweeps do not complete larger demanding-control corpus.",
        ],
    }
    phase = "source_preparation"
    try:
        if not meshcore_available():
            record.update(
                _missing_dependency(
                    "phydrax-meshcore",
                    "The required native construction library is unavailable.",
                )
            )
            return record
        if (
            args.repeats < 1
            or not np.isfinite(args.target_error)
            or args.target_error <= 0.0
        ):
            raise ValueError("Repeats and physical error target must be positive.")
        results, labels, acceptance, plans = {}, {}, {}, []
        for epoch in ("source", "target"):
            phase = f"{epoch}_preparation"
            prepared, measured = _measured(
                lambda epoch=epoch: prepare_polyhedral_case(
                    case.name,
                    args.resolution,
                    args.capacity,
                    args.timeout,
                    source=epoch == "source",
                )
            )
            geometry, request, options = prepared
            stages[phase] = measured["wall_seconds"]
            record[f"{epoch}_request_id"] = request.specification_id
            if epoch == "target":
                record["request_id"] = request.specification_id
            record[f"{epoch}_source_revision"] = geometry.source_revision
            phase = f"{epoch}_planning"
            provider = phx.meshing.NativeMeshingProvider(options)
            plan, measured = _measured(
                lambda: provider.plan(
                    geometry,
                    request,
                    coordinate_contract=phx.SpatialCoordinateContract.si(),
                    record_phase=native_phases.append,
                )
            )
            stages[phase] = measured["wall_seconds"]
            plans.append(plan)
            phase = f"{epoch}_generation_publication_certification"
            result, measured = _measured(
                lambda: plan.execute(record_phase=native_phases.append)
            )
            stages[phase] = measured["wall_seconds"]
            phase = f"{epoch}_independent_acceptance"
            checked, measured = _measured(lambda: _polyhedral_acceptance(result, case))
            labels[epoch], acceptance[epoch] = checked
            stages[phase] = measured["wall_seconds"]
            results[epoch] = result
        phase = "canonical_regeneration"
        if not isinstance(geometry, phx.meshing.NativePolyhedralSource):
            raise TypeError(
                "Canonical polyhedral target requires its authored sites/weights."
            )
        canonical, measured = _measured(
            lambda: phx.meshing.execute_mesh_adaptation(
                phx.meshing.prepare_mesh_adaptation(
                    results["source"],
                    phx.meshing.PolyhedralMeshAdaptation(
                        phx.meshing.PolyhedralAdaptationOperation.REGENERATE,
                        complex_=geometry.complex,
                        sites=geometry.sites,
                        weights=geometry.weights,
                        schedule=options.polyhedral_schedule,
                    ),
                    policy=phx.meshing.MeshAdaptationPolicy(
                        phx.meshing.MeshAdaptationRoute.NATIVE_POLYHEDRAL,
                        limits=request.limits,
                        audit_policy=phx.meshing.CellMeshAuditPolicy(
                            require_complete_association=True,
                            watertight_boundary=phx.meshing.CellMeshAuditDisposition.REJECT,
                        ),
                    ),
                )
            )
        )
        stages[phase] = measured["wall_seconds"]
        original_organization = results["source"]
        if (
            {patch.name for patch in canonical.target.patches}
            != {patch.name for patch in original_organization.patches}
            or {label.name for label in canonical.target.labels}
            != {label.name for label in original_organization.labels}
            or {
                (zone.name, zone.material_id, zone.region_role)
                for zone in canonical.target.zones
            }
            != {
                (zone.name, zone.material_id, zone.region_role)
                for zone in original_organization.zones
            }
        ):
            raise RuntimeError(
                "Canonical polyhedral regeneration lost authored source organization."
            )
        record["independent_target_generation"] = _result_identity(results["target"])
        results["target"] = canonical.target
        labels["target"], acceptance["target"] = _polyhedral_acceptance(
            canonical.target, case
        )
        if (
            canonical.common_refinement is None
            or not canonical.common_refinement.succeeded
        ):
            raise RuntimeError(
                "Canonical polyhedral regeneration lacks certified complete overlap."
            )
        record["canonical_adaptation"] = {
            "claimed": True,
            "status": canonical.status.value,
            "target_result_id": canonical.target.result_id,
            "transition_id": None
            if canonical.transition is None
            else canonical.transition.transition_id,
            "source_organization_preserved": True,
        }
        record["generation"] = {
            name: {
                **_result_identity(result),
                "family_counts": {
                    block.cell_kind: block.cell_count for block in result.mesh.blocks
                },
            }
            for name, result in results.items()
        }
        record["independent_acceptance"] = acceptance
        record["controls"] = {
            "family": "required polyhedron",
            "size_strength": "soft",
            "hard_size_claim": False,
            "materials": dict(case.expected_regions),
            "requested_resource_limits": "frozen; only runtime-listed bounds are enforced",
            "generation_resource_guarantees": {
                name: {
                    "enforced": list(result.runtime.enforced_limits),
                    "unenforced": list(result.runtime.unenforced_limits),
                }
                for name, result in results.items()
            },
            "target_request_id": record["request_id"],
        }
        phase = "common_refinement_and_conservative_remap"
        remap_policy = phx.geometry.CommonRefinementPolicy(
            maximum_candidate_pairs=32 * args.capacity,
            maximum_accepted_pairs=32 * args.capacity,
            maximum_memory_bytes=4096 * args.capacity,
        )
        transferred, measured = _measured(
            lambda: _polyhedral_remap(
                results["source"],
                results["target"],
                labels["source"],
                labels["target"],
                remap_policy,
            )
        )
        common, remapped, remap_evidence = transferred
        stages[phase] = measured["wall_seconds"]
        record["remap"] = remap_evidence
        phase = "prepared_consumers_and_transferred_physics"
        physics, error, retained = _polyhedral_physics(
            results["target"],
            remapped,
            args.repeats,
            stages,
            results["source"],
            common,
            labels["source"],
        )
        inventories = _record_mapping(
            remap_evidence["material_inventories"], "Material inventories"
        )
        inventory_after = sum(
            _record_float(
                _record_mapping(item, "Material inventory")["after"], "Target inventory"
            )
            for item in inventories.values()
        )
        fv_physics = _record_mapping(physics["fv"], "FV physics")
        consumed_inventory = _record_float(
            fv_physics["transferred_source_integral"], "Consumed inventory"
        )
        inventory_defect = abs(consumed_inventory - inventory_after)
        domain_measure = _record_float(fv_physics["domain_measure"], "FV domain measure")
        domain_defect = abs(domain_measure - sum(dict(case.expected_regions).values()))
        if (
            inventory_defect > 1e-10 * max(1.0, abs(inventory_after))
            or domain_defect > 1e-10
        ):
            raise RuntimeError(
                "FV physics did not consume the certified remapped material inventory."
            )
        remap_evidence["consumed_inventory_defect"] = inventory_defect
        elapsed = perf_counter() - started
        record.update(
            {
                "physics": physics,
                "physical_error": error,
                "mandatory_workflow_completion": "complete",
                "target_error_reached": error <= args.target_error,
                "status": "passed" if error <= min(args.target_error, 1e-7) else "failed",
                "time_to_target_error_seconds": elapsed
                if error <= args.target_error
                else None,
                "logical_retained_bytes": _bisection_retained_bytes(
                    (retained, results, plans, common, remapped, labels)
                ),
                "independent_scientific_certification": "passed",
            }
        )
        if elapsed > args.timeout:
            record["status"] = "timeout"
    except phx.meshing.MeshingFailure as failure:
        record.update(
            {
                "status": "timeout"
                if failure.category is phx.meshing.MeshingFailureCategory.TIMED_OUT
                else "failed",
                "failure_phase": phase,
                "failure": str(failure),
                "failure_category": failure.category.value,
                "failure_evidence_id": failure.evidence.evidence_id,
                "failure_message": failure.evidence.message,
                "provider_code": failure.evidence.provider_code,
                "native_stage": failure.evidence.stage,
                "locations": [list(point) for point in failure.evidence.locations],
                "checkpoint_id": failure.evidence.checkpoint_id,
                "requested": dict(failure.evidence.requested),
                "achieved": dict(failure.evidence.achieved),
                "failing_entities": list(failure.evidence.entity_ids),
            }
        )
    except (RuntimeError, ValueError, TypeError) as failure:
        record.update(
            {
                "failure_phase": phase,
                "failure": str(failure),
                "failure_type": type(failure).__name__,
            }
        )
    finally:
        record["native_phases"] = _phase_recordings(native_phases)
        record["end_to_end_seconds"] = perf_counter() - started
        record["peak_process_resident_bytes"] = resource.getrusage(
            resource.RUSAGE_SELF
        ).ru_maxrss * (1 if sys.platform == "darwin" else 1024)
        record["process_peak_scope"] = "process-lifetime"
        record["device_memory"] = [
            {
                "device_id": device.id,
                "platform": device.platform,
                "status": "unavailable" if statistics is None else "backend-reported",
                "peak_bytes": None
                if statistics is None
                else statistics.get("peak_bytes_in_use"),
                "memory_statistics": statistics,
            }
            for device in jax.local_devices()
            for statistics in (device.memory_stats(),)
        ]
    return record


def _envelope_qualification_fixture(
    resolution: int,
    capacity: int,
) -> tuple[RawTriangleSoup, SurfaceEnvelopePolicy, dict[str, object]]:
    """Freeze the positive open-sheet source and explicit thickening semantics."""
    from phydrax.geometry.surface._contracts import SurfaceMetadata
    from phydrax.meshing._surface_envelope import (
        EnvelopeFeaturePermission,
        EnvelopeTopologyPermission,
    )

    payload = {
        "vertices": ((0.0, 0.0, 0.0), (0.2, 0.0, 0.0), (0.0, 0.2, 0.0)),
        "triangles": ((0, 1, 2),),
        "feature_edges": ((0, 1),),
        "coordinate_units": "meter",
        "region_id": "wrapped-solid",
        "interpretation": "sampled_unsigned_distance_sublevel",
        "offset": 0.263,
        "maximum_deviation": 0.55,
        "feature_permission": "allow_rounding",
        "topology_permission": "allow_change",
        "provenance": "PHYDRA synthetic open sheet; test_surface_envelope positive fixture",
    }
    digest = canonical_fingerprint(payload)
    metadata = SurfaceMetadata(
        source_id="qualification-open-envelope-sheet",
        source_revision=digest,
        coordinate_contract=phx.SpatialCoordinateContract.si(),
        provenance=(payload["provenance"],),
    )
    soup = RawTriangleSoup(
        np.asarray(payload["vertices"], dtype=np.float64),
        np.asarray(payload["triangles"], dtype=np.int64),
        metadata,
        feature_edges=np.asarray(payload["feature_edges"], dtype=np.int64),
    )
    policy = SurfaceEnvelopePolicy(
        offset=0.263,
        maximum_deviation=0.55,
        spacing=0.44 / resolution,
        certificate_spacing=0.2 / resolution,
        feature_permission=EnvelopeFeaturePermission.ALLOW_ROUNDING,
        topology_permission=EnvelopeTopologyPermission.ALLOW_CHANGE,
        max_samples=5 * capacity,
        max_work_units=1000 * capacity,
        max_vertices=capacity,
        max_triangles=capacity,
        max_volume_vertices=capacity,
        max_tetrahedra=5 * capacity,
    )
    return (
        soup,
        policy,
        {
            "name": "open-sheet-repaired-envelope",
            "source_digest": digest,
            "source_geometry_id": soup.soup_id,
            "source_id": metadata.source_id,
            "source_revision": metadata.source_revision,
            "payload": payload,
            "policy_id": policy.policy_id,
            "spacing": policy.spacing,
            "certificate_spacing": policy.certificate_spacing,
        },
    )


def _envelope_qualification_limits(
    capacity: int, timeout: float
) -> phx.meshing.MeshingLimits:
    return phx.meshing.MeshingLimits(
        maximum_vertices=capacity,
        maximum_cells=5 * capacity,
        maximum_work_units=1000 * capacity,
        maximum_wall_seconds=timeout,
    )


def _envelope_qualification_prepare_source(
    soup: RawTriangleSoup,
    policy: SurfaceEnvelopePolicy,
    args: argparse.Namespace,
    phases: list[NativeMeshingPhaseMeasurement],
    record: dict[str, Any],
) -> tuple[
    SurfaceEnvelope,
    phx.meshing.NativeSurfaceEnvelopeSource,
    phx.meshing.VolumeMeshingSpec,
    phx.meshing.NativeMeshingOptions,
    NativeExecutionRecord,
]:
    from phydrax.meshing._surface_envelope import wrap_surface_envelope
    from phydrax.meshing._volume_generation import native_volume_execution_budget

    with native_volume_execution_budget(
        _envelope_qualification_limits(args.capacity, args.timeout),
        stage=phx.meshing.MeshingStageKind.SOURCE_INSPECTION,
    ) as budget:
        envelope, measured = _measured(
            lambda: wrap_surface_envelope(soup, policy, record_phase=phases.append)
        )
        record["stages_seconds"]["native_envelope_construction"] = measured[
            "wall_seconds"
        ]
        record["active_phase"] = "repaired_request_preparation"
        request, measured = _measured(
            lambda: _envelope_qualification_request(envelope, args.capacity, args.timeout)
        )
        record["stages_seconds"]["repaired_request_preparation"] = measured[
            "wall_seconds"
        ]
    if budget.evidence is None:
        raise RuntimeError(
            "Envelope source preparation lost its actual ended root receipt."
        )
    receipt = NativeExecutionRecord(budget.evidence, owner_id=envelope.envelope_id)
    return envelope, *request, receipt


def _envelope_qualification_request(
    envelope: SurfaceEnvelope,
    capacity: int,
    timeout: float,
) -> tuple[
    phx.meshing.NativeSurfaceEnvelopeSource,
    phx.meshing.VolumeMeshingSpec,
    phx.meshing.NativeMeshingOptions,
]:
    """Bind the volume request only to the separately repaired source identity."""
    from phydrax.meshing._volume_generation import NativeVolumeSchedule
    from phydrax.meshing.providers._native_sources import NativeSurfaceEnvelopeSource

    source = NativeSurfaceEnvelopeSource(envelope, "wrapped-solid")
    scope = phx.meshing.MeshingScope(
        source.source_id,
        source.source_revision,
        phx.meshing.MeshingEntityKind.GEOMETRY,
        2,
        "envelope-facets",
        np.arange(source.plc_source.complex.facet_count, dtype=np.int64),
    )
    specification = phx.meshing.VolumeMeshingSpec(
        phx.meshing.CellMeshingTarget(
            3, 3, phx.meshing.CellFamilyPolicy(required=("tetrahedron",))
        ),
        scope,
        phx.meshing.VolumeFillStrategy.SIMPLEX,
        size_controls=(
            phx.meshing.UniformSizeControl(
                scope, 2.0, strength=phx.meshing.SizeControlStrength.SOFT
            ),
        ),
        limits=_envelope_qualification_limits(capacity, timeout),
    )
    options = phx.meshing.NativeMeshingOptions(
        "surface_envelope_tetrahedral",
        volume_schedule=NativeVolumeSchedule(
            refinement_rounds=1, improvement_passes=1, minimum_dihedral_degrees=0.0
        ),
    )
    return source, specification, options


def _envelope_qualification_acceptance(
    source: phx.meshing.NativeSurfaceEnvelopeSource,
    result: phx.meshing.CellMeshingResult,
) -> dict[str, object]:
    """Check repaired-domain fill independently, retaining the repair theorem."""
    from dataclasses import asdict

    from phydrax.meshing._volume_generation import declared_plc_domain

    envelope = source.envelope
    evidence = envelope.evidence
    certificate = result.certification
    if certificate is None or not certificate.passed:
        raise RuntimeError("Envelope consumer requires strict native certification.")
    embedding, coverage = certificate.embedding, certificate.coverage
    if embedding is None or coverage is None:
        raise RuntimeError("Repaired envelope lacks global embedding or domain coverage.")
    if embedding.status != "certified" or coverage.status != "certified":
        raise RuntimeError("Repaired envelope embedding/domain coverage is unresolved.")
    domain = certificate.request.domain
    expected_domain = declared_plc_domain(source.plc_source.complex, source.source_id)
    if (
        domain is None
        or domain.domain_id != expected_domain.domain_id
        or coverage.domain_id != expected_domain.domain_id
        or domain.source_id != source.source_id
    ):
        raise RuntimeError("Envelope certificate lost the exact repaired source domain.")
    if coverage.covered_source_facet_count != coverage.source_facet_count:
        raise RuntimeError(
            "Repaired envelope does not cover every authoritative source facet."
        )
    if not result.audit.passed or not result.compliance.passed:
        raise RuntimeError("Repaired envelope audit or request compliance failed.")
    achieved = dict(result.compliance.achieved)
    for name in (
        "source_to_repaired_upper",
        "repaired_to_source_upper",
        "source_inclusion_margin",
        "interpolation_error",
    ):
        if achieved.get(f"envelope:{name}") != getattr(evidence, name):
            raise RuntimeError(
                f"Envelope consumer lost its original directed {name} evidence."
            )
    repair_inputs = (
        evidence.source_id,
        evidence.source_revision,
        evidence.source_geometry_id,
        evidence.policy_id,
    )
    repair_outputs = (
        source.source_id,
        source.source_revision,
        evidence.repaired_model_id,
        evidence.evidence_id,
    )
    if not any(
        stage.stage is phx.meshing.MeshingStageKind.TOPOLOGY_REPAIR
        and stage.status is phx.meshing.MeshingStageStatus.PASSED
        and stage.input_ids == repair_inputs
        and stage.output_ids == repair_outputs
        for stage in result.trace.stages
    ):
        raise RuntimeError(
            "Envelope consumer lost its original raw-source repair ancestry."
        )
    if (
        evidence.source_inclusion_margin <= 0.0
        or max(evidence.source_to_repaired_upper, evidence.repaired_to_source_upper)
        > envelope.policy.maximum_deviation
        or evidence.repaired_topology.boundary_edges
        or evidence.repaired_topology.nonmanifold_edges
        or evidence.repaired_topology.degenerate_faces
        or evidence.repaired_topology.duplicate_faces
    ):
        raise RuntimeError(
            "Explicit wrapping policy or repaired topology is not certified."
        )
    if not result.associations or any(
        association.source_id != source.source_id
        or association.source_revision != source.source_revision
        for association in result.associations
    ):
        raise RuntimeError("Repaired source associations are absent or stale.")
    zones = {
        zone.name for zone in result.zones if zone.role is phx.meshing.MeshZoneRole.REGION
    }
    if zones != {"wrapped-solid"} or coverage.region_ids != ("wrapped-solid",):
        raise RuntimeError("Envelope consumer lost the authoritative repaired region.")
    mesh = result.mesh
    if (
        mesh.topological_dimension != 3
        or mesh.ambient_dimension != 3
        or any(block.cell_kind != "tetrahedron" for block in mesh.blocks)
    ):
        raise RuntimeError(
            "Envelope diffusion requires full-dimensional affine tetrahedra."
        )
    points = np.asarray(mesh.coordinates, dtype=np.float64)
    cells = np.concatenate(
        [np.asarray(block.vertices, dtype=np.int64) for block in mesh.blocks]
    )
    measures = _simplex_measures(points, cells)
    surface = envelope.repaired.mesh
    skin = np.asarray(surface.coordinates, dtype=np.float64)[
        np.asarray(surface.blocks[0].vertices, dtype=np.int64)
    ]
    reference_volume = float(
        np.sum(np.sum(skin[:, 0] * np.cross(skin[:, 1], skin[:, 2]), axis=1)) / 6.0
    )
    volume = float(np.sum(measures))
    volume_defect = volume - reference_volume
    if np.any(measures <= 0.0) or reference_volume <= 0.0 or abs(volume_defect) > 1.0e-12:
        raise RuntimeError("Envelope tetrahedra fail independent signed-volume closure.")
    return {
        "passed": True,
        "repair_evidence": asdict(evidence),
        "interpretation": "sampled_unsigned_distance_sublevel",
        "source_solid_volume": None,
        "source_solid_volume_status": "undefined-open-sheet-no-interior-inference",
        "original_source_id": evidence.source_id,
        "original_source_revision": evidence.source_revision,
        "repaired_source_id": source.source_id,
        "repaired_source_revision": source.source_revision,
        "repaired_model_id": evidence.repaired_model_id,
        "carrier_id": envelope.carrier_id,
        "policy_id": envelope.policy.policy_id,
        "feature_permission": envelope.policy.feature_permission.value,
        "topology_permission": envelope.policy.topology_permission.value,
        "maximum_deviation": envelope.policy.maximum_deviation,
        "offset": envelope.policy.offset,
        "repaired_boundary_volume": reference_volume,
        "mesh_volume": volume,
        "volume_defect": volume_defect,
        "minimum_cell_volume": float(np.min(measures)),
        "boundary_coordinates_min": np.min(skin.reshape((-1, 3)), axis=0).tolist(),
        "boundary_coordinates_max": np.max(skin.reshape((-1, 3)), axis=0).tolist(),
        "topology_comparison_semantics": "incidence-counts-not-homeomorphism",
        "embedding_id": embedding.certificate_id,
        "embedding_checks": list(embedding.evaluated_checks),
        "coverage_id": coverage.certificate_id,
        "domain_id": coverage.domain_id,
        "covered_source_facets": coverage.covered_source_facet_count,
        "source_facets": coverage.source_facet_count,
        "requested_region_measures": list(coverage.requested_region_measures),
        "achieved_region_measures": list(coverage.achieved_region_measures),
        "requested_region_measure_bounds": list(coverage.requested_region_measure_bounds),
        "achieved_region_measure_bounds": list(coverage.achieved_region_measure_bounds),
        "integration_error_bounds": list(coverage.integration_error_bounds),
        "repair_fidelity_semantics": "rigorous-two-directed-envelope-bounds",
        "repaired_domain_fidelity_semantics": "exact-represented-PLC-domain-coverage",
        "fidelity_certificate_id": (
            None if certificate.fidelity is None else certificate.fidelity.certificate_id
        ),
        "association_ids": [
            association.association_id for association in result.associations
        ],
        "quality": _quality_summary(result.quality),
        "compliance_requested": dict(result.compliance.requested),
        "compliance_achieved": dict(result.compliance.achieved),
        "soft_aim_semantics": "Native radius-edge and dihedral aims retain explicit unmet evidence.",
    }


def _envelope_qualification_prepare_solver(
    result: phx.meshing.CellMeshingResult,
) -> tuple[
    phx.discretization.FiniteElementDiscretization,
    phx.equations.CompiledFiniteElementProblem,
    jax.Array,
]:
    """Scalar H1 diffusion on the repaired domain, not the original open sheet."""
    space = phx.discretization.FiniteElementPlan(
        result.mesh,
        phx.discretization.FiniteElementFieldSpec(
            "u", phx.discretization.lagrange_element("tetrahedron", 1)
        ),
        coordinate_spec=result.geometry,
    ).prepare()
    form = phx.equations.FiniteElementForm(
        "repaired-envelope-manufactured-diffusion",
        "u",
        (
            phx.equations.DiffusionAction("u", 1.0),
            phx.equations.SourceAction(
                "u",
                phx.equations.coefficient(
                    _manufactured_source,
                    coefficient_id="repaired-domain-quadratic-laplacian",
                ),
            ),
        ),
    )
    constraint = phx.discretization.dirichlet_constraint(space, "u")
    if constraint.free_dofs.size == 0:
        raise RuntimeError(
            "Envelope manufactured solve has no interior scalar H1 degrees of freedom."
        )
    problem = phx.equations.compile_finite_element_problem(
        form, space, constraint=constraint, dirichlet_values=_manufactured_value
    )
    return space, problem, constraint.free_dofs


def _envelope_qualification_association_transfer(
    source: phx.meshing.NativeSurfaceEnvelopeSource | phx.meshing.NativePlcSource,
    result: phx.meshing.CellMeshingResult,
    limits: phx.meshing.MeshingLimits,
) -> PlcAssociationTransfer:
    """Bind exact repaired-carrier identity tables in their owning source order."""
    from phydrax.meshing._surface_envelope import surface_envelope_source_entities
    from phydrax.meshing._volume_generation import declared_plc_domain, prepare_plc_source

    if isinstance(source, phx.meshing.NativePlcSource):
        transfer = prepare_plc_source(
            source.complex,
            source.source_id,
            source.source_revision,
            result.coordinate_contract,
            limits=limits,
        ).association_transfer
    else:
        complex_ = source.plc_source.complex
        triangles, polygons, edges = surface_envelope_source_entities(source)
        transfer = PlcAssociationTransfer(
            declared_plc_domain(complex_, source.source_id),
            result.coordinate_contract,
            source.source_revision,
            edge_vertices=edges,
            triangle_vertices=triangles,
            triangle_facets=complex_.polygon_facets[polygons],
            facet_regions=complex_.facet_regions,
            maximum_support_queries=min(
                limits.maximum_geometry_queries, limits.maximum_work_units
            ),
        )
    transfer.source_associations(result)
    return transfer


def _envelope_qualification_state_transition(
    result: phx.meshing.CellMeshingResult,
    adaptation: phx.meshing.MeshAdaptationResult,
    problem: phx.equations.CompiledFiniteElementProblem,
    values: jax.Array,
    epoch: int,
    auxiliary: tuple[jax.Array, jax.Array] | None = None,
    *,
    projection_policy: phx.discretization.CommonRefinementPolicy | None = None,
) -> tuple[jax.Array, tuple[jax.Array, jax.Array], dict[str, object]]:
    """Atomically carry solved, material-density and history fields without reseeding."""
    from phydrax.lifecycle import CompositionRebind

    dimension = result.mesh.topological_dimension
    if dimension not in (2, 3):
        raise ValueError(
            "Source lifecycle field transfer requires a triangle or tetrahedron mesh."
        )
    cell_kind = "triangle" if dimension == 2 else "tetrahedron"
    fields = tuple(
        phx.discretization.FiniteElementFieldSpec(
            name, phx.discretization.lagrange_element(cell_kind, 1)
        )
        for name in ("u", "density", "history")
    )
    all_fields = phx.discretization.FiniteElementPlan(
        result.mesh, fields, coordinate_spec=result.geometry
    ).prepare()
    if auxiliary is None:
        auxiliary = (
            jnp.full((all_fields.field_spaces[1].layout.size,), 2.0, dtype=values.dtype),
            all_fields.dof_maps[2].dof_coordinates[:, 0] + 0.5,
        )
    source_fields = (values, *auxiliary)
    accepted = phx.solver.FiniteElementAcceptedState(
        source_fields,
        0.0,
        epoch,
        result.mesh.topology_id,
        all_fields.prepared_id,
        problem.compilation_id,
        state_version=epoch,
    )
    rebinds: list[CompositionRebind] = []

    def capture(rebind: CompositionRebind) -> CompositionRebind:
        rebinds.append(rebind)
        return rebind

    def certify(
        mesh: phx.discretization.CellMesh,
        fields: tuple[jax.Array, ...],
        materials: object,
        lineage: object,
        context: object,
    ) -> bool:
        del mesh, materials, lineage, context
        return all(bool(jnp.all(jnp.isfinite(value))) for value in fields)

    def impossible_error_gate(
        mesh: phx.discretization.CellMesh,
        fields: tuple[jax.Array, ...],
        materials: object,
        lineage: object,
        context: object,
    ) -> bool:
        del materials, lineage, context
        return _physical_error(mesh, fields[0]) <= 0.0

    rejected = phx.solver.FiniteElementTopologyTransaction(
        impossible_error_gate,
        fields=fields,
        projection_policy=projection_policy,
    ).execute(accepted, result.mesh, adaptation)
    if (
        bool(rejected.committed)
        or rejected.receipt is None
        or rejected.receipt.published
        or rejected.state is not accepted
        or rejected.mesh is not result.mesh
        or any(
            not np.array_equal(np.asarray(actual), np.asarray(expected))
            for actual, expected in zip(rejected.state.fields, source_fields, strict=True)
        )
    ):
        raise RuntimeError(
            "Rejected source-volume state transaction did not preserve its accepted epoch."
        )
    transaction = phx.solver.FiniteElementTopologyTransaction(
        certify,
        fields=fields,
        composition_rebind=capture,
        projection_policy=projection_policy,
    ).execute(accepted, result.mesh, adaptation)
    if (
        not bool(transaction.committed)
        or transaction.receipt is None
        or not transaction.receipt.published
        or not rebinds
        or not all(item.evidence.passed for item in transaction.transfers)
    ):
        raise RuntimeError(
            f"Source-volume solver CompositionRebind refused: {transaction.diagnostics}."
        )
    target_fields = phx.discretization.FiniteElementPlan(
        adaptation.target.mesh, fields, coordinate_spec=adaptation.target.geometry
    ).prepare()
    density_defect = float(jnp.max(jnp.abs(transaction.state.fields[1] - 2.0)))
    history_defect = float(
        jnp.max(
            jnp.abs(
                transaction.state.fields[2]
                - (target_fields.dof_maps[2].dof_coordinates[:, 0] + 0.5)
            )
        )
    )
    if density_defect > 1.0e-12 or history_defect > 1.0e-12:
        raise RuntimeError(
            "Envelope density/history transfer failed independent affine field oracles."
        )
    return (
        transaction.state.fields[0],
        (transaction.state.fields[1], transaction.state.fields[2]),
        {
            "receipt_id": transaction.receipt.receipt_id,
            "source_composition_id": rebinds[-1].source.composition_id,
            "target_composition_id": transaction.receipt.composition.composition_id,
            "transport_accepted": list(transaction.receipt.transport_accepted),
            "field_names": [field.name for field in fields],
            "density_max_defect": density_defect,
            "history_max_defect": history_defect,
            "auxiliary_seed_origin": "authored-initial-fields"
            if epoch == 0
            else "actual-carried-fields",
            "field_transfers": [
                {
                    "transfer_id": item.transfer_id,
                    "evidence_id": item.evidence.evidence_id,
                    "passed": item.evidence.passed,
                    "defects": dict(item.evidence.defects),
                    "bounds": dict(item.evidence.bounds),
                }
                for item in transaction.transfers
            ],
            "rollback": {
                "passed": True,
                "requested_l2_error": 0.0,
                "diagnostics": rejected.diagnostics,
                "receipt_id": rejected.receipt.receipt_id,
                "accepted_id": accepted.accepted_id,
                "topology_id": rejected.mesh.topology_id,
                "state_version": rejected.state.state_version,
            },
        },
    )


def _envelope_qualification_epochs(
    source: phx.meshing.NativeSurfaceEnvelopeSource | phx.meshing.NativePlcSource,
    result: phx.meshing.CellMeshingResult,
    specification: phx.meshing.VolumeMeshingSpec,
    args: argparse.Namespace,
    record: dict[str, Any],
    started: float,
    *,
    accept_result: Callable[[phx.meshing.CellMeshingResult], dict[str, object]]
    | None = None,
) -> None:
    """Continue the PDE with every accepted density/history field carried atomically."""
    if accept_result is None:
        if not isinstance(source, phx.meshing.NativeSurfaceEnvelopeSource):
            raise ValueError(
                "An extracted PLC lifecycle requires its owning source acceptance callback."
            )

        def accept_envelope(
            candidate: phx.meshing.CellMeshingResult,
        ) -> dict[str, object]:
            return _envelope_qualification_acceptance(source, candidate)

        accept_result = accept_envelope
    previous_values = None
    previous_auxiliary = None
    stages = record["stages_seconds"]
    record["active_phase"] = "source_association_transfer_preparation"
    association_transfer, measured = _measured(
        lambda: _envelope_qualification_association_transfer(
            source, result, specification.limits
        )
    )
    stages[record["active_phase"]] = measured["wall_seconds"]
    record["association_transfer"] = {
        "transfer_id": association_transfer.transfer_id,
        "domain_id": association_transfer.domain.domain_id,
        "source_revision": association_transfer.source_revision,
        "source_edges": association_transfer.edge_vertices.shape[0],
        "source_triangles": association_transfer.triangle_vertices.shape[0],
        "retained_bytes": _bisection_retained_bytes(association_transfer),
    }
    for epoch in range(args.adaptation_rounds + 1):
        record["active_phase"] = f"solver_prepare_epoch_{epoch}"
        solver, measured = _measured(
            lambda: _envelope_qualification_prepare_solver(result)
        )
        space, problem, free_dofs = solver
        stages[record["active_phase"]] = measured["wall_seconds"]
        seed = (
            jnp.zeros((free_dofs.size,), dtype=result.mesh.coordinates.dtype)
            if previous_values is None
            else jnp.asarray(previous_values)[free_dofs]
        )
        record["active_phase"] = f"solver_execution_epoch_{epoch}"
        values, compiler, timings = _compiled_solver_stages(problem, seed, args.repeats)
        stages.update({f"{key}_epoch_{epoch}": value for key, value in timings.items()})
        error = _physical_error(result.mesh, values)
        if error <= args.target_error and record["time_to_target_error_seconds"] is None:
            record["time_to_target_error_seconds"] = perf_counter() - started
        epoch_record = {
            "epoch": epoch,
            "result": _result_identity(result),
            "l2_error": error,
            "dofs": space.dof_maps[0].global_dof_count,
            "free_dofs": free_dofs.size,
            "compiler": compiler,
            "retained_bytes": _bisection_retained_bytes(
                (result, space, problem, values, previous_values)
            ),
            "seed_origin": "zero"
            if previous_values is None
            else "actual-transferred-solver-state",
            "transferred_state_l2_error": (
                None
                if previous_values is None
                else _physical_error(result.mesh, previous_values)
            ),
        }
        record["epochs"].append(epoch_record)
        if epoch == args.adaptation_rounds:
            break
        record["active_phase"] = f"adaptation_prepare_epoch_{epoch}"
        request = phx.meshing.MarkedMeshAdaptation(
            np.concatenate(
                [
                    np.asarray(block.global_ids, dtype=np.int64)
                    for block in result.mesh.blocks
                ]
            ),
            np.empty((0,), dtype=np.int64),
        )
        policy = phx.meshing.MeshAdaptationPolicy(
            phx.meshing.MeshAdaptationRoute.NATIVE_MIXED,
            limits=specification.limits,
            association_transfer=association_transfer,
            audit_policy=phx.meshing.CellMeshAuditPolicy(
                require_complete_association=True,
                watertight_boundary=phx.meshing.CellMeshAuditDisposition.REJECT,
            ),
        )
        prepared, measured = _measured(
            lambda: phx.meshing.prepare_mesh_adaptation(result, request, policy=policy)
        )
        stages[record["active_phase"]] = measured["wall_seconds"]
        record["active_phase"] = f"adaptation_execute_epoch_{epoch}"
        adaptation, measured = _measured(
            lambda: phx.meshing.execute_mesh_adaptation(prepared)
        )
        stages[record["active_phase"]] = measured["wall_seconds"]
        if not adaptation.status.converged or adaptation.transition is None:
            raise RuntimeError(
                f"Positive source-volume adaptation did not complete: {adaptation.status.value}."
            )
        record["active_phase"] = f"solver_state_transfer_epoch_{epoch}"
        transition, measured = _measured(
            lambda: _envelope_qualification_state_transition(
                result, adaptation, problem, values, epoch, previous_auxiliary
            )
        )
        previous_values, previous_auxiliary, transfer = transition
        stages[record["active_phase"]] = measured["wall_seconds"]
        before = _bisection_p1_integral(adaptation.source.mesh, values)
        after = _bisection_p1_integral(adaptation.target.mesh, previous_values)
        if abs(after - before) > 1.0e-10 * max(1.0, abs(before)):
            raise RuntimeError(
                "Actual envelope solver-state P1 inventory changed in transfer."
            )
        epoch_record.update(
            {
                "transfer": transfer,
                "lineage": _bisection_lineage(adaptation),
                "state_inventory": {
                    "source": before,
                    "target": after,
                    "defect": after - before,
                },
                "adaptation_retained_bytes": _bisection_retained_bytes(adaptation),
            }
        )
        result = adaptation.target
        record["active_phase"] = f"independent_acceptance_epoch_{epoch + 1}"
        acceptance, measured = _measured(lambda: accept_result(result))
        stages[record["active_phase"]] = measured["wall_seconds"]
        epoch_record["target_acceptance"] = acceptance
    if isinstance(source, phx.meshing.NativeSurfaceEnvelopeSource):
        if previous_auxiliary is None:
            raise RuntimeError(
                "Envelope checkpoint requires its actually carried density/history fields."
            )
        _envelope_qualification_cold_reanalysis(
            source,
            result,
            specification,
            values,
            previous_auxiliary,
            args,
            record,
            started,
        )


def _envelope_qualification_cold_worker(
    path: str,
    content_id: str,
    expected: tuple[str, str, str, str],
    repeats: int,
    target_error: float,
) -> dict[str, object]:
    """Fresh-process source certification and continued solve from archived fields."""
    from phydrax._array_archive import ArrayArchiveLimits
    from phydrax._fingerprint import array_tree_fingerprint
    from phydrax.lifecycle._meshing_sources import read_meshing_source_closure

    restored = read_meshing_source_closure(
        Path(path), expected_content_id=content_id, limits=ArrayArchiveLimits()
    )
    source, result, specification, fields = (
        restored[name] for name in ("source", "result", "specification", "fields")
    )
    if (
        not isinstance(source, phx.meshing.NativeSurfaceEnvelopeSource)
        or not isinstance(result, phx.meshing.CellMeshingResult)
        or not isinstance(specification, phx.meshing.VolumeMeshingSpec)
        or not isinstance(fields, tuple)
        or len(fields) != 3
        or (
            source.binding_id,
            result.result_id,
            specification.specification_id,
            array_tree_fingerprint(fields),
        )
        != expected
    ):
        raise RuntimeError(
            "Cold envelope archive changed original source, controls or accepted fields."
        )
    acceptance = _envelope_qualification_acceptance(source, result)
    space, problem, free = _envelope_qualification_prepare_solver(result)
    values, compiler, timings = _compiled_solver_stages(
        problem, jnp.asarray(fields[0])[free], repeats
    )
    error = _physical_error(result.mesh, values)
    density_defect = float(jnp.max(jnp.abs(fields[1] - 2.0)))
    history_defect = float(
        jnp.max(jnp.abs(fields[2] - (space.dof_maps[0].dof_coordinates[:, 0] + 0.5)))
    )
    if error > target_error or density_defect > 1.0e-12 or history_defect > 1.0e-12:
        raise RuntimeError(
            "Cold envelope continued PDE or restored density/history oracle failed."
        )
    return {
        "passed": True,
        "process_id": os.getpid(),
        "runtime": _runtime_identity(),
        "source_acceptance": acceptance,
        "restored_result": _result_identity(result),
        "field_names": ["u", "density", "history"],
        "accepted_fields_bitwise_preserved": True,
        "prepared_fe_caches_serialized": False,
        "continued_physical_L2_error": error,
        "density_max_defect": density_defect,
        "history_max_defect": history_defect,
        "compiler": compiler,
        "solver_seconds": timings,
    }


def _envelope_qualification_cold_reanalysis(
    source: phx.meshing.NativeSurfaceEnvelopeSource,
    result: phx.meshing.CellMeshingResult,
    specification: phx.meshing.VolumeMeshingSpec,
    values: jax.Array,
    auxiliary: tuple[jax.Array, jax.Array],
    args: argparse.Namespace,
    record: dict[str, Any],
    started: float,
) -> None:
    import subprocess

    from phydrax._array_archive import ArrayArchiveLimits
    from phydrax._fingerprint import array_tree_fingerprint
    from phydrax.lifecycle._meshing_sources import write_meshing_source_closure

    limits = ArrayArchiveLimits()
    fields = (values, *auxiliary)
    records = {
        "source": source,
        "result": result,
        "specification": specification,
        "fields": fields,
    }
    with TemporaryDirectory(prefix="phydrax-native-envelope-source-") as directory:
        record["active_phase"] = "allfield_history_checkpoint_publication"
        receipt, timing = _measured(
            lambda: write_meshing_source_closure(
                Path(directory) / "envelope.checkpoint.zip", records, limits=limits
            )
        )
        record["stages_seconds"][record["active_phase"]] = timing["wall_seconds"]
        expected = (
            source.binding_id,
            result.result_id,
            specification.specification_id,
            array_tree_fingerprint(fields),
        )
        code = (
            "import json,sys; from tools.meshing_qualification import "
            "_envelope_qualification_cold_worker; "
            "print(json.dumps(_envelope_qualification_cold_worker("
            "sys.argv[1],sys.argv[2],tuple(json.loads(sys.argv[3])),"
            "int(sys.argv[4]),float(sys.argv[5]))))"
        )
        remaining = args.timeout - (perf_counter() - started)
        if remaining <= 0.0:
            raise phx.meshing.MeshingFailure(
                phx.meshing.MeshingFailureCategory.TIMED_OUT,
                "Original envelope wall allowance expired before cold continued solve.",
                stage=phx.meshing.MeshingStageKind.CERTIFICATION.value,
            )
        record["active_phase"] = "fresh_process_source_allfield_history_continued_PDE"
        try:
            completed, timing = _measured(
                lambda: subprocess.run(
                    [
                        sys.executable,
                        "-c",
                        code,
                        str(receipt.path),
                        receipt.content_id,
                        json.dumps(expected),
                        str(args.repeats),
                        str(args.target_error),
                    ],
                    capture_output=True,
                    text=True,
                    timeout=remaining,
                    check=False,
                )
            )
        except subprocess.TimeoutExpired as error:
            raise phx.meshing.MeshingFailure(
                phx.meshing.MeshingFailureCategory.TIMED_OUT,
                "Cold envelope process exhausted the original wall allowance.",
                stage=phx.meshing.MeshingStageKind.CERTIFICATION.value,
                requested=(("remaining_wall_seconds", remaining),),
            ) from error
        record["stages_seconds"][record["active_phase"]] = timing["wall_seconds"]
        if completed.returncode:
            record["cold_process_refusal"] = {
                "returncode": completed.returncode,
                "stdout": completed.stdout,
                "stderr": completed.stderr,
            }
            raise RuntimeError(
                f"Cold envelope child refused ({completed.returncode}): {completed.stderr}"
            )
        cold = json.loads(completed.stdout)
        if (
            not isinstance(cold, dict)
            or cold.get("passed") is not True
            or cold.get("process_id") == os.getpid()
        ):
            raise RuntimeError(
                "Envelope cold certificate did not originate in an independent process."
            )
        record["checkpoint"] = {
            **cold,
            "content_id": receipt.content_id,
            "container_bytes": receipt.path.stat().st_size,
            "archive_limits": {
                "members": limits.max_members,
                "nesting": limits.max_manifest_nesting,
                "rank": limits.max_array_rank,
            },
            "source_authority_stripped": False,
        }


def _reconstruction_qualification_source(
    resolution: int,
    capacity: int,
) -> tuple[
    phx.geometry.ReconstructedGeometrySource, phx.meshing.NativePlcSource, np.ndarray
]:
    """Reconstruct the actual noisy, nonspherical cloud with native numerical owners."""
    from dataclasses import asdict

    from phydrax._fingerprint import array_tree_fingerprint

    count = 8 * resolution * resolution
    index = np.arange(count, dtype=np.float64) + 0.5
    z = 1.0 - 2.0 * index / count
    angle = np.pi * (3.0 - np.sqrt(5.0)) * index
    radial = np.sqrt(1.0 - z * z)
    direction = np.stack((radial * np.cos(angle), radial * np.sin(angle), z), axis=1)
    radius = 0.2 * (1.0 + 0.04 * np.sin(3.0 * angle) * radial * radial)
    noise = np.random.default_rng(1709).normal(0.0, 0.0008, size=direction.shape)
    points = (
        direction * radius[:, None]
        + noise
        + np.asarray((0.07, -0.03, 0.02), dtype=np.float64)
    )
    reconstructed = phx.geometry.reconstruct_surface_region(
        points,
        recenter=False,
        sample_spacing=0.44 / resolution,
        maximum_grid_nodes=5 * capacity,
        discretization="octree",
        robustness=phx.geometry.ReconstructionRobustness(
            incomplete_sampling="refuse",
            coverage_distance=0.44 / resolution,
            thin_feature_distance=0.22 / resolution,
        ),
        feature_id="qualification-native-reconstructed-samples",
    )
    child = reconstructed.source
    if not isinstance(child, phx.geometry.MeshRegion):
        raise TypeError(
            "Native volume reconstruction must publish an actual closed MeshRegion."
        )
    vertices = np.asarray(child.vertices, dtype=np.float64)
    faces = np.asarray(child.faces, dtype=np.int64)
    revision = canonical_fingerprint(
        {
            "kind": "native-reconstructed-plc-source",
            "report": asdict(reconstructed.report),
            "vertices": array_tree_fingerprint(vertices),
            "triangles": array_tree_fingerprint(faces),
        }
    )
    complex_ = phx.meshing.PiecewiseLinearComplex(
        vertices,
        tuple(faces),
        np.arange(faces.shape[0], dtype=np.int64),
        np.tile(np.asarray((-1, 0), dtype=np.int64), (faces.shape[0], 1)),
        ("reconstructed-solid",),
        boundary="conforming",
    )
    return (
        reconstructed,
        phx.meshing.NativePlcSource(complex_, child.feature_id, revision),
        points,
    )


def _reconstruction_qualification_request(
    source: phx.meshing.NativePlcSource,
    capacity: int,
    timeout: float,
) -> tuple[phx.meshing.VolumeMeshingSpec, phx.meshing.NativeMeshingOptions]:
    """Freeze the original envelope profile on the actual extracted PLC."""
    from phydrax.meshing._volume_generation import NativeVolumeSchedule

    scope = phx.meshing.MeshingScope(
        source.source_id,
        source.source_revision,
        phx.meshing.MeshingEntityKind.GEOMETRY,
        2,
        "reconstructed-facets",
        np.arange(source.complex.facet_count, dtype=np.int64),
    )
    specification = phx.meshing.VolumeMeshingSpec(
        phx.meshing.CellMeshingTarget(
            3, 3, phx.meshing.CellFamilyPolicy(required=("tetrahedron",))
        ),
        scope,
        phx.meshing.VolumeFillStrategy.SIMPLEX,
        size_controls=(
            phx.meshing.UniformSizeControl(
                scope, 2.0, strength=phx.meshing.SizeControlStrength.SOFT
            ),
        ),
        limits=phx.meshing.MeshingLimits(
            maximum_vertices=capacity,
            maximum_cells=5 * capacity,
            maximum_work_units=1000 * capacity,
            maximum_wall_seconds=timeout,
        ),
    )
    return specification, phx.meshing.NativeMeshingOptions(
        "plc_tetrahedral",
        volume_schedule=NativeVolumeSchedule(
            refinement_rounds=1, improvement_passes=1, minimum_dihedral_degrees=0.0
        ),
    )


def _reconstruction_qualification_acceptance(
    reconstructed: phx.geometry.ReconstructedGeometrySource,
    source: phx.meshing.NativePlcSource,
    points: np.ndarray,
    result: phx.meshing.CellMeshingResult,
) -> dict[str, object]:
    """Separate sampled reconstruction evidence from exact extracted-domain fidelity."""
    from dataclasses import asdict

    from phydrax.geometry.reconstruction._core import _point_digest
    from phydrax.geometry.simplicial._bvh import TriangleBVH
    from phydrax.geometry.simplicial._mesh import TriangleMesh
    from phydrax.meshing._volume_generation import declared_plc_domain

    report = reconstructed.report
    if report.input_digest != _point_digest(points):
        raise RuntimeError("Reconstruction report binds a different actual sample cloud.")
    if (
        not report.watertight
        or not report.winding_consistent
        or report.poisson_evidence is None
        or not report.poisson_evidence.solver_converged
        or report.component_evidence is None
        or report.component_evidence.unresolved_components
        or report.coverage_evidence is None
        or report.coverage_evidence.unsupported_triangles
        or report.deviation_evidence is None
        or report.input_points != points.shape[0]
    ):
        raise RuntimeError(
            "Reconstructed source lacks accepted native topology, solve, or sampling evidence."
        )
    certificate = result.certification
    if (
        certificate is None
        or not certificate.passed
        or not result.audit.passed
        or not result.compliance.passed
    ):
        raise RuntimeError("Reconstructed volume requires strict native acceptance.")
    domain = declared_plc_domain(source.complex, source.source_id)
    coverage, embedding, fidelity = (
        certificate.coverage,
        certificate.embedding,
        certificate.fidelity,
    )
    if (
        coverage is None
        or embedding is None
        or coverage.status != "certified"
        or embedding.status != "certified"
        or certificate.request.domain is None
        or certificate.request.domain.domain_id != domain.domain_id
        or coverage.covered_source_facet_count != coverage.source_facet_count
        or coverage.region_ids != ("reconstructed-solid",)
        or {zone.name for zone in result.zones} != {"reconstructed-solid"}
    ):
        raise RuntimeError(
            "Native fill lost exact reconstructed source-domain coverage or region identity."
        )
    faces = np.asarray(source.complex.polygon_vertices, dtype=np.int64).reshape((-1, 3))
    skin = source.complex.vertices[faces]
    surface_volume = float(np.sum(skin[:, 0] * np.cross(skin[:, 1], skin[:, 2])) / 6.0)
    mesh_points = np.asarray(result.mesh.coordinates, dtype=np.float64)
    cells = np.concatenate(
        [np.asarray(block.vertices, dtype=np.int64) for block in result.mesh.blocks]
    )
    volumes = _simplex_measures(mesh_points, cells)
    volume = float(np.sum(volumes))
    if (
        np.any(volumes <= 0.0)
        or surface_volume <= 0.0
        or abs(volume - surface_volume) > 1.0e-12
    ):
        raise RuntimeError(
            "Native reconstructed fill fails independent signed-volume closure."
        )
    sample_distance = np.asarray(
        TriangleBVH(TriangleMesh(source.complex.vertices, faces)).query(points).distance,
        dtype=np.float64,
    )
    vertex_distance = np.min(
        np.linalg.norm(source.complex.vertices[:, None, :] - points[None, :, :], axis=-1),
        axis=1,
    )
    deviation = report.deviation_evidence
    if (
        abs(float(np.max(sample_distance)) - deviation.sample_to_surface_max) > 1.0e-12
        or abs(float(np.max(vertex_distance)) - deviation.surface_to_sample_max) > 1.0e-12
    ):
        raise RuntimeError(
            "Reconstruction report disagrees with independent actual-cloud distance queries."
        )
    return {
        "passed": True,
        "source_id": source.source_id,
        "source_revision": source.source_revision,
        "input_digest": report.input_digest,
        "reconstruction_report": asdict(report),
        "source_domain_id": domain.domain_id,
        "embedding_status": embedding.status,
        "coverage_status": coverage.status,
        "fidelity_status": "exact-domain-coverage",
        "coverage_certificate_id": coverage.certificate_id,
        "additional_fidelity_certificate_id": None
        if fidelity is None
        else fidelity.certificate_id,
        "source_boundary_volume": surface_volume,
        "mesh_volume": volume,
        "volume_defect": volume - surface_volume,
        "minimum_cell_volume": float(np.min(volumes)),
        "sample_to_surface_max": float(np.max(sample_distance)),
        "surface_vertex_to_sample_max": float(np.max(vertex_distance)),
        "reconstruction_fidelity_semantics": "sampled-two-sided-deviation-not-continuous-Hausdorff",
        "volume_fidelity_semantics": "exact-represented-extracted-PLC-domain",
    }


def _reconstruction_qualification_lifecycle(
    args: argparse.Namespace,
) -> dict[str, object]:
    """Actual sampled reconstruction → native volume → transferred solver lifecycle."""
    from dataclasses import asdict

    from phydrax.geometry.reconstruction import ReconstructionFailure

    if (
        args.resolution < 4
        or args.capacity < 1
        or args.repeats < 1
        or args.adaptation_rounds < 1
        or not np.isfinite(args.timeout)
        or args.timeout <= 0.0
        or not np.isfinite(args.target_error)
        or args.target_error <= 0.0
    ):
        raise ValueError(
            "Reconstruction requires resolution >= 4, positive controls, and transfer rounds >= 1."
        )
    started = perf_counter()
    phases: list[NativeMeshingPhaseMeasurement] = []
    record: dict[str, Any] = {
        "scenario": "native-reconstruction-lifecycle",
        "engine": "native",
        "status": "failed",
        "runtime": _runtime_identity(),
        "expected_admission": "positive",
        "targets": {"l2_error": args.target_error, "wall_seconds": args.timeout},
        "control_capacities": {
            "resolution": args.resolution,
            "entity_capacity": args.capacity,
            "adaptation_rounds": args.adaptation_rounds,
            "warm_repeats": args.repeats,
        },
        "epochs": [],
        "stages_seconds": {},
        "time_to_target_error_seconds": None,
        "mandatory_workflow_completion": "incomplete",
        "active_phase": "native_reconstruction",
        "nonclaims": [
            "Sampled reconstruction bounds are not continuous Hausdorff certificates.",
            "No analytic surface replaces the actual reconstructed triangles.",
            "This routine case does not close underspecified reconstruction or the mandatory corpus.",
        ],
    }
    stages = record["stages_seconds"]
    try:
        fixture, measured = _measured(
            lambda: _reconstruction_qualification_source(args.resolution, args.capacity)
        )
        reconstructed, source, points = fixture
        stages[record["active_phase"]] = measured["wall_seconds"]
        record["reconstruction"] = asdict(reconstructed.report)
        record["source_binding_id"] = source.binding_id
        record["active_phase"] = "reconstructed_request_preparation"
        specification, options = _reconstruction_qualification_request(
            source, args.capacity, args.timeout
        )
        record["request_id"] = specification.specification_id
        record["native_options_id"] = options.options_id
        record["active_phase"] = "geometry_constraint_preparation"
        plan, measured = _measured(
            lambda: phx.meshing.NativeMeshingProvider(options).plan(
                source,
                specification,
                coordinate_contract=phx.SpatialCoordinateContract.si(),
                record_phase=phases.append,
            )
        )
        stages[record["active_phase"]] = measured["wall_seconds"]
        record["active_phase"] = "generation_publication_certification"
        result, measured = _measured(lambda: plan.execute(record_phase=phases.append))
        stages[record["active_phase"]] = measured["wall_seconds"]
        record["generation"] = _result_identity(result)

        def accept_result(candidate: phx.meshing.CellMeshingResult) -> dict[str, object]:
            return _reconstruction_qualification_acceptance(
                reconstructed, source, points, candidate
            )

        record["active_phase"] = "independent_acceptance"
        record["independent_acceptance"] = accept_result(result)
        _envelope_qualification_epochs(
            source,
            result,
            specification,
            args,
            record,
            started,
            accept_result=accept_result,
        )
        final_error = record["epochs"][-1]["l2_error"]
        record.update(
            {
                "status": "passed" if final_error <= args.target_error else "failed",
                "physical_error": final_error,
                "target_error_reached": final_error <= args.target_error,
                "implemented_admitted_workflow": "native-reconstruction-volume-CompositionRebind-scalar-solve",
            }
        )
    except ReconstructionFailure as failure:
        record.update(
            {
                "failure_phase": record["active_phase"],
                "failure": str(failure),
                "failure_type": type(failure).__name__,
                "reconstruction": asdict(failure.report),
            }
        )
    except phx.meshing.MeshingFailure as failure:
        record.update(
            {
                "failure_phase": record["active_phase"],
                "failure": str(failure),
                "failure_category": failure.category.value,
                "failure_evidence_id": failure.evidence.evidence_id,
                "native_stage": failure.evidence.stage,
                "requested": dict(failure.evidence.requested),
                "achieved": dict(failure.evidence.achieved),
            }
        )
    except (RuntimeError, ValueError, TypeError) as failure:
        record.update(
            {
                "failure_phase": record["active_phase"],
                "failure": str(failure),
                "failure_type": type(failure).__name__,
            }
        )
    finally:
        record["native_phases"] = _phase_recordings(phases)
        record["end_to_end_seconds"] = perf_counter() - started
        if record["end_to_end_seconds"] > args.timeout:
            record["status"] = "timeout"
        record["peak_process_resident_bytes"] = resource.getrusage(
            resource.RUSAGE_SELF
        ).ru_maxrss * (1 if sys.platform == "darwin" else 1024)
        record["process_peak_scope"] = "process-lifetime"
        record.pop("active_phase")
    return record


def _envelope_qualification_lifecycle(args: argparse.Namespace) -> dict[str, object]:
    """Bounded native repair → strict volume → actual transferred-state diffusion."""
    from dataclasses import asdict

    if (
        args.resolution < 4
        or args.capacity < 1
        or args.repeats < 1
        or args.adaptation_rounds < 1
        or not np.isfinite(args.timeout)
        or args.timeout <= 0.0
        or not np.isfinite(args.target_error)
        or args.target_error <= 0.0
    ):
        raise ValueError(
            "Envelope requires resolution >= 4, positive capacities/repeats/targets, and transfer rounds >= 1."
        )
    started = perf_counter()
    phases: list[NativeMeshingPhaseMeasurement] = []
    record: dict[str, Any] = {
        "scenario": "native-envelope-lifecycle",
        "engine": "native",
        "status": "failed",
        "runtime": _runtime_identity(),
        "expected_admission": "positive",
        "adaptation_engine": "native-mixed-family-preserving-templates",
        "targets": {"l2_error": args.target_error, "wall_seconds": args.timeout},
        "control_capacities": {
            "resolution": args.resolution,
            "entity_capacity": args.capacity,
            "adaptation_rounds": args.adaptation_rounds,
            "warm_repeats": args.repeats,
        },
        "epochs": [],
        "stages_seconds": {},
        "time_to_target_error_seconds": None,
        "mandatory_workflow_completion": "incomplete",
        "release_evidence": "unassessed",
        "leadership_evidence": "unassessed",
        "active_phase": "source_preparation",
        "manufactured_solution": {
            "exact": "|x|^2",
            "forcing": -6.0,
            "diffusion": 1.0,
            "norm": "independent-exact-P1-quadratic-L2",
            "domain": "repaired-envelope-volume",
        },
        "nonclaims": [
            "No intended dirty-shell interior is inferred.",
            "Topology-change permission is not a homeomorphism theorem.",
            "This routine case is not the full mandatory W15 corpus.",
            "No release or performance leadership follows from this case.",
        ],
    }
    stages = record["stages_seconds"]
    try:
        fixture, measured = _measured(
            lambda: _envelope_qualification_fixture(args.resolution, args.capacity)
        )
        soup, policy, record["case"] = fixture
        stages["source_preparation"] = measured["wall_seconds"]
        record["active_phase"] = "native_envelope_construction"
        envelope, source, specification, options, source_receipt = (
            _envelope_qualification_prepare_source(soup, policy, args, phases, record)
        )
        record["repair"] = {
            "envelope_id": envelope.envelope_id,
            "carrier_id": envelope.carrier_id,
            "evidence": asdict(envelope.evidence),
            "original_source_geometry_id": soup.soup_id,
            "repaired_model_id": envelope.repaired.model.model_id,
            "interpretation": "sampled_unsigned_distance_sublevel",
            "offset": policy.offset,
            "maximum_deviation": policy.maximum_deviation,
            "spacing": policy.spacing,
            "certificate_spacing": policy.certificate_spacing,
            "feature_permission": policy.feature_permission.value,
            "topology_permission": policy.topology_permission.value,
            "topology_comparison_semantics": "incidence-counts-not-homeomorphism",
        }
        record.update(
            {
                "source_binding_id": source.binding_id,
                "request_id": specification.specification_id,
                "limits_id": specification.limits.limits_id,
                "native_options_id": options.options_id,
            }
        )
        provider = phx.meshing.NativeMeshingProvider(options)
        record["active_phase"] = "geometry_constraint_preparation"
        plan, measured = _measured(
            lambda: provider.plan(
                source,
                specification,
                coordinate_contract=phx.SpatialCoordinateContract.si(),
                record_phase=phases.append,
                source_preparation_evidence=source_receipt,
            )
        )
        stages["geometry_constraint_preparation"] = measured["wall_seconds"]
        record["prepared_id"] = plan.plan_id
        record["active_phase"] = "generation_publication_certification"
        result, measured = _measured(lambda: plan.execute(record_phase=phases.append))
        stages["generation_publication_certification"] = measured["wall_seconds"]
        record["generation"] = _result_identity(result)
        record["active_phase"] = "independent_acceptance"
        acceptance, measured = _measured(
            lambda: _envelope_qualification_acceptance(source, result)
        )
        stages["independent_acceptance"] = measured["wall_seconds"]
        record["independent_acceptance"] = acceptance
        _envelope_qualification_epochs(
            source, result, specification, args, record, started
        )
        elapsed = perf_counter() - started
        final_error = record["epochs"][-1]["l2_error"]
        record.update(
            {
                "status": (
                    "timeout"
                    if elapsed > args.timeout
                    else "passed"
                    if final_error <= args.target_error
                    else "failed"
                ),
                "physical_error": final_error,
                "target_error_reached": final_error <= args.target_error,
                "independent_scientific_certification": "passed",
                "mandatory_workflow_completion": (
                    "complete"
                    if elapsed <= args.timeout and final_error <= args.target_error
                    else "incomplete"
                ),
                "implemented_admitted_workflow": "repaired-envelope-allfield-history-transfer-continued-PDE-cold",
            }
        )
    except phx.meshing.MeshingFailure as failure:
        evidence = failure.evidence
        record.update(
            {
                "failure_phase": record["active_phase"],
                "failure": str(failure),
                "failure_category": failure.category.value,
                "failure_evidence_id": evidence.evidence_id,
                "native_stage": evidence.stage,
                "provider_code": evidence.provider_code,
                "failing_entities": list(evidence.entity_ids),
                "requested": dict(evidence.requested),
                "achieved": dict(evidence.achieved),
                "locations": list(evidence.locations),
                "checkpoint_id": evidence.checkpoint_id,
            }
        )
    except (RuntimeError, ValueError, TypeError) as failure:
        record.update(
            {
                "failure_phase": record["active_phase"],
                "failure": str(failure),
                "failure_type": type(failure).__name__,
            }
        )
        if (
            record["active_phase"].startswith("adaptation_")
            or record["active_phase"] == "source_association_transfer_preparation"
        ):
            record["positive_prerequisite"] = (
                "The exact repaired-PLC source binding and canonical lineage transfer "
                "must satisfy the requested association/domain contract without source stripping."
            )
    finally:
        record["native_phases"] = _phase_recordings(phases)
        record["end_to_end_seconds"] = perf_counter() - started
        record["peak_process_resident_bytes"] = resource.getrusage(
            resource.RUSAGE_SELF
        ).ru_maxrss * (1 if sys.platform == "darwin" else 1024)
        record["process_peak_scope"] = "process-lifetime"
        record["device_memory"] = [
            {
                "device_id": device.id,
                "platform": device.platform,
                "device_kind": device.device_kind,
                "status": "unavailable" if statistics is None else "backend-reported",
                "peak_bytes": None
                if statistics is None
                else statistics.get("peak_bytes_in_use"),
                "memory_statistics": statistics,
            }
            for device in jax.local_devices()
            for statistics in (device.memory_stats(),)
        ]
        record.pop("active_phase")
    return record


def _cad_qualification_requirements() -> dict[str, object]:
    """Parser and evidence contract; this does not register or execute a case."""
    return {
        "required_arguments": {
            "cad_format": {"choices": ["step", "iges", "brep"]},
            "resolution": {"minimum": 1},
            "capacity": {"minimum": 1},
            "timeout": {"exclusive_minimum": 0.0, "finite": True},
            "repeats": {"minimum": 1},
            "target_error": {"exclusive_minimum": 0.0, "finite": True},
            "adaptation_rounds": {"minimum": 1},
        },
        "callable": "_cad_qualification_lifecycle",
        "fixture": "native-authored-exact-box-format-roundtrip-and-intersection",
        "evidence_sections": [
            "imports",
            "boolean",
            "query",
            "source",
            "request",
            "native_phases",
            "stages_seconds",
            "epochs",
            "physical_error",
            "time_to_target_error_seconds",
            "peak_process_resident_bytes",
            "device_memory",
            "positive_prerequisite",
        ],
        "registration": "requires-parent-observed-positive-source-transfer-solver-evidence",
        "mandatory_workflow_completion": "incomplete",
        "nonclaims": [
            "Generated format files are not an independently authored external CAD corpus.",
            "The full curved/multiformat/partition/high-order combination remains incomplete.",
            "No optional external engine is a native fallback or a scientific reference.",
        ],
    }


def _cad_qualification_import(
    directory: Path,
    format_name: str,
    capacity: int,
    stages: dict[str, float],
) -> tuple[phx.geometry.brep.BRepModel, phx.geometry.brep.BRepModel, dict[str, object]]:
    """Construct licensed analytic operands, write actual bytes, then bounded decode."""
    fixture = load_cad_fixture()
    raw_operands = fixture["operands"]
    if not isinstance(raw_operands, list):
        raise TypeError("CAD source record operands must be a list.")
    source_operands: list[tuple[str, tuple[float, ...], tuple[float, ...]]] = []
    for operand in raw_operands:
        if not isinstance(operand, dict):
            raise TypeError("Each CAD source operand must be a record.")
        name, lower, upper = (
            operand.get("name"),
            operand.get("lower"),
            operand.get("upper"),
        )
        if (
            not isinstance(name, str)
            or not isinstance(lower, list)
            or not isinstance(upper, list)
            or len(lower) != 3
            or len(upper) != 3
            or any(
                not isinstance(value, (int, float)) or isinstance(value, bool)
                for value in (*lower, *upper)
            )
        ):
            raise ValueError(
                "CAD source operands require named three-dimensional numeric bounds."
            )
        source_operands.append(
            (
                name,
                tuple(float(value) for value in lower),
                tuple(float(value) for value in upper),
            )
        )
    contract = phx.SpatialCoordinateContract.si()
    byte_capacity = 4096 * capacity
    import_policy = phx.interchange.CadImportPolicy(
        contract,
        phx.interchange.ResourceLimits(
            max_bytes=byte_capacity,
            max_depth=64,
            max_nodes=64 * capacity,
            max_attributes=512 * capacity,
            max_losses=0,
        ),
        maximum_occurrences=capacity,
        pcurve_fit=None,
    )
    export_policy = phx.interchange.CadExportPolicy(
        maximum_bytes=byte_capacity, maximum_entities=64 * capacity
    )
    match format_name:
        case "step":
            writer, suffix = phx.interchange.write_step, ".step"
        case "iges":
            writer, suffix = phx.interchange.write_iges, ".iges"
        case "brep":
            writer, suffix = phx.interchange.write_brep_text, ".brep"
        case _:
            raise ValueError("cad_format must be step, iges or brep.")
    operands = []
    imports = []
    for name, lower, upper in source_operands:
        model, timing = _measured(
            lambda: phx.geometry.brep.brep_box(lower, upper, coordinate_contract=contract)
        )
        stages[f"source_construction_{name}"] = timing["wall_seconds"]
        path = directory / f"{name}{suffix}"
        exported, timing = _measured(lambda: writer(model, path, policy=export_policy))
        stages[f"format_encode_{name}"] = timing["wall_seconds"]
        if exported.approximations:
            raise RuntimeError(
                "The routine planar CAD fixture requires exact format export."
            )
        imported, timing = _measured(
            lambda: phx.interchange.read_cad(
                path,
                import_policy,
                trusted_root=directory,
                source_length_unit=contract.length_unit
                if format_name == "brep"
                else None,
            )
        )
        stages[f"format_decode_{name}"] = timing["wall_seconds"]
        if imported.coverage.pcurves_fitted or imported.model.geometry is None:
            raise RuntimeError(
                "The native CAD consumer requires exact carriers and p-curves."
            )
        operands.append(imported.model)
        imports.append(
            {
                "operand": name,
                "format": imported.format,
                "schema": imported.schema,
                "source_digest": imported.source_digest,
                "import_id": imported.result_id,
                "model_id": imported.model.model_id,
                "source_id": imported.model.source_id,
                "source_revision": imported.model.source_revision,
                "import_policy_id": import_policy.policy_id,
                "export_policy_id": export_policy.policy_id,
                "report_id": imported.report.report_id,
                "entity_counts": dict(imported.coverage.entity_counts),
                "pcurves_honored": imported.coverage.pcurves_honored,
                "pcurves_exact": imported.coverage.pcurves_exact,
                "pcurves_fitted": imported.coverage.pcurves_fitted,
                "source_length_unit_meters": imported.source_length_unit_meters,
                "provenance": dict(imported.provenance),
            }
        )
    reference = fixture["independent_reference"]
    if not isinstance(reference, dict):
        raise TypeError("CAD fixture independent reference must be a record.")
    return (
        operands[0],
        operands[1],
        {
            "operands": imports,
            "source_record": fixture,
            "source_record_id": fixture["record_id"],
            "provenance": fixture["provenance"],
            "license": fixture["license"],
            "reference_bounds": [[0.25, 0.0, 1.0], [0.75, 1.0, 1.0]],
            "reference_area": reference["selected_top_area"],
            "reference_solid_volume": reference["intersection_volume"],
            "independent_reference": reference,
        },
    )


def _cad_qualification_source(
    model: phx.geometry.brep.BRepModel,
    resolution: int,
    capacity: int,
    timeout: float,
) -> tuple[
    phx.meshing.NativeSurfaceSource,
    phx.meshing.SurfaceMeshingSpec,
    phx.meshing.NativeMeshingOptions,
    tuple[int, ...],
]:
    """Select a planar face by exact topology; retain the entire CAD authority."""
    geometry = model.geometry
    if geometry is None:
        raise ValueError("The Boolean result has no authoritative exact B-Rep geometry.")
    vertices = np.asarray(geometry.vertex_points, dtype=np.float64)
    selected = []
    for face, loops in enumerate(geometry.face_loops):
        members = np.unique(
            [
                vertex
                for loop in loops
                for coedge in loop
                for vertex in geometry.edge_vertices[geometry.coedge_edges[coedge]]
            ]
        )
        if np.all(np.abs(vertices[members, 2] - 1.0) <= 1.0e-12):
            selected.append(face)
    if not selected:
        raise RuntimeError("The exact Boolean rectangle has no top planar face.")
    domain = phx.geometry.MeshingDomain.from_brep(model)
    patches = tuple(
        local
        for local, source_index in enumerate(domain.source_indices[2])
        if source_index in selected
    )
    if not patches or domain.authority_id != model.model_id:
        raise RuntimeError("The surface bridge did not retain the Boolean CAD authority.")
    source = phx.meshing.NativeSurfaceSource(domain)
    scope = phx.meshing.MeshingScope(
        source.source_id,
        source.source_revision,
        phx.meshing.MeshingEntityKind.GEOMETRY,
        2,
        domain.entity_set_id(2),
        np.asarray(domain.scope_indices(2), dtype=np.int64)[list(patches)],
    )
    size = 0.5 / resolution
    limits = phx.meshing.MeshingLimits(
        maximum_vertices=capacity,
        maximum_cells=8 * capacity,
        maximum_edges=8 * capacity,
        maximum_faces=8 * capacity,
        maximum_connectivity_entries=64 * capacity,
        maximum_data_bytes=1024 * capacity,
        maximum_work_units=32 * capacity,
        maximum_cavity_cells=capacity,
        maximum_geometry_queries=64 * capacity,
        maximum_scratch_bytes=4096 * capacity,
        maximum_wall_seconds=timeout,
    )
    request = phx.meshing.SurfaceMeshingSpec(
        phx.meshing.CellMeshingTarget(
            2, 3, phx.meshing.CellFamilyPolicy(required=("triangle",))
        ),
        scope,
        size_controls=(
            phx.meshing.UniformSizeControl(
                scope,
                size,
                maximum_size=1.5 * size,
                strength=phx.meshing.SizeControlStrength.HARD,
            ),
        ),
        size_compliance=phx.meshing.SizeCompliancePolicy(
            relative_tolerance=0.5, target_statistics=("p50",)
        ),
        protected_features=(
            phx.meshing.ProtectedFeature(
                scope, phx.meshing.FeatureKind.SURFACE, maximum_deviation=1.0e-8
            ),
        ),
        quality_target=phx.meshing.MeshQualityTarget(
            minimum_angle=math.radians(10.0), hard=True
        ),
        limits=limits,
    )
    return (
        source,
        request,
        phx.meshing.NativeMeshingOptions("parametric_surface"),
        patches,
    )


def _cad_qualification_acceptance(
    result: phx.meshing.CellMeshingResult,
    source: phx.meshing.NativeSurfaceSource,
    patches: tuple[int, ...],
    request: phx.meshing.SurfaceMeshingSpec,
) -> dict[str, object]:
    """Analytic rectangle coverage plus strict authority/fidelity/control evidence."""
    certificate = result.certification
    if (
        certificate is None
        or not certificate.passed
        or not result.audit.passed
        or not result.compliance.passed
    ):
        raise RuntimeError(
            "The CAD surface requires strict audit, source/global and control certification."
        )
    quality_target = request.quality_target
    if quality_target is None:
        raise ValueError(
            "The CAD qualification request requires a frozen hard quality target."
        )
    mesh = result.mesh
    if mesh.topological_dimension != 2 or mesh.ambient_dimension != 3:
        raise RuntimeError("The CAD face consumer requires embedded triangular cells.")
    points = np.asarray(mesh.coordinates, dtype=np.float64)
    triangles = _mesh_triangles(mesh)
    area = float(np.sum(_triangle_areas(points, triangles)))
    plane_error = float(np.max(np.abs(points[:, 2] - 1.0)))
    outside = bool(
        np.any(points[:, 0] < 0.25 - 1.0e-12)
        or np.any(points[:, 0] > 0.75 + 1.0e-12)
        or np.any(points[:, 1] < -1.0e-12)
        or np.any(points[:, 1] > 1.0 + 1.0e-12)
    )
    expected_faces = {source.domain.entity_id(2, patch) for patch in patches}
    face_associations = [
        association
        for association in result.associations
        if association.target_entity_set_id == mesh.entity_set(2).entity_set_id
    ]
    if not result.associations or any(
        association.association_kind is not phx.meshing.GeometryAssociationKind.BREP
        or association.source_id != source.source_id
        or association.source_revision != source.source_revision
        for association in result.associations
    ):
        raise RuntimeError(
            "The surface result lost its exact CAD source/revision association."
        )
    if (
        len(face_associations) != 1
        or set(face_associations[0].source_entity_ids) != expected_faces
    ):
        raise RuntimeError(
            "The published face association lost the selected CAD entity scope."
        )
    quality = phx.meshing.summarize_cell_quality(phx.meshing.evaluate_cell_quality(mesh))
    passed = (
        abs(area - 0.5) <= 1.0e-10
        and plane_error <= 1.0e-10
        and not outside
        and quality.minimum_angle >= quality_target.minimum_angle - 1.0e-10
    )
    if not passed:
        raise RuntimeError(
            "Independent planar CAD coverage, bounds or hard quality failed."
        )
    return {
        "passed": passed,
        "analytic_area": 0.5,
        "mesh_area": area,
        "area_defect": area - 0.5,
        "plane_deviation": plane_error,
        "outside_analytic_bounds": outside,
        "selected_source_entities": sorted(expected_faces),
        "certification_id": certificate.report_id,
        "outcomes": {outcome.check: outcome.status for outcome in certificate.outcomes},
        "requested": dict(certificate.requested),
        "achieved": dict(certificate.achieved),
        "quality": _quality_summary(quality),
        "organization": {
            "patches": [patch.name for patch in result.patches],
            "labels": [label.name for label in result.labels],
        },
    }


def _cad_qualification_forcing(points: Any, context: Any) -> Any:
    del context
    # The planar surface has topological dimension two, not ambient dimension three.
    return jnp.full(points.shape[:-1], -4.0, dtype=points.dtype)


def _cad_qualification_solver(
    result: phx.meshing.CellMeshingResult,
) -> tuple[Any, Any, Any]:
    space = phx.discretization.FiniteElementPlan(
        result.mesh,
        phx.discretization.FiniteElementFieldSpec(
            "u", phx.discretization.lagrange_element("triangle", 1)
        ),
        coordinate_spec=result.geometry,
    ).prepare()
    constraint = phx.discretization.dirichlet_constraint(space, "u")
    if constraint.free_dofs.size == 0:
        raise RuntimeError(
            "The CAD PDE fixture needs interior scalar H1 degrees of freedom."
        )
    form = phx.equations.FiniteElementForm(
        "native-cad-planar-laplace-beltrami",
        "u",
        (
            phx.equations.DiffusionAction("u", 1.0),
            phx.equations.SourceAction(
                "u",
                phx.equations.coefficient(
                    _cad_qualification_forcing,
                    coefficient_id="planar-surface-quadratic-minus-four",
                ),
            ),
        ),
    )
    problem = phx.equations.compile_finite_element_problem(
        form, space, constraint=constraint, dirichlet_values=_manufactured_value
    )
    return space, problem, constraint.free_dofs


def _cad_qualification_epochs(
    result: phx.meshing.CellMeshingResult,
    model: phx.geometry.brep.BRepModel,
    source: phx.meshing.NativeSurfaceSource,
    patches: tuple[int, ...],
    request: phx.meshing.SurfaceMeshingSpec,
    args: argparse.Namespace,
    record: dict[str, Any],
    started: float,
) -> None:
    """Continue the actual PDE from its accepted scalar state through native lineage."""
    stages = record["stages_seconds"]
    previous_values = None
    hierarchy = None
    projection, timing = _measured(
        lambda: phx.geometry.brep.prepare_brep_projection(model)
    )
    stages["cad_projection_preparation"] = timing["wall_seconds"]
    association_transfer = phx.meshing.BRepAssociationTransfer(projection)
    policy = phx.meshing.MeshAdaptationPolicy(
        phx.meshing.MeshAdaptationRoute.NATIVE_BISECTION,
        limits=request.limits,
        compatibility=phx.meshing.BisectionCompatibility.UNIFORM_REFINEMENT,
        association_transfer=association_transfer,
    )
    for epoch in range(args.adaptation_rounds + 1):
        record["active_phase"] = f"solver_prepare_epoch_{epoch}"
        solver, timing = _measured(lambda: _cad_qualification_solver(result))
        space, problem, free_dofs = solver
        stages[record["active_phase"]] = timing["wall_seconds"]
        seed = (
            jnp.zeros((free_dofs.size,), dtype=result.mesh.coordinates.dtype)
            if previous_values is None
            else jnp.asarray(previous_values)[free_dofs]
        )
        record["active_phase"] = f"solver_execution_epoch_{epoch}"
        values, compiler, timings = _compiled_solver_stages(problem, seed, args.repeats)
        stages.update(
            {f"{name}_epoch_{epoch}": elapsed for name, elapsed in timings.items()}
        )
        error = _physical_error(result.mesh, values)
        if error <= args.target_error and record["time_to_target_error_seconds"] is None:
            record["time_to_target_error_seconds"] = perf_counter() - started
        row = {
            "epoch": epoch,
            "result": _result_identity(result),
            "l2_error": error,
            "dofs": space.dof_maps[0].global_dof_count,
            "compiler": compiler,
            "retained_bytes": _bisection_retained_bytes(
                (result, space, problem, hierarchy)
            ),
            "transferred_state_consumed_as_seed": previous_values is not None,
            "transferred_state_l2_error": (
                None
                if previous_values is None
                else _physical_error(result.mesh, previous_values)
            ),
        }
        record["epochs"].append(row)
        if epoch == args.adaptation_rounds:
            break
        record["active_phase"] = f"adaptation_prepare_epoch_{epoch}"
        marked = phx.meshing.MarkedMeshAdaptation(
            np.asarray(result.mesh.blocks[0].global_ids, dtype=np.int64),
            np.empty((0,), dtype=np.int64),
            hierarchy=hierarchy,
        )
        prepared, timing = _measured(
            lambda: phx.meshing.prepare_mesh_adaptation(result, marked, policy=policy)
        )
        stages[record["active_phase"]] = timing["wall_seconds"]
        record["active_phase"] = f"adaptation_execute_epoch_{epoch}"
        adaptation, timing = _measured(
            lambda: phx.meshing.execute_mesh_adaptation(prepared)
        )
        stages[record["active_phase"]] = timing["wall_seconds"]
        state_transfer = adaptation.transfer
        if (
            adaptation.status is not phx.meshing.MeshAdaptationStatus.COMPLETE
            or state_transfer is None
        ):
            raise RuntimeError(
                "CAD-preserving bisection did not produce a complete scalar state transfer."
            )
        record["active_phase"] = f"field_transfer_epoch_{epoch}"
        previous_values, timing = _measured(
            lambda: jax.block_until_ready(state_transfer.apply(values))
        )
        stages[record["active_phase"]] = timing["wall_seconds"]
        row["transfer"] = _bisection_transfer(adaptation)
        before = _bisection_p1_integral(result.mesh, values)
        after = _bisection_p1_integral(adaptation.target.mesh, previous_values)
        row["state_inventory"] = {
            "source": before,
            "target": after,
            "defect": after - before,
        }
        if abs(after - before) > 1.0e-10 * max(1.0, abs(before)):
            raise RuntimeError(
                "The actual CAD scalar solver-state transfer lost P1 inventory."
            )
        record["active_phase"] = f"independent_acceptance_epoch_{epoch + 1}"
        target_acceptance = _cad_qualification_acceptance(
            adaptation.target, source, patches, request
        )
        if (
            target_acceptance["organization"]
            != record["independent_acceptance"]["organization"]
        ):
            raise RuntimeError(
                "CAD adaptation lost authoritative patch/curve organization."
            )
        row["target_acceptance"] = target_acceptance
        result, hierarchy = adaptation.target, adaptation.hierarchy
    record["physical_error"] = record["epochs"][-1]["l2_error"]
    record["target_error_reached"] = record["physical_error"] <= args.target_error


def _cad_qualification_lifecycle(args: argparse.Namespace) -> dict[str, object]:
    """Bounded native format → Boolean/query → strict CAD face → H1 state loop."""
    requirements = _cad_qualification_requirements()
    if (
        args.resolution < 1
        or args.capacity < 1
        or args.repeats < 1
        or args.adaptation_rounds < 1
    ):
        raise ValueError(
            "CAD resolution, capacity, repeats and adaptation rounds must be positive."
        )
    if (
        not np.isfinite(args.timeout)
        or args.timeout <= 0.0
        or not np.isfinite(args.target_error)
        or args.target_error <= 0.0
    ):
        raise ValueError("CAD timeout and target error must be finite and positive.")
    started = perf_counter()
    record: dict[str, Any] = {
        "scenario": "native-cad-lifecycle",
        "status": "failed",
        "runtime": _runtime_identity(),
        "requirements": requirements,
        "format": args.cad_format,
        "stages_seconds": {},
        "native_phases": [],
        "epochs": [],
        "targets": {"l2_error": args.target_error, "wall_seconds": args.timeout},
        "control_capacities": {
            "resolution": args.resolution,
            "entity_capacity": args.capacity,
            "adaptation_rounds": args.adaptation_rounds,
        },
        "time_to_target_error_seconds": None,
        "positive_prerequisite": None,
        "mandatory_workflow_completion": "incomplete",
        "full_curved_multiformat_gate": "incomplete",
        "release_evidence": "unassessed",
        "leadership_evidence": "unassessed",
        "nonclaims": requirements["nonclaims"],
        "optional_external_baseline": "not-requested",
        "pde": "-Delta_S |x|^2 = -4 on an exact planar CAD rectangle",
        "active_phase": "source_format_preparation",
    }

    def record_phase(measurement: phx.meshing.NativeMeshingPhaseMeasurement) -> None:
        record["native_phases"].append(
            {
                "phase": measurement.phase,
                "elapsed_seconds": measurement.elapsed_seconds,
                "work_units": measurement.work_units,
                "invocations": measurement.invocations,
            }
        )

    stages = record["stages_seconds"]
    try:
        with TemporaryDirectory(prefix="phydrax-native-cad-") as temporary:
            first, second, imports = _cad_qualification_import(
                Path(temporary), args.cad_format, args.capacity, stages
            )
            record["imports"] = imports
            record["active_phase"] = "native_boolean"
            boolean, timing = _measured(
                lambda: phx.geometry.brep.boolean_brep(
                    first,
                    second,
                    "intersection",
                    policy=phx.geometry.brep.BRepBooleanPolicy(
                        maximum_cells=args.capacity, maximum_faces=args.capacity
                    ),
                )
            )
            stages[record["active_phase"]] = timing["wall_seconds"]
            model = boolean.model
            record["boolean"] = {
                "operation": boolean.operation,
                "certificate_id": boolean.certificate_id,
                "association_graph_id": boolean.association_graph.graph_id,
                "deleted_source_ids": list(boolean.deleted_source_ids),
                "model_id": model.model_id,
            }
            record["active_phase"] = "native_query_preparation"
            query, timing = _measured(lambda: phx.geometry.brep.prepare_brep_query(model))
            stages[record["active_phase"]] = timing["wall_seconds"]
            volume = float(np.sum(np.asarray(query.measures.solid_volumes)))
            if abs(volume - 0.5) > 1.0e-10:
                raise RuntimeError(
                    "The native Boolean query disagrees with analytic intersection volume."
                )
            record["query"] = {
                "query_id": query.query_id,
                "source_revision": query.source_revision,
                "analytic_solid_volume": 0.5,
                "solid_volume": volume,
                "face_areas": np.asarray(query.measures.face_areas).tolist(),
                "face_area_errors": np.asarray(query.measures.face_area_errors).tolist(),
                "solid_volume_errors": np.asarray(
                    query.measures.solid_volume_errors
                ).tolist(),
            }
            record["active_phase"] = "authoritative_source_request_preparation"
            prepared, timing = _measured(
                lambda: _cad_qualification_source(
                    model, args.resolution, args.capacity, args.timeout
                )
            )
            source, request, options, patches = prepared
            stages[record["active_phase"]] = timing["wall_seconds"]
            record["source"] = {
                "source_id": source.source_id,
                "source_revision": source.source_revision,
                "binding_id": source.binding_id,
                "authority_id": source.domain.authority_id,
                "domain_id": source.domain.domain_id,
                "selected_entities": [
                    source.domain.entity_id(2, patch) for patch in patches
                ],
                "accuracy": source.domain.accuracy,
                "whole_domain_retained": True,
            }
            quality_target = request.quality_target
            if quality_target is None:
                raise ValueError(
                    "The CAD qualification request requires a frozen hard quality target."
                )
            record["request"] = {
                "specification_id": request.specification_id,
                "limits_id": request.limits.limits_id,
                "scope_id": request.scope.scope_id,
                "quality_target_id": quality_target.target_id,
            }
            record["active_phase"] = "geometry_constraint_preparation"
            provider = phx.meshing.NativeMeshingProvider(options)
            plan, timing = _measured(
                lambda: provider.plan(
                    source,
                    request,
                    coordinate_contract=model.coordinate_contract,
                    record_phase=record_phase,
                )
            )
            stages[record["active_phase"]] = timing["wall_seconds"]
            record["prepared_id"] = plan.plan_id
            record["active_phase"] = "generation_publication_certification"
            result, timing = _measured(lambda: plan.execute(record_phase=record_phase))
            stages[record["active_phase"]] = timing["wall_seconds"]
            record["generation"] = _result_identity(result)
            record["active_phase"] = "independent_source_acceptance"
            acceptance, timing = _measured(
                lambda: _cad_qualification_acceptance(result, source, patches, request)
            )
            stages[record["active_phase"]] = timing["wall_seconds"]
            record["independent_acceptance"] = acceptance
            _cad_qualification_epochs(
                result, model, source, patches, request, args, record, started
            )
            record["status"] = "passed" if record["target_error_reached"] else "failed"
    except phx.meshing.MeshingFailure as failure:
        record.update(
            {
                "failure": str(failure),
                "failure_category": failure.category.value,
                "failure_evidence_id": failure.evidence.evidence_id,
                "native_stage": failure.evidence.stage,
                "failing_entities": list(failure.evidence.entity_ids),
                "requested": dict(failure.evidence.requested),
                "achieved": dict(failure.evidence.achieved),
                "positive_prerequisite": {
                    "phase": record["active_phase"],
                    "detail": str(failure),
                    "category": failure.category.value,
                    "safe_refusal_is_positive": False,
                },
            }
        )
    except (RuntimeError, ValueError, TypeError) as failure:
        record.update(
            {
                "failure": str(failure),
                "failure_type": type(failure).__name__,
                "positive_prerequisite": {
                    "phase": record["active_phase"],
                    "detail": str(failure),
                    "source_organization_stripped": False,
                    "safe_refusal_is_positive": False,
                },
            }
        )
    finally:
        record["end_to_end_seconds"] = perf_counter() - started
        record["peak_process_resident_bytes"] = resource.getrusage(
            resource.RUSAGE_SELF
        ).ru_maxrss * (1 if sys.platform == "darwin" else 1024)
        record["process_peak_scope"] = "process-lifetime"
        record["device_memory"] = [
            {
                "device_id": device.id,
                "platform": device.platform,
                "status": "unavailable" if statistics is None else "backend-reported",
                "peak_bytes": None
                if statistics is None
                else statistics.get("peak_bytes_in_use"),
                "memory_statistics": statistics,
            }
            for device in jax.local_devices()
            for statistics in (device.memory_stats(),)
        ]
        if record["status"] != "passed":
            record["failure_phase"] = record["active_phase"]
        if record["end_to_end_seconds"] > args.timeout:
            record["status"] = "timeout"
        del record["active_phase"]
    return record


