def _hybrid_qualification_original_wall_profiles() -> tuple[str, ...]:
    """Enumerate original independent source profiles; do not execute them."""
    return _hybrid_qualification_original_profile_names


def _hybrid_qualification_original_wall_profile(name: str) -> dict[str, Any]:
    """Run only the selected original wall/layer constructor and its full oracle."""
    if name not in _hybrid_qualification_original_profile_names:
        raise ValueError(f"unknown original wall profile: {name}")
    from phydrax._fingerprint import array_tree_fingerprint

    constructors: dict[str, Callable[[], Any]] = {
        "plate5": _hybrid_qualification_original_plate5,
        "quadrilateral_plate3": _hybrid_qualification_original_quadrilateral_plate3,
        "opposing_sloped_plates4": _hybrid_qualification_original_opposing_sloped_plates4,
        "sphere_radius04_subdivision2": _hybrid_qualification_original_sphere_radius04_subdivision2,
        "outward_box_count3": _hybrid_qualification_original_outward_box_count3,
        "concave_box_count3": _hybrid_qualification_original_concave_box_count3,
        "wedge30_rejection": _hybrid_qualification_original_wedge30_rejection,
        "open_box_floor_count4": _hybrid_qualification_original_open_box_floor_count4,
        "channel_gap005_rejection": _hybrid_qualification_original_channel_gap005_rejection,
        "channel_gap005_policies": _hybrid_qualification_original_channel_gap005_policies,
    }
    outcome: Any = constructors[name]()
    pairs: tuple[tuple[Any, Any, Any], ...] = (
        outcome if name == "channel_gap005_policies" else (outcome,)
    )
    rejected = name.endswith("_rejection")
    owners = []
    receipts = []
    for wall, control, result in pairs:
        receipt = {
            "source_bits_fingerprint": array_tree_fingerprint((wall, control)),
            "wall_mesh_id": str(wall.mesh_id),
            "wall_numeric_version": str(wall.numeric_version),
        }
        if rejected:
            receipt.update(
                category=result.category.name,
                entity_ids=[int(value) for value in result.entity_ids],
                locations=np.asarray(result.locations).tolist(),
            )
            owners.append({"wall": wall, "control": control, "failure": result})
        else:
            receipt.update(
                source_layer_bits_fingerprint=array_tree_fingerprint(
                    (wall, control, result)
                ),
                layer_mesh_id=str(result.mesh.mesh_id),
                cell_counts={
                    str(kind): int(count) for kind, count in result.evidence.cell_counts
                },
                certified_valid_count=int(result.evidence.certified_valid_count),
                closed_cap=bool(result.closed_cap),
                cap_mesh_id=None if result.cap is None else str(result.cap.mesh_id),
            )
            owners.append(
                {"wall": wall, "control": control, "layers": result, "cap": result.cap}
            )
        receipts.append(receipt)
    closed_original = name in {
        "sphere_radius04_subdivision2",
        "outward_box_count3",
        "concave_box_count3",
    }
    evidence = {
        "profile": name,
        "source": "tests/unit/meshing/test_boundary_layer.py scenarios 1-3",
        "original_controls": _hybrid_qualification_original_controls[name],
        "schedule": {"count": 3, "first_thickness": 0.01, "growth_rate": 1.2},
        "stage_scope": "original wall/control rejection"
        if rejected
        else "original wall and certified boundary-layer preparation only",
        "original_oracles_passed": True,
        "core_executed": False,
        "lifecycle_executed": False,
        "receipts": receipts,
        "full_core_boundary_composition": {
            "original_wall_closed": closed_original,
            "admissible_information": "Concave box is an authored closed container; its inward layer cap is the remaining-core boundary. No core mesh is authored by the original scenario."
            if name == "concave_box_count3"
            else "Original open box retains the four side walls and authors a floor-only layer scope; the top at z=0.5 was explicitly removed. Its exact discarded top triangles are recoverable from the original box constructor, but a closed cap/side/top core composition and its orientation were not authored by this oracle."
            if name == "open_box_floor_count4"
            else "Original outward closed wall and closed layer cap describe an obstacle and its outer layer front, not a bounded exterior core."
            if closed_original
            else "Original open sheets or floor-only wall selection do not author a closed remaining-core boundary; merged channel fronts have no free cap.",
            "missing_authoring": "Core meshing request and original independent core/lifecycle oracle."
            if name == "concave_box_count3"
            else "Explicit remaining side-wall trimming, top inclusion, closed core boundary composition, core request, and independent core/lifecycle oracle; no new enclosing geometry is justified."
            if name == "open_box_floor_count4"
            else "Original enclosing outer boundary, core boundary composition, core meshing request, and independent core/lifecycle oracle.",
        },
    }
    evidence["source"] = (
        "tools/meshing_qualification.py::_hybrid_qualification_original_wall_profile"
    )
    evidence["original_lineage"] = (
        "tests/unit/meshing/test_boundary_layer.py scenarios 1-3"
    )
    if name == "concave_box_count3":
        wall, control, layers = pairs[0]
        if layers.cap is None or not layers.closed_cap:
            raise AssertionError(
                "Original inward closed box must supply its closed remaining-core cap."
            )
        if any(block.cell_kind != "triangle" for block in layers.cap.blocks):
            raise AssertionError("Original inward-box cap must retain triangular rows.")
        cap_rows = np.concatenate(
            [np.asarray(block.vertices, dtype=np.int64) for block in layers.cap.blocks]
        )
        core = phx.meshing.PiecewiseLinearComplex(
            np.asarray(layers.cap.coordinates, dtype=np.float64),
            tuple(cap_rows),
            np.arange(cap_rows.shape[0], dtype=np.int64),
            np.tile(np.asarray((0, -1), dtype=np.int64), (cap_rows.shape[0], 1)),
            ("fluid",),
            boundary="fixed",
        )
        core_source = phx.meshing.NativeLayerCoreSource(
            layers,
            core,
            str(wall.mesh_id),
            str(wall.numeric_version),
            vertex_layer_ids=np.asarray(layers.cap_vertices, dtype=np.int64),
            cap_polygon_ids=np.arange(cap_rows.shape[0], dtype=np.int64),
            layer_regions=np.zeros(
                sum(block.cell_count for block in layers.mesh.blocks), dtype=np.int64
            ),
            region_ids=("fluid",),
            core_region_map=np.asarray((0,), dtype=np.int64),
        )
        owners[0]["core_source"] = core_source
        owners[0]["core_complex"] = core
        evidence["core_source_binding_id"] = core_source.binding_id
        evidence["core_source_bits_fingerprint"] = array_tree_fingerprint(core_source)
        evidence["stage_scope"] = (
            "original wall and certified layers with exact unchanged closed-cap core-source composition; no core fill or lifecycle"
        )
        evidence["full_core_boundary_composition"]["missing_authoring"] = (
            "Core fill request and independent core/lifecycle oracle; original wall mesh scope authors no geometry-domain association or fidelity query."
        )
    answer = {"evidence": evidence, "owners": tuple(owners)}
    if len(owners) == 1:
        answer.update(owners[0])
    return answer


def _hybrid_qualification_archived_profile(
    args: argparse.Namespace, record: dict[str, Any]
) -> None:
    """Consume the original archive once, in a genuinely remaining-budget cold process."""
    import subprocess

    from phydrax.lifecycle._meshing_sources import (
        MeshingSourceExecutionControls,
        read_meshing_source_execution_controls,
    )

    if not args.hybrid_archive or not args.hybrid_content_id:
        raise ValueError(
            "An archived original hybrid profile requires its actual archive and content identity."
        )
    retained_controls = vars(args).get("hybrid_execution_controls")

    def authenticated_controls() -> MeshingSourceExecutionControls:
        if retained_controls is None:
            return read_meshing_source_execution_controls(
                args.hybrid_archive, expected_content_id=args.hybrid_content_id
            )
        if (
            type(retained_controls) is not MeshingSourceExecutionControls
            or retained_controls.content_id != args.hybrid_content_id
        ):
            raise ValueError(
                "Retained hybrid controls do not bind the published archive identity."
            )
        retained_controls.execution_evidence.require_valid()
        return retained_controls

    controls = _hybrid_qualification_stage(
        record,
        "authenticated_original_execution_controls",
        authenticated_controls,
    )
    record["source"] = {
        "source_id": controls.source_id,
        "source_revision": controls.source_revision,
        "source_binding_id": controls.source_binding_id,
        "specification_id": controls.specification_id,
        "archive": str(args.hybrid_archive),
        "content_id": controls.content_id,
        "stage_scope": "original-authenticated-source-full-cold-read-allfields-FV-history-PDE",
        "controls_only": True,
        "controls_origin": (
            "authenticated-archive"
            if retained_controls is None
            else "retained-live-producer-evidence"
        ),
    }
    remaining = args.timeout - (perf_counter() - record["started"])
    if remaining <= 0.0:
        raise TimeoutError(
            "The original hybrid clock expired before its fresh-process consumer."
        )
    completed = _hybrid_qualification_stage(
        record,
        "original_fresh_process_full_read_allfields_FV_history_PDE",
        lambda: subprocess.run(
            [
                sys.executable,
                str(
                    Path(__file__).resolve().parent
                    / "layer_core_lifecycle_continuation.py"
                ),
                str(args.hybrid_archive),
                controls.content_id,
                "--region-densities",
                *(str(value) for value in args.hybrid_region_densities),
                "--material-site",
                args.hybrid_material_site,
            ],
            capture_output=True,
            text=True,
            check=False,
            timeout=remaining,
        ),
    )
    record["cold"] = {
        "returncode": completed.returncode,
        "stdout": completed.stdout,
        "stderr": completed.stderr,
        "archive_limits": "DEFAULT_ARRAY_ARCHIVE_LIMITS",
    }
    if completed.returncode:
        raise RuntimeError(
            "Fresh-process original hybrid continuation refused: " + completed.stderr
        )
    evidence = [
        json.loads(line) for line in completed.stdout.splitlines() if line.strip()
    ]
    if not evidence or (
        evidence[0].get("source_id"),
        evidence[0].get("source_revision"),
    ) != (
        controls.source_id,
        controls.source_revision,
    ):
        raise RuntimeError(
            "Fresh-process hybrid continuation lost its exact authenticated source."
        )
    cold_stages = evidence[0].get("stages_seconds")
    if (
        not isinstance(cold_stages, dict)
        or not cold_stages
        or any(
            type(name) is not str
            or not name
            or not isinstance(seconds, (int, float))
            or not np.isfinite(seconds)
            or seconds < 0.0
            for name, seconds in cold_stages.items()
        )
    ):
        raise RuntimeError(
            "Fresh-process hybrid continuation omitted finite owned phase timings."
        )
    record["cold_stages_seconds"] = cold_stages
    for section, output in (
        ("fields", "allfields"),
        ("finite_volume", "finite_volume"),
        ("history", "history"),
    ):
        values = [item[section] for item in evidence if section in item]
        if len(values) != 1:
            raise RuntimeError(
                f"Cold original hybrid omitted or duplicated its actual {section} consumer."
            )
        record[output] = values[0]
    declarations = evidence[0].get("material_declaration")
    if (
        not isinstance(declarations, dict)
        or declarations.get("densities") != list(args.hybrid_region_densities)
        or declarations.get("site_id") != args.hybrid_material_site
    ):
        raise RuntimeError(
            "Cold original hybrid changed its declared source-bound material decision."
        )
    record["material_declaration"] = declarations
    receipts = [item for item in evidence if "execution_evidence" in item]
    if len(receipts) != 1 or receipts[0].get("limits_id") != controls.limits.limits_id:
        raise RuntimeError(
            "Cold original hybrid omitted its actual ended original-scope evidence."
        )
    record["physical_error"] = max(
        stage["pde_defect"] for stage in record["history"]["stages"]
    )
    record["physical_error_scope"] = (
        "maximum-nodal-PDE-defect-across-original-history-transitions"
    )
    if (
        not np.isfinite(record["physical_error"])
        or record["physical_error"] > args.target_error
    ):
        raise RuntimeError(
            "Original continued PDE missed its declared physical error target."
        )
    record["cold"]["evidence"] = evidence
    record["source"]["controls_only"] = False
    record["independent_scientific_certification"] = "passed"
    record["status"] = "passed"


def _hybrid_qualification_concave_lifecycle(
    args: argparse.Namespace, record: dict[str, Any]
) -> None:
    """Fill the actual original closed inward cap and consume its complete lineage."""
    from phydrax.lifecycle._meshing_source_families import native_family_audit_policy
    from phydrax.lifecycle._meshing_sources import write_meshing_source_closure
    from phydrax.meshing._curving import _straight_geometry
    from phydrax.meshing._lineage import identity_lineage

    if (
        args.hybrid_core_size is None
        or not np.isfinite(args.hybrid_core_size)
        or args.hybrid_core_size <= 0.0
    ):
        raise ValueError(
            "Original closed-cap lifecycle requires a positive finite core size control."
        )
    if (
        args.adaptation_rounds < 1
        or not np.isfinite(args.target_error)
        or args.target_error <= 0.0
    ):
        raise ValueError(
            "Original lifecycle requires positive requested AMR cycles and physical error target."
        )
    owners = _hybrid_qualification_stage(
        record,
        "original_concave_wall_layers_and_cap",
        lambda: _hybrid_qualification_original_wall_profile("concave_box_count3"),
    )
    record["source_profile"] = owners["evidence"]
    source = owners["core_source"]
    limits = phx.meshing.MeshingLimits(maximum_wall_seconds=args.timeout)
    scope = phx.meshing.MeshingScope(
        source.source_id,
        source.source_revision,
        phx.meshing.MeshingEntityKind.GEOMETRY,
        2,
        "original-closed-cap-core-facets",
        np.arange(source.complex.facet_count, dtype=np.int64),
    )
    specification = phx.meshing.VolumeMeshingSpec(
        phx.meshing.CellMeshingTarget(
            3,
            3,
            phx.meshing.CellFamilyPolicy(
                required=("prism", "tetrahedron"), allow_mixed=True
            ),
        ),
        scope,
        phx.meshing.VolumeFillStrategy.SIMPLEX,
        size_controls=(
            phx.meshing.UniformSizeControl(
                scope,
                args.hybrid_core_size,
                strength=phx.meshing.SizeControlStrength.SOFT,
            ),
        ),
        limits=limits,
    )
    options = phx.meshing.NativeMeshingOptions("layer_core")
    plan = _hybrid_qualification_stage(
        record,
        "original_closed_cap_core_plan",
        lambda: phx.meshing.NativeMeshingProvider(options).plan(
            source, specification, coordinate_contract=phx.SpatialCoordinateContract.si()
        ),
    )
    generated = _hybrid_qualification_stage(
        record, "original_fixed_cap_core_publication", plan.execute
    )
    record["core_generation"] = _result_identity(generated)
    record["core_consumer_controls"] = {
        "specification_id": specification.specification_id,
        "size": args.hybrid_core_size,
        "limits_id": specification.limits.limits_id,
        "source_schedule_unchanged": list(source.layers.control.schedule.thicknesses),
    }
    if generated.certification is None or not generated.certification.passed:
        raise RuntimeError(
            "Original closed-cap core did not independently certify its source."
        )
    from tools.layer_core_lifecycle_continuation import material_declaration

    record["material_declaration"] = _hybrid_qualification_stage(
        record,
        "original_source_material_declaration",
        lambda: material_declaration(
            generated,
            densities=tuple(args.hybrid_region_densities),
            site_id=args.hybrid_material_site,
        ),
    )
    coverage = generated.certification.coverage
    if coverage is None or any(
        value is None for value in coverage.achieved_region_measures
    ):
        raise RuntimeError(
            "Original closed container lost its certified material measures."
        )
    np.testing.assert_allclose(coverage.achieved_region_measures, (1.0,), rtol=1.0e-12)
    authority = generated.certification.request
    geometry = _hybrid_qualification_stage(
        record,
        "original_map_high_order_entity_node_lift",
        lambda: _straight_geometry(
            generated.mesh,
            args.geometry_order,
            maximum_nodes=32 * args.capacity,
            maximum_entries=1024 * args.capacity,
        ),
    )
    inputs = phx.meshing.MeshCertificationInputs(
        generated.mesh,
        geometry,
        authority.schedule,
        domain=authority.domain,
        cell_regions=authority.cell_regions,
        source=authority.source,
        fidelity_tolerance=authority.fidelity_tolerance,
        fidelity_sample_order=authority.fidelity_sample_order,
        limits=authority.limits,
        junction_vertices=authority.junction_vertices,
        scoped_fidelity=authority.scoped_fidelity,
    )
    accepted = _hybrid_qualification_stage(
        record,
        "original_high_order_full_source_certification",
        lambda: phx.meshing.certify_cell_mesh(
            generated.mesh,
            generated.coordinate_contract,
            geometry=geometry,
            audit_policy=native_family_audit_policy(
                source, specification, generated.mesh
            ),
            patches=generated.patches,
            zones=generated.zones,
            labels=generated.labels,
            attributes=generated.attributes,
            associations=generated.associations,
            region_evidence=generated.region_evidence,
            region_boundary_evidence=generated.region_boundary_evidence,
            certification_inputs=inputs,
            lineage=identity_lineage(generated.mesh, generated.mesh),
        ),
    )
    if accepted.certification is None or not accepted.certification.passed:
        raise RuntimeError(
            "Original source high-order map did not pass full independent certification."
        )
    record["geometry_decision"] = {
        "degree": args.geometry_order,
        "source_geometry": "unchanged original piecewise source",
        "construction": "family-correct nodal lift accepted by full original-source certificates; no projection or field-degree substitution",
        "acceptance": _result_identity(accepted),
    }
    record["cycles"] = []
    for cycle in range(args.adaptation_rounds):
        columns = _hybrid_qualification_columns(accepted)
        policy = phx.meshing.MeshAdaptationPolicy(
            phx.meshing.MeshAdaptationRoute.NATIVE_MIXED,
            limits=specification.limits,
            audit_policy=native_family_audit_policy(source, specification, accepted.mesh),
            association_transfer=phx.meshing.prepare_native_layer_association_transfer(
                source, specification, accepted
            ),
        )
        first = int(np.min(np.asarray(columns.cell_ids)))
        refinement = _hybrid_qualification_stage(
            record,
            f"original_physical_layer_refinement:{cycle}",
            lambda: phx.meshing.execute_mesh_adaptation(
                phx.meshing.prepare_mesh_adaptation(
                    accepted,
                    phx.meshing.MarkedMeshAdaptation(
                        np.asarray((first,), dtype=np.int64), layer_columns=columns
                    ),
                    policy=policy,
                )
            ),
        )
        if refinement.status is not phx.meshing.MeshAdaptationStatus.COMPLETE:
            raise RuntimeError("Original physical-column refinement was not complete.")
        active = set(
            np.concatenate(
                [np.asarray(block.global_ids) for block in refinement.target.mesh.blocks]
            ).tolist()
        )
        children = sorted(
            {
                child
                for entry in refinement.hierarchy.records
                for child in entry.child_ids
                if child in active
            }
        )
        coarsening = _hybrid_qualification_stage(
            record,
            f"original_physical_layer_inverse_coarsening:{cycle}",
            lambda: phx.meshing.execute_mesh_adaptation(
                phx.meshing.prepare_mesh_adaptation(
                    refinement.target,
                    phx.meshing.MarkedMeshAdaptation(
                        (),
                        np.asarray(children, dtype=np.int64),
                        hierarchy=refinement.hierarchy,
                    ),
                    policy=policy,
                )
            ),
        )
        if coarsening.status is not phx.meshing.MeshAdaptationStatus.COMPLETE:
            raise RuntimeError(
                "Original physical-column inverse coarsening was not complete."
            )
        with TemporaryDirectory(prefix="native-original-concave-lineage-") as temporary:
            receipt = _hybrid_qualification_stage(
                record,
                f"original_default_durable_lineage:{cycle}",
                lambda: write_meshing_source_closure(
                    Path(temporary) / "lifecycle",
                    {
                        "certification_inputs": accepted.certification.request,
                        "report": accepted.certification,
                        "associations": accepted.associations,
                        "generation_source": source,
                        "generation_specification": specification,
                        "generation_options": options,
                        "generation_part": phx.meshing.MeshPart(
                            "original-concave-layer-core", accepted
                        ),
                        "accepted_data": {"adaptation_results": (refinement, coarsening)},
                    },
                ),
            )
            consumer = argparse.Namespace(**vars(args))
            consumer.hybrid_archive = str(receipt.path)
            consumer.hybrid_content_id = receipt.content_id
            continuation = {
                "cycle": cycle,
                "started": record["started"],
                "targets": record["targets"],
                "stages_seconds": {},
                "active_phase": "original_default_archive_renewal",
            }
            record["cycles"].append(continuation)
            try:
                _hybrid_qualification_archived_profile(consumer, continuation)
            except Exception:
                record["active_phase"] = continuation["active_phase"]
                raise
            finally:
                del continuation["started"]
                del continuation["active_phase"]
            accepted = coarsening.target
    cycles = record["cycles"]
    if not cycles:
        raise RuntimeError(
            "Original concave lifecycle produced no accepted adaptation cycle."
        )
    errors = [
        _record_float(cycle["physical_error"], "Hybrid continued physical error")
        for cycle in cycles
    ]
    record["physical_error"] = max(errors)
    if record["physical_error"] > args.target_error:
        raise RuntimeError(
            "Original concave lifecycle missed its frozen physical-error target."
        )
    record["independent_scientific_certification"] = "passed"
    record["status"] = "passed"


def _hybrid_qualification_original_curved_refusal_profile() -> dict[str, object]:
    """Bind the immutable original source to its exact nonperiodic trace proof."""
    from fractions import Fraction

    from tools._hybrid_layer_source import (
        ORIGINAL_CURVED_PERIODIC_SOURCE_DIGEST,
        ORIGINAL_CURVED_PERIODIC_SOURCE_ID,
        ORIGINAL_CURVED_PERIODIC_SOURCE_REVISION,
        ORIGINAL_PERIODIC_TRACE_RESIDUALS,
    )

    residuals = tuple(Fraction(value) for value in ORIGINAL_PERIODIC_TRACE_RESIDUALS)
    if any(value == 0 for value in residuals):
        raise RuntimeError(
            "The original negative trace proof no longer contains its exact mismatch."
        )
    evidence = {
        "profile": "original-curved-periodic-refusal",
        "stage_scope": "exact-original-source-periodic-trace-refusal",
        "source_id": ORIGINAL_CURVED_PERIODIC_SOURCE_ID,
        "source_revision": ORIGINAL_CURVED_PERIODIC_SOURCE_REVISION,
        "source_digest": ORIGINAL_CURVED_PERIODIC_SOURCE_DIGEST,
        "required_period_x": 1,
        "original_top_trace_x_residuals": list(ORIGINAL_PERIODIC_TRACE_RESIDUALS),
        "proof": "exact-rational-source-expression-trace",
        "proof_evidence": "tests/data/meshing/curved_periodic_sources.json",
        "source_bits_preserved": True,
        "rejection": (
            "Exact periodic certification refused the original source for residuals "
            + ", ".join(ORIGINAL_PERIODIC_TRACE_RESIDUALS)
        ),
    }
    return {"evidence": evidence}


def _hybrid_qualification_corrected_curved_lifecycle(
    args: argparse.Namespace,
    record: dict[str, Any],
) -> None:
    """Generate, adapt, archive, and cold-continue the exact-orbit curved source."""
    from phydrax.discretization._cell_geometry_validity import cell_geometry_id
    from phydrax.lifecycle._meshing_source_families import native_family_audit_policy
    from phydrax.lifecycle._meshing_sources import (
        MeshingSourceExecutionControls,
        write_meshing_source_closure,
    )
    from tools._hybrid_layer_source import (
        corrected_periodic_layer_source,
        ORIGINAL_CURVED_PERIODIC_SOURCE_DIGEST,
        ORIGINAL_CURVED_PERIODIC_SOURCE_ID,
        ORIGINAL_CURVED_PERIODIC_SOURCE_REVISION,
        ORIGINAL_PERIODIC_TRACE_RESIDUALS,
        source_identity_record,
    )

    if args.geometry_order != 2:
        raise ValueError(
            "The corrected authored quadratic source requires geometry_order=2."
        )
    if args.adaptation_rounds < 1:
        raise ValueError(
            "The corrected curved lifecycle requires at least one adaptation round."
        )
    limits, _ = _hybrid_qualification_limits(args)
    authored = _hybrid_qualification_stage(
        record,
        "corrected_fundamental_domain_source_authoring",
        lambda: corrected_periodic_layer_source(limits=limits),
    )
    source = authored.source
    specification = authored.specification
    identity = source_identity_record(authored)
    record["preserved_original_source"] = {
        "source_id": ORIGINAL_CURVED_PERIODIC_SOURCE_ID,
        "source_revision": ORIGINAL_CURVED_PERIODIC_SOURCE_REVISION,
        "source_digest": ORIGINAL_CURVED_PERIODIC_SOURCE_DIGEST,
        "exact_residuals": list(ORIGINAL_PERIODIC_TRACE_RESIDUALS),
    }
    if (
        source.source_id == ORIGINAL_CURVED_PERIODIC_SOURCE_ID
        or source.source_revision == ORIGINAL_CURVED_PERIODIC_SOURCE_REVISION
        or authored.source_digest == ORIGINAL_CURVED_PERIODIC_SOURCE_DIGEST
    ):
        raise RuntimeError(
            "The corrected source reused the immutable original source identity."
        )
    record["source_profile"] = {
        **identity,
        "profile": "curved-periodic-layer-core",
        "stage_scope": (
            "corrected-curved-ADVANCING-layer-core-highorder-AMR-"
            "H1Q2-DG1-Hcurl2-Hdiv2-FV-history-PDE-defaultcold"
        ),
        "source_composition": "fundamental-domain-representatives-plus-exact-unit-translation",
        "original_source_refusal_retained": {
            "source_id": ORIGINAL_CURVED_PERIODIC_SOURCE_ID,
            "exact_residuals": list(ORIGINAL_PERIODIC_TRACE_RESIDUALS),
        },
    }
    provider = phx.meshing.NativeMeshingProvider(authored.options)
    plan = _hybrid_qualification_stage(
        record,
        "corrected_layer_core_plan",
        lambda: provider.plan(
            source,
            specification,
            coordinate_contract=phx.SpatialCoordinateContract.si(),
        ),
    )
    generated = _hybrid_qualification_stage(
        record, "corrected_layer_core_generation", plan.execute
    )
    report = generated.certification
    if report is None or not report.passed or report.embedding is None:
        raise RuntimeError(
            "The corrected source did not pass complete native certification."
        )
    mismatches = [
        finding
        for finding in report.embedding.findings
        if finding.check == "periodic_mapped_trace_mismatch"
    ]
    if mismatches:
        raise RuntimeError(
            "The corrected source retained a nonperiodic exact source trace."
        )
    if generated.mesh.periodic_topology is None:
        raise RuntimeError(
            "The corrected publication lost its explicit periodic quotient."
        )
    if source.mapped_domain is None:
        raise RuntimeError(
            "The corrected publication lost its authored high-order source roots."
        )
    kinds = {block.cell_kind for block in generated.mesh.blocks}
    if kinds != {"prism", "tetrahedron"}:
        raise RuntimeError(
            "The corrected source did not publish the requested hybrid families."
        )
    record["generation"] = _result_identity(generated)
    record["immutable_cap"] = _hybrid_qualification_cap_identity(generated, source)
    record["curving"] = {
        "geometry_id": cell_geometry_id(generated.geometry),
        "mapped_domain_id": source.mapped_domain.domain_id,
        "degree": 2,
        "status": "certified",
        "periodic_trace_status": "certified",
        "periodic_topology_id": generated.mesh.periodic_topology.periodic_topology_id,
    }
    record["request"] = {
        "specification_id": specification.specification_id,
        "limits_id": specification.limits.limits_id,
        "options_id": authored.options.options_id,
        "prepared_id": plan.plan_id,
        "source_authoritative_schedule": list(source.layers.control.schedule.thicknesses),
        "resource_controls_unchanged": True,
    }
    columns = _hybrid_qualification_columns(generated)
    policy = phx.meshing.MeshAdaptationPolicy(
        phx.meshing.MeshAdaptationRoute.NATIVE_MIXED,
        limits=specification.limits,
        audit_policy=native_family_audit_policy(source, specification, generated.mesh),
        association_transfer=phx.meshing.prepare_native_layer_association_transfer(
            source, specification, generated
        ),
    )
    core_ids = np.sort(
        np.concatenate(
            [
                np.asarray(block.global_ids, dtype=np.int64)
                for block in generated.mesh.blocks
                if block.cell_kind == "tetrahedron"
            ]
        )
    )
    if not core_ids.size:
        raise RuntimeError("The corrected hybrid source has no native simplex core.")
    refinement = _hybrid_qualification_stage(
        record,
        "corrected_mixed_refinement",
        lambda: phx.meshing.execute_mesh_adaptation(
            phx.meshing.prepare_mesh_adaptation(
                generated,
                phx.meshing.MarkedMeshAdaptation(core_ids[:1], layer_columns=columns),
                policy=policy,
            )
        ),
    )
    if (
        refinement.status is not phx.meshing.MeshAdaptationStatus.COMPLETE
        or refinement.hierarchy is None
    ):
        raise RuntimeError("The corrected curved mixed refinement was not complete.")
    active = set(
        np.concatenate(
            [np.asarray(block.global_ids) for block in refinement.target.mesh.blocks]
        ).tolist()
    )
    children = np.asarray(
        sorted(
            {
                child
                for entry in refinement.hierarchy.records
                for child in entry.child_ids
                if child in active
            }
        ),
        dtype=np.int64,
    )
    coarsening = _hybrid_qualification_stage(
        record,
        "corrected_mixed_inverse_coarsening",
        lambda: phx.meshing.execute_mesh_adaptation(
            phx.meshing.prepare_mesh_adaptation(
                refinement.target,
                phx.meshing.MarkedMeshAdaptation(
                    (),
                    children,
                    hierarchy=refinement.hierarchy,
                    layer_columns=_hybrid_qualification_columns(refinement.target),
                ),
                policy=policy,
            )
        ),
    )
    if coarsening.status is not phx.meshing.MeshAdaptationStatus.COMPLETE:
        raise RuntimeError("The corrected curved inverse coarsening was not complete.")
    if coarsening.target.mesh.topology_id != generated.mesh.topology_id:
        raise RuntimeError("The corrected lifecycle did not restore its source topology.")
    if (
        coarsening.target.geometry.source_coordinates()
        != generated.geometry.source_coordinates()
    ):
        raise RuntimeError(
            "The corrected lifecycle changed its authored source coefficients."
        )
    with TemporaryDirectory(prefix="native-corrected-curved-lineage-") as temporary:
        receipt = _hybrid_qualification_stage(
            record,
            "corrected_durable_source_archive",
            lambda: write_meshing_source_closure(
                Path(temporary) / "lifecycle",
                {
                    "certification_inputs": report.request,
                    "report": report,
                    "associations": generated.associations,
                    "generation_source": source,
                    "generation_specification": specification,
                    "generation_options": authored.options,
                    "generation_part": phx.meshing.MeshPart(
                        "corrected-curved-periodic-layer-core", generated
                    ),
                    "accepted_data": {"adaptation_results": (refinement, coarsening)},
                },
                retained_layer_core_plan=plan,
            ),
        )
        if receipt.validation_id is None or generated.execution_evidence is None:
            raise RuntimeError(
                "Corrected lifecycle archive lacks retained producer validation."
            )
        consumer = argparse.Namespace(**vars(args))
        consumer.hybrid_archive = str(receipt.path)
        consumer.hybrid_content_id = receipt.content_id
        consumer.hybrid_execution_controls = MeshingSourceExecutionControls(
            generated.execution_evidence,
            specification.limits,
            source.source_id,
            source.source_revision,
            specification.specification_id,
            source.binding_id,
            receipt.content_id,
        )
        _hybrid_qualification_archived_profile(consumer, record)
        record["archive"] = {
            "content_id": receipt.content_id,
            "source_revision": source.source_revision,
            "source_binding_id": source.binding_id,
            "restored_cold_continuation": True,
        }
    record["source"].update(
        {
            "source_digest": authored.source_digest,
            "mapped_domain_id": source.mapped_domain.domain_id,
            "wall_orbit_ids": list(authored.wall_orbit_ids),
            "coefficient_orbit_ids": list(authored.coefficient_orbit_ids),
        }
    )
    record["adaptation"] = {
        "refinement_id": refinement.result_id,
        "coarsening_id": coarsening.result_id,
        "restored_topology": True,
        "restored_source_coefficients": True,
    }
    record["implemented_admitted_workflow"] = (
        "corrected-curved-periodic-ADVANCING-layer-core-highorder-"
        "mixed-allfield-history-PDE-cold-continuation"
    )


def _hybrid_qualification_original_profile(args: argparse.Namespace) -> dict[str, object]:
    """Run original source profiles without borrowing the unit-box acceptance law."""
    import subprocess

    started = perf_counter()
    record: dict[str, Any] = {
        "scenario": "native-hybrid-lifecycle",
        "profile": args.hybrid_profile,
        "engine": "native",
        "runtime": _runtime_identity(),
        "status": "failed",
        "started": started,
        "active_phase": "original_source_preparation",
        "stages_seconds": {},
        "mandatory_workflow_completion": "incomplete",
        "release_evidence": "unassessed",
        "leadership_evidence": "unassessed",
        "preserved_original_source": {
            "source_id": "curved-periodic-narrow-gap",
            "required_period_x": 1,
            "exact_residuals": [
                "-101121/2361183241434822606848",
                "-6620711477/77371252455336267181195264",
            ],
            "disposition": "immutable-negative-refusal",
        },
        "targets": {"wall_seconds": args.timeout},
        "contract": _hybrid_qualification_profile_contracts()[args.hybrid_profile],
    }
    try:
        if not np.isfinite(args.timeout) or args.timeout <= 0.0:
            raise ValueError(
                "Original hybrid profiles require their positive finite original clock."
            )
        if args.hybrid_profile == "archived-layer-core" and (
            not args.hybrid_archive or not args.hybrid_content_id
        ):
            record["status"] = "blocked"
            record["missing_prerequisite"] = (
                "Exact authored archive path and content identity."
            )
            return record
        if args.hybrid_profile == "archived-layer-core":
            _hybrid_qualification_archived_profile(args, record)
        elif args.hybrid_profile == "concave-box-core-lifecycle":
            _hybrid_qualification_concave_lifecycle(args, record)
        elif args.hybrid_profile == "curved-periodic-layer-core":
            _hybrid_qualification_corrected_curved_lifecycle(args, record)
        elif args.hybrid_profile == "original-curved-periodic-refusal":
            owners = _hybrid_qualification_stage(
                record,
                "original_curved_periodic_exact_refusal",
                _hybrid_qualification_original_curved_refusal_profile,
            )
            record["source_profile"] = owners["evidence"]
            record["status"] = "passed"
        elif args.hybrid_profile in _hybrid_qualification_original_wall_profiles():
            owners = _hybrid_qualification_stage(
                record,
                "original_wall_layer_oracles",
                lambda: _hybrid_qualification_original_wall_profile(args.hybrid_profile),
            )
            record["source_profile"] = owners["evidence"]
            record["status"] = "passed"
        else:
            with TemporaryDirectory(prefix="native-original-layer-") as temporary:
                owners = _hybrid_qualification_stage(
                    record,
                    "original_sweep_source_oracles",
                    lambda: _hybrid_qualification_original_layer_sweep_profile(
                        args.hybrid_profile,
                        destination=Path(temporary) / "original-source.brep",
                    ),
                )
                record["source_profile"] = owners["evidence"]
                record["status"] = "passed"
    except (
        phx.meshing.MeshingFailure,
        RuntimeError,
        ValueError,
        TypeError,
        AssertionError,
        TimeoutError,
        subprocess.TimeoutExpired,
    ) as failure:
        record.update(_hybrid_qualification_failure(failure, record["active_phase"]))
        if isinstance(failure, (TimeoutError, subprocess.TimeoutExpired)):
            record["status"] = "timeout"
    finally:
        record["end_to_end_seconds"] = perf_counter() - started
        record["peak_process_resident_bytes"] = resource.getrusage(
            resource.RUSAGE_SELF
        ).ru_maxrss * (1 if sys.platform == "darwin" else 1024)
        contract = _record_mapping(record["contract"], "Hybrid profile contract")
        expected_admission = contract["expected_admission"]
        if expected_admission not in ("positive", "refusal"):
            raise ValueError("Hybrid profile admission must be positive or refusal.")
        record["expected_admission"] = expected_admission
        if (
            expected_admission == "positive"
            and contract.get("full_workflow") is not True
            and record["status"] == "passed"
        ):
            record["case_contract_completion"] = "complete"
            record["independent_scientific_certification"] = "passed"
        if expected_admission == "refusal" and record["status"] == "passed":
            evidence = _record_mapping(
                record["source_profile"], "Hybrid refusal source evidence"
            )
            receipts = evidence.get("receipts")
            if not (isinstance(receipts, list) and receipts or "rejection" in evidence):
                raise RuntimeError(
                    "Hybrid refusal profile omitted its owning refusal evidence."
                )
            record.update(
                {
                    "status": "expected-refusal",
                    "failure_evidence_id": canonical_fingerprint(evidence),
                    "requested": {"expected_admission": "refusal"},
                    "achieved": {"source_refusal": True},
                    "source_bits_preserved": True,
                }
            )
        if (
            contract.get("full_workflow") is True
            and expected_admission == "positive"
            and record["status"] == "passed"
        ):
            physical_error = record.get("physical_error")
            if (
                record.get("independent_scientific_certification") != "passed"
                or not isinstance(physical_error, float)
                or not np.isfinite(physical_error)
                or physical_error > args.target_error
            ):
                raise RuntimeError(
                    "Full hybrid workflow lacks passing independent physical evidence."
                )
            record["mandatory_workflow_completion"] = "complete"
        if record["end_to_end_seconds"] > args.timeout:
            record["status"] = "timeout"
            record["mandatory_workflow_completion"] = "incomplete"
        del record["started"]
        del record["active_phase"]
    return record


def _hybrid_qualification_profiles() -> tuple[str, ...]:
    return (
        "unit-box",
        "curved-periodic-layer-core",
        "original-curved-periodic-refusal",
        "archived-layer-core",
        "concave-box-core-lifecycle",
        *_hybrid_qualification_original_wall_profiles(),
        "cad-slab-and-core",
        "cad-entire-solid-slab",
        "cad-outside-controlled-solid",
        "cad-overlapping-wall-slabs",
        *(
            f"periodic-{periodicity}-{kind}"
            for periodicity in ("translation", "partial", "rotation")
            for kind in ("triangle", "quadrilateral")
        ),
        "periodic-convex-ridge",
        *(
            f"exact-sweep-{periodicity}-{outcome}"
            for periodicity in ("nonperiodic", "periodic")
            for outcome in ("accepted", "perturbed-cap")
        ),
    )


def _hybrid_qualification_profile_contracts() -> dict[str, dict[str, object]]:
    contracts: dict[str, dict[str, object]] = {
        profile: {
            "expected_admission": "positive",
            "expected_outcome": "passed",
            "contract_scope": "wall-layer-source",
            "full_workflow": False,
        }
        for profile in _hybrid_qualification_profiles()
    }
    contracts["unit-box"].update(
        contract_scope="native-wall-core-curving-adaptation-H1-diffusion"
    )
    contracts["archived-layer-core"].update(
        contract_scope="original-mixed-lineage-H1Q2-DG1-Hcurl2-Hdiv2-FV-history-PDE-defaultcold",
        full_workflow=True,
        prerequisites=("hybrid_archive", "hybrid_content_id"),
    )
    contracts["concave-box-core-lifecycle"].update(
        contract_scope="original-concave-wall-core-highorder-AMR-H1Q2-DG1-Hcurl2-Hdiv2-FV-history-PDE-defaultcold",
        full_workflow=True,
        prerequisites=(
            "hybrid_core_size",
            "hybrid_region_densities",
            "hybrid_material_site",
        ),
    )
    contracts["curved-periodic-layer-core"].update(
        contract_scope=(
            "corrected-curved-periodic-ADVANCING-layer-core-highorder-AMR-"
            "H1Q2-DG1-Hcurl2-Hdiv2-FV-history-PDE-defaultcold"
        ),
        full_workflow=True,
        source_controls={
            "layer_count": 2,
            "first_thickness": 0.01,
            "growth_rate": 1.0,
            "period_x": 1,
            "geometry_order": 2,
        },
    )
    contracts["concave_box_count3"].update(contract_scope="wall-layer-cap-core-source")
    for profile in (
        "cad-slab-and-core",
        "cad-entire-solid-slab",
        "cad-outside-controlled-solid",
        "cad-overlapping-wall-slabs",
    ):
        contracts[profile].update(contract_scope="native-CAD-exact-partition-source")
    for profile in (
        "exact-sweep-nonperiodic-accepted",
        "exact-sweep-nonperiodic-perturbed-cap",
        "exact-sweep-periodic-accepted",
        "exact-sweep-periodic-perturbed-cap",
    ):
        contracts[profile].update(contract_scope="independent-source-exact-sweep")
    for profile in (
        "original-curved-periodic-refusal",
        "wedge30_rejection",
        "channel_gap005_rejection",
        "cad-outside-controlled-solid",
        "cad-overlapping-wall-slabs",
        "exact-sweep-nonperiodic-perturbed-cap",
        "exact-sweep-periodic-perturbed-cap",
    ):
        contracts[profile].update(
            expected_admission="refusal", expected_outcome="expected-refusal"
        )
    return contracts


def _hybrid_qualification_requirements() -> dict[str, object]:
    """Bounded caller/parser contract, independent of mandatory-corpus claims."""
    return {
        "callable": "_hybrid_qualification_lifecycle",
        "profile_contracts": _hybrid_qualification_profile_contracts(),
        "required_arguments": {
            "hybrid_profile": {
                "choices": list(_hybrid_qualification_profiles()),
                "default": "unit-box",
            },
            "hybrid_archive": {"required_for": "archived-layer-core"},
            "hybrid_content_id": {"required_for": "archived-layer-core"},
            "hybrid_core_size": {
                "default": 0.1,
                "exclusive_minimum": 0.0,
                "finite": True,
            },
            "hybrid_region_densities": {
                "default": [2.0, 3.0],
                "source_authoritative": True,
            },
            "hybrid_material_site": {
                "default": "two-material-density",
                "source_authoritative": True,
            },
            "resolution": {"minimum": 2},
            "capacity": {"minimum": 1},
            "layer_count": {"minimum": 1, "default": 2},
            "first_thickness": {"exclusive_minimum": 0.0, "finite": True, "default": 0.1},
            "layer_growth": {"minimum": 1.0, "finite": True, "default": 1.0},
            "geometry_order": {"choices": [2, 3, 4, 6, 10], "default": 2},
            "adaptation_rounds": {"minimum": 1},
            "repeats": {"minimum": 1},
            "timeout": {"exclusive_minimum": 0.0, "finite": True},
            "target_error": {"exclusive_minimum": 0.0, "finite": True},
        },
        "schedule_constraint": "sum(first_thickness * layer_growth**k) < 1",
        "adaptation_rounds_semantics": "complete-mixed-refine-and-coarsen-cycles",
        "evidence_sections": [
            "case",
            "request",
            "generation",
            "curving",
            "epochs",
            "transitions",
            "rejection_retention",
            "invariants",
            "native_phases",
            "stages_seconds",
            "physical_error",
            "time_to_target_error_seconds",
            "peak_process_resident_bytes",
            "device_memory",
        ],
        "mandatory_workflow_completion": "incomplete",
        "nonclaims": [
            "The unit-box routine does not qualify nonlinear curved-wall geometry.",
            "The immutable original curved source remains an exact periodic refusal.",
            "The corrected profile does not relabel or repair the original source.",
            "A high-order map certificate is not a corners-only validity check.",
            "No release or performance leadership is inferred.",
        ],
    }


def _hybrid_qualification_stage(
    record: dict[str, Any],
    name: str,
    call: Callable[[], Any],
    /,
) -> Any:
    """Measure complete owned intervals; enforce the campaign deadline between them."""
    record["active_phase"] = name
    if perf_counter() - record["started"] >= record["targets"]["wall_seconds"]:
        raise TimeoutError(f"Hybrid lifecycle deadline reached before {name}.")
    value, measured = _measured(call)
    record["stages_seconds"][name] = measured["wall_seconds"]
    if perf_counter() - record["started"] > record["targets"]["wall_seconds"]:
        raise TimeoutError(f"Hybrid lifecycle deadline exceeded during {name}.")
    return value


def _hybrid_qualification_limits(args: argparse.Namespace) -> tuple[Any, Any]:
    limits = phx.meshing.MeshingLimits(
        maximum_vertices=args.capacity,
        maximum_cells=8 * args.capacity,
        maximum_edges=16 * args.capacity,
        maximum_faces=16 * args.capacity,
        maximum_connectivity_entries=128 * args.capacity,
        maximum_data_bytes=4096 * args.capacity,
        maximum_work_units=128 * args.capacity,
        maximum_cavity_cells=args.capacity,
        maximum_geometry_queries=128 * args.capacity,
        maximum_scratch_bytes=8192 * args.capacity,
        maximum_wall_seconds=args.timeout,
    )
    certificates = phx.geometry.MeshCertificateLimits(
        maximum_candidate_pairs=128 * args.capacity,
        maximum_ray_tests=512 * args.capacity,
        maximum_source_samples=32 * args.capacity,
        maximum_distance_evaluations=1024 * args.capacity,
        maximum_subdivision_pieces=128 * args.capacity,
        maximum_bernstein_nodes=32 * args.capacity,
    )
    return limits, certificates


def _hybrid_qualification_geometry(
    args: argparse.Namespace,
    record: dict[str, Any],
    phases: list[NativeMeshingPhaseMeasurement],
    limits: Any,
) -> tuple[Any, Any, Any, Any, dict[tuple[int, int], int], Any]:
    """Generate the complete native CAD boundary, then select its actual bottom wall."""
    model = _hybrid_qualification_stage(
        record,
        "native_cad_preparation",
        lambda: phx.geometry.brep_box(
            (0.0, 0.0, 0.0),
            (1.0, 1.0, 1.0),
            coordinate_contract=phx.SpatialCoordinateContract.si(),
            source_id="hybrid-unit-box",
        ),
    )
    domain = phx.geometry.MeshingDomain.from_brep(model)
    geometry = model.geometry
    if geometry is None:
        raise RuntimeError("Hybrid wall source requires native exact B-Rep authority.")
    vertices = np.asarray(geometry.vertex_points, dtype=np.float64)
    faces: dict[tuple[int, int], int] = {}
    for local, definition in enumerate(domain.source_indices[2]):
        loops = geometry.face_loops[definition]
        members = np.unique(
            [
                vertex
                for loop in loops
                for coedge in loop
                for vertex in geometry.edge_vertices[geometry.coedge_edges[coedge]]
            ]
        )
        for axis in range(3):
            for side in (0, 1):
                if np.all(vertices[members, axis] == side):
                    faces[axis, side] = int(domain.scope_indices(2)[local])
    if set(faces) != {(axis, side) for axis in range(3) for side in (0, 1)}:
        raise RuntimeError("Native unit-box source lost an exact boundary face.")
    scope = phx.meshing.MeshingScope(
        domain.source_id,
        domain.source_revision,
        phx.meshing.MeshingEntityKind.GEOMETRY,
        2,
        domain.entity_set_id(2),
        np.asarray(domain.scope_indices(2), dtype=np.int64),
    )
    request = phx.meshing.SurfaceMeshingSpec(
        phx.meshing.CellMeshingTarget(
            2, 3, phx.meshing.CellFamilyPolicy(required=("triangle",))
        ),
        scope,
        size_controls=(
            phx.meshing.UniformSizeControl(
                scope,
                1.0 / args.resolution,
                strength=phx.meshing.SizeControlStrength.SOFT,
            ),
        ),
        limits=limits,
    )
    provider = phx.meshing.NativeMeshingProvider(
        phx.meshing.NativeMeshingOptions("parametric_surface")
    )
    plan = _hybrid_qualification_stage(
        record,
        "wall_source_plan",
        lambda: provider.plan(
            phx.meshing.NativeSurfaceSource(domain),
            request,
            coordinate_contract=phx.SpatialCoordinateContract.si(),
            record_phase=phases.append,
        ),
    )
    boundary = _hybrid_qualification_stage(
        record,
        "native_wall_source_generation",
        lambda: plan.execute(record_phase=phases.append),
    )
    if boundary.certification is None or boundary.certification.request.source is None:
        raise RuntimeError(
            "Generated native wall lacks the original complete CAD source query."
        )
    query = boundary.certification.request.source
    points = np.asarray(boundary.mesh.coordinates, dtype=np.float64)
    triangles = np.concatenate(
        [np.asarray(block.vertices, dtype=np.int64) for block in boundary.mesh.blocks]
    )
    triangles = triangles[np.all(np.abs(points[triangles, 2]) <= 1.0e-12, axis=1)]
    rows = np.unique(triangles)
    if rows.size == 0:
        raise RuntimeError(
            "Native boundary generation produced no bottom-wall triangles."
        )
    wall_points = points[rows]
    triangles = np.searchsorted(rows, triangles)
    normals = np.cross(
        wall_points[triangles[:, 1]] - wall_points[triangles[:, 0]],
        wall_points[triangles[:, 2]] - wall_points[triangles[:, 0]],
    )
    triangles[normals[:, 2] < 0.0] = triangles[normals[:, 2] < 0.0][:, ::-1]
    wall = phx.discretization.CellMesh(
        wall_points, (phx.discretization.CellBlock("native-wall", "triangle", triangles),)
    )
    record["wall_source"] = {
        "result": _result_identity(boundary),
        "request_id": request.specification_id,
        "source_id": query.source_id,
        "source_revision": query.source_revision,
        "wall_mesh_id": wall.mesh_id,
        "wall_vertices": rows.size,
        "wall_triangles": triangles.shape[0],
        "authority_id": domain.authority_id,
    }
    return model, domain, query, scope, faces, wall


def _hybrid_qualification_core(
    layers: Any,
    domain: Any,
    query: Any,
    scope: Any,
    faces: dict[tuple[int, int], int],
) -> Any:
    """Build all core facets and exact cap identities, never a cap-only PLC."""
    if layers.cap is None:
        raise RuntimeError("The generated unit-box wall must have an open immutable cap.")
    points = np.asarray(layers.cap.coordinates, dtype=np.float64)
    cap = np.concatenate(
        [np.asarray(block.vertices, dtype=np.int64) for block in layers.cap.blocks]
    )
    edges = np.concatenate((cap[:, [0, 1]], cap[:, [1, 2]], cap[:, [2, 0]]))
    _, inverse, counts = np.unique(
        np.sort(edges, axis=1), axis=0, return_inverse=True, return_counts=True
    )
    rim = edges[counts[inverse] == 1]
    upper = points.copy()
    upper[:, 2] = 1.0
    count = points.shape[0]
    sides: list[tuple[int, int, int]] = []
    side_facets: list[int] = []
    side_keys = ((0, 0), (0, 1), (1, 0), (1, 1))
    for a, b in rim:
        selected = [
            facet
            for facet, (axis, side) in enumerate(side_keys, start=2)
            if np.all(np.abs(points[[a, b], axis] - side) <= 1.0e-12)
        ]
        if len(selected) != 1:
            raise RuntimeError(
                "Every cap rim edge must belong to one exact original side face."
            )
        sides.extend(
            ((int(a), int(b), int(b + count)), (int(a), int(b + count), int(a + count)))
        )
        side_facets.extend((selected[0], selected[0]))
    complex_ = phx.meshing.PiecewiseLinearComplex(
        np.concatenate((points, upper)),
        np.concatenate((cap, cap + count, np.asarray(sides, dtype=np.int64))),
        np.concatenate(
            (
                np.zeros(cap.shape[0], dtype=np.int64),
                np.ones(cap.shape[0], dtype=np.int64),
                np.asarray(side_facets, dtype=np.int64),
            )
        ),
        np.asarray(((0, -1), *((-1, 0),) * 5), dtype=np.int64),
        ("fluid",),
        boundary="fixed",
    )
    return phx.meshing.NativeLayerCoreSource(
        layers,
        complex_,
        domain.source_id,
        domain.source_revision,
        vertex_layer_ids=np.concatenate(
            (
                np.asarray(layers.cap_vertices, dtype=np.int64),
                np.full(count, -1, dtype=np.int64),
            )
        ),
        cap_polygon_ids=np.arange(cap.shape[0], dtype=np.int64),
        layer_regions=np.zeros(
            sum(block.cell_count for block in layers.mesh.blocks), dtype=np.int64
        ),
        source_boundary_scope=scope,
        source_domain=domain,
        fidelity_source=query,
        core_facet_source_ids=np.asarray(
            [-1, faces[2, 1], *(faces[key] for key in side_keys)], dtype=np.int64
        ),
    )


def _hybrid_qualification_generation(
    args: argparse.Namespace,
    record: dict[str, Any],
    phases: list[NativeMeshingPhaseMeasurement],
    limits: Any,
) -> tuple[Any, Any, Any, Any, Any]:
    model, domain, query, scope, faces, wall = _hybrid_qualification_geometry(
        args, record, phases, limits
    )
    projection = _hybrid_qualification_stage(
        record,
        "native_projection_preparation",
        lambda: phx.geometry.prepare_brep_projection(model),
    )
    association_policy = phx.meshing.AssociationPropagationPolicy(
        classification_tolerance=1.0e-8
    )
    wall_vertices = _hybrid_qualification_stage(
        record,
        "wall_cad_association",
        lambda: phx.meshing.associate_mesh_vertices(
            wall, projection, policy=association_policy
        ),
    )
    wall_association = _hybrid_qualification_stage(
        record,
        "wall_cad_face_association",
        lambda: phx.meshing.associate_mesh_entities(
            wall, wall_vertices, projection, 2, policy=association_policy
        ),
    )
    wall_scope = phx.meshing.MeshingScope(
        domain.source_id,
        domain.source_revision,
        phx.meshing.MeshingEntityKind.GEOMETRY,
        2,
        domain.entity_set_id(2),
        np.asarray([faces[2, 0]], dtype=np.int64),
    )
    schedule = phx.meshing.LayerSchedule.geometric(
        args.layer_count, args.first_thickness, growth_rate=args.layer_growth
    )
    control = phx.meshing.BoundaryLayerControl(
        wall_scope,
        schedule,
        route=phx.meshing.BoundaryLayerRoute.ADVANCING,
        collision=phx.meshing.BoundaryLayerCollisionPolicy.FAIL,
        growth_rate_bounds=(
            args.layer_growth * (1.0 - 1.0e-10),
            args.layer_growth * (1.0 + 1.0e-10),
        ),
    )
    layers = _hybrid_qualification_stage(
        record,
        "native_advancing_layers",
        lambda: phx.meshing.prepare_boundary_layers(
            wall,
            control,
            wall_association=wall_association,
            source_domain=domain,
            policy=phx.meshing.BoundaryLayerPolicy(
                visibility_iterations=128, proximity_samples=16
            ),
        ),
    )
    source = _hybrid_qualification_stage(
        record,
        "complete_plc_cap_preparation",
        lambda: _hybrid_qualification_core(layers, domain, query, scope, faces),
    )
    specification = phx.meshing.VolumeMeshingSpec(
        phx.meshing.CellMeshingTarget(
            3,
            3,
            phx.meshing.CellFamilyPolicy(
                required=("prism", "tetrahedron"), allow_mixed=True
            ),
        ),
        scope,
        phx.meshing.VolumeFillStrategy.SIMPLEX,
        size_controls=(
            phx.meshing.UniformSizeControl(
                scope,
                1.0 / args.resolution,
                strength=phx.meshing.SizeControlStrength.SOFT,
            ),
        ),
        layer_controls=(control,),
        limits=limits,
    )
    provider = phx.meshing.NativeMeshingProvider(
        phx.meshing.NativeMeshingOptions("layer_core")
    )
    record["case"] = {
        "case_id": canonical_fingerprint(
            {
                "source": source.binding_id,
                "schedule": schedule.schedule_id,
                "geometry_order": args.geometry_order,
                "limits": limits.limits_id,
            }
        ),
        "source_id": source.source_id,
        "source_revision": source.source_revision,
        "source_binding_id": source.binding_id,
        "cad_authority_id": domain.authority_id,
        "core_complex_id": source.complex.complex_id,
        "cap_id": layers.cap.mesh_id,
        "material_ids": ["fluid"],
        "independent_domain": "analytic-unit-box",
        "source_geometry": "native-exact-planar-BRep-faces",
        "hard_schedule": list(schedule.thicknesses),
        "layer_control_id": control.control_id,
        "cap_polygon_ids": source.cap_polygon_ids.tolist(),
        "cap_vertex_layer_ids": source.vertex_layer_ids[
            source.vertex_layer_ids >= 0
        ].tolist(),
        "core_facet_original_face_ids": source.core_facet_source_ids.tolist(),
        "layer_evidence": _layer_evidence(layers.evidence),
        "layer_validity": _cad_curving_certificate(layers.validity),
    }
    record["request"] = {
        "request_id": specification.specification_id,
        "limits_id": limits.limits_id,
        "native_options_id": provider.options.options_id,
        "required_families": ["prism", "tetrahedron"],
        "immutable_core_boundary": True,
    }
    record["request"]["limits"] = {
        "maximum_vertices": limits.maximum_vertices,
        "maximum_cells": limits.maximum_cells,
        "maximum_edges": limits.maximum_edges,
        "maximum_faces": limits.maximum_faces,
        "maximum_connectivity_entries": limits.maximum_connectivity_entries,
        "maximum_data_bytes": limits.maximum_data_bytes,
        "maximum_work_units": limits.maximum_work_units,
        "maximum_cavity_cells": limits.maximum_cavity_cells,
        "maximum_geometry_queries": limits.maximum_geometry_queries,
        "maximum_scratch_bytes": limits.maximum_scratch_bytes,
        "maximum_wall_seconds": limits.maximum_wall_seconds,
    }
    plan = _hybrid_qualification_stage(
        record,
        "core_geometry_constraint_preparation",
        lambda: provider.plan(
            source,
            specification,
            coordinate_contract=phx.SpatialCoordinateContract.si(),
            record_phase=phases.append,
        ),
    )
    record["request"]["prepared_id"] = plan.plan_id
    result = _hybrid_qualification_stage(
        record,
        "native_core_generation_publication",
        lambda: plan.execute(record_phase=phases.append),
    )
    record["generation"] = _result_identity(result)
    record["cap_identity"] = _hybrid_qualification_cap_identity(result, source)
    return result, source, projection, query, specification


def _hybrid_qualification_curving(
    result: Any,
    query: Any,
    projection: Any,
    args: argparse.Namespace,
    certificates: Any,
    record: dict[str, Any],
) -> Any:
    """Bind high-order curving and every successor to the independent full box."""
    from phydrax.meshing._lineage import identity_lineage

    vertices = np.asarray(
        phx.discretization.reference_cell_topology("hexahedron").vertices,
        dtype=np.float64,
    )
    faces = (
        (0, 3, 2, 1),
        (4, 5, 6, 7),
        (0, 1, 5, 4),
        (1, 2, 6, 5),
        (2, 3, 7, 6),
        (3, 0, 4, 7),
    )
    triangles = np.asarray(
        [row for a, b, c, d in faces for row in ((a, b, c), (a, c, d))], dtype=np.int64
    )
    domain = phx.geometry.PiecewiseLinearDomain(
        vertices,
        triangles,
        np.tile(np.asarray([0, -1], dtype=np.int64), (12, 1)),
        ("fluid",),
        source_id="independently-declared-hybrid-unit-box",
    )
    regions = np.zeros(
        sum(block.cell_count for block in result.mesh.blocks), dtype=np.int64
    )
    association = _hybrid_qualification_stage(
        record,
        "combined_cad_association",
        lambda: phx.meshing.associate_mesh_vertices(
            result.mesh,
            projection,
            policy=phx.meshing.AssociationPropagationPolicy(
                classification_tolerance=1.0e-8
            ),
        ),
    )
    policy = phx.meshing.HighOrderCurvingPolicy(
        degree=args.geometry_order,
        relaxation_rounds=0,
        fidelity_tolerance=1.0e-7,
        maximum_geometry_nodes=32 * args.capacity,
        maximum_tabulation_entries=1024 * args.capacity,
    )
    curved = _hybrid_qualification_stage(
        record,
        "high_order_curving_and_independent_certification",
        lambda: phx.meshing.curve_cell_mesh(
            result.mesh,
            association,
            projection,
            policy=policy,
            source=query,
            domain=domain,
            cell_regions=regions,
            certificate_limits=certificates,
        ),
    )
    record["curving"] = {
        "status": curved.status.value,
        "policy_id": policy.policy_id,
        "accepted": curved.evidence.accepted,
        "certification_failures": list(curved.evidence.certification_failures),
        "coordinate_map_certificate": _cad_curving_certificate(
            curved.evidence.certificate
        ),
        "certificate_limits_id": certificates.limits_id,
        "maximum_geometry_nodes": policy.maximum_geometry_nodes,
        "maximum_tabulation_entries": policy.maximum_tabulation_entries,
        "maximum_source_residual": curved.evidence.maximum_residual,
        "geometry_order": args.geometry_order,
        "domain_id": domain.domain_id,
        "source_query_id": query.source_id,
        "source_query_revision": query.source_revision,
        "nonlinear_curved_wall_qualification": "not-claimed",
    }
    if (
        curved.status is not phx.meshing.HighOrderCurvingStatus.CURVED
        or not curved.evidence.accepted
    ):
        raise RuntimeError(
            "Native hybrid high-order curving did not pass the complete source certificate."
        )
    inputs = phx.meshing.MeshCertificationInputs(
        result.mesh,
        result.geometry,
        phx.meshing.MeshCertificationSchedule("volume_layer"),
        domain=domain,
        cell_regions=regions,
        source=query,
        fidelity_tolerance=policy.fidelity_tolerance,
        limits=certificates,
    )
    return _hybrid_qualification_stage(
        record,
        "curved_canonical_publication",
        lambda: phx.meshing.certify_cell_mesh(
            result.mesh,
            result.coordinate_contract,
            geometry=curved.geometry,
            patches=result.patches,
            zones=result.zones,
            labels=result.labels,
            attributes=result.attributes,
            associations=(association,),
            region_evidence=result.region_evidence,
            region_boundary_evidence=result.region_boundary_evidence,
            certification_inputs=inputs,
            lineage=identity_lineage(result.mesh, result.mesh),
        ),
    )


def _hybrid_qualification_solver(result: Any) -> tuple[Any, Any, Any]:
    from examples.boundary_layer_core_mesh import exact_solution

    field = phx.discretization.FiniteElementFieldSpec(
        "u",
        {
            block.name: phx.discretization.lagrange_element(block.cell_kind, 1)
            for block in result.mesh.blocks
        },
    )
    space = phx.discretization.FiniteElementPlan(
        result.mesh, field, coordinate_spec=result.geometry
    ).prepare()
    constraint = phx.discretization.dirichlet_constraint(space, "u")
    form = phx.equations.FiniteElementForm(
        "qualified-hybrid-diffusion", "u", (phx.equations.DiffusionAction("u", 1.0),)
    )
    problem = phx.equations.compile_finite_element_problem(
        form, space, constraint=constraint, dirichlet_values=exact_solution
    )
    return space, problem, constraint.free_dofs


def _hybrid_qualification_physical(
    result: Any, space: Any, values: Any
) -> dict[str, float]:
    """Integrate actual mixed mapped fields against the independent analytic patch."""
    from examples.boundary_layer_core_mesh import exact_solution

    squared = 0.0
    integral = 0.0
    volume = 0.0
    for geometry, dofs in zip(
        space.evaluate_geometry("u", result.geometry.coordinates),
        space.dof_maps[0].cell_dofs,
        strict=True,
    ):
        local = np.asarray(values)[np.asarray(dofs)]
        evaluated = local @ np.asarray(geometry.basis_values).T
        weights = np.asarray(geometry.physical_weights, dtype=np.float64)
        exact = np.asarray(exact_solution(geometry.physical_points))
        squared += float(np.sum(weights * (evaluated - exact) ** 2))
        integral += float(np.sum(weights * evaluated))
        volume += float(np.sum(weights))
    return {
        "l2_error": float(np.sqrt(max(0.0, squared))),
        "state_integral": integral,
        "mapped_volume": volume,
        "analytic_volume_defect": volume - 1.0,
        "nodal_maximum_error": float(
            np.max(
                np.abs(
                    np.asarray(values)
                    - np.asarray(exact_solution(space.dof_maps[0].dof_coordinates))
                )
            )
        ),
    }


def _hybrid_qualification_acceptance(result: Any, source: Any) -> dict[str, object]:
    certificate = result.certification
    if certificate is None or not certificate.passed:
        raise RuntimeError("Hybrid result lacks strict complete certification.")
    coverage, fidelity, embedding = (
        certificate.coverage,
        certificate.fidelity,
        certificate.embedding,
    )
    if coverage is None or fidelity is None or embedding is None:
        raise RuntimeError(
            "Hybrid result lacks independent coverage, fidelity, or global embedding."
        )
    if (
        coverage.status != "certified"
        or fidelity.status != "certified"
        or embedding.status != "certified"
    ):
        raise RuntimeError("Hybrid source certificates are unresolved.")
    if (certificate.request.source_id, certificate.request.source_revision) != (
        source.source_id,
        source.source_revision,
    ):
        raise RuntimeError("Hybrid successor lost original CAD source authority.")
    if (
        not result.audit.validity.all_certified
        or not result.audit.passed
        or not result.compliance.passed
    ):
        raise RuntimeError(
            "Hybrid mapped-cell or canonical compliance certificate failed."
        )
    kinds = {block.cell_kind for block in result.mesh.blocks}
    if kinds != {"prism", "tetrahedron"}:
        raise RuntimeError(
            "Hybrid lifecycle substituted or lost a required mixed cell family."
        )
    if (
        coverage.region_ids != ("fluid",)
        or coverage.covered_source_facet_count != coverage.source_facet_count
    ):
        raise RuntimeError(
            "Hybrid source material or complete boundary coverage changed."
        )
    markers = {attribute.name: attribute for attribute in result.attributes}
    layer = markers["layer_index"]
    by_id = dict(
        zip(
            np.asarray(layer.scope.entity_ids).tolist(),
            np.asarray(layer.values).tolist(),
            strict=True,
        )
    )
    thicknesses = source.layers.control.schedule.thicknesses
    starts = np.concatenate((np.zeros(1, dtype=np.float64), np.cumsum(thicknesses)))
    points = np.asarray(result.mesh.coordinates, dtype=np.float64)
    defects = []
    for block in result.mesh.blocks:
        for identifier, corners in zip(
            np.asarray(block.global_ids),
            np.asarray(block.vertices),
            strict=True,
        ):
            interval = by_id[int(identifier)]
            if interval >= 0:
                heights = points[corners, 2]
                defects.extend(
                    (
                        abs(float(np.min(heights)) - starts[interval]),
                        abs(float(np.max(heights)) - starts[interval + 1]),
                    )
                )
    if not defects or max(defects) > 1.0e-10:
        raise RuntimeError("Hybrid mixed adaptation changed a hard layer interval.")
    return {
        "passed": True,
        "coverage_id": coverage.certificate_id,
        "source_fidelity_id": fidelity.certificate_id,
        "embedding_id": embedding.certificate_id,
        "source_id": certificate.request.source_id,
        "source_revision": certificate.request.source_revision,
        "domain_id": coverage.domain_id,
        "covered_source_facets": coverage.covered_source_facet_count,
        "source_facets": coverage.source_facet_count,
        "material_ids": list(coverage.region_ids),
        "requested_region_measures": list(coverage.requested_region_measures),
        "achieved_region_measures": list(coverage.achieved_region_measures),
        "hard_schedule_maximum_defect": float(max(defects)),
        "map_certificate": _cad_curving_certificate(result.audit.validity),
        "quality": _quality_summary(result.quality),
    }


def _hybrid_qualification_columns(result: Any) -> Any:
    attributes = {attribute.name: attribute for attribute in result.attributes}
    layer, column = attributes["layer_index"], attributes["layer_column"]
    columns = dict(
        zip(
            np.asarray(column.scope.entity_ids).tolist(),
            np.asarray(column.values).tolist(),
            strict=True,
        )
    )
    ids = np.asarray(layer.scope.entity_ids, dtype=np.int64)
    intervals = np.asarray(layer.values, dtype=np.int64)
    active = intervals >= 0
    return phx.meshing.MixedLayerColumns(
        ids[active],
        np.asarray(
            [columns[int(identifier)] for identifier in ids[active]], dtype=np.int64
        ),
        intervals[active],
        hard_first_thickness=True,
        axial_refinement=False,
    )


def _hybrid_qualification_cap_identity(result: Any, source: Any) -> dict[str, object]:
    """Recount the shared interface with exact row identities, not coordinate welding."""
    layers = source.layers
    rows = np.asarray(layers.cap_vertices, dtype=np.int64)
    if not np.array_equal(
        np.asarray(result.mesh.coordinates)[rows],
        np.asarray(layers.cap.coordinates),
    ):
        raise RuntimeError("Native core publication moved an immutable layer-cap vertex.")
    cap = rows[
        np.concatenate(
            [np.asarray(block.vertices, dtype=np.int64) for block in layers.cap.blocks]
        )
    ]
    incidence: dict[tuple[int, ...], list[str]] = {}
    for block in result.mesh.blocks:
        facets = phx.discretization.reference_cell_topology(block.cell_kind).entities[2]
        for cell in np.asarray(block.vertices, dtype=np.int64):
            for facet in facets:
                key = tuple(sorted(cell[np.asarray(facet, dtype=np.int64)].tolist()))
                incidence.setdefault(key, []).append(block.cell_kind)
    if any(
        sorted(incidence.get(tuple(sorted(face.tolist())), []))
        != ["prism", "tetrahedron"]
        for face in cap
    ):
        raise RuntimeError(
            "An immutable cap face lacks exactly one prism and one core tetrahedron."
        )
    return {
        "cap_mesh_id": layers.cap.mesh_id,
        "shared_vertex_rows": rows.tolist(),
        "bitwise_coordinates_retained": True,
        "shared_cap_faces": cap.shape[0],
        "incidence": "one-prism-and-one-tetrahedron",
        "identity_semantics": "explicit-layer-row-maps-without-tolerance-welding",
    }


def _hybrid_qualification_lineage(adaptation: Any) -> dict[str, object]:
    """Check each actual entity dimension; prism vertex count is not dimension."""
    lineage = adaptation.lineage
    source, target = adaptation.source.mesh, adaptation.target.mesh
    if lineage is None or tuple(
        relation.dimension for relation in lineage.entities
    ) != tuple(range(4)):
        raise RuntimeError("Hybrid mixed lineage omitted an actual entity dimension.")
    if (lineage.source_topology_id, lineage.target_topology_id) != (
        source.topology_id,
        target.topology_id,
    ):
        raise RuntimeError("Hybrid mixed lineage lost source/target topology identity.")
    dimensions = {}
    for relation in lineage.entities:
        before = np.asarray(source.entity_set(relation.dimension).entity_ids)
        after = np.asarray(target.entity_set(relation.dimension).entity_ids)
        created, deleted = (
            np.asarray(relation.created_target_ids),
            np.asarray(relation.deleted_source_ids),
        )
        if (
            not np.all(
                np.isin(
                    after, np.concatenate((before, relation.target_global_ids, created))
                )
            )
            or not np.all(
                np.isin(
                    before, np.concatenate((after, relation.source_global_ids, deleted))
                )
            )
            or not np.all(np.isin(created, after) & ~np.isin(created, before))
            or not np.all(np.isin(deleted, before) & ~np.isin(deleted, after))
        ):
            raise RuntimeError("Hybrid mixed lineage failed complete entity accounting.")
        dimensions[str(relation.dimension)] = {
            "relations": relation.relation_kinds.shape[0],
            "created": created.size,
            "deleted": deleted.size,
        }
    return {"lineage_id": lineage.lineage_id, "complete": True, "dimensions": dimensions}


def _hybrid_qualification_state_id(result: Any, values: Any) -> str:
    from phydrax._fingerprint import array_tree_fingerprint

    return canonical_fingerprint(
        {
            "result": result.result_id,
            "topology": result.mesh.topology_id,
            "arrays": array_tree_fingerprint(
                (
                    result.mesh.coordinates,
                    result.geometry.coordinates,
                    result.mesh.vertex_global_ids,
                    tuple(block.vertices for block in result.mesh.blocks),
                    tuple(block.global_ids for block in result.mesh.blocks),
                    values,
                )
            ),
        }
    )


def _hybrid_qualification_failure(failure: Exception, phase: str) -> dict[str, object]:
    record: dict[str, object] = {
        "failure_phase": phase,
        "failure_type": type(failure).__name__,
        "failure": str(failure),
    }
    if isinstance(failure, phx.meshing.MeshingFailure):
        evidence = failure.evidence
        record.update(
            {
                "failure_category": failure.category.value,
                "failure_evidence_id": evidence.evidence_id,
                "native_stage": evidence.stage,
                "provider_code": evidence.provider_code,
                "failing_entities": list(evidence.entity_ids),
                "requested": dict(evidence.requested),
                "achieved": dict(evidence.achieved),
                "locations": list(evidence.locations),
                "checkpoint_id": evidence.checkpoint_id,
            }
        )
    return record


def _hybrid_qualification_rejection(
    adapted: Any,
    values: Any,
    policy: Any,
    record: dict[str, Any],
    cycle: int,
) -> None:
    """An incomplete sibling request must retain the complete accepted state."""
    if adapted.hierarchy is None or not adapted.hierarchy.records:
        raise RuntimeError("Hybrid refinement did not publish complete sibling ancestry.")
    child = adapted.hierarchy.records[0].child_ids[0]
    source = adapted.target
    before = _hybrid_qualification_state_id(source, values)
    request = phx.meshing.MarkedMeshAdaptation(
        (),
        np.asarray([child], dtype=np.int64),
        hierarchy=adapted.hierarchy,
        layer_columns=_hybrid_qualification_columns(source),
    )
    prepared = _hybrid_qualification_stage(
        record,
        f"rejection_prepare_cycle_{cycle}",
        lambda: phx.meshing.prepare_mesh_adaptation(source, request, policy=policy),
    )
    refused = _hybrid_qualification_stage(
        record,
        f"rejection_execute_cycle_{cycle}",
        lambda: phx.meshing.execute_mesh_adaptation(prepared),
    )
    if refused.target.result_id != source.result_id or refused.transition is not None:
        raise RuntimeError(
            "Incomplete mixed sibling coarsening published a changed target."
        )
    if refused.evidence is None or child not in np.asarray(
        refused.evidence.rejected_coarsening_ids
    ):
        raise RuntimeError(
            "Incomplete mixed sibling refusal omitted the actual rejected child."
        )
    after = _hybrid_qualification_state_id(source, values)
    if before != after:
        raise RuntimeError(
            "Refused mixed coarsening changed accepted geometry, identities, or state."
        )
    record["rejection_retention"].append(
        {
            "cycle": cycle,
            "request_id": request.request_id,
            "status": refused.status.value,
            "rejected_coarsening_ids": np.asarray(
                refused.evidence.rejected_coarsening_ids
            ).tolist(),
            "accepted_result_id": source.result_id,
            "before_state_id": before,
            "after_state_id": after,
            "exact_retention": True,
        }
    )


def _hybrid_qualification_transition(
    result: Any,
    space: Any,
    values: Any,
    request: Any,
    policy: Any,
    source: Any,
    record: dict[str, Any],
    label: str,
    coarsening: bool,
) -> tuple[Any, Any, Any, Any, Any]:
    prepared = _hybrid_qualification_stage(
        record,
        f"{label}_prepare",
        lambda: phx.meshing.prepare_mesh_adaptation(result, request, policy=policy),
    )
    adaptation = _hybrid_qualification_stage(
        record, f"{label}_execute", lambda: phx.meshing.execute_mesh_adaptation(prepared)
    )
    if adaptation.transition is None or adaptation.geometry_transition is None:
        raise RuntimeError(
            "Hybrid mixed adaptation did not publish an actual geometry-preserving transition."
        )
    if not adaptation.geometry_transition.evidence.exact:
        raise RuntimeError(
            "Hybrid mixed refinement/coarsening changed the authoritative coordinate map."
        )
    acceptance = _hybrid_qualification_stage(
        record,
        f"{label}_source_recertification",
        lambda: _hybrid_qualification_acceptance(adaptation.target, source),
    )
    target_solver = _hybrid_qualification_stage(
        record,
        f"{label}_target_solver_preparation",
        lambda: _hybrid_qualification_solver(adaptation.target),
    )
    target_space, problem, free = target_solver
    transfer = _hybrid_qualification_stage(
        record,
        f"{label}_field_transfer_preparation",
        lambda: phx.discretization.prepare_nested_field_transfer(
            space,
            target_space,
            None if coarsening else adaptation.parent_cells,
            field_name="u",
            parent_reference_vertices=None
            if coarsening
            else adaptation.parent_reference_vertices,
            source_geometry=result.geometry,
            target_geometry=adaptation.target.geometry,
            geometry_transition=adaptation.geometry_transition,
        ),
    )
    if not transfer.evidence.passed:
        raise RuntimeError("Hybrid actual scalar H1 transfer certification failed.")
    carried = _hybrid_qualification_stage(
        record,
        f"{label}_actual_scalar_state_transfer",
        lambda: jax.block_until_ready(transfer.transfer.apply(values)),
    )
    from examples.boundary_layer_core_mesh import exact_solution

    probe = transfer.transfer.apply(exact_solution(space.dof_maps[0].dof_coordinates))
    linear_defect = float(
        jnp.max(jnp.abs(probe - exact_solution(target_space.dof_maps[0].dof_coordinates)))
    )
    constant_defect = float(
        jnp.max(jnp.abs(transfer.transfer.apply(jnp.ones_like(values)) - 1.0))
    )
    before = _hybrid_qualification_physical(result, space, values)
    after = _hybrid_qualification_physical(adaptation.target, target_space, carried)
    inventory_defect = after["state_integral"] - before["state_integral"]
    if max(linear_defect, constant_defect, abs(inventory_defect)) > 1.0e-9:
        raise RuntimeError(
            "Hybrid scalar patch transfer changed the actual field or its physical inventory."
        )
    record["transitions"].append(
        {
            "operation": label,
            "request_id": request.request_id,
            "prepared_id": prepared.prepared_id,
            "status": adaptation.status.value,
            "source": _result_identity(result),
            "target": _result_identity(adaptation.target),
            "acceptance": acceptance,
            "geometry_transition_id": adaptation.geometry_transition.transition_id,
            "exact_geometry_transfer": adaptation.geometry_transition.evidence.exact,
            "lineage": _hybrid_qualification_lineage(adaptation),
            "field": "u",
            "field_semantics": transfer.semantics,
            "constant_reproduction_defect": constant_defect,
            "linear_reproduction_defect": linear_defect,
            "source_state_integral": before["state_integral"],
            "target_state_integral": after["state_integral"],
            "state_inventory_defect": inventory_defect,
            "transferred_state_error": after["l2_error"],
            "retained_bytes": _bisection_retained_bytes((adaptation, transfer)),
            "general_coarsening_conservation": "not-claimed-scalar-patch-only",
        }
    )
    return adaptation, target_space, problem, free, carried


def _hybrid_qualification_epoch(
    result: Any,
    space: Any,
    problem: Any,
    free: Any,
    carried: Any,
    args: argparse.Namespace,
    record: dict[str, Any],
    name: str,
) -> Any:
    seed = (
        jnp.zeros((free.size,), dtype=result.mesh.coordinates.dtype)
        if carried is None
        else jnp.asarray(carried)[free]
    )
    solved = _hybrid_qualification_stage(
        record,
        f"{name}_solver_execution",
        lambda: _compiled_solver_stages(problem, seed, args.repeats),
    )
    values, compiler, timings = solved
    record["stages_seconds"].update(
        {f"{name}_{key}": value for key, value in timings.items()}
    )
    physical = _hybrid_qualification_stage(
        record,
        f"{name}_physical_error",
        lambda: _hybrid_qualification_physical(result, space, values),
    )
    if abs(physical["analytic_volume_defect"]) > 1.0e-10:
        raise RuntimeError(
            "Hybrid mapped volume differs from the independent analytic unit box."
        )
    record["epochs"].append(
        {
            "name": name,
            "result": _result_identity(result),
            "physical": physical,
            "dofs": space.dof_maps[0].global_dof_count,
            "free_dofs": free.size,
            "compiler": compiler,
            "seed_origin": "zero"
            if carried is None
            else "actual-transferred-scalar-H1-state",
            "retained_bytes": _bisection_retained_bytes(
                (result, space, problem, values, carried)
            ),
        }
    )
    record["physical_error"] = physical["l2_error"]
    if (
        physical["l2_error"] <= args.target_error
        and record["time_to_target_error_seconds"] is None
    ):
        record["time_to_target_error_seconds"] = perf_counter() - record["started"]
    return values


def _hybrid_qualification_epochs(
    result: Any,
    source: Any,
    projection: Any,
    specification: Any,
    args: argparse.Namespace,
    record: dict[str, Any],
) -> None:
    space, problem, free = _hybrid_qualification_stage(
        record, "initial_solver_preparation", lambda: _hybrid_qualification_solver(result)
    )
    values = _hybrid_qualification_epoch(
        result, space, problem, free, None, args, record, "initial"
    )
    policy = phx.meshing.MeshAdaptationPolicy(
        phx.meshing.MeshAdaptationRoute.NATIVE_MIXED,
        limits=specification.limits,
        association_transfer=phx.meshing.BRepAssociationTransfer(
            projection,
            policy=phx.meshing.AssociationPropagationPolicy(
                classification_tolerance=1.0e-8
            ),
        ),
    )
    for cycle in range(args.adaptation_rounds):
        root = result
        core_ids = np.concatenate(
            [
                np.asarray(block.global_ids, dtype=np.int64)
                for block in result.mesh.blocks
                if block.cell_kind == "tetrahedron"
            ]
        )
        request = phx.meshing.MarkedMeshAdaptation(
            core_ids, layer_columns=_hybrid_qualification_columns(result)
        )
        adaptation, space, problem, free, carried = _hybrid_qualification_transition(
            result,
            space,
            values,
            request,
            policy,
            source,
            record,
            f"refine_{cycle}",
            False,
        )
        result = adaptation.target
        values = _hybrid_qualification_epoch(
            result, space, problem, free, carried, args, record, f"refine_{cycle}"
        )
        _hybrid_qualification_rejection(adaptation, values, policy, record, cycle)
        children = np.asarray(
            sorted(
                {
                    child
                    for sibling in adaptation.hierarchy.records
                    for child in sibling.child_ids
                }
            ),
            dtype=np.int64,
        )
        request = phx.meshing.MarkedMeshAdaptation(
            (),
            children,
            hierarchy=adaptation.hierarchy,
            layer_columns=_hybrid_qualification_columns(result),
        )
        adaptation, space, problem, free, carried = _hybrid_qualification_transition(
            result,
            space,
            values,
            request,
            policy,
            source,
            record,
            f"coarsen_{cycle}",
            True,
        )
        result = adaptation.target
        values = _hybrid_qualification_epoch(
            result, space, problem, free, carried, args, record, f"coarsen_{cycle}"
        )
        if result.mesh.topology_id != root.mesh.topology_id:
            raise RuntimeError(
                "Complete hybrid sibling coarsening did not restore the original topology."
            )
        record["invariants"].append(
            {
                "cycle": cycle,
                "complete_refine_coarsen": True,
                "restored_topology_id": result.mesh.topology_id,
                "final_source_acceptance": _hybrid_qualification_acceptance(
                    result, source
                ),
            }
        )


def _hybrid_qualification_lifecycle(args: argparse.Namespace) -> dict[str, object]:
    """Callable native generated wall → curved mixed epochs → transferred-state PDE."""
    if getattr(args, "hybrid_profile", "unit-box") != "unit-box":
        return _hybrid_qualification_original_profile(args)
    counts = (
        args.resolution,
        args.capacity,
        args.layer_count,
        args.repeats,
        args.adaptation_rounds,
    )
    if (
        any(value < 1 for value in counts)
        or args.resolution < 2
        or args.geometry_order not in (2, 3, 4, 6, 10)
        or not all(
            np.isfinite(value) and value > 0.0
            for value in (
                args.first_thickness,
                args.layer_growth,
                args.timeout,
                args.target_error,
            )
        )
        or args.layer_growth < 1.0
    ):
        raise ValueError(
            "Hybrid controls require resolution >= 2, positive finite bounds, and admitted geometry order."
        )
    schedule = phx.meshing.LayerSchedule.geometric(
        args.layer_count, args.first_thickness, growth_rate=args.layer_growth
    )
    if sum(schedule.thicknesses) >= 1.0:
        raise ValueError(
            "The hard hybrid schedule must leave positive unit-box core height."
        )
    started = perf_counter()
    phases: list[NativeMeshingPhaseMeasurement] = []
    record: dict[str, Any] = {
        "scenario": "native-hybrid-lifecycle",
        "engine": "native",
        "status": "failed",
        "runtime": _runtime_identity(),
        "started": started,
        "active_phase": "source_preparation",
        "expected_admission": "positive",
        "targets": {"l2_error": args.target_error, "wall_seconds": args.timeout},
        "control_capacities": {
            "resolution": args.resolution,
            "entity_capacity": args.capacity,
            "layer_count": args.layer_count,
            "first_thickness": args.first_thickness,
            "layer_growth": args.layer_growth,
            "geometry_order": args.geometry_order,
            "adaptation_cycles": args.adaptation_rounds,
            "warm_repeats": args.repeats,
        },
        "manufactured_solution": {
            "exact": "x+y+z",
            "forcing": 0.0,
            "diffusion": 1.0,
            "norm": "mixed-mapped-physical-quadrature-L2-versus-analytic-patch",
            "declared_fields": ["scalar-H1-u"],
        },
        "stages_seconds": {},
        "epochs": [],
        "transitions": [],
        "invariants": [],
        "rejection_retention": [],
        "time_to_target_error_seconds": None,
        "physical_error": None,
        "target_error_reached": False,
        "independent_scientific_certification": "unassessed",
        "mandatory_workflow_completion": "incomplete",
        "release_evidence": "unassessed",
        "leadership_evidence": "unassessed",
        "nonclaims": _hybrid_qualification_requirements()["nonclaims"],
        "deadline_scope": "native-work-bounds-and-between-measured-phase-boundaries",
    }
    try:
        limits, certificates = _hybrid_qualification_limits(args)
        result, source, projection, query, specification = (
            _hybrid_qualification_generation(args, record, phases, limits)
        )
        record["generation_acceptance"] = _hybrid_qualification_acceptance(result, source)
        result = _hybrid_qualification_curving(
            result, query, projection, args, certificates, record
        )
        record["curved_acceptance"] = _hybrid_qualification_acceptance(result, source)
        _hybrid_qualification_epochs(
            result, source, projection, specification, args, record
        )
        record["target_error_reached"] = record["physical_error"] <= args.target_error
        record["status"] = "passed" if record["target_error_reached"] else "failed"
        record["independent_scientific_certification"] = "passed"
        record["implemented_admitted_workflow"] = (
            "native-wall-layer-core-curving-mixed-H1-state-diffusion"
        )
    except (
        phx.meshing.MeshingFailure,
        RuntimeError,
        ValueError,
        TypeError,
        TimeoutError,
    ) as failure:
        record.update(_hybrid_qualification_failure(failure, record["active_phase"]))
        if isinstance(failure, TimeoutError):
            record["status"] = "timeout"
    finally:
        record["native_phases"] = _phase_recordings(phases)
        record["end_to_end_seconds"] = perf_counter() - started
        record["peak_process_resident_bytes"] = resource.getrusage(
            resource.RUSAGE_SELF
        ).ru_maxrss * (1 if sys.platform == "darwin" else 1024)
        record["process_peak_scope"] = "process-lifetime"
        record["device_memory"] = [
            {
                "device_id": device.id,
                "platform": device.platform,
                "kind": device.device_kind,
                "status": "unavailable" if statistics is None else "backend-reported",
                "peak_bytes": None
                if statistics is None
                else statistics.get("peak_bytes_in_use"),
                "statistics": statistics,
            }
            for device in jax.local_devices()
            for statistics in (device.memory_stats(),)
        ]
        if record["end_to_end_seconds"] > args.timeout:
            record["status"] = "timeout"
        del record["active_phase"]
        del record["started"]
    return record


def _implicit_qualification_requirements() -> dict[str, object]:
    """Parser and evidence contract for the actual analytic restricted volume loop."""
    return {
        "callable": "_implicit_qualification_lifecycle",
        "required_arguments": {
            "resolution": {"minimum": 4},
            "capacity": {"minimum": 64},
            "repeats": {"minimum": 1},
            "adaptation_rounds": {"minimum": 1},
            "timeout": {"exclusive_minimum": 0.0, "finite": True},
            "target_error": {"exclusive_minimum": 0.0, "finite": True},
            "maximum_memory_bytes": {"minimum": 1},
            "implicit_radius": {
                "default": 0.371,
                "exclusive_minimum": 0.0,
                "finite": True,
            },
            "implicit_fidelity": {
                "default": 0.02,
                "exclusive_minimum": 0.0,
                "finite": True,
            },
            "implicit_maximum_level": {"default": 9, "minimum": 3, "maximum": 16},
            "implicit_edge_isolation_depth": {"default": 8, "minimum": 0},
            "implicit_root_tolerance": {
                "default": 1.0e-10,
                "exclusive_minimum": 0.0,
                "finite": True,
            },
            "implicit_refinement_rounds": {"default": 8, "minimum": 1},
            "implicit_improvement_passes": {"default": 8, "minimum": 1},
            "implicit_metric_passes": {"default": 16, "minimum": 1},
        },
        "restricted_dual_maximum_depth": 32,
        "restricted_dual_depth_owner": "_construct_implicit_restriction",
        "evidence_sections": [
            "source",
            "discovery",
            "request",
            "generation",
            "epochs",
            "native_phases",
            "stages_seconds",
            "failed_positive_attempts",
            "physical_error",
            "time_to_target_error_seconds",
            "peak_process_resident_bytes",
            "checkpoint",
        ],
        "hard_timeout_owner": "isolated qualification subprocess",
        "nonclaims": [
            "No generic Boolean/neural/periodic implicit-volume admission.",
            "No workset is a published volume or positive completion.",
            "No full mandatory corpus, release, or performance leadership claim.",
        ],
    }


def _implicit_qualification_fixture(
    args: argparse.Namespace,
) -> tuple[
    phx.geometry.CompiledGeometry,
    phx.meshing.NativeImplicitSource,
    phx.meshing.VolumeMeshingSpec,
    phx.meshing.NativeMeshingOptions,
    np.ndarray,
    phx.meshing.MeshQualityTarget,
]:
    """Freeze the analytic source and every hard physical and resource request."""
    from phydrax.meshing._volume_generation import NativeVolumeSchedule

    M, D = phx.meshing, phx.discretization
    radius = args.implicit_radius
    domain = np.asarray(((-1.2 * radius,) * 3, (1.2 * radius,) * 3), dtype=np.float64)
    geometry = phx.geometry.Sphere(
        (0.0, 0.0, 0.0), radius, feature_id="qualification-implicit-sphere"
    ).compile()
    revision = canonical_fingerprint(
        {
            "kind": "qualification-analytic-sphere",
            "radius": radius,
            "center": (0.0, 0.0, 0.0),
            "state": np.asarray(geometry.state.values),
            "domain": domain,
            "coordinates": phx.SpatialCoordinateContract.si().spatial_id,
        }
    )
    grid = D.TensorGridPlan(
        tuple(D.UniformAxisSpec(args.resolution + 1) for _ in range(3)),
        axis_names=("x", "y", "z"),
    ).prepare(jnp.asarray(domain, dtype=jnp.float64))
    source = M.NativeImplicitSource(
        geometry, grid, "qualification-implicit-sphere", revision
    )
    scope = M.MeshingScope(
        source.source_id,
        revision,
        M.MeshingEntityKind.GEOMETRY,
        2,
        "implicit-zero-set",
        np.asarray((0,), dtype=np.int64),
    )
    h = 2.0 * radius / args.resolution
    limits = M.MeshingLimits(
        maximum_vertices=args.capacity,
        maximum_edges=6 * args.capacity,
        maximum_faces=4 * args.capacity,
        maximum_cells=args.capacity,
        maximum_connectivity_entries=16 * args.capacity,
        maximum_data_bytes=args.maximum_memory_bytes,
        maximum_scratch_bytes=args.maximum_memory_bytes,
        maximum_work_units=256 * args.capacity,
        maximum_cavity_cells=args.capacity,
        maximum_geometry_queries=256 * args.capacity,
        maximum_wall_seconds=args.timeout,
    )
    request = M.VolumeMeshingSpec(
        M.CellMeshingTarget(3, 3, M.CellFamilyPolicy(required=("tetrahedron",))),
        scope,
        M.VolumeFillStrategy.SIMPLEX,
        size_controls=(
            M.UniformSizeControl(
                scope, h, maximum_size=1.5 * h, strength=M.SizeControlStrength.HARD
            ),
        ),
        size_compliance=M.SizeCompliancePolicy(relative_tolerance=0.5),
        protected_features=(
            M.ProtectedFeature(
                scope,
                M.FeatureKind.SURFACE,
                maximum_deviation=args.implicit_fidelity,
                hard=True,
            ),
        ),
        region_seeds=(
            M.RegionSeed(
                np.asarray((0.0, 0.0, 0.0), dtype=np.float64),
                "interior",
                "uniform-material",
                M.RegionRole.USER,
            ),
        ),
        limits=limits,
    )
    options = M.NativeMeshingOptions(
        "implicit_restricted_delaunay",
        volume_schedule=NativeVolumeSchedule(
            radius_edge_bound=2.0,
            minimum_dihedral_degrees=10.0,
            refinement_rounds=args.implicit_refinement_rounds,
            improvement_passes=args.implicit_improvement_passes,
        ),
    )
    quality = M.MeshQualityTarget(minimum_angle=np.deg2rad(1.0), hard=True)
    return geometry, source, request, options, domain, quality


def _implicit_qualification_acceptance(
    result: phx.meshing.CellMeshingResult,
    original: phx.meshing.CellMeshingResult,
    geometry: phx.geometry.CompiledGeometry,
    request: phx.meshing.VolumeMeshingSpec,
    quality: phx.meshing.MeshQualityTarget,
) -> dict[str, object]:
    """Require fresh source/projection/global/domain proofs and independent volume."""
    from phydrax.geometry._mesh_certificates import ImplicitProjectionBoundarySource
    from phydrax.geometry.implicit._analytic_profile import AnalyticImplicitProfile

    certificate = result.certification
    if (
        certificate is None
        or not certificate.passed
        or not result.audit.passed
        or not result.compliance.passed
    ):
        raise RuntimeError("Implicit volume lacks strict passing canonical publication.")
    embedding, coverage, fidelity = (
        certificate.embedding,
        certificate.coverage,
        certificate.fidelity,
    )
    if (
        embedding is None
        or coverage is None
        or fidelity is None
        or embedding.status != "certified"
        or coverage.status != "certified"
        or fidelity.status != "certified"
    ):
        raise RuntimeError(
            "Implicit volume lacks source fidelity, global embedding, or declared-domain coverage."
        )
    retained = certificate.request
    if original.certification is None:
        raise RuntimeError(
            "The original implicit result has no authoritative certification request."
        )
    reference = original.certification.request
    retained.validate_source_integrity()
    query = retained.source
    if not isinstance(query, ImplicitProjectionBoundarySource) or not isinstance(
        query.profile, AnalyticImplicitProfile
    ):
        raise RuntimeError(
            "Implicit successor discarded the owning analytic projection query."
        )
    profile = query.profile
    profile.require_bound(geometry, result.coordinate_contract)
    original_query = reference.source
    if (
        not isinstance(original_query, ImplicitProjectionBoundarySource)
        or not isinstance(original_query.profile, AnalyticImplicitProfile)
        or profile.profile_id != original_query.profile.profile_id
        or retained.source_id != reference.source_id
        or retained.source_revision != reference.source_revision
        or retained.domain is None
        or coverage.domain_id != retained.domain_id
        or retained.fidelity_tolerance != reference.fidelity_tolerance
        or retained.mesh_id != result.mesh.mesh_id
        or retained.topology_id != result.mesh.topology_id
    ):
        raise RuntimeError(
            "Implicit successor changed source/query/domain/request authority or retained a stale binding."
        )
    projection = fidelity.projection_coverage
    if (
        projection is None
        or projection.status != "certified"
        or projection.fiber_crossing_classes.count("interior") != profile.component_count
    ):
        raise RuntimeError("Source-enclosed component projection coverage is incomplete.")
    epsilon = projection.forward_upper
    if (
        not np.isfinite(epsilon)
        or epsilon > request.protected_features[0].maximum_deviation
        or epsilon >= profile.radius
    ):
        raise RuntimeError("Implicit source fidelity exceeds the frozen hard request.")
    mesh = result.mesh
    if len(mesh.blocks) != 1 or mesh.blocks[0].cell_kind != "tetrahedron":
        raise RuntimeError("Implicit diffusion requires one actual tetrahedral body.")
    points = np.asarray(mesh.coordinates, dtype=np.float64)
    cells = np.asarray(mesh.blocks[0].vertices, dtype=np.int64)
    corners = points[cells]
    signed = np.linalg.det(corners[:, 1:] - corners[:, :1]) / 6.0
    volume = float(np.sum(signed))
    lower = 4.0 * np.pi / 3.0 * (profile.radius - epsilon) ** 3
    upper = 4.0 * np.pi / 3.0 * (profile.radius + epsilon) ** 3
    connectivity = mesh.connectivity
    if not isinstance(connectivity, phx.discretization.TetrahedralConnectivity):
        raise TypeError(
            "Implicit acceptance requires canonical tetrahedral connectivity."
        )
    edges = np.asarray(connectivity.edges)
    lengths = np.linalg.norm(points[edges[:, 1]] - points[edges[:, 0]], axis=1)
    control = request.size_controls[0]
    if (
        not isinstance(control, phx.meshing.UniformSizeControl)
        or control.maximum_size is None
    ):
        raise ValueError(
            "Implicit qualification requires its frozen hard uniform maximum-size control."
        )
    maximum = control.maximum_size * (1.0 + request.size_compliance.relative_tolerance)
    if (
        np.any(signed <= 0.0)
        or not lower <= volume <= upper
        or float(np.max(lengths)) > maximum
        or result.quality.minimum_angle < quality.minimum_angle
    ):
        raise RuntimeError(
            "Implicit tetrahedra fail independent signed-volume, hard size, or hard quality acceptance."
        )
    return {
        "passed": True,
        "certificate_id": certificate.report_id,
        "embedding_id": embedding.certificate_id,
        "coverage_id": coverage.certificate_id,
        "fidelity_id": fidelity.certificate_id,
        "projection_id": projection.evidence_id,
        "profile_id": profile.profile_id,
        "source_id": retained.source_id,
        "source_revision": retained.source_revision,
        "domain_id": retained.domain_id,
        "original_approximation_domain_id": reference.domain_id,
        "target_approximation_domain_id": retained.domain_id,
        "source_request_id": retained.request_id,
        "original_source_request_id": reference.request_id,
        "source_state_id": profile.state_id,
        "source_query_preserved": True,
        "source_component_count": profile.component_count,
        "projection_fiber_classes": list(projection.fiber_crossing_classes),
        "projection_query_count": projection.query_count,
        "projection_ray_test_count": projection.ray_test_count,
        "coverage_semantics": "declared-restricted-approximation-domain",
        "source_fidelity_semantics": "original-analytic-source-degree-one-projection",
        "source_fidelity_upper": epsilon,
        "source_fidelity_tolerance": retained.fidelity_tolerance,
        "mesh_volume": volume,
        "analytic_volume": 4.0 * np.pi / 3.0 * profile.radius**3,
        "independent_volume_bounds": [lower, upper],
        "minimum_signed_cell_volume": float(np.min(signed)),
        "maximum_edge": float(np.max(lengths)),
        "quality": _quality_summary(result.quality),
    }


def _implicit_qualification_prepare_solver(
    result: phx.meshing.CellMeshingResult,
) -> tuple[
    phx.discretization.FiniteElementDiscretization,
    phx.equations.CompiledFiniteElementProblem,
    jax.Array,
    phx.discretization.FiniteElementFieldSpec,
]:
    """Configure the owning one-region FE diffusion formulation; no solver copy."""
    field = phx.discretization.FiniteElementFieldSpec(
        "u", phx.discretization.lagrange_element("tetrahedron", 1)
    )
    space = phx.discretization.FiniteElementPlan(
        result.mesh, field, coordinate_spec=result.geometry
    ).prepare()
    constraint = phx.discretization.dirichlet_constraint(space, "u")
    if not constraint.free_dofs.size:
        raise RuntimeError(
            "Implicit manufactured diffusion has no interior scalar H1 degrees of freedom."
        )
    form = phx.equations.FiniteElementForm(
        "analytic-implicit-manufactured-diffusion",
        "u",
        (
            phx.equations.DiffusionAction("u", 1.0),
            phx.equations.SourceAction(
                "u",
                phx.equations.coefficient(
                    _manufactured_source, coefficient_id="uniform-quadratic-laplacian-3D"
                ),
            ),
        ),
    )
    problem = phx.equations.compile_finite_element_problem(
        form, space, constraint=constraint, dirichlet_values=_manufactured_value
    )
    return space, problem, constraint.free_dofs, field


def _implicit_qualification_cold_process(
    path: str,
    content_id: str,
    repeats: int,
    target_error: float,
) -> dict[str, Any]:
    """Reopen and reanalyse actual accepted source state in a fresh interpreter."""
    from phydrax._fingerprint import array_tree_fingerprint
    from phydrax.lifecycle._meshing_sources import read_meshing_source_closure

    restored = read_meshing_source_closure(path, expected_content_id=content_id)
    cold, geometry, request, quality, fields = (
        restored[name] for name in ("result", "geometry", "request", "quality", "fields")
    )
    acceptance = _implicit_qualification_acceptance(
        cold, cold, geometry, request, quality
    )
    space, problem, free, _ = _implicit_qualification_prepare_solver(cold)
    continued, compiler, timings = _compiled_solver_stages(
        problem,
        jnp.asarray(fields[0])[free],
        repeats,
    )
    error = _physical_error(cold.mesh, continued)
    density_defect = float(jnp.max(jnp.abs(fields[1] - 2.0)))
    history_defect = float(
        jnp.max(jnp.abs(fields[2] - (space.dof_maps[0].dof_coordinates[:, 0] + 0.5)))
    )
    if error > target_error or density_defect > 1.0e-12 or history_defect > 1.0e-12:
        raise RuntimeError(
            "Cold continued PDE or restored allfield/history oracle failed."
        )
    peak = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
    return {
        "source_fingerprint": array_tree_fingerprint(geometry),
        "field_fingerprint": array_tree_fingerprint(fields),
        "request_id": request.specification_id,
        "quality_id": quality.target_id,
        "restored_result": _result_identity(cold),
        "source_acceptance": acceptance,
        "prepared_field_id": space.prepared_id,
        "compiler": compiler,
        "continued_physical_L2_error": error,
        "density_max_defect": density_defect,
        "history_max_defect": history_defect,
        "stages_seconds": timings,
        "peak_process_resident_bytes": peak * (1 if sys.platform == "darwin" else 1024),
        "interpreter": sys.executable,
        "process_id": os.getpid(),
    }


def _implicit_qualification_cold_reanalysis(
    geometry: phx.geometry.CompiledGeometry,
    result: phx.meshing.CellMeshingResult,
    request: phx.meshing.VolumeMeshingSpec,
    quality: phx.meshing.MeshQualityTarget,
    args: argparse.Namespace,
    record: dict[str, Any],
    values: jax.Array,
    auxiliary: tuple[jax.Array, jax.Array],
    started: float,
) -> None:
    """Restore scientific source, accepted carrier and every field without FE caches."""
    import subprocess

    from phydrax._array_archive import ArrayArchiveLimits
    from phydrax._fingerprint import array_tree_fingerprint
    from phydrax.lifecycle._meshing_sources import (
        write_meshing_source_closure,
    )

    limits = ArrayArchiveLimits()
    fields = (values, *auxiliary)
    records = {
        "geometry": geometry,
        "result": result,
        "request": request,
        "quality": quality,
        "fields": fields,
    }
    with TemporaryDirectory(prefix="phydrax-native-implicit-source-") as directory:
        record["active_phase"] = "allfield_history_checkpoint_publication"
        receipt, timing = _measured(
            lambda: write_meshing_source_closure(
                Path(directory) / "implicit.checkpoint.zip", records, limits=limits
            )
        )
        record["stages_seconds"][record["active_phase"]] = timing["wall_seconds"]
        record["active_phase"] = (
            "fresh_process_allfield_history_restore_and_continued_pde"
        )
        remaining = args.timeout - (perf_counter() - started)
        if remaining <= 0.0:
            raise phx.meshing.MeshingFailure(
                phx.meshing.MeshingFailureCategory.RESOURCE_EXHAUSTED,
                "The original implicit campaign clock expired before cold reanalysis.",
                stage=record["active_phase"],
            )
        script = """
import json
import sys
from tools.meshing_qualification import _implicit_qualification_cold_process
payload = _implicit_qualification_cold_process(sys.argv[1], sys.argv[2], int(sys.argv[3]), float(sys.argv[4]))
print(json.dumps(payload))
"""
        try:
            cold, timing = _measured(
                lambda: subprocess.run(
                    (
                        sys.executable,
                        "-c",
                        script,
                        str(receipt.path),
                        receipt.content_id,
                        str(args.repeats),
                        str(args.target_error),
                    ),
                    check=True,
                    capture_output=True,
                    text=True,
                    timeout=remaining,
                )
            )
        except subprocess.TimeoutExpired as failure:
            raise phx.meshing.MeshingFailure(
                phx.meshing.MeshingFailureCategory.RESOURCE_EXHAUSTED,
                "Cold reanalysis exhausted the remaining original campaign clock.",
                stage=record["active_phase"],
            ) from failure
        except subprocess.CalledProcessError as failure:
            raise RuntimeError(
                f"Cold implicit source/PDE reanalysis refused: {failure.stderr}"
            ) from failure
        restored = json.loads(cold.stdout)
        record["stages_seconds"][record["active_phase"]] = timing["wall_seconds"]
        if (
            restored["restored_result"] != _result_identity(result)
            or restored["request_id"] != request.specification_id
            or restored["quality_id"] != quality.target_id
            or restored["source_fingerprint"] != array_tree_fingerprint(geometry)
            or restored["field_fingerprint"] != array_tree_fingerprint(fields)
            or restored["process_id"] == os.getpid()
        ):
            raise RuntimeError(
                "Fresh implicit restore changed scientific source, controls or accepted fields."
            )
        if restored["peak_process_resident_bytes"] > args.maximum_memory_bytes:
            raise phx.meshing.MeshingFailure(
                phx.meshing.MeshingFailureCategory.RESOURCE_EXHAUSTED,
                "Cold reanalysis exceeded the original process-resident memory allowance.",
                stage=record["active_phase"],
                achieved=(
                    (
                        "peak_process_resident_bytes",
                        restored["peak_process_resident_bytes"],
                    ),
                ),
            )
        record["checkpoint"] = {
            "content_id": receipt.content_id,
            "container_bytes": receipt.path.stat().st_size,
            "archive_limits": {
                "members": limits.max_members,
                "nesting": limits.max_manifest_nesting,
                "rank": limits.max_array_rank,
            },
            "source_authority_stripped": False,
            "prepared_fe_caches_serialized": False,
            "field_names": ["u", "density", "history"],
            "accepted_fields_bitwise_preserved": True,
            "fresh_interpreter": restored,
        }


def _implicit_qualification_epochs(
    geometry: phx.geometry.CompiledGeometry,
    original: phx.meshing.CellMeshingResult,
    request: phx.meshing.VolumeMeshingSpec,
    quality: phx.meshing.MeshQualityTarget,
    args: argparse.Namespace,
    record: dict[str, Any],
    started: float,
) -> None:
    """Carry all accepted fields/history through metric edits and continue diffusion."""
    from phydrax.discretization.fem._point_interpolation import (
        prepare_finite_element_field_reconstruction,
    )
    from phydrax.geometry._supermesh import CommonRefinementPolicy

    current, carried = original, None
    auxiliary = None
    stages = record["stages_seconds"]
    for epoch in range(args.adaptation_rounds + 1):
        record["active_phase"] = f"source_certification_epoch_{epoch}"
        acceptance, timing = _measured(
            lambda: _implicit_qualification_acceptance(
                current, original, geometry, request, quality
            )
        )
        stages[record["active_phase"]] = timing["wall_seconds"]
        record["active_phase"] = f"solver_preparation_epoch_{epoch}"
        bundle, timing = _measured(
            lambda: _implicit_qualification_prepare_solver(current)
        )
        space, problem, free, _ = bundle
        stages[record["active_phase"]] = timing["wall_seconds"]
        seed = (
            jnp.zeros((free.size,), dtype=jnp.float64)
            if carried is None
            else jnp.asarray(carried)[free]
        )
        row: dict[str, Any] = {
            "epoch": epoch,
            "result": _result_identity(current),
            "acceptance": acceptance,
            "prepared_field_id": space.prepared_id,
            "compiled_problem_id": problem.compilation_id,
            "seed_origin": "zero"
            if carried is None
            else "actual-transferred-prior-diffusion-solution",
            "transferred_state_L2_error": None
            if carried is None
            else _physical_error(current.mesh, carried),
        }
        record["epochs"].append(row)
        record["active_phase"] = f"diffusion_solve_epoch_{epoch}"
        values, compiler, timings = _compiled_solver_stages(problem, seed, args.repeats)
        row["compiler"] = compiler
        stages.update({f"{name}_epoch_{epoch}": value for name, value in timings.items()})
        record["active_phase"] = f"independent_physical_error_epoch_{epoch}"
        error, timing = _measured(lambda: _physical_error(current.mesh, values))
        stages[record["active_phase"]] = timing["wall_seconds"]
        row.update(
            {
                "physical_L2_error": error,
                "free_dofs": free.size,
                "dofs": space.dof_maps[0].global_dof_count,
                "retained_bytes": _bisection_retained_bytes(
                    (current, space, problem, values, carried)
                ),
            }
        )
        if error <= args.target_error and record["time_to_target_error_seconds"] is None:
            record["time_to_target_error_seconds"] = perf_counter() - started
        record["physical_error"] = error
        if epoch == args.adaptation_rounds:
            break
        record["active_phase"] = f"metric_preparation_epoch_{epoch}"
        control = request.size_controls[0]
        if not isinstance(control, phx.meshing.UniformSizeControl):
            raise ValueError(
                "Implicit metric qualification requires the original uniform size control."
            )
        h = control.target_size / (2.0 ** ((epoch + 1) / 3.0))
        vertices = current.mesh.entity_set(0)
        scope = phx.meshing.MeshingScope(
            current.mesh.mesh_id,
            current.mesh.numeric_version,
            phx.meshing.MeshingEntityKind.MESH,
            0,
            vertices.entity_set_id,
            vertices.entity_ids,
        )
        tensors = np.broadcast_to(
            np.eye(3, dtype=np.float64) / h**2, (current.mesh.coordinates.shape[0], 3, 3)
        ).copy()
        metric = phx.meshing.MeshMetricField(
            scope, tensors, minimum_size=h, maximum_size=h, maximum_anisotropy=1.0
        )
        policy = phx.meshing.MeshAdaptationPolicy(
            phx.meshing.MeshAdaptationRoute.NATIVE_METRIC_3D,
            maximum_passes=args.implicit_metric_passes,
            relocation=True,
            limits=request.limits,
        )
        prepared, timing = _measured(
            lambda: phx.meshing.prepare_mesh_adaptation(
                current, phx.meshing.MetricMeshAdaptation(metric), policy=policy
            )
        )
        stages[record["active_phase"]] = timing["wall_seconds"]
        row["metric"] = {
            "metric_id": metric.metric_id,
            "target_size": h,
            "policy_id": policy.policy_id,
            "prepared_id": prepared.prepared_id,
        }
        record["active_phase"] = f"native_metric_execution_epoch_{epoch}"
        adaptation, timing = _measured(
            lambda: phx.meshing.execute_mesh_adaptation(prepared)
        )
        stages[record["active_phase"]] = timing["wall_seconds"]
        row["adaptation"] = {
            "result_id": adaptation.result_id,
            "status": adaptation.status.value,
            "target": _result_identity(adaptation.target),
            "compliance_passed": adaptation.compliance.passed,
            "retained_bytes": _bisection_retained_bytes((prepared, adaptation)),
        }
        if (
            not adaptation.status.converged
            or adaptation.transition is None
            or not adaptation.compliance.passed
        ):
            raise RuntimeError(
                f"Positive source-aware metric cycle did not complete: {adaptation.status.value}."
            )
        record["active_phase"] = f"target_source_acceptance_epoch_{epoch}"
        row["adaptation"]["acceptance"] = _implicit_qualification_acceptance(
            adaptation.target, original, geometry, request, quality
        )
        record["active_phase"] = f"allfield_history_composition_rebind_epoch_{epoch}"
        transferred, timing = _measured(
            lambda: _envelope_qualification_state_transition(
                current,
                adaptation,
                problem,
                values,
                epoch,
                auxiliary,
                projection_policy=CommonRefinementPolicy(
                    overlap_simplices=True,
                    maximum_candidate_pairs=256 * args.capacity,
                    maximum_accepted_pairs=256 * args.capacity,
                    maximum_memory_bytes=args.maximum_memory_bytes,
                ),
            )
        )
        stages[record["active_phase"]] = timing["wall_seconds"]
        carried, auxiliary, row["transfer"] = transferred
        row["transfer"]["state_L2_error"] = _physical_error(
            adaptation.target.mesh, carried
        )
        record["active_phase"] = f"prepared_scalar_query_epoch_{epoch}"
        reconstruction, timing = _measured(
            lambda: prepare_finite_element_field_reconstruction(space, "u")
        )
        stages[record["active_phase"]] = timing["wall_seconds"]
        sites = jnp.asarray(((0.0, 0.0, 0.0),), dtype=jnp.float64)
        query, timing = _measured(
            lambda: reconstruction.prepare_query(sites, coverage="complete")
        )
        stages[f"scalar_query_location_epoch_{epoch}"] = timing["wall_seconds"]
        sample, timing = _measured(lambda: jax.block_until_ready(query.apply(values)))
        stages[f"scalar_query_execution_epoch_{epoch}"] = timing["wall_seconds"]
        row["prepared_field_query"] = {
            "query_id": query.query_id,
            "values": np.asarray(sample).tolist(),
            "retained_bytes": _bisection_retained_bytes((reconstruction, query)),
            "origin": "actual-source-diffusion-state",
            "site": [0.0, 0.0, 0.0],
        }
        current = adaptation.target
    errors = [item["physical_L2_error"] for item in record["epochs"]]
    record["physical_error_convergence"] = {
        "errors": errors,
        "strictly_decreasing": all(b < a for a, b in zip(errors, errors[1:])),
        "target_met": errors[-1] <= args.target_error,
    }
    if (
        not record["physical_error_convergence"]["strictly_decreasing"]
        or errors[-1] > args.target_error
    ):
        raise RuntimeError(
            "Actual metric/transfer/diffusion lifecycle failed physical-error convergence or target."
        )
    if auxiliary is None:
        raise RuntimeError(
            "Implicit allfield/history continuation lost its accepted auxiliary fields."
        )
    _implicit_qualification_cold_reanalysis(
        geometry,
        current,
        request,
        quality,
        args,
        record,
        values,
        auxiliary,
        started,
    )


def _implicit_qualification_lifecycle(args: argparse.Namespace) -> dict[str, object]:
    """Execute certified discovery → strict native volume → metric/transfer/solve."""
    from dataclasses import asdict

    from phydrax.geometry.implicit import discover_adaptive_implicit_surface

    started = perf_counter()
    native: list[NativeMeshingPhaseMeasurement] = []
    record: dict[str, Any] = {
        "scenario": "native-implicit-lifecycle",
        "engine": "native",
        "status": "failed",
        "runtime": _runtime_identity(),
        "expected_admission": "positive",
        "requirements": _implicit_qualification_requirements(),
        "targets": {
            "physical_L2_error": args.target_error,
            "wall_seconds": args.timeout,
            "maximum_memory_bytes": args.maximum_memory_bytes,
        },
        "epochs": [],
        "stages_seconds": {},
        "failed_positive_attempts": [],
        "physical_error": None,
        "time_to_target_error_seconds": None,
        "mandatory_workflow_completion": "incomplete",
        "release_evidence": "unassessed",
        "leadership_evidence": "unassessed",
        "active_phase": "frozen_request_validation",
        "manufactured_diffusion": {
            "exact": "|x|^2",
            "forcing": -6.0,
            "conductivity": 1.0,
            "norm": "independent-exact-affine-P1-quadratic-L2",
        },
    }
    stages = record["stages_seconds"]
    try:
        positive = (
            args.timeout,
            args.target_error,
            args.implicit_radius,
            args.implicit_fidelity,
            args.implicit_root_tolerance,
        )
        if (
            any(not np.isfinite(value) or value <= 0.0 for value in positive)
            or args.resolution < 4
            or args.capacity < 64
            or args.repeats < 1
            or args.adaptation_rounds < 1
            or args.maximum_memory_bytes < 1
            or not 3 <= args.implicit_maximum_level <= 16
            or args.implicit_edge_isolation_depth < 0
            or min(
                args.implicit_refinement_rounds,
                args.implicit_improvement_passes,
                args.implicit_metric_passes,
            )
            < 1
        ):
            raise ValueError(
                "Implicit qualification requires finite positive targets and declared bounded capacities."
            )
        record["active_phase"] = "analytic_source_request_preparation"
        bundle, timing = _measured(lambda: _implicit_qualification_fixture(args))
        geometry, source, request, options, domain, quality = bundle
        stages[record["active_phase"]] = timing["wall_seconds"]
        discovery_policy = phx.geometry.AdaptiveImplicitSurfacePolicy(
            enclosure="interval",
            initial_level=2,
            minimum_surface_level=3,
            maximum_level=args.implicit_maximum_level,
            maximum_boxes=args.capacity,
            maximum_evaluations=64 * args.capacity,
            maximum_faces=args.capacity,
            maximum_intersection_pairs=32 * args.capacity,
            edge_isolation_depth=args.implicit_edge_isolation_depth,
            root_tolerance=args.implicit_root_tolerance,
            flatness_tolerance=args.implicit_fidelity,
        )
        record["source"] = {
            "source_id": source.source_id,
            "source_revision": source.source_revision,
            "radius": args.implicit_radius,
            "domain": domain.tolist(),
            "state_values": np.asarray(geometry.state.values).tolist(),
        }
        control = request.size_controls[0]
        schedule = options.volume_schedule
        if not isinstance(control, phx.meshing.UniformSizeControl) or schedule is None:
            raise RuntimeError(
                "The prepared implicit qualification lost its physical sizing or numerical schedule."
            )
        record["request"] = {
            "specification_id": request.specification_id,
            "limits_id": request.limits.limits_id,
            "options_id": options.options_id,
            "target_size": control.target_size,
            "size_control_id": control.control_id,
            "size_compliance_id": request.size_compliance.policy_id,
            "quality_target_id": quality.target_id,
            "hard_quality_minimum_angle": quality.minimum_angle,
            "hard_quality_owner": "canonical-MeshQualityTarget-independent-qualification-gate",
            "volume_spec_quality_enforcement": "not-declared-by-current-VolumeMeshingSpec",
            "qualification_request_id": canonical_fingerprint(
                {
                    "volume_request": request.specification_id,
                    "hard_quality": quality.target_id,
                }
            ),
            "fidelity_feature_id": request.protected_features[0].feature_id,
            "discovery_policy": asdict(discovery_policy),
            "source_authority_stripped": False,
        }
        record["request"]["resource_budgets"] = {
            "vertices": args.capacity,
            "cells": args.capacity,
            "edges": 6 * args.capacity,
            "faces": 4 * args.capacity,
            "connectivity_entries": 16 * args.capacity,
            "work_units": 256 * args.capacity,
            "geometry_queries": 256 * args.capacity,
            "cavity_cells": args.capacity,
            "data_bytes": args.maximum_memory_bytes,
            "scratch_bytes": args.maximum_memory_bytes,
            "wall_seconds": args.timeout,
        }
        record["request"]["volume_schedule"] = {
            "schedule_id": schedule.schedule_id,
            "radius_edge_bound": 2.0,
            "minimum_dihedral_degrees": 10.0,
            "refinement_rounds": args.implicit_refinement_rounds,
            "improvement_passes": args.implicit_improvement_passes,
            "restricted_dual_maximum_depth": 32,
            "restricted_dual_spatial_tolerance": args.implicit_fidelity * 1.0e-3,
        }
        record["active_phase"] = "certified_adaptive_discovery"
        discovery, timing = _measured(
            lambda: discover_adaptive_implicit_surface(
                geometry,
                domain=domain,
                policy=discovery_policy,
                source_id=source.source_id,
            )
        )
        stages[record["active_phase"]] = timing["wall_seconds"]
        evidence = discovery.evidence
        record["discovery"] = {
            "evidence_id": evidence.evidence_id,
            "accuracy": evidence.accuracy,
            "status": evidence.status,
            "unresolved_boxes": np.asarray(evidence.unresolved_boxes).tolist(),
            "unresolved_issues": np.asarray(evidence.unresolved_issues).tolist(),
            "domain_query_id": discovery.volume.query_id,
            "leaf_count": evidence.leaf_count,
            "box_evaluations": evidence.box_evaluations,
            "point_evaluations": evidence.point_evaluations,
            "extraction_evaluations": evidence.extraction_evaluations,
            "retained_bytes": _bisection_retained_bytes(discovery),
            "extracted_surface_used_for_fill": False,
        }
        if (
            evidence.accuracy != "certified"
            or discovery.topology is None
            or evidence.unresolved_boxes.shape[0]
        ):
            raise RuntimeError(
                "Positive certified discovery remained uncertain; no workset or extraction substitutes for volume."
            )
        record["active_phase"] = "certified_domain_queries"
        classified, timing = _measured(
            lambda: discovery.volume.classify_boxes(
                np.asarray(
                    ((0.0, 0.0, 0.0), (1.1 * args.implicit_radius,) * 3), dtype=np.float64
                ),
                np.asarray(
                    ((0.0, 0.0, 0.0), (1.1 * args.implicit_radius,) * 3), dtype=np.float64
                ),
            )
        )
        stages[record["active_phase"]] = timing["wall_seconds"]
        classes = np.asarray(classified.classes)
        record["discovery"]["domain_probe_classes"] = classes.tolist()
        if not np.array_equal(
            classes,
            (
                int(phx.geometry.ImplicitVolumeClass.INSIDE),
                int(phx.geometry.ImplicitVolumeClass.OUTSIDE),
            ),
        ):
            raise RuntimeError(
                "Source-enclosed interior/exterior domain probes were not certified."
            )
        record["active_phase"] = "native_restricted_volume_preparation"
        plan, timing = _measured(
            lambda: phx.meshing.NativeMeshingProvider(options).plan(
                source,
                request,
                coordinate_contract=phx.SpatialCoordinateContract.si(),
                record_phase=native.append,
            )
        )
        stages[record["active_phase"]] = timing["wall_seconds"]
        record["plan_id"] = plan.plan_id
        from phydrax.meshing._implicit_volume import PreparedImplicitVolume

        prepared_volume = plan.prepared
        if not isinstance(prepared_volume, PreparedImplicitVolume):
            raise TypeError(
                "The declared restricted volume route must retain its actual owning preparation."
            )
        record["active_phase"] = "native_restricted_volume_publication"
        current, timing = _measured(lambda: plan.execute(record_phase=native.append))
        stages[record["active_phase"]] = timing["wall_seconds"]
        record["generation"] = _result_identity(current)
        record["retained_plan_bytes"] = _bisection_retained_bytes((source, plan))
        record["restricted_source"] = {
            "domain_query_id": prepared_volume.query.query_id,
            "profile_id": prepared_volume.profile.profile_id,
            "prepared_id": prepared_volume.prepared_id,
            "query_certified": prepared_volume.query.certified,
            "seed_cover_radius": prepared_volume.seed_cover_radius,
            "actual_fidelity_tolerance": prepared_volume.fidelity_tolerance,
            "surface_extraction_used_as_source": False,
        }
        _implicit_qualification_epochs(
            geometry, current, request, quality, args, record, started
        )
        record["status"] = "passed"
        record["implemented_admitted_workflow"] = (
            "analytic-sphere-restricted-tetra-metric-allfield-history-rollback-diffusion-cold-reanalysis"
        )
    except (phx.meshing.MeshingFailure, RuntimeError, ValueError, TypeError) as failure:
        detail: dict[str, Any] = {
            "phase": record["active_phase"],
            "message": str(failure),
            "type": type(failure).__name__,
            "category": None,
            "evidence_id": None,
            "native_stage": None,
            "provider_code": None,
            "entity_ids": [],
            "requested": {},
            "achieved": {},
            "locations": [],
            "checkpoint_id": None,
        }
        if isinstance(failure, phx.meshing.MeshingFailure):
            evidence = failure.evidence
            detail.update(
                {
                    "category": failure.category.value,
                    "evidence_id": evidence.evidence_id,
                    "native_stage": evidence.stage,
                    "provider_code": evidence.provider_code,
                    "entity_ids": list(evidence.entity_ids),
                    "requested": dict(evidence.requested),
                    "achieved": dict(evidence.achieved),
                    "locations": list(evidence.locations),
                    "checkpoint_id": evidence.checkpoint_id,
                }
            )
        record["failure"] = detail
        record["failed_positive_attempts"].append(detail)
    finally:
        record["native_phases"] = _phase_recordings(native)
        record["end_to_end_seconds"] = perf_counter() - started
        record["peak_process_resident_bytes"] = resource.getrusage(
            resource.RUSAGE_SELF
        ).ru_maxrss * (1 if sys.platform == "darwin" else 1024)
        record["memory_scope"] = (
            "process-lifetime-peak; per-artifact distinct-leaf retained bytes separate"
        )
        record["device_memory"] = [
            {
                "device_id": device.id,
                "status": "unavailable" if statistics is None else "backend-reported",
                "statistics": statistics,
            }
            for device in jax.local_devices()
            for statistics in (device.memory_stats(),)
        ]
        for exceeded, status, label in (
            (record["end_to_end_seconds"] > args.timeout, "timeout", "wall"),
            (
                record["peak_process_resident_bytes"] > args.maximum_memory_bytes,
                "failed",
                "memory",
            ),
        ):
            if exceeded:
                record["status"] = status
                detail = {
                    "phase": record["active_phase"],
                    "message": f"Frozen {label} budget exceeded.",
                    "type": "ResourceBudgetExceeded",
                    "category": "resource_exhausted",
                    "evidence_id": None,
                    "native_stage": None,
                    "provider_code": None,
                    "entity_ids": [],
                    "requested": record["targets"],
                    "achieved": {
                        "wall_seconds": record["end_to_end_seconds"],
                        "peak_process_resident_bytes": record[
                            "peak_process_resident_bytes"
                        ],
                    },
                    "locations": [],
                    "checkpoint_id": None,
                }
                record["failure"] = detail
                record["failed_positive_attempts"].append(detail)
        if record["status"] != "passed":
            record["failure_phase"] = record["active_phase"]
            record["time_to_target_error_seconds"] = None
        record["counts"] = {
            "passed": int(record["status"] == "passed"),
            "failed": int(record["status"] == "failed"),
            "timeout": int(record["status"] == "timeout"),
            "uncertainty_or_refusal_is_positive": False,
        }
        del record["active_phase"]
    return record


def _distributed_qualification_stage[T](
    record: dict[str, Any],
    name: str,
    call: Callable[[], T],
    started: float,
    timeout: float,
) -> T:
    """Measure an actual call and preserve the exact phase on failure."""
    record["active_phase"] = name
    if perf_counter() - started >= timeout:
        raise TimeoutError("Distributed lifecycle exhausted its frozen wall deadline.")
    stage_started = perf_counter()
    try:
        value, timing = _measured(call)
    finally:
        record["stages_seconds"][name] = perf_counter() - stage_started
        record["stage_peak_process_bytes"][name] = resource.getrusage(
            resource.RUSAGE_SELF
        ).ru_maxrss * (1 if sys.platform == "darwin" else 1024)
    record["stages_seconds"][name] = timing["wall_seconds"]
    record["stage_peak_process_bytes"][name] = timing["peak_resident_bytes"]
    record["attempts"].append({"phase": name, "status": "passed"})
    if perf_counter() - started >= timeout:
        raise TimeoutError("Distributed lifecycle exhausted its frozen wall deadline.")
    return value


def _distributed_qualification_generate(
    args: argparse.Namespace,
    record: dict[str, Any],
    phases: list[NativeMeshingPhaseMeasurement],
    started: float,
) -> tuple[Any, Any, Any, Any]:
    """Freeze one authored source/request/options and consume exactly its accepted provider result."""
    source, request, options = _distributed_qualification_stage(
        record,
        "source_preparation",
        lambda: _distributed_qualification_source(args),
        started,
        args.timeout,
    )
    record["source"] = {
        "source_id": source.source_id,
        "source_revision": source.source_revision,
        "source_binding_id": source.binding_id,
        "request_id": request.specification_id,
        "coordinate_contract_id": phx.SpatialCoordinateContract.si().spatial_id,
        "control_ids": [control.control_id for control in request.size_controls],
        "quality_target_id": request.quality_target.target_id,
        "limits_id": request.limits.limits_id,
    }
    provider = phx.meshing.NativeMeshingProvider(options)
    plan = _distributed_qualification_stage(
        record,
        "geometry_constraint_preparation",
        lambda: provider.plan(
            source,
            request,
            coordinate_contract=phx.SpatialCoordinateContract.si(),
            record_phase=phases.append,
        ),
        started,
        args.timeout,
    )
    result = _distributed_qualification_stage(
        record,
        "native_generation_publication_certification",
        lambda: plan.execute(record_phase=phases.append),
        started,
        args.timeout,
    )
    result.audit.require_passed()
    if not result.compliance.passed or result.certification is None:
        raise RuntimeError(
            "Native distributed source lacks actual source/control acceptance."
        )
    result.certification.require_passed()
    cells = _mesh_triangles(result.mesh)
    coordinates = np.asarray(result.mesh.coordinates)
    measures = _simplex_measures(coordinates, cells)
    connectivity = result.mesh.connectivity
    if not isinstance(connectivity, phx.discretization.PolygonalConnectivity):
        raise TypeError(
            "The distributed unit-square source requires planar polygonal connectivity."
        )
    edge_rows = np.asarray(connectivity.boundary_edges)
    edges = np.asarray(connectivity.edges)[edge_rows]
    perimeter = float(
        np.sum(
            np.linalg.norm(coordinates[edges[:, 1]] - coordinates[edges[:, 0]], axis=1)
        )
    )
    area = float(np.sum(measures))
    if (
        np.any(measures <= 0.0)
        or abs(area - 1.0) > 1.0e-10
        or abs(perimeter - 4.0) > 1.0e-10
    ):
        raise RuntimeError(
            "Provider source disagrees with independent unit-square area/orientation/boundary."
        )
    record["generation"] = {
        **_result_identity(result),
        "plan_id": plan.plan_id,
        "certification_id": result.certification.report_id,
        "independent_area": area,
        "independent_perimeter": perimeter,
    }
    return source, request, options, result


def _distributed_qualification_entity_cells(mesh: Any, /) -> np.ndarray:
    """Cell vertex rows in the mesh's cell entity order across all blocks."""
    ids = np.concatenate(
        [np.asarray(block.global_ids, dtype=np.int64) for block in mesh.blocks]
    )
    vertices = np.concatenate(
        [np.asarray(block.vertices, dtype=np.int64) for block in mesh.blocks]
    )
    order = np.argsort(ids, kind="stable")
    entity_ids = np.asarray(
        mesh.entity_set(mesh.topological_dimension).entity_ids, dtype=np.int64
    )
    return vertices[order[np.searchsorted(ids[order], entity_ids)]]


def _distributed_qualification_fe_declaration() -> tuple[tuple[Any, ...], Any]:
    """Declare the one physical P1 temperature field and its precision policy."""
    from phydrax.discretization.fem._generic import FiniteElementFieldSpec
    from phydrax.discretization.fem._precision import FiniteElementPrecisionPolicy
    from phydrax.discretization.fem._reference import lagrange_element

    return (
        FiniteElementFieldSpec("temperature", lagrange_element("triangle", 1)),
    ), FiniteElementPrecisionPolicy()


def _distributed_qualification_fe(
    carrier: Any,
    fields: tuple[Any, ...],
    precision: Any,
    numeric_version: str,
) -> Any:
    """Prepare the declared physical field space on one accepted carrier."""
    from phydrax.discretization.fem._generic import FiniteElementPlan

    return FiniteElementPlan(
        carrier.mesh,
        fields,
        coordinate_spec=carrier.geometry,
        precision_policy=precision,
    ).prepare(numeric_version=numeric_version)


def _distributed_qualification_policy(
    policy: Any, distribution: Any, partition: Any
) -> Any:
    """Rebind one frozen adaptation policy to an accepted distribution and partition request."""
    return phx.meshing.MeshAdaptationPolicy(
        policy.route,
        protected_scopes=policy.protected_scopes,
        compatibility=policy.compatibility,
        predicate_mode=policy.predicate_mode,
        maximum_passes=policy.maximum_passes,
        maximum_closure_iterations=policy.maximum_closure_iterations,
        relocation=policy.relocation,
        limits=policy.limits,
        audit_policy=policy.audit_policy,
        device_policy=policy.device_policy,
        provider=policy.provider,
        provider_options=policy.provider_options,
        distribution=distribution,
        partition_policy=partition,
        association_transfer=policy.association_transfer,
        geometry_transition=policy.geometry_transition,
    )


def _distributed_qualification_histories(
    fields: _DistributedFields,
    association: str,
) -> tuple[jax.Array, ...]:
    """Allocated history banks of one association in their repack history-index order."""
    rows = sorted(
        (row for row in _DISTRIBUTED_FIELD_ROLES if row[5] == association),
        key=lambda row: row[6],
    )
    return tuple(jnp.asarray(fields[row[1]]) for row in rows)


def _distributed_qualification_project(
    carrier: Any,
    values: _DistributedFields,
    baselines: _DistributedFields,
    fe_fields: tuple[Any, ...],
    precision: Any,
    mesh_epoch: int,
) -> tuple[Any, tuple[Any, ...], _DistributedFields]:
    """Project every compact physical role into its stable-ID allocated history bank."""
    from phydrax.lifecycle._meshing_field_records import (
        MeshingFieldStateRole,
        prepare_meshing_field_index_binding,
        project_meshing_field_history,
    )

    physical = _distributed_qualification_fe(
        carrier, fe_fields, precision, f"accepted-{mesh_epoch}"
    )
    space = physical.field_spaces[0]
    material = values["material-temperature"]
    compact_values = {
        **values,
        "essential-mask": physical.dof_maps[0].boundary_dof_mask,
        "material-cell-average": jnp.mean(
            material[jnp.asarray(_distributed_qualification_entity_cells(carrier.mesh))],
            axis=1,
        ),
    }
    roles: list[Any] = []
    fields: _DistributedFields = {
        "accepted-epoch": jnp.asarray(mesh_epoch, dtype=jnp.int64)
    }
    for (
        name,
        raw_name,
        kind,
        raw_kind,
        bank,
        association,
        _,
        indexed,
        _,
        units,
    ) in _DISTRIBUTED_FIELD_ROLES:
        value = compact_values[name]
        field_space = space if indexed else None
        value_units = None if units is None else (phx.units.KELVIN,)
        compact_index = prepare_meshing_field_index_binding(
            carrier, bank, field_space=field_space
        )
        raw_index = prepare_meshing_field_index_binding(
            carrier, f"epoch/{association}_ids"
        )
        compact = MeshingFieldStateRole(
            name,
            "temperature",
            kind,
            value.shape,
            np.dtype(value.dtype),
            mesh_epoch,
            value_units=value_units,
            index_binding=compact_index,
        )
        raw = MeshingFieldStateRole(
            raw_name,
            "temperature",
            raw_kind,
            raw_index.index_values.shape,
            np.dtype(value.dtype),
            mesh_epoch,
            value_units=value_units,
            index_binding=raw_index,
        )
        baseline = baselines.get(raw_name)
        if baseline is None:
            index_values = raw_index.index_values
            if not isinstance(index_values, jax.Array):
                raise TypeError("Allocated history banks must remain placed JAX arrays.")
            baseline = jnp.zeros(raw.shape, dtype=raw.dtype, device=index_values.sharding)
        projected = project_meshing_field_history(
            compact,
            value,
            raw,
            baseline,
            carrier,
            field_space=field_space,
            index_source=carrier,
        )
        baselines[raw_name] = projected
        roles.extend((compact, raw))
        fields[name] = value
        fields[raw_name] = projected
    roles.append(
        MeshingFieldStateRole(
            "accepted-epoch",
            "temperature",
            "state-epoch",
            (),
            np.dtype(np.int64),
            mesh_epoch,
        )
    )
    return physical, tuple(roles), fields


def _distributed_qualification_recover(
    carrier: Any,
    receipt: Any,
    roles: tuple[Any, ...],
    fields: _DistributedFields,
    space: Any,
) -> tuple[tuple[Any, ...], _DistributedFields]:
    """Rebind allocated histories through one repack receipt and recover every compact role."""
    from dataclasses import replace

    from phydrax.lifecycle._meshing_field_records import (
        prepare_meshing_field_index_binding,
        rebind_meshing_field_history,
        recover_meshing_field_history,
    )

    by_name = {role.entry_name: role for role in roles}
    recovered_roles: list[Any] = []
    recovered: _DistributedFields = {"accepted-epoch": fields["accepted-epoch"]}
    for (
        name,
        raw_name,
        _,
        _,
        bank,
        _,
        history_index,
        indexed,
        _,
        _,
    ) in _DISTRIBUTED_FIELD_ROLES:
        field_space = space if indexed else None
        index = prepare_meshing_field_index_binding(
            carrier, bank, field_space=field_space
        )
        compact = replace(
            by_name[name], shape=index.index_values.shape, index_binding=index
        )
        raw, payload = rebind_meshing_field_history(
            by_name[raw_name],
            fields[raw_name],
            carrier,
            receipt,
            history_index=history_index,
        )
        recovered[name] = recover_meshing_field_history(
            raw,
            payload,
            compact,
            carrier,
            receipt,
            history_index=history_index,
            field_space=field_space,
        )
        recovered[raw_name] = payload
        recovered_roles.extend((compact, raw))
    recovered_roles.append(by_name["accepted-epoch"])
    return tuple(recovered_roles), recovered


def _distributed_qualification_repository(root: Path, /) -> tuple[Any, Any]:
    """Open the shared accepted-checkpoint repository under its frozen limits."""
    from phydrax._array_archive import ArrayArchiveLimits
    from phydrax.lifecycle._repository import (
        HPCFilesystemProfile,
        POSIXArtifactRepository,
        POSIXRepositoryPolicy,
    )

    profile = HPCFilesystemProfile(
        "distributed-qualification-posix",
        "declared-posix",
        atomic_rename_same_filesystem=True,
        file_fsync=True,
        directory_fsync=True,
        advisory_locking=True,
        attempt_private_staging=True,
    )
    repository = POSIXArtifactRepository(
        root / "repository",
        POSIXRepositoryPolicy(
            profile,
            maximum_chunk_bytes=_DISTRIBUTED_REPOSITORY_POLICY["maximum_chunk_bytes"],
            maximum_metadata_bytes=_DISTRIBUTED_REPOSITORY_POLICY[
                "maximum_metadata_bytes"
            ],
        ),
    )
    return repository, ArrayArchiveLimits(
        max_members=_DISTRIBUTED_ARCHIVE_LIMITS["max_members"],
        max_manifest_nesting=_DISTRIBUTED_ARCHIVE_LIMITS["max_manifest_nesting"],
        max_manifest_bytes=_DISTRIBUTED_ARCHIVE_LIMITS["max_manifest_bytes"],
        max_central_directory_bytes=_DISTRIBUTED_ARCHIVE_LIMITS[
            "max_central_directory_bytes"
        ],
    )


def _distributed_qualification_refuses(call: Callable[[], object], /) -> bool:
    """Whether an owning proof refuses one deliberately tampered receipt."""
    try:
        call()
    except ValueError:
        return True
    return False


def _distributed_qualification_epochs(
    args: argparse.Namespace,
    author: Any,
    request: Any,
    source: Any,
    record: dict[str, Any],
    started: float,
    mesh_epoch: int,
) -> tuple[Any, ...]:
    """Accept native owner-local refine/coarsen epochs and project every physical role."""
    from phydrax.discretization._adaptive_simplex import (
        AdaptiveSimplexPolicy,
        coarsen_adaptive_simplex_parts,
        refine_adaptive_simplex_parts,
    )
    from phydrax.meshing._association import PlcAssociationTransfer
    from phydrax.meshing._device_adaptation import (
        commit_partitioned_adaptive_simplex,
        prepare_partitioned_mesh_adaptation,
        restore_partitioned_mesh_state,
    )
    from phydrax.meshing._result import CollectiveMeshEvidence

    meshing = phx.meshing
    domain = source.certification.request.domain
    association = PlcAssociationTransfer(
        domain,
        source.coordinate_contract,
        author.source_revision,
        edge_vertices=np.asarray(author.region.edges, dtype=np.int64),
        triangle_vertices=np.empty((0, 3), dtype=np.int64),
        triangle_facets=np.empty((0,), dtype=np.int64),
        facet_regions=np.asarray(domain.facet_regions, dtype=np.int64),
    )
    partition = meshing.MeshPartitionPolicy(
        meshing.MeshPartitionKind.MORTON,
        args.distributed_parts,
        halo_width=args.distributed_halo_width,
    )
    distribution = _distributed_qualification_stage(
        record,
        "native_morton_partition",
        lambda: meshing.prepare_mesh_distribution(
            meshing.MeshPart(_DISTRIBUTED_PART, source), policy=partition
        ),
        started,
        args.timeout,
    )
    # Each refine epoch bisects every marked cell at most once.
    growth = 2 ** (args.adaptation_rounds + 1)
    cells = sum(block.cell_count for block in source.mesh.blocks)
    policy = meshing.MeshAdaptationPolicy(
        meshing.MeshAdaptationRoute.DEVICE_BISECTION,
        device_policy=AdaptiveSimplexPolicy(
            vertex_capacity=min(
                args.capacity,
                args.distributed_slack * growth * source.mesh.coordinates.shape[0],
            ),
            cell_capacity=min(
                args.capacity,
                args.distributed_cavity_capacity,
                args.distributed_slack * growth * cells,
            ),
        ),
        distribution=distribution,
        partition_policy=partition,
        association_transfer=association,
        audit_policy=meshing.CellMeshAuditPolicy(
            watertight_boundary=meshing.CellMeshAuditDisposition.REJECT
        ),
        limits=request.limits,
    )
    fe_fields, precision = _distributed_qualification_fe_declaration()
    points = (
        _distributed_qualification_fe(
            source, fe_fields, precision, f"accepted-{mesh_epoch}"
        )
        .dof_maps[0]
        .dof_coordinates
    )
    temperature = 1.0 + points[:, 0] + 2.0 * points[:, 1]
    values: _DistributedFields = {
        "temperature": temperature,
        "material-temperature": 37.0 + 3.0 * points[:, 0] - points[:, 1],
        "essential-values": temperature,
    }
    current, baselines = source, {}
    previous_ids: tuple[jax.Array, jax.Array] | None = None
    for epoch, operation in enumerate(
        ("refine", *(("coarsen", "refine") * args.adaptation_rounds))
    ):
        partitioned = _distributed_qualification_stage(
            record,
            f"owner_local_preparation_{epoch}",
            lambda: prepare_partitioned_mesh_adaptation(
                meshing.prepare_mesh_adaptation(
                    current,
                    meshing.MarkedMeshAdaptation(),
                    policy=_distributed_qualification_policy(
                        policy, distribution, partition
                    ),
                )
            ),
            started,
            args.timeout,
        )
        states = partitioned.states
        # Every active cell is marked: retained Morton ownership stays within its balance
        # tolerance only because each part refines or coarsens uniformly.
        operation_kernel = (
            coarsen_adaptive_simplex_parts
            if operation == "coarsen"
            else refine_adaptive_simplex_parts
        )
        kernel = lambda: operation_kernel(
            partitioned.layout, partitioned.parts, states, states.mesh.cell_active
        )
        updated = _distributed_qualification_stage(
            record,
            f"owner_local_{operation}_{epoch}",
            lambda: jax.block_until_ready(kernel()),
            started,
            args.timeout,
        )
        results = _distributed_qualification_stage(
            record,
            f"owner_local_publication_{epoch}",
            lambda: commit_partitioned_adaptive_simplex(partitioned, updated.state),
            started,
            args.timeout,
        )
        if (
            len(results) != 1
            or results[0].status is not meshing.MeshAdaptationStatus.COMPLETE
        ):
            raise RuntimeError(
                f"Actual owner-local {operation} epoch {epoch} was not accepted by this process."
            )
        result = results[0]
        transfer, transition, current = (
            result.transfer,
            result.distribution,
            result.target,
        )
        storage, evidence = current.mesh.storage, current.collective_evidence
        if (
            transfer is None
            or transition is None
            or storage is None
            or not isinstance(evidence, CollectiveMeshEvidence)
        ):
            raise RuntimeError(
                "Accepted owner-local publication omitted its transfer, distribution, storage, or proof."
            )
        values = {name: transfer.apply(value) for name, value in values.items()}
        distribution = transition.target
        evidence.require_passed()
        current.audit.require_passed()
        raw_layout, raw_state, _ = restore_partitioned_mesh_state(storage, evidence)
        ids = (raw_state.mesh.vertex_ids, raw_state.mesh.cell_ids)
        if previous_ids is not None and any(
            old.shape != new.shape
            or not bool(jax.device_get(jnp.all((old < 0) | (old == new))))
            for old, new in zip(previous_ids, ids, strict=True)
        ):
            raise RuntimeError(
                "A topology epoch changed the identity meaning of retained raw history slots."
            )
        previous_ids = ids
        physical, roles, fields = _distributed_qualification_stage(
            record,
            f"all_field_history_projection_{epoch}",
            lambda: _distributed_qualification_project(
                current, values, baselines, fe_fields, precision, mesh_epoch
            ),
            started,
            args.timeout,
        )
        dofs = physical.dof_maps[0].dof_coordinates
        error = float(
            jnp.max(
                jnp.abs(values["temperature"] - (1.0 + dofs[:, 0] + 2.0 * dofs[:, 1]))
            )
        )
        if error > 1.0e-10:
            raise RuntimeError(
                "Accepted H1 transfer lost the exactly representable affine temperature."
            )
        record["epochs"].append(
            {
                "epoch": epoch,
                "operation": operation,
                "status": result.status.value,
                "result_id": current.result_id,
                "source_result_id": result.source.result_id,
                "topology_id": current.mesh.topology_id,
                "evidence_id": evidence.evidence_id,
                "lineage_id": None
                if result.lineage is None
                else result.lineage.lineage_id,
                "transfer_id": transfer.transfer_id,
                "distribution_kind": distribution.evidence.kind.value,
                "local_cells": current.mesh.entity_set(2).count,
                "global_cells": storage.global_entity_counts[-1],
                "h1_affine_transfer_error": error,
                "accepted_cross_epoch": True,
                "allocator_cursors_local": np.asarray(
                    raw_state.cursors.addressable_shards[0].data
                ).tolist(),
                "allocator_clocks_local": np.asarray(
                    raw_state.clocks.addressable_shards[0].data
                ).tolist(),
                "allocator_counters_local": np.asarray(
                    raw_state.counters.addressable_shards[0].data
                ).tolist(),
                "field_roles": [role.entry_name for role in roles],
            }
        )
    return current, distribution, policy, partition, roles, fields, raw_layout, raw_state


def _distributed_qualification_graph(
    args: argparse.Namespace,
    current: Any,
    distribution: Any,
    policy: Any,
    partition: Any,
    roles: tuple[Any, ...],
    fields: _DistributedFields,
    raw_layout: Any,
    raw_state: Any,
    record: dict[str, Any],
    started: float,
    mesh_epoch: int,
) -> tuple[Any, ...]:
    """Replay a native graph restart repartition and recover every physical role across it."""
    from phydrax.discretization._distributed_field import make_owner_local_field_array
    from phydrax.execution import ExecutionRuntime
    from phydrax.meshing._device_adaptation import (
        commit_partitioned_mesh_restart,
        prepare_partitioned_mesh_adaptation,
    )
    from phydrax.meshing._distribution_migration import (
        prepare_graph_restart_proposal,
        prepare_ownerlocal_migration_state,
    )
    from phydrax.meshing._restart_distribution import (
        repack_simplex_restart,
        SimplexRestartRepackProof,
    )

    meshing = phx.meshing
    graph = meshing.MeshPartitionPolicy(
        meshing.MeshPartitionKind.GRAPH,
        args.distributed_parts,
        halo_width=partition.halo_width,
        maximum_imbalance=_DISTRIBUTED_GRAPH_IMBALANCE,
        curve_depth=partition.curve_depth,
        metis_seed=partition.metis_seed,
    )
    adaptation = meshing.prepare_mesh_adaptation(
        current,
        meshing.MarkedMeshAdaptation(),
        policy=_distributed_qualification_policy(policy, distribution, graph),
    )
    partitioned = prepare_partitioned_mesh_adaptation(adaptation)
    devices = tuple(partitioned.parts.mesh.devices.flat)

    def bucket(
        values: jax.Array | np.ndarray, capacity: int, fill: int | float
    ) -> jax.Array:
        if values.shape[0] > capacity:
            raise RuntimeError(
                "An actual indexed physical field exceeds its declared native bucket."
            )
        local = jnp.pad(
            jnp.asarray(values), ((0, capacity - values.shape[0]),), constant_values=fill
        )
        return make_owner_local_field_array(
            (local,),
            (jax.process_index(),),
            devices,
            axis_name=partitioned.parts.axis_name,
        )

    by_name = {role.entry_name: role for role in roles}
    bound = _distributed_qualification_stage(
        record,
        "graph_field_forest_binding",
        lambda: prepare_ownerlocal_migration_state(
            partitioned,
            raw_state,
            cell_field_ids=bucket(
                by_name["material-cell-average"].index_binding.index_values,
                raw_layout.cell_capacity,
                -1,
            ),
            cell_fields=bucket(
                fields["material-cell-average"], raw_layout.cell_capacity, 0.0
            ),
            vertex_field_ids=bucket(
                by_name["temperature"].index_binding.index_values,
                raw_layout.vertex_capacity,
                -1,
            ),
            vertex_fields=bucket(fields["temperature"], raw_layout.vertex_capacity, 0.0),
            cell_epochs=jnp.full(
                raw_state.mesh.cell_ids.shape,
                mesh_epoch,
                dtype=jnp.int64,
                device=raw_state.mesh.cell_ids.sharding,
            ),
            cell_history=_distributed_qualification_histories(fields, "cell"),
            vertex_history=_distributed_qualification_histories(fields, "vertex"),
        ),
        started,
        args.timeout,
    )
    cell_owners, vertex_owners = bound.forest_cell_owners, bound.forest_vertex_owners
    if cell_owners is None or vertex_owners is None:
        raise RuntimeError(
            "Native migration binding omitted its reassembled forest ownership."
        )
    proposal = _distributed_qualification_stage(
        record,
        "native_graph_restart_proposal",
        lambda: prepare_graph_restart_proposal(
            partitioned.parts,
            raw_state,
            bound,
            graph,
            vertex_weights=jnp.where(
                bound.workset.cell_valid, 1 + bound.workset.cell_ids % 3, 0
            ).astype(jnp.int64),
        ),
        started,
        args.timeout,
    )
    receipt = _distributed_qualification_stage(
        record,
        "native_graph_restart_repartition",
        lambda: repack_simplex_restart(
            ExecutionRuntime.current().root_group,
            raw_layout,
            raw_state,
            cell_owners,
            vertex_owners,
            proposal.requested_target_owners,
            cell_history=bound.cell_history,
            vertex_history=bound.vertex_history,
            source_result=current,
            graph_proposal=proposal,
        ),
        started,
        args.timeout,
    )
    proof = SimplexRestartRepackProof(receipt)
    proof.require_receipt(receipt)
    results = _distributed_qualification_stage(
        record,
        "graph_restart_publication",
        lambda: commit_partitioned_mesh_restart(receipt, adaptation),
        started,
        args.timeout,
    )
    if (
        len(results) != 1
        or results[0].status is not meshing.MeshAdaptationStatus.COMPLETE
    ):
        raise RuntimeError(
            "The actual native graph restart epoch was not accepted by this process."
        )
    target, transition = results[0].target, results[0].distribution
    evidence, migration_counts = target.collective_evidence, receipt.cell_migration_counts
    if evidence is None or transition is None or migration_counts is None:
        raise RuntimeError(
            "Graph restart publication omitted its proof, distribution, or migration counts."
        )
    evidence.require_passed()
    target.audit.require_passed()
    fe_fields, precision = _distributed_qualification_fe_declaration()
    physical = _distributed_qualification_fe(
        target, fe_fields, precision, f"accepted-{mesh_epoch}"
    )
    roles, recovered = _distributed_qualification_stage(
        record,
        "graph_field_history_recovery",
        lambda: _distributed_qualification_recover(
            target, receipt, roles, fields, physical.field_spaces[0]
        ),
        started,
        args.timeout,
    )
    mask = physical.dof_maps[0].boundary_dof_mask
    if not bool(jnp.array_equal(recovered["essential-mask"], mask)):
        raise RuntimeError(
            "Recovered essential mask differs from the repartitioned physical boundary."
        )
    if not bool(jax.device_get(jnp.any(~mask))):
        raise RuntimeError("The graph epoch lost every physical interior FE unknown.")
    points = physical.dof_maps[0].dof_coordinates
    temperature = 1.0 + points[:, 0] + 2.0 * points[:, 1]
    vertices = target.mesh.coordinates
    material = 37.0 + 3.0 * vertices[:, 0] - vertices[:, 1]
    references = {
        "temperature": temperature,
        "essential-values": temperature,
        "material-temperature": material,
        "material-cell-average": jnp.mean(
            material[jnp.asarray(_distributed_qualification_entity_cells(target.mesh))],
            axis=1,
        ),
    }
    errors = {
        name: float(jnp.max(jnp.abs(recovered[name] - reference)))
        for name, reference in references.items()
    }
    if max(errors.values()) > 1e-12:
        raise RuntimeError(
            "Hot graph history recovery disagrees with the independent physical references."
        )
    counts = np.asarray(migration_counts.addressable_shards[0].data).tolist()
    valid = np.asarray(proposal.workset.cell_valid.addressable_shards[0].data)
    record["migration"] = {
        "status": "accepted",
        "route": "native-graph-restart-repack",
        "distribution_kind": transition.target.evidence.kind.value,
        "provenance": transition.target.evidence.provenance,
        "graph_parts_local": np.asarray(proposal.parts.addressable_shards[0].data)[
            valid
        ].tolist(),
        "cell_migration_counts_local": counts,
        "receipt_id": proof.content_id,
        "result_id": target.result_id,
        "local_cells": target.mesh.entity_set(2).count,
        "hot_field_reference_errors": errors,
        "essential_mask_exact": True,
        "saved_cursors_local": np.asarray(
            receipt.saved_cursors.addressable_shards[0].data
        ).tolist(),
        "saved_clocks_local": np.asarray(
            receipt.saved_clocks.addressable_shards[0].data
        ).tolist(),
        "saved_counters_local": np.asarray(
            receipt.saved_counters.addressable_shards[0].data
        ).tolist(),
        "recovered_roles": sorted(recovered),
    }
    record["communication"] = {
        "status": "measured-owner-message-counts",
        "cell_migration_counts_local": counts,
        "message_payload_bytes": None,
        "payload_byte_status": "unmeasured",
    }
    return results, physical, roles, recovered, partitioned.parts


def _distributed_qualification_publish(
    args: argparse.Namespace,
    author: Any,
    request: Any,
    options: Any,
    source: Any,
    results: tuple[Any, ...],
    physical: Any,
    roles: tuple[Any, ...],
    fields: _DistributedFields,
    parts: Any,
    record: dict[str, Any],
    started: float,
    mesh_epoch: int,
) -> None:
    """Publish this process's accepted owner-local result through the canonical source closure."""
    from jax.experimental import multihost_utils
    from jax.sharding import PartitionSpec

    from phydrax._differentiation import BranchDifferentiationPolicy
    from phydrax._frozendict import frozendict
    from phydrax._model._structure import (
        model_recipe_array_values,
        model_structure_recipe,
    )
    from phydrax.discretization._cell_geometry_validity import cell_geometry_id
    from phydrax.discretization._views import FieldTracePolicy
    from phydrax.lifecycle._distributed_checkpoint import (
        assemble_distributed_checkpoint_from_repository,
        publish_process_meshing_checkpoint,
    )
    from phydrax.lifecycle._meshing_field_records import MeshingFieldDeclaration
    from phydrax.lifecycle._meshing_sources import (
        meshing_source_shared_array_aliases,
        register_meshing_source_artifacts,
    )
    from phydrax.lifecycle._restart_topology import (
        MeshingArrayRole,
        MeshingCheckpointState,
    )
    from phydrax.meshing._device_adaptation import restore_partitioned_mesh_state
    from phydrax.meshing._distribution_forest import _vertex_record_owners

    result = results[0]
    target = result.target
    fe_fields, precision = _distributed_qualification_fe_declaration()
    space = physical.field_spaces[0]
    declaration = MeshingFieldDeclaration(
        part_name=_DISTRIBUTED_PART,
        owner="finite_element",
        topology_id=target.mesh.topology_id,
        geometry_layout_id=target.geometry.geometry_layout_id,
        field_space_ids=frozendict({"temperature": space.field_space_id}),
        value_units=frozendict({"temperature": (phx.units.KELVIN,)}),
        maximum_derivative_orders=frozendict({"temperature": 1}),
        branch_policy=BranchDifferentiationPolicy.SMOOTH,
        trace_policy=FieldTracePolicy("cell-sided"),
        state_roles=roles,
        history_policy="material-history",
        numeric_version=f"accepted-{mesh_epoch}",
        finite_element_fields=fe_fields,
        precision_policy=precision,
    )
    closure = {
        "certification_inputs": source.certification.request,
        "report": source.certification,
        "associations": source.associations,
        "generation_part": phx.meshing.MeshPart(_DISTRIBUTED_PART, source),
        "generation_source": author,
        "generation_specification": request,
        "generation_options": options,
        "collective_target": target,
        "field_declarations": {_DISTRIBUTED_PART: declaration},
        "accepted_data": {"adaptation_results": results, "fields": fields},
    }
    register_meshing_source_artifacts()
    repository, limits = _distributed_qualification_repository(
        Path(args.distributed_checkpoint_root)
    )
    values = model_recipe_array_values(
        closure, model_structure_recipe(closure), prefix="source-record", limits=limits
    )
    bank, aliases = meshing_source_shared_array_aliases(closure)
    bindings = {
        name: aliases[id(value)] for name, value in values.items() if id(value) in aliases
    }
    missing = [
        name
        for name, value in values.items()
        if isinstance(value, jax.Array)
        and not value.is_fully_addressable
        and name not in bindings
    ]
    if missing:
        raise RuntimeError(
            f"Actual global source records lack scientific alias roles: {missing}"
        )
    storage = target.mesh.storage
    _, raw_state, _ = restore_partitioned_mesh_state(storage, target.collective_evidence)
    cell_ids = raw_state.mesh.cell_ids
    ranks = jnp.arange(args.distributed_parts, dtype=jnp.int32)[:, None]
    vertex_owners = jax.shard_map(
        lambda block: _vertex_record_owners(parts, block[0])[None],
        mesh=parts.mesh,
        in_specs=PartitionSpec(parts.axis_name),
        out_specs=PartitionSpec(parts.axis_name),
        check_vma=False,
    )(raw_state.mesh.vertex_ids)
    # Allocated-slot leaves share the raw forest placement; logical mesh leaves keep the storage owner's.
    allocated = {
        "lineage": raw_state.parents,
        "epoch": jnp.full(cell_ids.shape, mesh_epoch, dtype=jnp.int64),
        "evidence": target.collective_evidence.partition_checks,
        "cell_owners": jnp.where(cell_ids >= 0, ranks, -1),
        "vertex_owners": vertex_owners,
        "allocated-temperature": fields["allocated-temperature"],
        "allocated-material-temperature": fields["allocated-material-temperature"],
    }
    logical = dict(storage.logical_arrays)
    arrays = {
        "vertex_ids": logical["vertex_global_ids"],
        "coordinates": logical["coordinates"],
        "topology": logical["cell_vertices"],
        **{
            name: jax.device_put(value, cell_ids.sharding)
            for name, value in allocated.items()
        },
    }
    array_roles: dict[str, MeshingArrayRole] = {
        "vertex_ids": "entity-ids",
        "coordinates": "geometry",
        "topology": "topology",
        "lineage": "lineage",
        "epoch": "epoch",
        "evidence": "evidence",
        "cell_owners": "state",
        "vertex_owners": "state",
        "allocated-temperature": "state",
        "allocated-material-temperature": "state",
    }
    evidence = target.collective_evidence
    state = _distributed_qualification_stage(
        record,
        "checkpoint_scientific_binding",
        lambda: MeshingCheckpointState(
            source_topology_id=evidence.source.mesh.topology_id,
            source_geometry_id=cell_geometry_id(evidence.source.geometry),
            topology_id=target.mesh.topology_id,
            geometry_id=cell_geometry_id(target.geometry),
            result_id=target.result_id,
            source_revision_id=author.source_revision,
            coordinate_contract_id=target.coordinate_contract.spatial_id,
            lineage_id=None if result.lineage is None else result.lineage.lineage_id,
            epoch_id=canonical_fingerprint(
                {"accepted": target.result_id, "epoch": mesh_epoch}
            ),
            evidence_id=evidence.evidence_id,
            transfer_id=None if result.transfer is None else result.transfer.transfer_id,
            request_id=evidence.preparation.request.request_id,
            mesh_epoch=mesh_epoch,
            array_roles=tuple(array_roles.items()),
            source_closure=closure,
            source_owner_index=jax.process_index(),
            source_array_bindings=bindings,
            source_logical_arrays=bank,
            limits=limits,
        ),
        started,
        args.timeout,
    )
    identities = {
        "checkpoint_id": canonical_fingerprint(
            {
                "kind": "distributed-qualification-scientific-checkpoint",
                "request": record["request_id"],
            }
        ),
        "execution_id": canonical_fingerprint(
            record["actual_topology"]["source_devices"]
        ),
        "analysis_plan_id": request.specification_id,
        "numeric_revision_id": author.source_revision,
    }
    publication = _distributed_qualification_stage(
        record,
        "process_local_checkpoint",
        lambda: publish_process_meshing_checkpoint(
            repository,
            identities["checkpoint_id"],
            identities["execution_id"],
            state,
            arrays,
            analysis_plan_id=identities["analysis_plan_id"],
            numeric_revision_id=identities["numeric_revision_id"],
            writer_id=f"distributed-qualification-process-{jax.process_index()}",
            limits=limits,
        ),
        started,
        args.timeout,
    )
    multihost_utils.sync_global_devices("distributed-qualification-checkpoint-published")
    manifest = _distributed_qualification_stage(
        record,
        "checkpoint_exact_coverage_assembly",
        lambda: assemble_distributed_checkpoint_from_repository(
            repository,
            identities["checkpoint_id"],
            identities["analysis_plan_id"],
            identities["numeric_revision_id"],
            identities["execution_id"],
            expected_process_count=jax.process_count(),
            limits=limits,
        ),
        started,
        args.timeout,
    )
    record["checkpoint"] = {
        "status": "published",
        **identities,
        "manifest_id": manifest.manifest_id,
        "state_id": state.checkpoint_state_id,
        "source_closure_id": state.source_closure_id,
        "result_id": target.result_id,
        "field_space_id": space.field_space_id,
        "process_index": jax.process_index(),
        "process_shards": len(publication.shards),
        "mesh_epoch": mesh_epoch,
        "scientific_roles": [
            list(role) for role in state.array_roles if role[1] != "source-record"
        ],
        "nonaddressable_arrays": sum(
            not value.is_fully_addressable for value in arrays.values()
        ),
        "closure_roles": sorted(closure),
        "accepted_data_roles": sorted(closure["accepted_data"]),
    }


def _distributed_qualification_produce(
    args: argparse.Namespace,
    record: dict[str, Any],
    phases: list[NativeMeshingPhaseMeasurement],
    started: float,
    mesh_epoch: int,
) -> None:
    """Generate, adapt, repartition, and publish this actual producer process's accepted epoch."""
    author, request, options, source = _distributed_qualification_generate(
        args, record, phases, started
    )
    record["field_declarations"] = [
        {
            **declaration,
            "source_field_id": canonical_fingerprint(
                {
                    "declaration": declaration,
                    "source_result": source.result_id,
                    "entity_set": source.mesh.entity_set(
                        0 if declaration["association"] == "vertex" else 2
                    ).entity_set_id,
                }
            ),
        }
        for declaration in _distributed_qualification_requirements()["fields"]
    ]
    current, distribution, policy, partition, roles, fields, raw_layout, raw_state = (
        _distributed_qualification_epochs(
            args, author, request, source, record, started, mesh_epoch
        )
    )
    results, physical, roles, fields, parts = _distributed_qualification_graph(
        args,
        current,
        distribution,
        policy,
        partition,
        roles,
        fields,
        raw_layout,
        raw_state,
        record,
        started,
        mesh_epoch,
    )
    _distributed_qualification_publish(
        args,
        author,
        request,
        options,
        source,
        results,
        physical,
        roles,
        fields,
        parts,
        record,
        started,
        mesh_epoch,
    )


def _distributed_qualification_launch(
    args: argparse.Namespace,
    record: dict[str, Any],
    started: float,
) -> list[dict[str, Any]]:
    """Run the producer half in actual JAX processes and retain every process record."""
    import socket

    from phydrax.execution import (
        launch_local_processes,
        LocalProcessLaunchError,
        LocalProcessLaunchPlan,
    )

    # Fresh repository root: concurrent writers must not open an unprovisioned or reused directory.
    Path(args.distributed_checkpoint_root, "repository").mkdir(
        parents=True, exist_ok=False
    )
    command = [
        sys.executable,
        "-m",
        "tools.meshing_qualification",
        "--scenario",
        "native-distributed-lifecycle",
    ]
    for name in _distributed_qualification_requirements()["required_arguments"]:
        command += [f"--{name.replace('_', '-')}", str(vars(args)[name])]
    with socket.socket() as listener:
        listener.bind(("127.0.0.1", 0))
        coordinator = f"127.0.0.1:{listener.getsockname()[1]}"
    root = str(Path(__file__).resolve().parents[1])
    environment = dict(os.environ)
    environment["PYTHONPATH"] = os.pathsep.join(
        (root, *((environment["PYTHONPATH"],) if environment.get("PYTHONPATH") else ()))
    )
    environment.setdefault("PHYDRAX_CPU_COLLECTIVES", "gloo")

    def launch() -> tuple[Any, ...]:
        try:
            return launch_local_processes(
                command,
                LocalProcessLaunchPlan(args.distributed_processes, coordinator),
                environment=environment,
                cwd=os.getcwd(),
            )
        except LocalProcessLaunchError as failure:
            # Failed producers still print their phase-resolved records.
            return failure.results

    results = _distributed_qualification_stage(
        record, "producer_processes", launch, started, args.timeout
    )
    producers: list[dict[str, Any]] = []
    for result in results:
        text = result.stdout.decode("utf-8")
        if not text.strip():
            raise RuntimeError(
                f"Producer process {result.process_id} exited {result.returncode} without its record: "
                + result.stderr.decode("utf-8", errors="replace")[-4000:]
            )
        producers.append(json.loads(text))
    record["producer_processes"] = producers
    for result, producer in zip(results, producers, strict=True):
        if producer["status"] != "passed":
            failure = producer["failure"]
            raise RuntimeError(
                f"Producer process {result.process_id} failed in {failure['phase']}: "
                f"{failure['type']}: {failure['message']}"
            )
    return producers


def _distributed_qualification_restore(
    args: argparse.Namespace,
    record: dict[str, Any],
    producers: list[dict[str, Any]],
    started: float,
) -> tuple[Any, Any, Any, Any]:
    """Restore every producer owner into a fresh process set with a changed owner count."""
    from jax.sharding import PartitionSpec

    from phydrax._model._structure import model_recipe_array_inventory
    from phydrax.execution import ExecutionRuntime
    from phydrax.lifecycle._distributed_checkpoint import (
        assemble_distributed_checkpoint_from_repository,
        read_meshing_checkpoint_states,
        restore_meshing_checkpoint,
    )
    from phydrax.lifecycle._meshing_field_records import prepare_meshing_field_owner
    from phydrax.lifecycle._meshing_sources import (
        recertify_restored_meshing_source,
        register_meshing_source_artifacts,
    )
    from phydrax.lifecycle._restart_topology import (
        TopologyRestartPolicy,
        TopologyRestartRelation,
    )

    register_meshing_source_artifacts()
    repository, limits = _distributed_qualification_repository(
        Path(args.distributed_checkpoint_root)
    )
    published = [producer["checkpoint"] for producer in producers]
    identity_names = (
        "checkpoint_id",
        "execution_id",
        "analysis_plan_id",
        "numeric_revision_id",
    )
    if any(
        {name: item[name] for name in identity_names}
        != {name: published[0][name] for name in identity_names}
        for item in published
    ):
        raise RuntimeError(
            "Producer processes published different accepted checkpoint identities."
        )
    expected = {item["process_index"]: item["state_id"] for item in published}
    manifest = _distributed_qualification_stage(
        record,
        "restore_checkpoint_coverage_assembly",
        lambda: assemble_distributed_checkpoint_from_repository(
            repository,
            published[0]["checkpoint_id"],
            published[0]["analysis_plan_id"],
            published[0]["numeric_revision_id"],
            published[0]["execution_id"],
            expected_process_count=args.distributed_processes,
            limits=limits,
        ),
        started,
        args.timeout,
    )
    states = read_meshing_checkpoint_states(repository, manifest, limits=limits)
    if {
        state.source_owner_index: state.checkpoint_state_id for state in states
    } != expected:
        raise RuntimeError(
            "Restored owner records differ from the producer-published scientific states."
        )
    names = {name for state in states for name, _ in state.array_roles}
    host_names: set[str] = set()
    for owner in states:
        recipe = owner.source_recipe_json
        if recipe is None:
            raise RuntimeError(
                "Every restored owner requires its retained source recipe."
            )
        host_names |= {
            owner.source_array_name(entry.name)
            for entry in model_recipe_array_inventory(
                json.loads(recipe), prefix="source-record", limits=limits
            )
            if entry.backend == "numpy"
        }
    group = ExecutionRuntime.current().root_group
    relation = TopologyRestartRelation(
        published[0]["execution_id"],
        canonical_fingerprint(record["actual_topology"]["restart_devices"]),
        "bitwise",
    )
    state, arrays, admission = _distributed_qualification_stage(
        record,
        "changed_owner_count_restore",
        lambda: restore_meshing_checkpoint(
            repository,
            manifest,
            {name: group.named_sharding(PartitionSpec()) for name in names - host_names},
            relation,
            TopologyRestartPolicy(allow_topology_change=True),
            expected_state_id=expected,
            source_owner_index=0,
            limits=limits,
            maximum_host_packet_bytes=args.distributed_host_packet_bytes,
        ),
        started,
        args.timeout,
    )
    if (
        not admission.admitted
        or len(state.source_owner_states) != args.distributed_processes
    ):
        raise RuntimeError(
            "Changed owner-count restore did not admit every original producer owner."
        )
    closure = state.source_closure
    if closure is None:
        raise RuntimeError(
            "Restored checkpoint lost its canonical meshing source closure."
        )
    source = closure["generation_part"].carrier
    renewed = _distributed_qualification_stage(
        record,
        "source_recertification",
        lambda: recertify_restored_meshing_source(
            closure["certification_inputs"],
            source.mesh,
            source.geometry,
            source.audit,
            archive_limits=limits,
        ),
        started,
        args.timeout,
    )
    renewed.require_passed()
    if renewed.report_id != closure["report"].report_id:
        raise RuntimeError(
            "Restored source recertification differs from the original theorem."
        )
    accepted = closure["collective_target"]
    declaration = closure["field_declarations"][_DISTRIBUTED_PART]
    physical, _ = prepare_meshing_field_owner(
        declaration, accepted, index_source=accepted
    )
    if physical.field_spaces[0].field_space_id != published[0]["field_space_id"]:
        raise RuntimeError(
            "Restored physical field space differs from the published owner-0 space."
        )
    if int(closure["accepted_data"]["fields"]["accepted-epoch"]) != state.mesh_epoch:
        raise RuntimeError(
            "Restored physical state epoch differs from its checkpoint epoch."
        )
    record["checkpoint"] = {
        "status": "restored",
        **{name: published[0][name] for name in identity_names},
        "manifest_id": manifest.manifest_id,
        "state_ids": {str(owner): value for owner, value in expected.items()},
        "source_process_count": len(states),
        "restored_process_count": jax.process_count(),
        "source_result_ids": {
            str(item["process_index"]): item["result_id"] for item in published
        },
        "source_closure_ids": {
            str(item["process_index"]): item["source_closure_id"] for item in published
        },
        "restored_field_space_id": physical.field_spaces[0].field_space_id,
        "source_closure_id": state.source_closure_id,
        "recertified_report_id": renewed.report_id,
    }
    return state, arrays, closure, accepted


def _distributed_qualification_repack(
    args: argparse.Namespace,
    closure: Any,
    accepted: Any,
    arrays: dict[str, Any],
    record: dict[str, Any],
    started: float,
) -> tuple[Any, Any, Any, Any, _DistributedFields]:
    """Repack the restored allocated forest onto the changed owner count and recover all roles."""
    from dataclasses import replace

    from phydrax._frozendict import frozendict
    from phydrax.execution import ExecutionRuntime
    from phydrax.lifecycle._meshing_field_records import (
        validate_meshing_field_declarations,
    )
    from phydrax.meshing._device_adaptation import (
        commit_partitioned_mesh_restart,
        restore_partitioned_mesh_state,
    )
    from phydrax.meshing._restart_distribution import (
        repack_simplex_restart,
        SimplexRestartRepackProof,
    )

    meshing = phx.meshing
    fields = closure["accepted_data"]["fields"]
    layout, raw, _ = restore_partitioned_mesh_state(
        accepted.mesh.storage, accepted.collective_evidence
    )
    owners = arrays["cell_owners"]
    receipt = _distributed_qualification_stage(
        record,
        "changed_owner_count_repack",
        lambda: repack_simplex_restart(
            ExecutionRuntime.current().root_group,
            layout,
            raw,
            owners,
            arrays["vertex_owners"],
            # Every restored cell is requested by the single changed owner.
            jnp.zeros_like(owners),
            cell_history=_distributed_qualification_histories(fields, "cell"),
            vertex_history=_distributed_qualification_histories(fields, "vertex"),
            source_result=accepted,
        ),
        started,
        args.timeout,
    )
    proof = SimplexRestartRepackProof(receipt)
    proof.require_receipt(receipt)
    counts = receipt.cell_migration_counts
    if (
        counts is None
        or not bool(jnp.all(receipt.status == 0))
        or counts.shape != (args.distributed_parts, args.restart_parts)
        or int(jnp.sum(counts)) != int(jnp.sum(raw.mesh.cell_active))
    ):
        raise RuntimeError(
            "Changed owner-count repack did not move every accepted cell exactly once."
        )
    corrupt = replace(
        receipt,
        vertex_history=(
            receipt.vertex_history[0].at[0, 0].add(0.25),
            *receipt.vertex_history[1:],
        ),
    )
    tamper = {
        "fresh_proof_refused": _distributed_qualification_refuses(
            lambda: SimplexRestartRepackProof(corrupt)
        ),
        "bound_proof_refused": _distributed_qualification_refuses(
            lambda: proof.require_receipt(corrupt)
        ),
    }
    if not all(tamper.values()):
        raise RuntimeError("A tampered physical history receipt was accepted.")
    results = closure["accepted_data"]["adaptation_results"]
    old_policy = results[0].policy
    old_partition = old_policy.partition_policy
    partition = meshing.MeshPartitionPolicy(
        meshing.MeshPartitionKind.PROVIDER,
        args.restart_parts,
        halo_width=old_partition.halo_width,
        maximum_imbalance=old_partition.maximum_imbalance,
        curve_depth=old_partition.curve_depth,
        metis_seed=old_partition.metis_seed,
    )
    prepared = meshing.prepare_mesh_adaptation(
        accepted,
        meshing.MarkedMeshAdaptation(),
        policy=_distributed_qualification_policy(
            old_policy, results[0].distribution.target, partition
        ),
    )
    restored = _distributed_qualification_stage(
        record,
        "changed_owner_count_publication",
        lambda: commit_partitioned_mesh_restart(receipt, prepared),
        started,
        args.timeout,
    )
    if len(restored) != 1:
        raise RuntimeError(
            "The changed owner count must publish exactly one accepted local result."
        )
    result = restored[0]
    target, transition = result.target, result.distribution
    storage, evidence = target.mesh.storage, target.collective_evidence
    if storage is None or evidence is None or transition is None:
        raise RuntimeError(
            "Changed owner-count publication omitted its storage, proof, or distribution."
        )
    stable = np.unique(
        np.asarray(raw.mesh.vertex_ids)[np.asarray(raw.mesh.vertex_active)]
    )
    if (
        storage.partition_count != args.restart_parts
        or evidence.partition_count != args.restart_parts
        or transition.source.partition.part_count != args.distributed_parts
        or transition.target.partition.part_count != args.restart_parts
        or not np.array_equal(np.sort(np.asarray(target.mesh.vertex_global_ids)), stable)
        or not all(
            np.array_equal(np.asarray(saved), np.asarray(value))
            for saved, value in (
                (receipt.saved_cursors, raw.cursors),
                (receipt.saved_clocks, raw.clocks),
                (receipt.saved_counters, raw.counters),
            )
        )
    ):
        raise RuntimeError(
            "Changed owner-count publication lost stable IDs, ownership, or allocator clocks."
        )
    declaration = closure["field_declarations"][_DISTRIBUTED_PART]
    prepared_fe = _distributed_qualification_fe(
        target,
        declaration.finite_element_fields,
        declaration.precision_policy,
        declaration.numeric_version,
    )
    roles, recovered = _distributed_qualification_stage(
        record,
        "restored_field_history_recovery",
        lambda: _distributed_qualification_recover(
            target, receipt, declaration.state_roles, fields, prepared_fe.field_spaces[0]
        ),
        started,
        args.timeout,
    )
    renewed = replace(
        declaration,
        topology_id=target.mesh.topology_id,
        geometry_layout_id=target.geometry.geometry_layout_id,
        field_space_ids=frozendict(
            {"temperature": prepared_fe.field_spaces[0].field_space_id}
        ),
        state_roles=roles,
    )
    new_closure = {
        **closure,
        "collective_target": target,
        "field_declarations": {_DISTRIBUTED_PART: renewed},
        "accepted_data": {"adaptation_results": restored, "fields": recovered},
    }
    validate_meshing_field_declarations(new_closure)
    record["restart"] = {
        "status": "full-accepted-result-reconstructed",
        "source_parts": args.distributed_parts,
        "destination_parts": args.restart_parts,
        "receipt_id": proof.content_id,
        "restored_kind": transition.target.evidence.kind.value,
        "result_id": target.result_id,
        "tamper_refusal": tamper,
        "source_result_id": accepted.result_id,
        "field_space_id": prepared_fe.field_spaces[0].field_space_id,
        "saved_cursors": np.asarray(receipt.saved_cursors).tolist(),
        "saved_clocks": np.asarray(receipt.saved_clocks).tolist(),
        "saved_counters": np.asarray(receipt.saved_counters).tolist(),
        "recovered_roles": sorted(recovered),
        "full_accepted_result_reconstructed": True,
    }
    record["stable_ids"] = {
        "vertex_count": stable.size,
        "preserved": True,
        "allocator_clocks_preserved": True,
    }
    return target, new_closure, receipt, proof, recovered


def _distributed_qualification_continue(
    args: argparse.Namespace,
    new_closure: dict[str, Any],
    record: dict[str, Any],
    started: float,
) -> None:
    """Rearchive the restored closure and continue nonempty FE and FV physics from it."""
    from phydrax.discretization._distributed_field import prepare_owner_local_halo_plans
    from phydrax.discretization.finite_volume._unstructured_dynamics import (
        execute_owner_local_finite_volume_advance,
        PreparedUnstructuredFiniteVolumeDynamics,
    )
    from phydrax.execution import ExecutionGroup, ExecutionGroupSpec
    from phydrax.lifecycle._meshing_field_records import prepare_meshing_field_owner
    from phydrax.lifecycle._meshing_sources import (
        read_meshing_source_closure,
        write_meshing_source_closure,
    )

    _, limits = _distributed_qualification_repository(
        Path(args.distributed_checkpoint_root)
    )
    archived = _distributed_qualification_stage(
        record,
        "restored_closure_rearchive",
        lambda: write_meshing_source_closure(
            Path(args.distributed_checkpoint_root) / "restored-closure.zip",
            new_closure,
            limits=limits,
        ),
        started,
        args.timeout,
    )
    reopened = read_meshing_source_closure(
        archived.path, expected_content_id=archived.content_id, limits=limits
    )
    target = reopened["collective_target"]
    fields = reopened["accepted_data"]["fields"]
    final, _ = prepare_meshing_field_owner(
        reopened["field_declarations"][_DISTRIBUTED_PART], target, index_source=target
    )
    if not isinstance(final, phx.discretization.FiniteElementDiscretization):
        raise TypeError(
            "The restored temperature owner must remain a finite-element discretization."
        )
    restored_fields = new_closure["accepted_data"]["fields"]
    if any(
        not np.array_equal(np.asarray(fields[name]), np.asarray(restored_fields[name]))
        for name in restored_fields
    ):
        raise RuntimeError(
            "Rearchived accepted fields differ from the restored accepted fields."
        )
    points = final.dof_maps[0].dof_coordinates
    expected = 1.0 + points[:, 0] + 2.0 * points[:, 1]
    cells = _distributed_qualification_entity_cells(target.mesh)
    vertices = target.mesh.coordinates
    material = 37.0 + 3.0 * vertices[:, 0] - vertices[:, 1]
    errors = {
        "temperature": float(jnp.max(jnp.abs(fields["temperature"] - expected))),
        "essential-values": float(
            jnp.max(jnp.abs(fields["essential-values"] - expected))
        ),
        "material-temperature": float(
            jnp.max(jnp.abs(fields["material-temperature"] - material))
        ),
        "material-cell-average": float(
            jnp.max(
                jnp.abs(
                    fields["material-cell-average"]
                    - jnp.mean(material[jnp.asarray(cells)], axis=1)
                )
            )
        ),
    }
    mask_exact = bool(
        jnp.array_equal(fields["essential-mask"], final.dof_maps[0].boundary_dof_mask)
    )
    if not mask_exact:
        raise RuntimeError(
            "Restored essential mask differs from the accepted physical boundary."
        )
    form = phx.equations.FiniteElementForm(
        "restored-temperature",
        "temperature",
        (phx.equations.DiffusionAction("temperature", 1.0),),
    )
    problem = _distributed_qualification_stage(
        record,
        "continued_fe_preparation",
        lambda: phx.equations.compile_finite_element_problem(
            form,
            final,
            constraint=phx.discretization.dirichlet_constraint(
                final, "temperature", boundary_mask=fields["essential-mask"]
            ),
            dirichlet_values=fields["essential-values"],
        ),
        started,
        args.timeout,
    )
    operator, rhs = problem.linear_system()
    policy = phx.linalg.LinearSolvePolicy(
        tolerance=phx.linalg.TolerancePolicy(relative=1e-12, absolute=1e-13)
    )
    solved = _distributed_qualification_stage(
        record,
        "continued_fe_solve",
        lambda: jax.block_until_ready(phx.linalg.solve(operator, rhs, policy=policy)),
        started,
        args.timeout,
    )
    warm = []
    for repeat in range(args.repeats):
        name = f"continued_fe_warm_solve_{repeat}"
        _distributed_qualification_stage(
            record,
            name,
            lambda: jax.block_until_ready(phx.linalg.solve(operator, rhs, policy=policy)),
            started,
            args.timeout,
        )
        warm.append(record["stages_seconds"][name])
    record["active_phase"] = "continued_fe_validation"
    solve_error = float(jnp.max(jnp.abs(problem.expand(solved.value) - expected)))
    free = int(jnp.sum(~final.dof_maps[0].boundary_dof_mask))
    if (
        not bool(jnp.all(solved.successful))
        or free == 0
        or solve_error > 1e-10
        or max(errors.values()) > 1e-12
    ):
        raise RuntimeError(
            "Restored physical fields or continued FE solve disagree with the affine reference."
        )
    record["active_phase"] = "restored_field_integral_validation"
    triangles = np.asarray(target.mesh.coordinates)[cells]
    first, second = triangles[:, 1] - triangles[:, 0], triangles[:, 2] - triangles[:, 0]
    area = np.abs(first[:, 0] * second[:, 1] - first[:, 1] * second[:, 0]) / 2
    integrals = {
        "area": float(np.sum(area)),
        "temperature": float(
            np.sum(area * np.mean(np.asarray(fields["temperature"])[cells], axis=1))
        ),
        "material-temperature": float(
            np.sum(
                area * np.mean(np.asarray(fields["material-temperature"])[cells], axis=1)
            )
        ),
        "material-cell-average": float(
            np.sum(area * np.asarray(fields["material-cell-average"]))
        ),
    }
    references = {
        "area": 1.0,
        "temperature": 2.5,
        "material-temperature": 38.0,
        "material-cell-average": 38.0,
    }
    if any(abs(integrals[name] - value) > 1e-12 for name, value in references.items()):
        raise RuntimeError(
            "Restored physical inventories disagree with their independent integrals."
        )
    record["archive"] = {
        "content_id": archived.content_id,
        "path": str(archived.path),
        "reopened_roles": sorted(reopened),
    }
    record["restored_fields"] = {
        "affine_reference_errors": errors,
        "essential_mask_exact": mask_exact,
        "reopened_state_roles": sorted(fields),
        "integrals": integrals,
        "independent_references": references,
    }
    record["continued_fe"] = {
        "status": "executed",
        "physical_problem": "restored-Dirichlet-Laplace-affine-temperature",
        "free_dofs": free,
        "solve_max_error": solve_error,
        "warm_samples_seconds": warm,
        "coefficient_shape": list(fields["temperature"].shape),
        "continued_from_restart": True,
    }
    record["physical_error"] = solve_error
    mesh = target.mesh
    storage = mesh.storage
    record["active_phase"] = "continued_fv_preparation"
    system = phx.equations.EulerSystem(2)
    geometry = phx.discretization.UnstructuredFiniteVolumePlan.from_cell_mesh(
        mesh,
        component_names=system.component_names,
        neighborhood_complete=storage.local_neighborhood_complete,
        physical_boundary_faces=storage.local_physical_boundary_facets,
        closure_evidence_id=storage.evidence_id,
    ).prepare(owned_face_capacity=4 * storage.global_entity_counts[1])
    boundaries = phx.discretization.UnstructuredFiniteVolumeBoundarySet(
        geometry.boundary_patch_names,
        {
            name: phx.discretization.SlipWallBoundary()
            for name in geometry.boundary_patch_names
        },
    )
    dynamics = PreparedUnstructuredFiniteVolumeDynamics(
        system,
        geometry,
        phx.discretization.UnstructuredFiniteVolumeMethodPlan(
            phx.discretization.PiecewiseConstantReconstruction(),
            phx.discretization.RusanovFluxPlan(),
        ),
        boundaries,
    )
    count = dynamics.discretization.cell_centers.shape[0]
    # Density carries the restored material-cell history; the advance must move it while conserving inventory.
    density = (
        jnp.asarray(fields["material-cell-average"]) / references["material-cell-average"]
    )
    seed = system.primitive_to_conserved(
        jnp.stack((density, jnp.zeros(count), jnp.zeros(count), jnp.ones(count)), axis=1)
    )[None]
    devices = tuple(jax.devices())
    group = ExecutionGroup(
        ExecutionGroupSpec(
            canonical_fingerprint(
                {
                    "kind": "distributed-qualification-restored-group",
                    "devices": [(device.process_index, device.id) for device in devices],
                }
            ),
            tuple(sorted({device.process_index for device in devices})),
            tuple((device.process_index, device.id) for device in devices),
            mesh_axes=(("parts", args.restart_parts),),
        ),
        devices,
    )
    record["active_phase"] = "continued_fv_halo_preparation"
    halos = prepare_owner_local_halo_plans(
        (mesh,),
        2,
        devices=devices,
        axis_name="parts",
        message_capacity=min(
            args.distributed_halo_capacity, storage.entity_global_ids[2].size
        ),
    )
    advance = _distributed_qualification_stage(
        record,
        "continued_owner_local_fv",
        lambda: jax.block_until_ready(
            execute_owner_local_finite_volume_advance(
                ((dynamics, halos[0]),),
                seed,
                jnp.asarray(0.0),
                jnp.asarray(0.01),
                group,
                axis_name="parts",
            )
        ),
        started,
        args.timeout,
    )
    drift = float(jnp.max(jnp.abs(advance.inventory_after - advance.inventory_before)))
    changed = int(
        np.count_nonzero(np.asarray(advance.state[0][:, 0]) != np.asarray(seed[0][:, 0]))
    )
    if not bool(advance.finite & advance.admissible) or drift > 1e-12 or changed == 0:
        raise RuntimeError(
            "Continued FV advance is inadmissible, nonconservative, or stationary."
        )
    record["continued_fv"] = {
        "status": "executed",
        "physical_problem": "restored-material-density-slip-wall-Euler",
        "changed_cells": changed,
        "inventory_drift": drift,
        "system_id": system.system_id,
        "continued_from_restart": True,
    }
    record["conservation"] = {
        "status": "measured",
        "material_cell_inventory": integrals["material-cell-average"],
        "fv_inventory_drift": drift,
    }


def _distributed_qualification_lifecycle(args: argparse.Namespace) -> dict[str, object]:
    """Publish from actual producer processes, then restore with a changed owner count.

    A single-process invocation launches ``distributed_processes`` producer
    processes with the same frozen request, then restores, rearchives and
    continues the published accepted state in its own fresh process.
    """
    from phydrax.execution import initialize_from_environment

    # Producer processes join their distributed runtime before any JAX backend use.
    initialize_from_environment()
    started = perf_counter()
    phases: list[NativeMeshingPhaseMeasurement] = []
    requirements = _distributed_qualification_requirements()
    frozen = {name: vars(args)[name] for name in requirements["required_arguments"]}
    record: dict[str, Any] = {
        "scenario": "native-distributed-lifecycle",
        "status": "failed",
        "request": frozen,
        "request_id": None,
        "runtime": _runtime_identity(),
        "frozen_targets": requirements,
        "source": None,
        "generation": None,
        "actual_topology": None,
        "epochs": [],
        "stages_seconds": {},
        "stage_peak_process_bytes": {},
        "attempts": [],
        "timeout_scope": "native-provider-limits-and-stage-deadline-checks; external-command-owns-hard-deadline",
        "compiler": {
            "status": "unmeasured",
            "temporary_bytes": None,
            "output_bytes": None,
            "argument_bytes": None,
            "generated_code_bytes": None,
        },
        "communication": {
            "status": "unmeasured",
            "scope": "included-in-owner-local-execution",
        },
        "migration": {"status": "not-executed"},
        "checkpoint": {"status": "not-executed"},
        "restart": {"status": "not-executed"},
        "conservation": {"status": "unmeasured"},
        "physical_error": None,
        "time_to_target_error_seconds": None,
        "independent_scientific_certification": "unassessed",
        "mandatory_workflow_completion": "incomplete",
        "active_phase": "actual_placement_admission",
        "nonclaims": requirements["nonclaims"],
    }
    try:
        record["request_id"] = canonical_fingerprint(frozen)
        topology = _distributed_qualification_topology(args)
        record["actual_topology"] = topology
        # Refine/coarsen epochs plus the graph restart epoch.
        mesh_epoch = 2 * args.adaptation_rounds + 2
        match topology["role"]:
            case "producer":
                _distributed_qualification_produce(
                    args, record, phases, started, mesh_epoch
                )
                record["mandatory_workflow_completion"] = "producer-published"
            case "restore":
                producers = _distributed_qualification_launch(args, record, started)
                _, arrays, closure, accepted = _distributed_qualification_restore(
                    args, record, producers, started
                )
                _, new_closure, _, _, _ = _distributed_qualification_repack(
                    args, closure, accepted, arrays, record, started
                )
                _distributed_qualification_continue(args, new_closure, record, started)
                if record["physical_error"] > args.target_error:
                    raise RuntimeError(
                        "Continued distributed physics missed the frozen physical-error target."
                    )
                record["time_to_target_error_seconds"] = perf_counter() - started
                record["independent_scientific_certification"] = "passed"
                record["mandatory_workflow_completion"] = "complete"
            case role:
                raise ValueError(f"Unknown distributed qualification role {role!r}.")
        record["status"] = "passed"
    except Exception as error:
        native_timeout = isinstance(error, phx.meshing.MeshingFailure) and (
            error.category is phx.meshing.MeshingFailureCategory.TIMED_OUT
        )
        record["status"] = (
            "timeout" if isinstance(error, TimeoutError) or native_timeout else "failed"
        )
        detail: dict[str, Any] = {
            "phase": record["active_phase"],
            "type": type(error).__name__,
            "message": str(error),
            "category": None,
            "evidence_id": None,
            "native_stage": None,
            "provider_code": None,
            "entity_ids": [],
            "requested": {},
            "achieved": {},
            "locations": [],
            "checkpoint_id": None,
        }
        if isinstance(error, phx.meshing.MeshingFailure):
            evidence = error.evidence
            detail.update(
                {
                    "category": error.category.value,
                    "evidence_id": evidence.evidence_id,
                    "native_stage": evidence.stage,
                    "provider_code": evidence.provider_code,
                    "entity_ids": list(evidence.entity_ids),
                    "requested": dict(evidence.requested),
                    "achieved": dict(evidence.achieved),
                    "locations": list(evidence.locations),
                    "checkpoint_id": evidence.checkpoint_id,
                }
            )
        record["failure"] = detail
        record["attempts"].append(
            {
                "phase": record["active_phase"],
                "status": record["status"],
                "failure": record["failure"],
            }
        )
    finally:
        record["native_phases"] = _phase_recordings(phases)
        record["end_to_end_seconds"] = perf_counter() - started
        record["peak_process_resident_bytes"] = resource.getrusage(
            resource.RUSAGE_SELF
        ).ru_maxrss * (1 if sys.platform == "darwin" else 1024)
        record["process_peak_scope"] = "process-lifetime"
        record["device_memory"] = [
            {
                "device_id": device.id,
                "process_index": device.process_index,
                "memory_statistics": statistics,
                "peak_bytes": None
                if statistics is None
                else statistics.get("peak_bytes_in_use"),
                "status": "unavailable" if statistics is None else "backend-reported",
            }
            for device in jax.local_devices()
            for statistics in (device.memory_stats(),)
        ]
        if record["end_to_end_seconds"] > args.timeout:
            record["status"] = "timeout"
            record["failure"] = {
                "phase": record["active_phase"],
                "type": "TimeoutError",
                "category": "wall-deadline",
                "message": "Frozen distributed lifecycle wall deadline exceeded.",
                "evidence_id": None,
                "native_stage": None,
                "provider_code": None,
                "entity_ids": [],
                "requested": {"wall_seconds": args.timeout},
                "achieved": {"wall_seconds": record["end_to_end_seconds"]},
                "locations": [],
                "checkpoint_id": None,
            }
        record["counts"] = {
            "passed": int(record["status"] == "passed"),
            "failed": int(record["status"] == "failed"),
            "timeout": int(record["status"] == "timeout"),
            "uncertainty_or_refusal_is_positive": False,
        }
    return record


