_MANDATORY_WORKFLOW_RESULT_FIELDS = frozenset(
    {
        "kind",
        "workflow",
        "scenario",
        "expected_admission",
        "observed_status",
        "status",
        "positive_completion",
        "refusal_certified",
        "refusals_count_as_positive_completion",
        "scientific_certification",
        "mandatory_workflow_completion",
        "release",
        "leadership",
        "result_id",
    }
)


def _validate_mandatory_workflow_result(value: object, /) -> dict[str, object]:
    """Validate the exact fail-closed result emitted by every mandatory driver."""
    result = _record_mapping(value, "Mandatory meshing workflow result")
    missing = sorted(_MANDATORY_WORKFLOW_RESULT_FIELDS - set(result))
    unknown = sorted(set(result) - _MANDATORY_WORKFLOW_RESULT_FIELDS)
    if missing or unknown:
        details = []
        if missing:
            details.append(f"missing fields: {', '.join(missing)}")
        if unknown:
            details.append(f"unknown fields: {', '.join(unknown)}")
        raise ValueError(f"Mandatory meshing workflow result has {'; '.join(details)}.")
    for field in (
        "kind",
        "workflow",
        "scenario",
        "expected_admission",
        "observed_status",
        "status",
        "scientific_certification",
        "mandatory_workflow_completion",
        "release",
        "leadership",
        "result_id",
    ):
        if not isinstance(result[field], str) or not result[field]:
            raise TypeError(
                f"Mandatory meshing workflow result {field} must be a string."
            )
    for field in (
        "positive_completion",
        "refusal_certified",
        "refusals_count_as_positive_completion",
    ):
        if type(result[field]) is not bool:
            raise TypeError(
                f"Mandatory meshing workflow result {field} must be a boolean."
            )
    if result["kind"] != "mandatory-meshing-workflow-result":
        raise ValueError("Mandatory meshing workflow result has the wrong kind.")
    if result["expected_admission"] not in ("positive", "refusal"):
        raise ValueError("Mandatory meshing workflow result has an invalid admission.")
    if result["status"] not in ("positive-complete", "refusal-certified", "blocked"):
        raise ValueError("Mandatory meshing workflow result has an invalid status.")
    if result["refusals_count_as_positive_completion"] is not False:
        raise ValueError("A refusal cannot count as mandatory positive completion.")
    positive = (
        result["expected_admission"] == "positive"
        and result["observed_status"] == "passed"
        and result["scientific_certification"] == "passed"
        and result["mandatory_workflow_completion"] == "complete"
    )
    refusal = (
        result["expected_admission"] == "refusal"
        and result["observed_status"] == "expected-refusal"
    )
    expected_status = (
        "positive-complete" if positive else "refusal-certified" if refusal else "blocked"
    )
    if (
        result["positive_completion"] is not positive
        or result["refusal_certified"] is not refusal
        or result["status"] != expected_status
    ):
        raise ValueError("Mandatory meshing workflow result fields are inconsistent.")
    body = {name: field for name, field in result.items() if name != "result_id"}
    if result["result_id"] != canonical_fingerprint(body):
        raise ValueError("Mandatory meshing workflow result identity is invalid.")
    return result


def _finalize_mandatory_cli_record(
    args: argparse.Namespace,
    record: dict[str, object],
) -> dict[str, object]:
    """Attach the same fail-closed outcome schema to every mandatory driver."""
    if args.scenario == "native-corpus":
        return record
    workflow = _MANDATORY_SCENARIO_WORKFLOWS.get(args.scenario)
    if args.scenario == "native-lifecycle":
        workflow = meshing_case(args.corpus_case).workflow
    if workflow is None:
        return record
    expected_value = record.get("expected_admission", "positive")
    if expected_value not in ("positive", "refusal"):
        raise ValueError("Qualification expected admission must be positive or refusal.")
    observed = record.get("status", "failed")
    scientific = record.get("independent_scientific_certification", "unassessed")
    refusal = expected_value == "refusal" and observed == "expected-refusal"
    positive = (
        expected_value == "positive"
        and observed == "passed"
        and scientific == "passed"
        and record.get("mandatory_workflow_completion") == "complete"
    )
    result_body: dict[str, object] = {
        "kind": "mandatory-meshing-workflow-result",
        "workflow": workflow,
        "scenario": args.scenario,
        "expected_admission": expected_value,
        "observed_status": observed,
        "status": (
            "positive-complete"
            if positive
            else "refusal-certified"
            if refusal
            else "blocked"
        ),
        "positive_completion": positive,
        "refusal_certified": refusal,
        "refusals_count_as_positive_completion": False,
        "scientific_certification": scientific,
        "mandatory_workflow_completion": record.get(
            "mandatory_workflow_completion", "incomplete"
        ),
        "release": record.get("release_evidence", "unassessed"),
        "leadership": record.get("leadership_evidence", "unassessed"),
    }
    workflow_result = _validate_mandatory_workflow_result(
        {
            **result_body,
            "result_id": canonical_fingerprint(result_body),
        }
    )
    return {
        **record,
        "kind": "native-meshing-qualification-result",
        "positive_completion": positive,
        "refusal_certified": refusal,
        "workflow_result": workflow_result,
    }


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--scenario", choices=tuple(_SCENARIOS), default="manifold")
    parser.add_argument("--executable", default="vc_mesh")
    parser.add_argument("--worker", default=None)
    parser.add_argument(
        "--corpus-case", choices=CASE_NAMES, default="planar-hole-feature"
    )
    parser.add_argument(
        "--corpus-profile",
        nargs="+",
        default=None,
        help="Execute only these original profiles; retain every unrun mandatory obligation.",
    )
    parser.add_argument(
        "--polyhedral-source",
        choices=POLYHEDRAL_CASE_NAMES,
        default="polyhedral-material-L",
    )
    parser.add_argument("--resolution", type=int, default=4)
    parser.add_argument("--capacity", type=int, default=20000)
    parser.add_argument("--timeout", type=float, default=120.0)
    parser.add_argument("--repeats", type=int, default=3)
    parser.add_argument("--target-error", type=float, default=0.05)
    parser.add_argument("--adaptation-rounds", type=int, default=1)
    surface_arguments = _surface_qualification_requirements()["required_arguments"]
    if not isinstance(surface_arguments, dict) or not isinstance(
        surface_arguments["surface_case"], dict
    ):
        raise TypeError(
            "Surface profile arguments must be the canonical requirement mapping."
        )
    surface_argument = surface_arguments["surface_case"]
    surface_choices, surface_default = (
        surface_argument["choices"],
        surface_argument["default"],
    )
    if (
        not isinstance(surface_choices, tuple)
        or not all(isinstance(name, str) for name in surface_choices)
        or not isinstance(surface_default, str)
        or surface_default not in surface_choices
    ):
        raise TypeError(
            "Surface profile choices/default must be canonical named original sources."
        )
    parser.add_argument(
        "--surface-case", choices=surface_choices, default=surface_default
    )
    parser.add_argument("--cad-format", choices=("step", "iges", "brep"), default="step")
    parser.add_argument(
        "--periodic-case",
        choices=("skew-lattice", "skew-material-feature"),
        default="skew-lattice",
    )
    parser.add_argument("--maximum-memory-bytes", type=int, default=8 * 1024**3)
    parser.add_argument("--maximum-condition", type=float, default=1.0e12)
    parser.add_argument("--overset-motion-steps", type=int, default=2)
    parser.add_argument("--overset-wall-pairs", type=int, default=500000)
    parser.add_argument("--overset-donor-pairs", type=int, default=500000)
    parser.add_argument("--overset-overlap-pairs", type=int, default=500000)
    family_choices = _family_qualification_requirements()["parser_choices"]
    if not isinstance(family_choices, tuple):
        raise TypeError("Family parser choices must be a canonical tuple.")
    validated_family_choices: list[str] = []
    for choice in family_choices:
        if not isinstance(choice, str):
            raise TypeError("Family parser choices must contain source-profile names.")
        validated_family_choices.append(choice)
    parser.add_argument(
        "--family-case", choices=tuple(validated_family_choices), default="dual-hex"
    )
    parser.add_argument("--layer-count", type=int, default=2)
    parser.add_argument(
        "--hybrid-profile", choices=_hybrid_qualification_profiles(), default="unit-box"
    )
    parser.add_argument("--hybrid-archive")
    parser.add_argument("--hybrid-content-id")
    parser.add_argument(
        "--hybrid-region-densities", type=float, nargs="+", default=(2.0, 3.0)
    )
    parser.add_argument("--hybrid-material-site", default="two-material-density")
    parser.add_argument("--hybrid-core-size", type=float, default=0.1)
    parser.add_argument("--first-thickness", type=float, default=0.1)
    parser.add_argument("--layer-growth", type=float, default=1.0)
    parser.add_argument("--geometry-order", type=int, choices=(2, 3, 4, 6, 10), default=2)
    parser.add_argument("--implicit-radius", type=float, default=0.371)
    parser.add_argument("--implicit-fidelity", type=float, default=0.02)
    parser.add_argument("--implicit-maximum-level", type=int, default=9)
    parser.add_argument("--implicit-edge-isolation-depth", type=int, default=8)
    parser.add_argument("--implicit-root-tolerance", type=float, default=1.0e-10)
    parser.add_argument("--implicit-refinement-rounds", type=int, default=8)
    parser.add_argument("--implicit-improvement-passes", type=int, default=8)
    parser.add_argument("--implicit-metric-passes", type=int, default=16)
    parser.add_argument("--distributed-parts", type=int, default=2)
    parser.add_argument("--restart-parts", type=int, default=1)
    parser.add_argument("--distributed-processes", type=int, default=2)
    parser.add_argument(
        "--distributed-source",
        choices=("native-unit-square",),
        default="native-unit-square",
    )
    parser.add_argument("--distributed-halo-width", type=int, default=2)
    parser.add_argument("--distributed-halo-capacity", type=int, default=20000)
    parser.add_argument("--distributed-cavity-capacity", type=int, default=20000)
    parser.add_argument("--distributed-slack", type=int, default=2)
    parser.add_argument(
        "--distributed-host-packet-bytes", type=int, default=64 * 1024 * 1024
    )
    parser.add_argument("--distributed-checkpoint-root", default=None)
    parser.add_argument("--image-size", type=int, default=2)
    parser.add_argument("--transport-steps", type=int, default=5)
    parser.add_argument("--transport-dt", type=float, default=0.01)
    parser.add_argument("--balance-tolerance", type=float, default=1.0e-9)
    parser.add_argument("--oracle-capacity", type=int, default=2048)
    args = parser.parse_args()
    record = _finalize_mandatory_cli_record(args, _SCENARIOS[args.scenario](args))
    print(json.dumps(record, indent=2))
    if record.get("status") in ("failed", "timeout"):
        raise SystemExit(1)
    if args.scenario == "native-corpus":
        counts = record["counts"]
        if not isinstance(counts, dict):
            raise TypeError(
                "Native corpus qualification must retain its outcome-count mapping."
            )
        if (
            counts.get("failed", 0)
            or counts.get("timeout", 0)
            or record.get("unqualified_selected_profiles")
            or record.get("mandatory_workflows_incomplete")
        ):
            raise SystemExit(1)


if __name__ == "__main__":
    main()
